from datetime import datetime
from typing import Optional

def parse_date(text: str) -> datetime.date:
    """
    Parses a date string into a datetime.date object supporting three formats:
    1. ISO format: YYYY-MM-DD (e.g., "2025-03-07")
    2. British numeric: DD/MM/YYYY (e.g., "07/03/2025")
    3. Short text: D [Mon/Tue/Feb.../Dec] YYYY (e.g., "7 Mar 2025" or "07 March 2025")

    Raises ValueError for invalid formats, whitespace-only strings, or impossible dates.
    """
    # Remove surrounding whitespace but keep internal spaces if any (though not expected in these strict formats)
    text = text.strip()

    if not text:
        raise ValueError("Empty input string.")

    # Try ISO format first: YYYY-MM-DD
    try:
        return datetime.strptime(text, "%Y-%m-%d").date()
    except ValueError:
        pass

    # Try British numeric format: DD/MM/YYYY
    try:
        return datetime.strptime(text, "%d/%m/%Y").date()
    except ValueError:
        pass

    # Try Short text format: D Month YYYY or DD Month YYYY
    # We need to handle month names (case-insensitive) and optional leading zero in day.
    months = {
        "jan": 0, "feb": 1, "mar": 2, "apr": 3, "may": 4, "jun": 5,
        "jul": 6, "aug": 7, "sep": 8, "oct": 9, "nov": 10, "dec": 11
    }

    # Try splitting by space. The format is likely "Day Month Year" or "Month Abbreviated Name"? 
    # Wait, the prompt says: "7 Mar 2025". This is Day, Month (Abbrev), Year.
    # But standard English often writes "March 7, 2025". The prompt specifically defines:
    # "Short text: `7 Mar 2025` (English three-letter month; day with or without a leading zero)"
    # So the order is Day, Month(Abbrev), Year.

    parts = text.split()
    if len(parts) != 3:
        raise ValueError(f"Invalid date format for short text: expected 'D Mon Y', got '{text}'")

    try:
        day_str, month_abbr, year_str = parts
    except ValueError:
        raise ValueError(f"Could not split input into three parts: '{text}'")

    # Validate year
    try:
        year = int(year_str)
    except ValueError:
        raise ValueError(f"Invalid year format: '{year_str}'")

    # Validate day (with or without leading zero)
    try:
        day = int(day_str)
    except ValueError:
        raise ValueError(f"Invalid day format: '{day_str}'")

    # Validate month abbreviation
    month_abbr_lower = month_abbr.lower()
    if month_abbr_lower not in months:
        raise ValueError(f"Unknown month abbreviation: '{month_abbr}'")

    month = months[month_abbr_lower]

    try:
        return datetime(year, month + 1, day).date()
    except ValueError:
        # Date is impossible (e.g., Feb 30)
        raise ValueError(f"Impossible date: {day}/{month+1}/{year}")
