function deepMerge(base, override) {
  if (!override || typeof override !== 'object' || Array.isArray(override)) {
    return { ...base };
  }

  const result = { ...base };
  const keys = Object.keys(override);

  for (const key of keys) {
    const baseValue = result[key];
    const overrideValue = override[key];

    if (overrideValue === undefined) {
      // Ignore undefined values in override, keep base value
      continue;
    } else if (overrideValue === null || overrideValue === false) {
      // Null explicitly replaces, even for keys that exist in base
      result[key] = overrideValue;
    } else if (
      typeof baseValue === 'object' &&
      baseValue !== null &&
      !Array.isArray(baseValue) &&
      typeof overrideValue === 'object' &&
      overrideValue !== null &&
      !Array.isArray(overrideValue)
    ) {
      // Recursive merge for plain objects
      result[key] = deepMerge(baseValue, overrideValue);
    } else {
      // Override replaces base (including arrays and primitives)
      result[key] = overrideValue;
    }
  }

  return result;
}
