import datetime
import re

def parse_date(text: str) -> datetime.date:
    """
    Parses a date string accepted by an invoicing service from three specific formats.

    Args:
        text: The date string to parse.

    Returns:
        A datetime.date object representing the parsed date.

    Raises:
        ValueError: If the date string does not match one of the allowed formats 
                   or represents an impossible date.
    """
    text = text.strip()

    # Format 1: ISO (YYYY-MM-DD)
    iso_match = re.fullmatch(r'\d{4}-\d{2}-\d{2}', text)
    if iso_match:
        date_str = text
    else:
        date_str = None

    # Format 2: British numeric (DD/MM/YYYY)
    british_match = re.fullmatch(r'(\d{1,2})/(\d{1,2})/(\d{4})', text)
    if british_match:
        date_str = text
    else:
        date_str = None

    # Format 3: Short text (D MMM YYYY)
    # \d{1,2} matches day (1 or 2 digits)
    # [A-Za-z]{3} matches three-letter month
    # \s+ matches one or more whitespace
    text_match = re.fullmatch(r'(\d{1,2})\s+([A-Z]{3})\s+(\d{4})', text, re.IGNORECASE)
    if text_match:
        date_str = text
    else:
        date_str = None

    # Try parsing the matched string if it exists
    if date_str:
        try:
            if re.fullmatch(r'\d{4}-\d{2}-\d{2}', date_str):
                # ISO format parsing: 2025-03-07
                return datetime.datetime.strptime(date_str, '%Y-%m-%d).date()

