        // Decode '+' to space first
        const decodedKey = decodeURIComponent(keyPart.replace(/\+/g, ' '));
        const decodedValue = decodeURIComponent(valuePart.replace(/\+/g, ' '));

        // Initialize key in obj if it doesn't exist
        if (!(decodedKey in obj)) {
