    // Refined logic check: If the value is not an array, we treat it as a single value.
    // However, the prompt implies that if a key is encountered more than once, it MUST be an array.
    // If it's encountered once, it should be a string.

    const finalObj = {};
    for (const key in obj) {
        if (Array.isArray(obj[key])) {
            finalObj[key] = obj[key];
        } else if (typeof obj[key] === 'string') {
             // Check if this single string was the result of a first-time assignment, 
             // or if it was actually an array representation that got incorrectly flattened.
             // Given the structure of the logic above, if it's not an array, it's a single value.
             finalObj[key] = obj[key];
        }
    }

    // Re-running the core logic to ensure correct type handling based on the strict requirement:
    const finalResult = {};
    const intermediateMap = {}; // { key: { value: string, count: number } }

    for (const pair of queryString.split('&').filter(p => p.length > 0)) {
        const parts = pair.split('=');
        let keyPart = parts[0];
        let valuePart = parts.length > 1 ? parts.slice(1).join('=') : "";

        const k = decodeURIComponent(keyPart.replace(/\+/g, ' '));
        const v = decodeURIComponent(valuePart.replace(/\+/g, ' '));

        if (!intermediateMap[k]) {
            intermediateMap[k] = { values: [], count: 0 };
        }
        intermediateMap[k].values.push(v);
        intermediateMap[k].count++;
    }

    for (const key in intermediateMap) {
        const item = intermediateMap[key];
        if (item.count === 1) {
            finalResult[key] = item.values[0]; // String
        } else {
            finalResult[key] = item.values; // Array
        }
    }

    return finalResult;
