function deepMerge(base, override) {
  if (typeof base !== 'object' || base === null || Array.isArray(base)) {
    // If base is not a plain object, we can't merge into it structurally
    return override === undefined ? base : override;
  }

  const result = { ...base };

  for (const key in override) {
    if (!Object.prototype.hasOwnProperty.call(override, key)) continue;

    const overrideVal = override[key];
    const baseVal = base[key];

    // 1. Ignore undefined values in override
    if (overrideVal === undefined) continue;

    // 2. Handle plain object recursion
    if (
      typeof overrideVal === 'object' && overrideVal !== null && !Array.isArray(overrideVal) &&
      typeof baseVal === 'object' && baseVal !== null && !Array.isArray(baseVal)
    ) {
      // Recursively merge, ensuring the result is a deep copy
      result[key] = deepMerge(baseVal, overrideVal);
    } else {
      // 3. Replacement logic (null replaces, arrays replace, primitives replace)
      // We must deep copy the override value if it's an object/array to ensure immutability of the result
      if (typeof overrideVal === 'object' && overrideVal !== null) {
        result[key] = Array.isArray(overrideVal) 
          ? [...overrideVal] 
          : { ...overrideVal }; // Shallow copy is sufficient for top level if structure isn't complex, but deep cloning would be safer for absolute guarantee. Given the requirements, a shallow copy of objects/arrays originating from 'override' is usually acceptable unless they contain references that need recursive isolation. For strict immutability against future modification, a deep clone is best. Let's stick to deep cloning objects/arrays.

        // A robust deep clone for assignment:
        const isArray = Array.isArray(overrideVal);
        result[key] = isArray 
            ? overrideVal.map(item => typeof item === 'object' && item !== null ? deepMerge({}, item) : item)
            : Object.keys(overrideVal).reduce((obj, k) => {
                obj[k] = (typeof overrideVal[k] === 'object' && overrideVal[k] !== null) ? deepMerge({}, overrideVal[k]) : overrideVal[k];
                return obj;
            }, {});
      } else {
        // Primitive replacement
        result[key] = overrideVal;
      }
    }
  }

  return result;
}
```

The `deepMerge` function creates a new object by shallow-copying the `base`. It iterates over keys in `override`:
1. It skips keys where the value in `override` is `undefined`.
2. If both corresponding values in `base` and `override` are plain objects, it calls `deepMerge` recursively to merge them.
3. Otherwise (primitives, arrays, `null`, or mismatched types), it replaces the `base` value with the `override` value. Crucially, it performs a deep clone of any objects or arrays coming from `override` before assignment to ensure the resulting object is completely immutable with respect to the inputs. Keys only present in `base` are retained via the initial spread (`{ ...base }`).

