def normalise_order(raw: dict) -> dict:
    """
    Normalises a raw order dictionary into a standardised format.

    Args:
        raw: The raw order dictionary from the web form.

    Returns:
        A new dictionary with normalised order data.

    Raises:
        ValueError: If any required field is invalid or missing.
    """
    # Validate required keys presence
    if 'sku' not in raw or 'qty' not in raw or 'unit_price_pence' not in raw:
        raise ValueError("Missing required order fields: sku, qty, or unit_price_pence.")

    # 1. Normalise SKU
    sku = str(raw['sku']).strip()
    if not sku:
        raise ValueError("SKU must not be empty after stripping.")

    # 2. Normalise Quantity (qty)
    try:
        qty = int(str(raw['qty']).strip())
    except ValueError:
        raise ValueError("Quantity must be a valid integer.")
    if not (1 <= qty <= 99):
        raise ValueError("Quantity must be between 1 and 99 inclusive.")

    # 3. Normalise Unit Price (unit_price_pence)
    try:
        unit_price_pence = int(str(raw['unit_price_pence']).strip())
    except ValueError:
        raise ValueError("Unit price must be a valid integer.")
    if unit_price_pence < 0:
        raise ValueError("Unit price must be 0 or more.")

    # 4. Normalise Currency
    currency = raw.get("currency")
    if currency is None:
        currency = "GBP"  # Default if missing
    else:
        currency_str = str(currency).strip().upper()
        allowed_currencies = {"GBP", "EUR", "USD"}
        if currency_str not in allowed_currencies:
            # Only raise error if it's present but invalid, otherwise default behavior handles blank/None
            if currency_str != "" and currency_str not in allowed_currencies:
                raise ValueError(f"Invalid currency: {currency_str}. Allowed: {allowed_currencies}")
            # If it was blank or None, it would have been set to GBP above, but if we reach here,
            # and the original was a blank string, we treat it as potentially invalid if we didn't force GBP on blank.
            # Based on prompt: 'GBP' when it is missing, None or blank.
            if currency_str == "" or currency_str == "None":
                 currency = "GBP"
            else:
                 currency = currency_str # Should not happen due to allowed_currencies check

    # Refined currency logic to match prompt:
    currency_input = raw.get("currency")
    if currency_input is None or str(currency_input).strip() == "":
        currency_final = "GBP"
    else:
        currency_stripped = str(currency_input).strip().upper()
        allowed_currencies = {"GBP", "EUR", "USD"}
        if currency_stripped in allowed_currencies:
            currency_final = currency_stripped
        else:
            # If it's present but not allowed (e.g. "JPY")
            raise ValueError(f"Invalid currency: {currency_input}. Only GBP, EUR, USD are allowed.")


    # 5. Calculate Total
    total_pence = qty * unit_price_pence

    # Return the new dict, ignoring other keys
    return {
        "sku": sku,
        "qty": qty,
        "unit_price_pence": unit_price_pence,
        "currency": currency_final,
        "total_pence": total_pence
    }
