    let queryString = qs.startsWith('?') ? qs.substring(1) : qs;

    if (!queryString) {
        return result;
    }

    const pairs = queryString.split('&');

    for (const pair of pairs) {
        // Skip empty pairs
        if (!pair) {
            continue;
        }

        let [keyEncoded, valueEncoded] = pair.split('=');

        let key = keyEncoded;
        let value = "";

        if (valueEncoded !== undefined) {
            value = valueEncoded;
        }

        // 1. Decode '+' as space in both key and value (since they are encoded first)
        key = key.replace(/\+/g, ' ');
        value = value.replace(/\+/g, ' ');

        // 2. Percent-decode both key and value
        try {
            key = decodeURIComponent(key);
            value = decodeURIComponent(value);
        } catch (e) {
            // Handle potential decoding errors by keeping the raw decoded string
            console.error("Decoding error:", e);
        }

        // Handle key insertion logic
        if (!(key in result)) {
            // First time seeing this key
            result[key] = value;
        } else {
            // Key already exists
            const currentValue = result[key];
            if (Array.isArray(currentValue)) {
                // Already an array, append new value
                currentValue.push(value);
            } else {
                // Was a string, convert to array with current and new value
                result[key] = [currentValue, value];
            }
        }
    }

    return result;
