import re

def parse_date(text: str) -> datetime.date:
    # Clean whitespace
    text = text.strip()

    # Try ISO format: YYYY-MM-DD
    try:
        return datetime.strptime(text, "%Y-%m-%d").date()
    except ValueError:
        pass

    # Try British numeric: DD/MM/YYYY (allow leading zeros)
    try:
        return datetime.strptime(text, "%d/%m/%Y").date()
    except ValueError:
        pass

    # Try Short text: D Mon YYYY or DD Mon YYYY
    # Month names must be exact three-letter English months
    month_map = {
        "Jan": 1, "Feb": 2, "Mar": 3, "Apr": 4, "May": 5, "Jun": 6,
        "Jul": 7, "Aug": 8, "Sep": 9, "Oct": 10, "Nov": 11, "Dec": 12
    }

    # Pattern: optional day, space, month name (3 letters), space, year
    pattern = r'^(\d+)?\s+(\w+)\s+(\d{4})$'
    match = re.match(pattern, text)

    if not match:
        raise ValueError(f"Date format not recognized in '{text}'")

    day_str, month_str, year_str = match.groups()

    if not day_str:
        day_str = "1"

    try:
        day = int(day_str)
        month = month_map[month_str]
        year = int(year_str)

        # Construct and validate date to ensure it's impossible dates like Feb 30 are rejected
        return datetime(year, month, day).date()
    except (ValueError, KeyError):
        raise ValueError(f"Invalid date format or values in '{text}'")
