def normalise_order(raw: dict) -> dict:
    # Validate required keys exist before accessing to raise KeyError as per standard practice for missing keys,
    # but the prompt explicitly says "missing sku, qty or unit_price_pence must raise ValueError (not KeyError)".
    # To satisfy this strictly, we check existence first and raise ValueError if missing.

    if "sku" not in raw:
        raise ValueError("Missing required key 'sku'")
    if "qty" not in raw:
        raise ValueError("Missing required key 'qty'")
    if "unit_price_pence" not in raw:
        raise ValueError("Missing required key 'unit_price_pence'")

    sku = raw["sku"]
    qty_raw = raw["qty"]
    unit_price_raw = raw["unit_price_pence"]

    # Process SKU
    if not isinstance(sku, str):
        raise ValueError("'sku' must be a string")
    sku_cleaned = sku.strip().upper()
    if not sku_cleaned:
        raise ValueError("'sku' must not be empty after stripping")

    # Process Qty
    if isinstance(qty_raw, str):
        qty_cleaned = int(qty_raw.strip())
    elif isinstance(qty_raw, (int, float)):
        # If it's a float like 3.0, convert to int; otherwise assume int
        try:
            qty_cleaned = int(qty_raw)
        except ValueError:
            raise ValueError("'qty' must be convertible to an integer")
    else:
        raise ValueError("'qty' must be an int or a string representing an int")

    if not (1 <= qty_cleaned <= 99):
        raise ValueError("'qty' must be between 1 and 99 inclusive")

    # Process Unit Price
    if not isinstance(unit_price_raw, (int, float)):
        raise ValueError("'unit_price_pence' must be a number")

    try:
        unit_price_cleaned = int(unit_price_raw)
    except ValueError:
        raise ValueError("'unit_price_pence' must be convertible to an integer")

    if unit_price_cleaned < 0:
        raise ValueError("'unit_price_pence' must be zero or more")

    # Process Currency
    currency = raw.get("currency", "")
    if not isinstance(currency, str):
        currency_str = ""
    else:
        currency_str = currency.strip().upper()

    allowed_currencies = {"GBP", "EUR", "USD"}
    if currency_str in allowed_currencies:
        final_currency = currency_str
    elif currency_str == "":
        final_currency = "GBP" # Default when missing/blank after strip
    else:
        raise ValueError(f"'currency' must be one of {allowed_currencies} or empty")

    total_pence = qty_cleaned * unit_price_cleaned

    return {
        "sku": sku_cleaned,
        "qty": qty_cleaned,
        "unit_price_pence": unit_price_cleaned,
        "currency": final_currency,
        "total_pence": total_pence
    }
