function parseQuery(qs) {
  if (!qs || typeof qs !== 'string') return {};

  // Remove leading/trailing whitespace and optional leading '?'
  let str = qs.trim().replace(/^[\?]*$/, '');

  const result = {};
  const pairs = str.split('&');

  for (let i = 0; i < pairs.length; i++) {
    const pair = pairs[i].trim();

    // Skip empty pairs
    if (!pair) continue;

    const eqIndex = pair.indexOf('=');
    let key, value;

    if (eqIndex === -1) {
      // Key without value gets empty string
      key = decodeURIComponent(pair.replace(/\+/g, ' '));
      value = '';
    } else {
      key = decodeURIComponent(pair.substring(0, eqIndex).replace(/\+/g, ' '));
      value = decodeURIComponent(pair.substring(eqIndex + 1).replace(/\+/g, ' '));
    }

    if (!key) continue; // Skip keys that are empty after decoding/trimming logic if needed, though spec implies skip empty pairs.

    if (result[key] === undefined) {
      result[key] = value;
    } else {
      if (!Array.isArray(result[key])) {
        result[key] = [result[key]];
      }
      result[key].push(value);
    }
  }

  return result;
}
