function deepMerge(base, override) {
  if (typeof base !== 'object' || base === null || typeof override !== 'object' || override === null) {
    return override;
  }

  const result = {};
  const keys = new Set([...Object.keys(base), ...Object.keys(override)]);

  for (const key of keys) {
    const baseVal = base[key];
    const overrideVal = override[key];

    // If override is undefined, keep base value; if null, replace with null
    if (overrideVal === undefined) {
      result[key] = baseVal;
    } else {
      // Check if both are plain objects
      const isPlainObj = (val) => val !== null && typeof val === 'object' && !Array.isArray(val);

      if (isPlainObj(baseVal) && isPlainObj(overrideVal)) {
        result[key] = deepMerge(baseVal, overrideVal);
      } else {
        // Arrays and non-objects are replaced; null also replaces
        result[key] = overrideVal;
      }
    }
  }

  return result;
}
