from datetime import datetime, date
from typing import Union

def parse_date(text: str) -> date:
    """
    Parses a date string into a datetime.date object supporting three formats:
    - ISO: 2025-03-07
    - British numeric: 07/03/2025 (day/month/year)
    - Short text: 7 Mar 2025 (English three-letter month; day with or without leading zero)

    Raises ValueError for invalid formats or impossible dates.
    """
    text = text.strip()

    # Try ISO format first: YYYY-MM-DD
    try:
        return datetime.strptime(text, "%Y-%m-%d").date()
    except ValueError:
        pass

    # Try British numeric format: DD/MM/YYYY
    try:
        return datetime.strptime(text, "%d/%m/%Y").date()
    except ValueError:
        pass

    # Try short text format: D Mon YYYY or DD Mon YYYY
    months = {
        "jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6,
        "jul": 7, "aug": 8, "sep": 9, "oct": 10, "nov": 11, "dec": 12
    }

    parts = text.split()
    if len(parts) != 3:
        raise ValueError(f"Invalid short date format. Expected 'D Mon YYYY' or 'DD Mon YYYY'. Got: {text}")

    day_str, month_str, year_str = parts

    # Normalize day to int (handle both "7" and "07")
    try:
        day = int(day_str)
    except ValueError:
        raise ValueError(f"Invalid day value: {day_str}")

    if not 1 <= day <= 31:
        raise ValueError(f"Day must be between 1 and 31. Got: {day}")

    month_key = month_str.lower()
    if month_key not in months:
        raise ValueError(f"Invalid month name: {month_str}")

    month = months[month_key]

    try:
        year = int(year_str)
    except ValueError:
        raise ValueError(f"Invalid year value: {year_str}")

    # Construct date object and let datetime handle validation (e.g., Feb 30)
    try:
        return date(year, month, day)
    except ValueError as e:
        raise ValueError(f"Impossible date: {text}") from e
```

