from typing import Any, Dict, Optional


def normalise_order(raw: dict) -> dict:
    """
    Normalises a raw order dictionary into a standardized format.

    Args:
        raw: A dictionary containing raw order data from a web form.

    Returns:
        A new dictionary with keys: sku, qty, unit_price_pence, currency, total_pence.

    Raises:
        ValueError: If any required field is missing or invalid.
    """

    # Validate and extract SKU
    if "sku" not in raw:
        raise ValueError("Missing required key 'sku'")
    sku = raw["sku"].strip().upper()
    if not sku:
        raise ValueError("'sku' must not be empty after stripping")

    # Validate and extract Quantity
    if "qty" not in raw:
        raise ValueError("Missing required key 'qty'")
    try:
        qty = int(raw["qty"].strip())
    except (ValueError, AttributeError):
        raise ValueError("'qty' must be a valid integer")

    if qty < 1 or qty > 99:
        raise ValueError("'qty' must be between 1 and 99 inclusive")

    # Validate and extract Unit Price
    if "unit_price_pence" not in raw:
        raise ValueError("Missing required key 'unit_price_pence'")
    try:
        unit_price_pence = int(raw["unit_price_pence"])
    except (ValueError, AttributeError):
        raise ValueError("'unit_price_pence' must be a valid integer")

    if unit_price_pence < 0:
        raise ValueError("'unit_price_pence' must be 0 or more")

    # Extract and validate Currency
    currency = raw.get("currency")
    if currency is not None:
        currency = currency.strip().upper()
        if not currency:
            currency = None
        else:
            allowed_currencies = {"GBP", "EUR", "USD"}
            if currency not in allowed_currencies:
                raise ValueError(f"'currency' must be one of {allowed_currencies}, got '{currency}'")

    # Calculate Total
    total_pence = qty * unit_price_pence

    return {
        "sku": sku,
        "qty": qty,
        "unit_price_pence": unit_price_pence,
        "currency": currency,
        "total_pence": total_pence
    }
