function parseQuery(qs) {
  const result = {};

  // If the string starts with '?', remove it
  if (qs.startsWith('?')) {
    qs = qs.slice(1);
  }

  // Split by '&' to get individual pairs
  const pairs = qs.split('&');

  for (let i = 0; i < pairs.length; i++) {
    const pair = pairs[i].trim();

    // Skip empty pairs
    if (!pair) continue;

    // Find the first '=' to separate key and value
    const eqIndex = pair.indexOf('=');
    let key, value;

    if (eqIndex === -1) {
      // Key without value gets empty string
      key = decodeURIComponent(pair.replace(/\+/g, ' '));
      value = '';
    } else {
      key = decodeURIComponent(pair.slice(0, eqIndex).replace(/\+/g, ' '));
      value = decodeURIComponent(pair.slice(eqIndex + 1).replace(/\+/g, ' '));
    }

    // If key exists and is already an array, push the new value
    if (key in result) {
      const arr = result[key];
      if (!Array.isArray(arr)) {
        result[key] = [arr];
      }
      result[key].push(value);
    } else {
      result[key] = value;
    }
  }

  return result;
}
