function deepMerge(base, override) {
  if (!override || typeof override !== 'object' || Array.isArray(override)) {
    return override;
  }

  const result = {};

  // First, copy all keys from base (unless overridden by a non-object value in override)
  for (const key in base) {
    if (Object.prototype.hasOwnProperty.call(base, key)) {
      // Check if this key is actually being overridden with a primitive/null/undefined
      const overrideVal = override[key];

      if (overrideVal === undefined || (typeof overrideVal !== 'object' && !Array.isArray(overrideVal))) {
        result[key] = base[key];
      } else if (overrideVal === null) {
        result[key] = null;
      } else {
        // Value exists in override, will be handled by the loop below or merged here
        result[key] = deepMerge(base[key], overrideVal);
      }
    }
  }

  // Now process keys from override to handle merging logic correctly
  for (const key in override) {
    if (Object.prototype.hasOwnProperty.call(override, key)) {
      const baseVal = base[key];
      const overrideVal = override[key];

      // Skip undefined values in override
      if (overrideVal === undefined) continue;

      // Check if both are plain objects (not arrays)
      const isBasePlain = typeof baseVal === 'object' && !Array.isArray(baseVal);
      const isOverridePlain = typeof overrideVal === 'object' && !Array.isArray(overrideVal);

      if (isBasePlain && isOverridePlain) {
        result[key] = deepMerge(baseVal, overrideVal);
      } else {
        // Override replaces base (including arrays and primitives)
        result[key] = overrideVal;
      }
    }
  }

  return result;
}
```

This function creates a new object by first copying all keys from `base`, then iterating through `override` to determine how to handle each key. If both values are plain objects, it recursively merges them; otherwise, the override value replaces the base value. It correctly handles `undefined` (ignored), `null` (replaces), and arrays (replaced).

