long long parse_duration(const std::string& s) {
    if (s.empty()) {
        return -1;
    }

    std::map<char, long long> units_map = {
        {'h', 3600},
        {'m', 60},
        {'s', 1}
    };

    long long total_seconds = 0;
    int unit_idx = 0; // Expect h, then m, then s

    for (int i = 0; i < s.length(); ) {
