      if (str === null) return "";
      return decodeURIComponent(str.replace(/\+/g, ' '));
    };

    const key = decodeAndClean(keyEncoded);
    const value = decodeAndClean(valueEncoded);

    // 6. Store in result object, handling arrays vs strings
    if (result.hasOwnProperty(key)) {
      // Key already exists
      if (Array.isArray(result[key])) {
        // If it's already an array, push the new value
        result[key].push(value);
      } else {
        // Convert the existing string to an array and push the new value
        result[key] = [result[key], value];
      }
    } else {
      // First occurrence
