        // Check if a number was found
        if (start_num == current_pos) {
            return -1; // Unit must be preceded by a number
        }

        // 2. Parse the unit
        if (current_pos >= s.length() || !std::string("hms").find(s[current_pos]) == current_pos) {
            // Check if the character is 'h', 'm', or 's' and not part of the number
            if (std::isdigit(s[current_pos])) {
                // This case implies the string continued with another digit 
                // but the loop structure should handle this by re-evaluating the next part.
                // However, if we are at the end or the next char is not a unit, it's invalid.
                // We must check if the next char is a unit.
                if (current_pos == s.length()) return -1;
                // If it's a digit, it must be the start of the next number block, but we are expecting a unit.
                return -1;
            } else {
                // Not a digit, and not one of the expected units
                return -1;
            }
        }

        char unit = s[current_pos];
        current_pos++;

        // 3. Validate unit
        if (unit != 'h' && unit != 'm' && unit != 's') {
            return -1; // Unknown unit
        }

        if (seen_units.count(unit)) {
            return -1; // Repeated unit
