        switch (unit) {
            case 'h':
                total_seconds += value * 3600;
                break;
            case 'm':
                total_seconds += value * 60;
                break;
            case 's':
                total_seconds += value;
                break;
        }
    }

    // 5. Validate order (must appear in h, m, s sequence)
    // If we have units, we need to check if the required sequence was followed.
    // The strict order check:
