                    // the lowest order unit present must be 'h', then 'm', then 's'.
                    // Let's simplify the interpretation: if h is present, it must be first. If h is absent but m is present, this is invalid.
                    if (seen_units.count('h') == 0 && seen_units.count('m') && seen_units.count('s') && last_unit_index != -1) {
                         // This logic is getting overly complex for the constraints. Sticking to the iteration logic is safer.
                    }
