    }

    // The sequential loop structure combined with unit tracking *is* the check for "no spaces" and "correct order" 
    // *if* the input is strictly concatenated like `N1u1N2u2N3u3`. 
    // Example: "30m1h" -> Loop sees '30', then 'm'. It expects 'h' to appear before 'm' if both exist.
    // Since the loop iterates strictly left-to-right, if 'm' is processed before 'h', it means 'm' appeared first in the string.

    // Final check on order based on the sequence of units encountered in the loop (stored in `seen_units` is not enough):
    // We need the order they were *found*. We'll use a vector to store the units in order found.

    std::vector<char> found_order;
    current_pos = 0;
    while (current_pos < s.length()) {
        size_t start_num = current_pos;
        while (current_pos < s.length() && std::isdigit(s[current_pos])) {
            current_pos++;
        }
        if (start_num == current_pos || current_pos >= s.length()) return -1;

        char unit = s[current_pos];
        current_pos++;

        if (unit != 'h' && unit != 'm' && unit != 's') return -1;

        if (found_order.empty()) {
            found_order.push_back(unit);
        } else {
            char last_unit = found_order.back();
            if ((unit == 'm' && last_unit == 'h') || (unit == 's' && last_unit == 'm')) {
                 found_order.push_back(unit);
            } else if (unit == 'h' && last_unit == 'm' || unit == 'h' && last_unit == 's') {
                return -1; // h cannot appear after m or s
            } else if (unit == 'm' && (last_unit == 'h' || last_unit == 's')) {
                 return -1; // m cannot appear after s
            } else if (unit == 's' && (last_unit == 'h' || last_unit == 'm')) {
                 // Valid progression, but if last_unit was 's' (impossible due to unique check), this would be an issue.
                 // If last_unit was 'h' or 'm', it's valid progression.
                 found_order.push_back(unit);
            } else {
                // This catches cases like 'm' followed by 'h' if 'h' was skipped initially, 
                // or if the sequence jumps unexpectedly.
                // If the previous unit wasn't the direct predecessor, it's invalid.
                return -1;
            }
        }
    }


    return total_seconds;
}
