def normalise_order(raw: Dict[str, Any]) -> Dict[str, Any]:
    """
    Normalises a raw order dictionary from a web form into a standard format.
    """
    # Validate mandatory keys and handle SKU
    if "sku" not in raw:
        raise ValueError("Missing required field: sku")

    sku = str(raw["sku"]).strip().upper()
    if not sku:
        raise ValueError("SKU cannot be empty after stripping.")

    # Validate and process quantity
    if "qty" not in raw:
        raise ValueError("Missing required field: qty")

    try:
        qty = int(str(raw["qty"]).strip())
        if not (1 <= qty <= 99):
            raise ValueError(f"Quantity must be between 1 and 99, got {qty}")
    except ValueError:
        raise ValueError(f"Quantity must be a valid integer, got {raw['qty']}")

    # Validate and process unit price
    if "unit_price_pence" not in raw:
        raise ValueError("Missing required field: unit_price_pence")

    try:
        unit_price_pence = int(str(raw["unit_price_pence"]).strip())
        if unit_price_pence < 0:
            raise ValueError(f"Unit price must be 0 or more, got {unit_price_pence}")
    except ValueError:
        raise ValueError(f"Unit price must be a valid integer, got {raw['unit_price_pence']}")

    # Process currency
    currency = raw.get("currency")
    if currency is None or str(currency).strip() == "":
        currency = "GBP"
    else:
        currency = str(currency).strip().upper()

    allowed_currencies = {"GBP", "EUR", "USD"}
    if currency not in allowed_currencies:
