        # Based on requirement: "GBP when it is missing, None or blank. Only GBP, EUR and USD are allowed."
        # This implies if it's present but invalid, it's an error.
        if currency != "GBP": # Check if we defaulted to GBP above
            raise ValueError(f"Invalid currency: {currency}. Must be GBP, EUR, or USD.")


    # Calculate total
    total_pence = qty * unit_price_pence

    # Return the new dictionary
    return {
        "sku": sku,
        "qty": qty,
        "unit_price_pence": unit_price_pence,
        "currency": currency,
        "total_pence": total_pence
    }

