/**
 * Parses a query string into a plain JavaScript object.
 *
 * @param {string} qs The query string (with or without leading '?').
 * @returns {Object<string, string|string[]>} The parsed query object.
 */
function parseQuery(qs) {
    const query = {};
    if (!qs || typeof qs !== 'string') {
        return query;
    }

    // 1. Remove leading '?' if present
    let sanitizedQs = qs.startsWith('?') ? qs.substring(1) : qs;

    if (!sanitizedQs) {
        return query;
    }

    // Split by '&'
    const pairs = sanitizedQs.split('&);

    for (let i = 0; i < pairs.length; i++) {
        const pair = pairs[i];

        // 5. Skip empty pairs
        if (pair.length === 0) {
            continue;
        }

        // 2. Split by the FIRST '='
        const separatorIndex = pair.indexOf('=');
        let keyPart, valuePart;

        if (separatorIndex === -1) {
            keyPart = pair;
            valuePart = ""; // 4. A key without '=' gets value ""
        } else {
            keyPart = pair.substring(0, separatorIndex);
            valuePart = pair.substring(separatorIndex + 1);
        }

        // 2. Decode '+' to space
        const decodedKey = keyPart.split('+').join(' ');
        const decodedValue = valuePart.split('+').join(' ');

        // 2. Percent-decode keys and values
        try {
            const finalKey = decodeURIComponent(decodedKey);
            const finalValue = decodeURIComponent(decodedValue);

            // 6. Skip if key becomes empty after decoding (though usually keys are non-empty)
            if (finalKey === "") {
                continue;
            }

            // 4. Handle single vs multiple occurrences
            if (Object.prototype.hasOwnProperty.call(query, finalKey)) {
                if (Array.isArray(query[finalKey])) {
                    // Key appeared again, push to existing array
                    query[finalKey].push(finalValue);
                } else {
                    // Key appeared before as a single string, convert to array
                    query[finalKey] = [query[finalKey], finalValue];
                }
            } else {
                // First time seeing this key
                query[finalKey] = finalValue;
            }

        } catch (e) {
            // Handle malformed URI components by skipping or logging if necessary
            console.error(`Decoding error for pair "${pair}":`, e);
        }
    }

    return query;
}
