function deepMerge(base, override) {
    // Helper function to check if a value is a plain object (and not null/array)
    const isPlainObject = (obj) => {
        return obj !== null && 
               typeof obj === 'object' && 
               !Array.isArray(obj);
    };

    // Start by deep copying the base object to ensure immutability
    const result = Array.isArray(base) ? [...base] : (isPlainObject(base) ? { ...base } : base);

    if (!isPlainObject(base) || !isPlainObject(override)) {
        // If inputs aren't plain objects, simple replacement logic based on the problem constraints
        return override === undefined ? base : override;
    }

    // Iterate over override keys
    Object.keys(override).forEach(key => {
        const baseValue = result[key];
        const overrideValue = override[key];

        // 1. Ignore undefined values in override
        if (overrideValue === undefined) {
            return;
        }

        // 2. Check for recursive merge condition
        if (isPlainObject(baseValue) && isPlainObject(overrideValue)) {
            // Recursive merge: create a new object to avoid sharing references
            result[key] = deepMerge(baseValue, overrideValue);
        } else {
            // 3. Replace (this covers arrays, null replacements, and primitives)
            // Ensure the replacement is a deep copy if it's an object/array, 
            // to maintain the strict immutability requirement for nested structures.
            if (typeof overrideValue === 'object' && overrideValue !== null) {
                const isArray = Array.isArray(overrideValue);
                result[key] = isArray 
                    ? [...overrideValue] 
                    : { ...overrideValue };
            } else {
                // Primitives, null, etc.
                result[key] = overrideValue;
            }
        }
    });

    return result;
