    size_t current_pos = 0;

    while (current_pos < s.length()) {
        size_t start_num = current_pos;
        while (current_pos < s.length() && std::isdigit(s[current_pos])) {
            current_pos++;
        }

        // If no digits were found, it's an error (e.g., starting with 'h', or sequence like "h30")
        if (current_pos == start_num) {
            return -1;
        }

        // Extract the number
        std::string num_str = s.substr(start_num, current_pos - start_num);
        long long value = std::stoll(num_str);

        // Check for unit
        if (current_pos >= s.length() || !std::isalpha(s[current_pos])) {
            return -1; // Number without a unit
        }

        char unit_char = s[current_pos];
        current_pos++;

        // 1. Check for valid unit
        if (unit_char == 'h' || unit_char == 'm' || unit_char == 's') {
            int unit_idx = unit_to_index[unit_char];

            // 2. Check for wrong order or repeated unit
            // The expected order is h (0), m (1), s (2).
            // We must process units in this increasing order (0 -> 1 -> 2).
            if (unit_idx != expected_next_unit_idx) {
                return -1; // Wrong order or repeated unit (if expected_next_unit_idx was already processed)
            }

            // 3. Apply value
            total_seconds += value * unit_multipliers[unit_char];

            // Update expectation: next unit must be one step further in the sequence
            expected_next_unit_idx++;

        } else {
            // Unknown unit
            return -1;
        }

        // If we have processed all possible unit types (h, m, s), but still have string left, it's invalid.
        if (expected_next_unit_idx > 2) {
            return -1;
        }
    }

    // Final check: ensure all expected units were potentially present IF we parsed a non-empty string
    // The problem implies structure like 1h30m, 45s. If the input was "1h", expected_next_unit_idx is 1. This is valid.
    // If the input was "1h2m", expected_next_unit_idx is 2. This is valid.
    // If the input was "1h2m3s", expected_next_unit_idx is 3. This is valid.
    // We only need to check if we consumed the whole string, which the loop ensures.
    // Since the units must appear in order h, m, s *if they are present*, the strict progression check handles correctness.

    // Special check: If the input contained digits but no units, expected_next_unit_idx remains 0, but the loop would have failed
    // unless the string was just digits, which fails the 'unit without number' check inside the loop if the string ends.
    // If the string was "123", the loop consumes "123", but fails the unit check.
    return (total_seconds == 0 && !s.empty()) ? -1 : total_seconds;
