def parse_date(text: str) -> datetime.date:
    """
    Parses a date string from an invoicing service based on specific formats.

    Formats accepted:
    - ISO: 'YYYY-MM-DD'
    - British numeric: 'DD/MM/YYYY'
    - Short text: 'D Mon YYYY' (e.g., '7 Mar 2025')

    Raises ValueError if the format does not match or if the date is invalid.
    """
    text = text.strip()

    # 1. ISO Format (YYYY-MM-DD)
    try:
        return datetime.datetime.strptime(text, '%Y-%m-%d').date()
    except ValueError:
        pass

    # 2. British numeric (DD/MM/YYYY)
    try:
        # We explicitly check for the expected format structure before parsing
        parts = text.split('/')
        if len(parts) == 3:
            day, month, year = parts[0], parts[1], parts[2]
            return datetime.datetime.strptime(f"{day}/{month}/{year}", '%d/%m/%Y').date()
