    # 3. Short text (e.g., '7 Mar 2025')
    # Python's strptime handles single or double digits for the day automatically
    try:
        # Handles '7 Mar 2025' and '07 Mar 2025'
        return datetime.datetime.strptime(text, '%d %b %Y').date()
    except ValueError:
        pass

    # If all parsing attempts fail
    raise ValueError(f"Date '{text}' does not match required formats (ISO, DD/MM/YYYY, D Mon YYYY)")

