def normalise_order(raw: dict) -> dict:
    """
    Normalises a raw order dictionary received from a web form.
    """
    # 1. SKU validation and transformation
    if 'sku' not in raw:
        raise ValueError("Missing required field: sku")
    sku = str(raw['sku']).strip().upper()
    if not sku:
        raise ValueError("SKU must not be empty after stripping")

    # 2. Quantity validation and transformation
    if 'qty' not in raw:
        raise ValueError("Missing required field: qty")
    try:
        # Handle strings like " 3 " or actual ints
        qty = int(str(raw['qty']).strip())
    except ValueError:
        raise ValueError("Invalid format for quantity (qty)")

    if not (1 <= qty <= 99):
        raise ValueError("Quantity (qty) must be between 1 and 99 inclusive")

    # 3. Unit Price validation and transformation
    if 'unit_price_pence' not in raw:
        raise ValueError("Missing required field: unit_price_pence")
    try:
        unit_price_pence = int(str(raw['unit_price_pence']).strip())
    except ValueError:
        raise ValueError("Invalid format for unit_price_pence")

    if unit_price_pence < 0:
        raise ValueError("Unit price (unit_price_pence) must be 0 or more")

    # 4. Currency validation and transformation
    currency = raw.get("currency")
    if currency is None or str(currency).strip() == "":
        final_currency = "GBP"
    else:
        stripped_currency = str(currency).strip().upper()
        allowed_currencies = ["GBP", "EUR", "USD"]
        if stripped_currency not in allowed_currencies:
            raise ValueError(f"Invalid currency: {currency}. Must be one of {allowed_currencies}")
        final_currency = stripped_currency

    # 5. Calculate total
    total_pence = qty * unit_price_pence

    # 6. Return new dict with required keys
    return {
        "sku": sku,
        "qty": qty,
        "unit_price_pence": unit_price_pence,
        "currency": final_currency,
        "total_pence": total_pence
    }
