/**
 * Merges override configuration into a base configuration recursively.
 *
 * @param {Object} base - The base configuration object.
 * @param {Object} override - The configuration object whose properties override the base.
 * @returns {Object} A new, deeply merged object.
 */
function deepMerge(base, override) {
  // Create a deep clone of the base to ensure immutability
  const result = Array.isArray(base) ? [...base] : { ...base };

  if (typeof base !== 'object' || base === null) {
    return { ...base };
  }
  if (typeof override !== 'object' || override === null) {
    return { ...base };
  }

  for (const key in override) {
    if (Object.hasOwnProperty.call(override, key)) {
      const overrideValue = override[key];
      const baseValue = base[key];

      // Ignore undefined values in override
      if (typeof overrideValue === 'undefined') {
        continue;
      }

      const isPlainObject = (val) =>
        typeof val === 'object' && val !== null && !Array.isArray(val) && val.constructor === Object;

      const isBaseObject = isPlainObject(baseValue);
      const isOverrideObject = isPlainObject(overrideValue);

      if (isBaseObject && isOverrideObject) {
        // Recursive merge for plain objects
        result[key] = deepMerge(baseValue, overrideValue);
      } else {
        // Replacement for primitives, arrays, null, or mismatched types
        // We must deep clone the override value if it's an object or array
        if (typeof overrideValue === 'object' && overrideValue !== null) {
          result[key] = Array.isArray(overrideValue) ? [...overrideValue] : { ...overrideValue };
        } else {
          result[key] = overrideValue;
        }
      }
    }
  }

  return result;
}
