        size_t start_number = current_pos;
        size_t end_number = current_pos;

        // 1. Parse the number (digits only)
        while (end_number < remaining_s.length() && std::isdigit(remaining_s[end_number])) {
            end_number++;
        }

        // Check if we found any digits
        if (start_number == end_number) {
            // Expected a number but found non-digit character at this position
            return -1;
        }

        std::string num_str = remaining_s.substr(start_number, end_number - start_number);
        long long value;
        try {
            value = std::stoll(num_str);
        } catch (const std::out_of_range& oor) {
            // Though problem states no overflow, defensive programming
            return -1;
        }

        current_pos = end_number;

        // 2. Parse the unit
        if (current_pos >= remaining_s.length()) {
            // Number found but no unit follows
            return -1;
