        // Check for repeated units
        if (unit_found[unit_idx]) {
            return -1;
        }

        // Check for correct order (h, then m, then s)
        // The unit found must be either the next expected one, or an earlier one 
        // if the sequence is currently awaiting that unit (this logic is tricky).
        // Simpler rule: we check if the current unit violates the order constraint.

        if (unit_idx < expected_unit_index) {
