/**
 * Parses a query string into a plain JavaScript object.
 * @param {string} qs The query string (with or without a leading '?').
 * @returns {Object.<string, string|string[]>} The parsed query parameters.
 */
function parseQuery(qs) {
    const params = {};

    if (!qs || qs === '?') {
        return params;
    }

    // Remove leading '?' if present
    const cleanQs = qs.startsWith('?') ? qs.substring(1) : qs;

    // Split by '&' and iterate over pairs
    const pairs = cleanQs.split('&);

    for (const pair of pairs) {
        // Skip empty pairs
        if (pair.length === 0) {
            continue;
        }

        const [keyPart, valuePart] = pair.split('=');

        // If no '=', the value is an empty string
        const rawKey = keyPart || "";
        const rawValue = valuePart !== undefined ? valuePart : "";

        // 1. Decode '+' as space, then percent-decode
        // First replace '+' with ' '
        let decodedKey = rawKey.replace(/\+/g, ' ');
        let decodedValue = rawValue.replace(/\+/g, ' ');

        // Then apply decodeURIComponent
        try {
            decodedKey = decodeURIComponent(decodedKey);
            decodedValue = decodeURIComponent(decodedValue);
        } catch (e) {
            // Handle malformed URI components gracefully by leaving them as is
        }


        // 2. Populate the object
        if (decodedKey === "") continue; // Skip pairs with empty keys

        if (params.hasOwnProperty(decodedKey)) {
            // Key already exists
            const existing = params[decodedKey];
            if (Array.isArray(existing)) {
                existing.push(decodedValue);
            } else {
                // Convert single string to array and add new value
                params[decodedKey] = [existing, decodedValue];
            }
        } else {
            // New key
            params[decodedKey] = decodedValue;
        }
    }

    // Final pass: Convert single-value arrays back to strings
    const finalParams = {};
    for (const key in params) {
        if (Array.isArray(params[key]) && params[key].length === 2 && typeof params[key][0] === 'string') {
             // If it was converted to an array of size 2 (original string + new value), 
             // the requirement is to keep it as array if it appeared more than once,
             // but if it only appeared once, it should be a string.
             // The logic above ensures single occurrences are strings unless a collision happened.
             // The logic implemented above naturally results in an array of size 1 if only one value was ever found.
             // We rely on the initial logic: if it exists, and it wasn't an array, it was a string.
        }

        // Check if it's an array and length is > 1 (multiple occurrences)
        if (Array.isArray(params[key]) && params[key].length > 1) {
            finalParams[key] = params[key];
        } else if (typeof params[key] === 'string') {
            finalParams[key] = params[key];
        } else if (Array.isArray(params[key]) && params[key].length === 1) {
            // If it's an array of length 1, return the string value inside
            finalParams[key] = params[key][0];
        }
    }

    return finalParams;
}
```

