function deepMerge(base, override) {
    // Create a deep copy of the base object to ensure immutability
    const result = typeof base === 'object' && base !== null ? deepClone(base) : base;

    if (typeof override !== 'object' || override === null) {
        return override !== undefined ? override : result;
    }

    Object.keys(override).forEach(key => {
        const baseValue = result[key];
        const overrideValue = override[key];

        // 1. Ignore undefined in override
        if (overrideValue === undefined) {
            return;
        }

        // 2. Check if both values are plain objects (not arrays, not null)
        const isObject = (val) => typeof val === 'object' && val !== null && !Array.isArray(val);

        if (isObject(baseValue) && isObject(overrideValue)) {
            // 3. Recursive merge for plain objects
            result[key] = deepMerge(baseValue, overrideValue);
        } else {
            // 4. Override replaces base (including arrays, null, primitives)
            // Deep clone the override value to ensure the result is fully independent
            result[key] = deepClone(overrideValue);
        }
    });

    return result;
}

/**
 * Helper function for deep cloning values (to satisfy the immutability requirement)
 * Handles primitives, arrays, and plain objects recursively.
 * @param {*} obj The object/value to clone.
 * @returns {*} A deep copy of the input.
 */
function deepClone(obj) {
    if (obj === null || typeof obj !== 'object') {
        return obj;
    }

    if (Array.isArray(obj)) {
        return obj.map(item => deepClone(item));
    }

    const clone = {};
    Object.keys(obj).forEach(key => {
        clone[key] = deepClone(obj[key]);
    });
    return clone;
}
```

This function uses a helper `deepClone` to ensure that whenever a new value is assigned to the `result`, it is a fully independent copy, satisfying the strict immutability requirement. It iterates over the `override` keys: ignoring `undefined`, recursively merging properties if both current values are plain objects, and replacing the value otherwise (including arrays and `null`). Keys only in `base` are preserved by starting the process with a deep copy of `base`.

