        if (current_pos == num_start) return -1;

        std::string num_str = s.substr(num_start, current_pos - num_start);
        long long value;
        try {
            value = std::stoll(num_str);
        } catch (...) {
            return -1;
        }

        // 2. Parse unit
        if (current_pos >= s.length()) return -1;

        char unit_char = s[current_pos];
        current_pos++;

        if (unit_char != 'h' && unit_char != 'm' && unit_char != 's') {
            return -1; // Unknown unit or space/invalid char
        }

        // Check order and duplication
        if (unit_char == 'h') {
            if (state != 0) return -1; // 'h' appeared after 'm' or 's'
