            state = 2; // Next expected unit is 's'
        } else { // unit_char == 's'
            if (state != 2) return -1; // 's' appeared before 'm' or 'h'
            seconds = value;
            state = 3; // Finished
        }
    }

    // If the input ended prematurely (e.g., "1h2m" but no 's' part provided, which is fine)
    // the state check is sufficient. The order must be H->M->S.

    return hours * 3600LL + minutes * 60LL + seconds;
}
