    if "sku" not in raw:
        raise ValueError("Missing required field: sku")
    sku = str(raw["sku"]).strip().upper()
    if not sku:
        raise ValueError("SKU cannot be empty after stripping.")

    # --- Qty Normalisation ---
    if "qty" not in raw:
        raise ValueError("Missing required field: qty")
    try:
        qty_raw = raw["qty"]
        qty = int(str(qty_raw).strip())
    except (TypeError, ValueError):
        raise ValueError(f"Invalid quantity format: {raw['qty']}")

    if not (1 <= qty <= 99):
        raise ValueError("Quantity must be between 1 and 99 inclusive.")

    # --- Unit Price Normalisation ---
    if "unit_price_pence" not in raw:
        raise ValueError("Missing required field: unit_price_pence")
    try:
        unit_price_pence = int(str(raw["unit_price_pence"]).strip())
    except (TypeError, ValueError):
        raise ValueError(f"Invalid unit_price_pence format: {raw['unit_price_pence']}")

    if unit_price_pence < 0:
        raise ValueError("Unit price cannot be negative.")

    # --- Currency Normalisation ---
    currency = raw.get("currency")

    # Default is "GBP" if missing, None, or blank
    if currency is None or str(currency).strip() == "":
        standard_currency = "GBP"
    else:
        standard_currency = str(currency).strip().upper()

    allowed_currencies = {"GBP", "EUR", "USD"}

