/**
 * Parses a URL query string into a plain JavaScript object.
 * 
 * @param {string} qs The query string (with or without a leading '?').
 * @returns {Object.<string, string|string[]>} The parsed query object.
 */
function parseQuery(qs) {
    const params = {};

    if (!qs) {
        return params;
    }

    // Remove leading '?' if present
    let queryString = qs.startsWith('?') ? qs.substring(1) : qs;

    if (!queryString) {
        return params;
    }

    const pairs = queryString.split('&');

    for (const pair of pairs) {
        if (!pair) {
            continue; // Skip empty pairs (e.g., from '&&' or trailing '&')
        }

        let key, value;
        const eqIndex = pair.indexOf('=');

        if (eqIndex === -1) {
            key = pair;
            value = ""; // Key without '=' gets an empty string value
        } else {
            key = pair.substring(0, eqIndex);
            value = pair.substring(eqIndex + 1);
        }

        // Decode: + to space, then percent decode
        // First, replace '+' with ' ' (common for space encoding)
        let decodedKey = decodeURIComponent(key.replace(/\+/g, ' '));
        let decodedValue = decodeURIComponent(value.replace(/\+/g, ' '));

        // Handle duplicate keys: array if already exists, string otherwise
        if (Object.prototype.hasOwnProperty.call(params, decodedKey)) {
            if (Array.isArray(params[decodedKey])) {
                params[decodedKey].push(decodedValue);
            } else {
                // Convert existing string to array, then push new value
                params[decodedKey] = [params[decodedKey], decodedValue];
            }
        } else {
            // First time seeing this key
            params[decodedKey] = decodedValue;
        }
    }

    return params;
}
