/**
 * Deep merges two configuration objects.
 * 
 * @param {object} base - The base configuration object.
 * @param {object} override - The configuration object containing overrides.
 * @returns {object} A new object containing the deep merge result.
 */
const deepMerge = (base, override) => {
  // Start with a deep clone of the base object to ensure immutability
  const result = JSON.parse(JSON.stringify(base));

  for (const key in override) {
    if (!Object.prototype.hasOwnProperty.call(override, key)) {
      continue;
    }

    const overrideValue = override[key];

    // 1. Handle undefined: ignore if present in override
    if (overrideValue === undefined) {
      continue;
    }

    const baseValue = base[key];

    // 2. Handle recursive merging for plain objects
    if (isPlainObject(baseValue) && isPlainObject(overrideValue)) {
      // Recurse and assign the new deeply merged object
      result[key] = deepMerge(baseValue, overrideValue);
    } else {
      // 3. For all other cases (primitives, arrays, null, or mixed types), 
      // the override value replaces the base value.

      // Deep clone the override value to ensure the result is completely independent
      if (Array.isArray(overrideValue)) {
        result[key] = overrideValue.map(item => 
          isPlainObject(item) ? deepMerge({}, item) : item
        );
      } else if (typeof overrideValue === 'object' && overrideValue !== null) {
         // For complex objects that aren't plain objects (like Date, RegExp), 
         // we still clone them to ensure isolation.
         try {
             result[key] = JSON.parse(JSON.stringify(overrideValue));
         } catch (e) {
             // Fallback if JSON serialization fails (e.g., circular references)
             result[key] = overrideValue;
         }
      } else {
        result[key] = overrideValue;
      }
    }
  }

  return result;
};
