function parseQuery(qs) {
    const result = {};

    // 1. Remove leading '?' if present
    let queryString = qs.startsWith('?') ? qs.substring(1) : qs;

    if (!queryString) {
        return result;
    }

    // 2. Split into pairs
    const pairs = queryString.split('&);

    for (const pair of pairs) {
        // Skip empty pairs (from && or trailing &)
        if (pair === "") {
            continue;
        }

        // 3. Split key and value (only at the first '=')
        const parts = pair.indexOf('=');
        let key, value;

        if (parts === -1) {
            key = pair;
            value = ""; // A key without '=' gets the value ""
        } else {
            key = pair.substring(0, parts);
            value = pair.substring(parts + 1);
        }

        // 4. Decode: '+' as space, then percent-decode
        // decodeURIComponent does not handle '+' as space, so we replace it first.
        const decodedKey = decodeURIComponent(key.replace(/\+/g, ' '));
        const decodedValue = decodeURIComponent(value.replace(/\+/g, ' '));

        // 5. Handle aggregation
        if (result.hasOwnProperty(decodedKey)) {
            // Key already exists
            if (Array.isArray(result[decodedKey])) {
                // Convert existing array to hold the new value
                result[decodedKey].push(decodedValue);
            } else {
                // Convert string to array, add new value
                result[decodedKey] = [result[decodedKey], decodedValue];
            }
        } else {
            // First time seeing the key
            result[decodedKey] = decodedValue;
        }
    }

    return result;
}
```
