function deepMerge(base, override) {
    const result = Array.isArray(base) || typeof base !== 'object' ? {} : { ...base };

    if (typeof override !== 'object' || override === null || Array.isArray(override)) {
        return Array.isArray(base) ? [...base] : { ...base };
    }

    for (const key in override) {
        if (Object.prototype.hasOwnProperty.call(override, key)) {
            const overrideValue = override[key];
            const baseValue = result[key];

            if (overrideValue === undefined) {
                continue; // Ignore undefined in override
            }

            if (baseValue !== undefined && 
                typeof baseValue === 'object' && baseValue !== null && !Array.isArray(baseValue) &&
                typeof overrideValue === 'object' && overrideValue !== null && !Array.isArray(overrideValue)) {

                // Both are plain objects, recurse
                result[key] = deepMerge(baseValue, overrideValue);
            } else {
                // Override replaces base (includes arrays, primitives, null, or if base wasn't an object)
                // Deep clone if the override value is an object/array to ensure immutability
                if (typeof overrideValue === 'object' && overrideValue !== null) {
                    result[key] = Array.isArray(overrideValue) ? [...overrideValue] : { ...overrideValue };
                } else {
                    result[key] = overrideValue;
                }
            }
        }
    }

    return result;
}
