from datetime import datetime
import re

def parse_date(text: str) -> datetime.date:
    """
    Parses a date string into a datetime.date object.

    Accept formats: ISO (YYYY-MM-DD), British numeric (DD/MM/YYYY), Short text (D Mon YYYY).
    Raises ValueError for unsupported formats or impossible dates.
    """
    # 1. Try ISO Format: YYYY-MM-DD
    text = text.strip()
    try:
        return datetime.strptime(text, '%Y-%m-%d').date()
    except ValueError:
        pass

    # 2. Try British Numeric Format: DD/MM/YYYY
    # Ensure it matches exactly DD/MM/YYYY to avoid partial matches
    if re.match(r"^\d{1,2}/\d{1,2}/\d{4}$", text):
        try:
            # %d/%m/%Y ensures day/month/year order
            return datetime.strptime(text, '%d/%m/%Y').date()
        except ValueError:
            pass

    # 3. Try Short Text Format: D Mon YYYY (e.g., "7 Mar 2025" or "07 Mar 2025")
    # Regex to capture: (D or DD) (Mon) (YYYY)
    text = text.strip()
    match = re.match(r"^\s*(\d{1,2})\s+([A-Z]{3})\s+(\d{4})\s*$", text)

    if match:
        try:
            day_str, month_abbr, year_str = match.groups()
            return datetime.strptime(f"{day_str} {month_abbr} {year_str}", '%d %b %Y').date()
        except ValueError:
            # Catches cases where the month abbreviation is invalid (e.g., "32 Feb 2025")
            pass

    raise ValueError(f"Date string '{text}' does not match any supported format or contains an impossible date.")

