    print(f"British (Mixed Space): {parse_date(' 07 / 03 / 2025 ')}") # Note: The regex for British doesn't allow spaces around /

    print(f"Short (No Leading Zero): {parse_date('7 Mar 2025')}")
    print(f"Short (Leading Zero): {parse_date('01 Jan 2024')}")

