 * Checks if a value is a plain object (and not null or an array).
 * @param {*} item - The value to check.
 * @returns {boolean}
 */
const isPlainObject = (item) => {
  return (
    item && typeof item === 'object' && !Array.isArray(item) && item.constructor === Object
  );
};

/**
 * Deeply merges two service configuration objects.
 * @param {Object} base - The base configuration object.
 * @param {Object} override - The override configuration object.
 * @returns {Object} A new merged object.
 */
const deepMerge = (base, override) => {
  const result = { ...base };

  if (!isPlainObject(base) || !isPlainObject(override)) {
    // If inputs are not plain objects, we return a deep copy of override if available, 
    // or a copy of base, depending on the structure.
    // Given the requirement to merge config objects, we expect them to be objects.
    return { ...override }; 
  }

  for (const key in override) {
    if (!Object.hasOwnProperty.call(override, key)) continue;

    const overrideValue = override[key];
    const baseValue = base[key];

    // 1. Ignore undefined in override
    if (overrideValue === undefined) {
      continue; // Keep base value
    }

    // 2. Check for recursive merge condition
    if (isPlainObject(baseValue) && isPlainObject(overrideValue)) {
      // Recursive merge: ensures new objects are created for nested structures
      result[key] = deepMerge(baseValue, overrideValue);
    } else {
      // 3. Otherwise, override replaces the base value (deep copy applied for objects/arrays)
      if (Array.isArray(overrideValue)) {
        // Deep copy arrays
        result[key] = overrideValue.map(item => 
          isPlainObject(item) ? deepMerge({}, item) : item
        );
      } else if (isPlainObject(overrideValue)) {
        // Deep copy plain objects
        result[key] = deepMerge({}, overrideValue);
      } else {
        // Primitive values, null, etc.
        result[key] = overrideValue;
      }
    }
  }

  return result;
};
```

