function parseQuery(qs) {
  if (!qs || typeof qs !== 'string') return {};

  const params = {};
  // Remove leading '?' if present, then split by '&'
  const parts = (qs.startsWith('?') ? qs.slice(1) : qs).split('&');

  for (let i = 0; i < parts.length; i++) {
    const part = parts[i].trim();

    // Skip empty pairs (e.g., from && or trailing &)
    if (!part) continue;

    const eqIndex = part.indexOf('=');

    // If no '=', key is the whole string, value is empty string
    const key = eqIndex === -1 ? part : part.slice(0, eqIndex);
    const value = eqIndex === -1 ? '' : part.slice(eqIndex + 1);

    // Decode: replace '+' with ' ', then percent-decode
    let decodedKey = decodeURIComponent(key.replace(/+/g, ' '));
    let decodedValue = decodeURIComponent(value.replace(/+/g, ' '));

    if (decodedKey === '') continue; // Skip empty keys

    if (!params.hasOwnProperty(decodedKey)) {
      params[decodedKey] = decodedValue;
    } else {
      if (Array.isArray(params[decodedKey])) {
        params[decodedKey].push(decodedValue);
      } else {
        params[decodedKey] = [params[decodedKey], decodedValue];
      }
    }
  }

  return params;
}
```

