                num = num * 10 + (s[i] - '0');
                ++i;
            }

            if (multiplier == 3600) { // Hours
                if (has_hours) return -1; // Repeated unit
                has_hours = true;
                total_seconds += num * multiplier;
                multiplier = 60;
            } else if (multiplier == 60) { // Minutes
                if (has_minutes) return -1; // Repeated unit
                has_minutes = true;
                total_seconds += num * multiplier;
                multiplier = 1;
            } else if (multiplier == 1) { // Seconds
                if (has_seconds) return -1; // Repeated unit
                has_seconds = true;
                total_seconds += num;
                multiplier = 0;
            } else {
                // Reached end of number without expected unit or wrong state
                return -1;
            }

        } else if (c == 'h') {
            if (!has_hours) {
                has_hours = true;
                multiplier = 3600;
            } else {
                return -1; // Repeated unit
            }
        } else if (c == 'm') {
            if (!has_minutes) {
                has_minutes = true;
                multiplier = 60;
            } else {
                return -1; // Repeated unit
            }
        } else if (c == 's') {
            if (!has_seconds) {
                has_seconds = true;
                multiplier = 1;
            } else {
                return -1; // Repeated unit
            }
        } else {
            // Invalid character (space, sign, unknown char)
            return -1;
        }

        ++i;
    }

    // Final validation: must have consumed the whole string and end at correct state
    if (multiplier != 0 || !has_hours && !has_minutes && !has_seconds) {
        return -1;
