from datetime import datetime, date
import re

def parse_date(text: str) -> date:
    # Normalize whitespace and strip
    text = " ".join(text.split())

    # Try ISO format (YYYY-MM-DD)
    try:
        return datetime.strptime(text, "%Y-%m-%d").date()
    except ValueError:
        pass

    # Try British numeric format (DD/MM/YYYY)
    try:
        return datetime.strptime(text, "%d/%m/%Y").date()
    except ValueError:
        pass

    # Try short text format (D Mon YYYY or DD Mon YYYY)
    # Month names: Jan Feb Mar Apr May Jun Jul Aug Sep Oct Nov Dec
    months = ["Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"]

    # Regex to match: optional day, month name, year
    pattern = r"(\d+)?\s+(\w+)\s+(\d{4})"
    match = re.match(pattern, text)

    if not match:
        raise ValueError(f"Unrecognized date format: {text}")

    day_str, month_name, year_str = match.groups()
    day = int(day_str) if day_str else 1
    month_idx = months.index(month_name) + 1

    try:
        return datetime.strptime(f"{year_str}-{month_idx:02d}-{day:02d}", "%Y-%m-%d").date()
    except ValueError:
        raise ValueError(f"Invalid date: {text}")
