  const result = {};

  // Remove leading '?' if present, then split by '&'
  const parts = (qs || "").replace(/^\?/, "").split('&');

  for (const part of parts) {
    // Skip empty pairs (from && or trailing &)
    if (!part.trim()) continue;

    // Split on the FIRST '=' only. If no '=', key is the whole part, value is empty.
    const eqIndex = part.indexOf('=');
    const key = eqIndex === -1 ? part : part.substring(0, eqIndex);
    const value = eqIndex === -1 ? "" : part.substring(eqIndex + 1);

    // Decode: replace '+' with space, then percent-decode
    let decodedKey = decodeURIComponent(key.replace(/\+/g, ' '));
    let decodedValue = decodeURIComponent(value.replace(/\+/g, ' '));

    // Handle case where decoding fails (e.g., invalid hex), though standard input is expected.
    // If the string contains non-ASCII characters not properly encoded, they remain as-is or throw.
    // For robustness in simple scenarios, we assume valid input format.

    if (decodedKey === "") continue; // Skip keys that decode to empty string

    if (!result[decodedKey]) {
      result[decodedKey] = decodedValue;
    } else {
      // Ensure it's an array for multiple occurrences
      const existing = result[decodedKey];
      if (typeof existing === 'string') {
        result[decodedKey] = [existing, decodedValue];
      } else {
        result[decodedKey].push(decodedValue);
      }
    }
  }

  return result;
