long long parse_duration(const std::string& s) {
    if (s.empty()) return -1;

    long long total_seconds = 0;
    size_t i = 0;

    // Helper to check if character is a digit
    auto is_digit = [](char c) { return std::isdigit(c); };

    while (i < s.size()) {
        // Check for space or sign at the start of a part -> invalid
        if (!is_digit(s[i]) && s[i] != 'h' && s[i] != 'm' && s[i] != 's') {
            return -1;
        }

        // If we hit a unit, the previous part must be complete (digits only)
        if (s[i] == 'h' || s[i] == 'm' || s[i] == 's') {
            // Previous number must exist and not be empty
            if (i > 0 && !is_digit(s[i-1])) {
                return -1;
            }
            break; // Unit processed, move to next part
        }

        // Parse digits
        long long num = 0;
        while (i < s.size() && is_digit(s[i])) {
            if (num > 9223372036854775LL) return -1; // Prevent overflow before adding
            num = num * 10 + (s[i] - '0');
            i++;
        }

        // If we parsed digits but didn't hit a unit, invalid
        if (!is_digit(s[i]) && s[i] != 'h' && s[i] != 'm' && s[i] != 's') {
            return -1;
        }
    }

    // Parse remaining units (if any)
    while (i < s.size()) {
        char unit = s[i];
        if (unit == 'h' || unit == 'm' || unit == 's') {
            // Check for digits before this unit
            if (i > 0 && !is_digit(s[i-1])) {
                return -1;
            }

            long long multiplier = 0;
            switch (unit) {
                case 'h': multiplier = 3600; break;
                case 'm': multiplier = 60; break;
                case 's': multiplier = 1; break;
            }

            total_seconds += multiplier;
            i++; // Consume unit
        } else {
            return -1;
        }
    }

    return total_seconds;
}
