def normalise_order(raw: dict) -> dict:
    # Validate required keys exist
    if "sku" not in raw or "qty" not in raw or "unit_price_pence" not in raw:
        raise ValueError("Missing required key: sku, qty, or unit_price_pence")

    sku = raw["sku"]
    qty_str = str(raw["qty"])
    price_str = str(raw["unit_price_pence"])

    # Validate and process SKU
    if not isinstance(sku, str):
        raise ValueError("sku must be a string")
    sku = sku.strip().upper()
    if not sku:
        raise ValueError("sku cannot be empty after stripping")

    # Validate and process qty
    try:
        qty = int(qty_str)
    except ValueError:
        raise ValueError(f"qty must be an integer, got '{qty_str}'")

    if not (1 <= qty <= 99):
        raise ValueError(f"qty must be between 1 and 99 inclusive, got {qty}")

    # Validate and process unit_price_pence
    try:
        price = int(price_str)
    except ValueError:
        raise ValueError(f"unit_price_pence must be an integer, got '{price_str}'")

    if price < 0:
        raise ValueError("unit_price_pence must be 0 or more")

    # Validate currency
    currency = raw.get("currency")
    if currency is not None:
        if not isinstance(currency, str):
            raise ValueError("currency must be a string when present")
        currency = currency.strip().upper()
        if currency not in ("GBP", "EUR", "USD"):
            raise ValueError(f"currency must be GBP, EUR, or USD, got '{currency}'")
    else:
        # Missing currency defaults to None (as per spec: 'None' or blank)
        currency = None

    total_pence = qty * price

    return {
        "sku": sku,
        "qty": qty,
        "unit_price_pence": price,
        "currency": currency,
        "total_pence": total_pence
    }
