import datetime
import re

def parse_date(text: str) -> datetime.date:
    """
    Parses a date string in one of three formats for an invoicing service.

    Formats supported:
    - ISO: YYYY-MM-DD (e.g., 2025-03-07)
    - British numeric: DD/MM/YYYY (e.g., 07/03/2025)
    - Short text: D Mon YYYY (e.g., 7 Mar 2025)

    Raises:
        ValueError: If the input does not match any supported format or is an invalid date.
    """
    text = text.strip()

    # 1. ISO Format: YYYY-MM-DD
    try:
        if re.fullmatch(r"\d{4}-\d{2}-\d{2}", text):
            return datetime.datetime.strptime(text, "%Y-%m-%d").date()
    except ValueError:
        pass

    # 2. British Numeric Format: DD/MM/YYYY
    try:
        if re.fullmatch(r"\d{1,2}/\d{1,2}/\d{4}", text):
            # We use strptime with format %d/%m/%Y. Python's parsing handles day/month validation,
            # and raising an error if the date is impossible (e.g., 31/02/2025).
            return datetime.datetime.strptime(text, "%d/%m/%Y").date()
    except ValueError:
        pass

    # 3. Short Text Format: D Mon YYYY
    # We use strptime with format %d %b %Y. %b handles abbreviated English month names.
    # The day can be 1 or 2 digits without a leading zero.
    try:
        if re.fullmatch(r"\d{1,2}\s[A-Za-z]{3}\s\d{4}", text):
            return datetime.datetime.strptime(text, "%d %b %Y").date()
    except ValueError:
        pass

    raise ValueError(f"Date string '{text}' does not match supported formats or is an invalid date.")

