    for (const pair of pairs) {
        // 3. Skip empty pairs
        if (!pair) {
            continue;
        }

        // 4. Split by the FIRST '='
        const [keyPart, valuePart] = pair.split('=');

        // Determine the raw key and value
        let rawKey = keyPart;
        let rawValue = valuePart === undefined ? "" : valuePart;

        // 5. Decode '+' to space, then percent-decode both key and value
        const decode = (str) => {
            // Replace '+' with space (only for the purpose of URI decoding)
            const plusReplaced = str.replace(/\+/g, ' ');
            try {
                return decodeURIComponent(plusReplaced);
            } catch (e) {
                return str; // Return original if decoding fails
            }
        };

        const key = decode(rawKey);
        const value = decode(rawValue);

        if (key === "") continue; // Skip if key itself is empty after decoding

        // 6. Handle assignment logic (String vs Array)
        if (result.hasOwnProperty(key)) {
            // Key already exists
            if (Array.isArray(result[key])) {
                result[key].push(value);
            } else {
                // Convert existing string value to an array and add the new value
                result[key] = [result[key], value];
            }
        } else {
            // New key
            result[key] = value;
        }
    }

    return result;
}
