            multiplier = 3600;
            current_expected_order = 1;
            valid_unit = true;
        } else if (unit == 'm') {
            if (current_expected_order != 1) return -1; // Wrong order or repeat
            multiplier = 60;
            current_expected_order = 2;
            valid_unit = true;
        } else if (unit == 's') {
            if (current_expected_order != 2) return -1; // Wrong order or repeat
            multiplier = 1;
            current_expected_order = 3;
            valid_unit = true;
        } else {
            return -1; // Unknown unit
        }

        total_seconds += value * multiplier;

        // Advance past the number and unit
        remaining = remaining.substr(end_of_number + 1);
    }

    // Check if we processed exactly what was expected (i.e., reached the end of string)
    if (!remaining.empty()) {
        return -1; // Trailing invalid characters/units
    }

    return total_seconds;
}
```

This function uses an iterative, state-based parsing approach. It processes the string by finding a sequence of digits followed immediately by a unit. It uses `current_expected_order` to enforce the strict ordering (h $\rightarrow$ m $\rightarrow$ s) and ensures each unit is used at most once. If any part of the input violates the rules (missing number/unit, wrong order, unknown unit, remaining characters), it returns -1.

**Note on Implementation Choice:** While standard library functions like `std::from_chars` could be used for performance, the complex state-dependent validation (order, repetition) is clearer using string searching and manual advancement here, adhering strictly to the error conditions provided.

