    if "sku" not in raw:
        raise ValueError("Missing 'sku' field in raw order.")
    if "qty" not in raw:
        raise ValueError("Missing 'qty' field in raw order.")
    if "unit_price_pence" not in raw:
        raise ValueError("Missing 'unit_price_pence' field in raw order.")

    # 1. SKU Normalisation
    sku = str(raw["sku"]).strip().upper()
    if not sku:
        raise ValueError("SKU must not be empty after stripping.")

    # 2. Quantity Normalisation and Validation
    try:
        # Attempt to cast to int, handling string representations like " 3 "
        qty = int(raw["qty"])
    except (TypeError, ValueError):
        raise ValueError("'qty' must be a valid integer.")

    if not (1 <= qty <= 99):
        raise ValueError("'qty' must be between 1 and 99 inclusive.")

    # 3. Unit Price Normalisation and Validation
    try:
        unit_price_pence = int(raw["unit_price_pence"])
    except (TypeError, ValueError):
        raise ValueError("'unit_price_pence' must be a valid integer.")

    if unit_price_pence < 0:
        raise ValueError("'unit_price_pence' must be zero or more.")

    # 4. Currency Normalisation and Validation
    currency = raw.get("currency")

    if currency is None:
        currency_str = ""
    else:
        currency_str = str(currency).strip().upper()

    allowed_currencies = {"GBP", "EUR", "USD"}

    if not currency_str and currency is not None:
        # If input existed but was blank after stripping, treat as empty string for logic check
        pass 
    elif currency_str not in allowed_currencies:
        raise ValueError(f"Invalid currency '{currency}'. Must be one of {allowed_currencies}")

    if not currency_str:
        currency = "GBP" if currency is None or not raw["currency"].strip() else None
    else:
        currency = currency_str

    # 5. Total Calculation
    total_pence = qty * unit_price_pence

    return {
        "sku": sku,
        "qty": qty,
        "unit_price_pence": unit_price_pence,
        "currency": currency,
        "total_pence": total_pence
    }

