function parseQuery(qs) {
  const result = {};

  if (!qs) {
    return result;
  }

  const searchString = qs.startsWith('?') ? qs.substring(1) : qs;

  if (!searchString) {
    return result;
  }

  const pairs = searchString.split('&');

  for (const pair of pairs) {
    if (!pair) {
      continue; // Skip empty pairs
    }

    let [key, value] = pair.split('=');

    // Decode key
    let decodedKey;
    if (key) {
      decodedKey = decodeURIComponent(key.replace(/\+/g, ' '));
    } else {
      continue; // Should not happen if pair is not empty, but safety check
    }

    // Handle value: if no '=', value is an empty string, otherwise decode it
    if (value === undefined) {
      value = "";
    } else {
      value = decodeURIComponent(value.replace(/\+/g, ' '));
    }

    if (result.hasOwnProperty(decodedKey)) {
      // Key already exists, convert to array if it's currently a string
      if (Array.isArray(result[decodedKey])) {
        result[decodedKey].push(value);
      } else {
        // Convert existing string to an array containing the original string and the new value
        result[decodedKey] = [result[decodedKey], value];
      }
    } else {
      // First occurrence
      result[decodedKey] = value;
    }
  }

  return result;
}
```

This function handles the required logic manually: it strips the leading `?`, splits pairs by `&`, splits key/value by the first `=`, decodes `+` to spaces and performs `decodeURIComponent`, and manages single/multiple occurrences of keys by storing them as a string or an array.

