/**
 * Checks if a value is a plain object (and not null or an array).
 * @param {*} item
 * @returns {boolean}
 */
const isPlainObject = (item) => {
  return (item && typeof item === 'object' && !Array.isArray(item) && item.constructor === Object);
};

/**
 * Recursively merges properties from an override object into a base object,
 * ensuring immutability.
 *
 * @param {Object} base The base configuration object.
 * @param {Object} override The configuration object providing overrides.
 * @returns {Object} A new merged object.
 */
const deepMerge = (base, override) => {
  // Create a shallow copy of the base to start the merge, ensuring base is never modified
  const result = { ...base };

  if (typeof override !== 'object' || override === null) {
    // If override is not an object, there's nothing to merge properties from.
    return { ...base };
  }

  Object.keys(override).forEach(key => {
    const baseValue = base[key];
    const overrideValue = override[key];

    // 1. Handle undefined in override: ignore it (keep base value)
    if (overrideValue === undefined) {
      return;
    }

    // 2. Handle recursive merge condition: both are plain objects
    if (isPlainObject(baseValue) && isPlainObject(overrideValue)) {
      // Recurse: the result of the recursive call becomes the new value for this key
      result[key] = deepMerge(baseValue, overrideValue);
      return;
    }

    // 3. Handle replacement: (overrideValue is null, array, or baseValue isn't a mergeable object)
    // Since we are creating a new object structure, we must deep clone the replacement
    // if it is an object or array, to prevent shared references.
    const replacement = Array.isArray(overrideValue) ? 
        // Simple deep copy for arrays (shallow copy of elements is usually sufficient 
        // unless elements themselves are complex objects needing deep cloning)
        overrideValue.map(item => typeof item === 'object' && item !== null ? deepMerge({}, item) : item) :
        // Deep copy for objects
        isPlainObject(overrideValue) ? deepMerge({}, overrideValue) : overrideValue;

    result[key] = replacement;
  });

  return result;
};
```

This `deepMerge` function achieves immutability by using spread syntax (`{...}`) for shallow copies and recursion for nested objects. It strictly adheres to the requirements:

1.  **Immutability:** New objects and arrays are created for the result and for any complex value taken from `override` to prevent shared references.
2.  **Recursive Merge:** If both the base and override values for a key are plain objects, `deepMerge` is called recursively.
3.  **Replacement Logic:** Otherwise (if they are primitives, arrays, or one is null/primitive), the `override` value replaces the `base` value.
4.  **Handling `undefined`:** Keys with `override[key] === undefined` are skipped, retaining `base[key]`.
5.  **Keys only in `base`:** Because we start with `result = { ...base }`, keys only present in `base` are naturally carried over.

