import datetime
from typing import Union

def parse_date(text: str) -> datetime.date:
    """
    Parses a date string from one of three specific formats:
    - ISO: YYYY-MM-DD
    - British numeric: DD/MM/YYYY
    - Short text: D MMM YYYY (e.g., 7 Mar 2025)

    Args:
        text: The date string to parse.

    Returns:
        A datetime.date object.

    Raises:
        ValueError: If the format is incorrect or the date is invalid.
    """
    text = text.strip()

    # 1. ISO format: YYYY-MM-DD
    if len(text) == 10 and text[4] == '-' and text[7] == '-':
        try:
            return datetime.datetime.strptime(text, '%Y-%m-%d').date()
        except ValueError:
            pass

    # 2. British numeric format: DD/MM/YYYY
    if text.count('/') == 2:
        try:
            return datetime.datetime.strptime(text, '%d/%m/%Y').date()
        except ValueError:
            pass

    # 3. Short text format: D MMM YYYY
    # We need to handle both '7 Mar 2025' and '07 Mar 2025'
    # We check if it has at least 1 line and contains a 3-letter month
    parts = text.split()
    if len(parts) >= 3:
        # Try parsing as Day Month Year
        try:
            # Standard strptime handles single digits vs leading zeros for %d
            return datetime.datetime.strptime(" ".join(parts), "%d %b %Y").date()
        except ValueError:
            pass

    raise ValueError(f"Invalid date format or impossible date: {text}")
