    const result = {};

    if (!qs) {
        return result;
    }

    // Remove leading '?' if it exists
    let query = qs.startsWith('?') ? qs.substring(1) : qs;

    if (!query) {
        return result;
    }

    const pairs = query.split('&);

    for (const pair of pairs) {
        if (pair === '') {
            continue;
        }

        let [keyPart, valuePart] = pair.split('=');

        // Handle key without '='
        if (valuePart === undefined) {
            valuePart = "";
        }

        // Decode + to space, then percent-decode
        const decode = (str) => {
            if (!str) return "";
            return decodeURIComponent(str.replace(/\+/g, ' '));
        };

        const key = decode(keyPart);
        const value = decode(valuePart);

        if (key === "") continue;

        if (Object.prototype.hasOwnProperty.call(result, key)) {
            const existing = result[key];
            if (Array.isArray(existing)) {
                existing.push(value);
            } else {
                // Convert to array if it's the second occurrence
                result[key] = [existing, value];
            }
        } else {
            result[key] = value;
        }
    }

    // Final conversion: if a key has only one element in the array, return the string
    for (const key in result) {
        if (Array.isArray(result[key]) && result[key].length === 1) {
            result[key] = result[key][0];
        }
    }

    return result;
}
```

