/**
 * Checks if a value is a plain object (and not null or an array).
 * @param {*} item - The value to check.
 * @returns {boolean} True if the value is a plain object, false otherwise.
 */
function isPlainObject(item) {
    return (item && typeof item === 'object' && !Array.isArray(item));
}

/**
 * Deep merges two configuration objects.
 * Returns a new object, ensuring no shared references with the inputs.
 * 
 * Rules:
 * 1. Returns a new object. Does not mutate base or override.
 * 2. If both values are plain objects, merges recursively. Otherwise, override replaces base.
 * 3. `undefined` in override is ignored (base value kept). `null` replaces.
 * 4. Keys only in base are kept.
 * 
 * @param {Object} base - The base configuration object.
 * @param {Object} override - The configuration object containing overrides.
 * @returns {Object} The deeply merged configuration object.
 */
function deepMerge(base, override) {
    if (!isPlainObject(base) || !isPlainObject(override)) {
        // If inputs are not plain objects, return a shallow copy of the override if it exists, otherwise copy base.
        return isPlainObject(override) ? { ...override } : (base ? { ...base } : {});
    }

    const result = { ...base };

    Object.keys(override).forEach(key => {
        const overrideValue = override[key];
        const baseValue = base[key];

        // Rule 3: Ignore undefined in override
        if (overrideValue === undefined) {
            return;
        }

        // Rule 2: Recursive merge if both are plain objects
        if (isPlainObject(overrideValue) && isPlainObject(baseValue)) {
            result[key] = deepMerge(baseValue, overrideValue);
        } else {
            // In all other cases (including arrays, null, primitives, or if one is not a plain object), 
            // the override value replaces the base value, ensuring a new reference for safety.

            // Special handling for null: null replaces the base value.
            // If overrideValue is not null, we ensure it's deep-cloned if it's an object/array 
            // to maintain immutability guarantees for complex types.
            if (overrideValue !== null && typeof overrideValue === 'object') {
                // Deep clone arrays and objects from override to prevent shared references
                result[key] = Array.isArray(overrideValue) ? [...overrideValue] : { ...overrideValue };
            } else {
                // Primitives or null
                result[key] = overrideValue;
            }
        }
    });

    // Rule 4: Keys only in base are already included via `const result = { ...base };`

    return result;
}
```

The provided `deepMerge` function creates a new object by merging `base` and `override`. It handles deep merging for nested plain objects recursively, ensuring that when values differ or are primitives/arrays, the `override` value takes precedence. Crucially, it avoids mutating the input objects by using spread syntax (`{...}`) and explicitly cloning new objects/arrays assigned during the merge process. `undefined` values in `override` are skipped, while `null` replaces the base value.

