            }
            std::string number_str = s.substr(start, i - start);

            if (i == s.length()) {
                // Number without a unit
                return -1;
            }

            char unit_char = s[i];
            if (unit_char == 'h' || unit_char == 'm' || unit_char == 's') {
                long long value = std::stoll(number_str);
                long long multiplier;

                switch (unit_char) {
                    case 'h':
                        if (unit_order != 0) return -1; // Repeated unit or wrong order
                        multiplier = 3600;
                        unit_order = 1;
