                                                    // Re-eval: The rule is "Units must appear in the order h, m, s".
                                                    // If we encounter 'm' and unit_order is 0, it means 'h' was skipped.
                        multiplier = 60;
                        unit_order = 2;
                        break;
                    case 's':
                        if (unit_order != 2) return -1; // Must follow 'm' or be first if no 'h'/'m' were allowed.
                        multiplier = 1;
                        unit_order = 3;
                        break;
                    default:
                        // Should not happen due to the 'if' check above, but for safety
                        return -1; 
                }

                total_seconds += value * multiplier;
                i++; // Move past the unit character
            } else {
                // Unknown unit or invalid character where unit should be
                return -1;
            }
        } else if (std::isalpha(s[i])) {
            // Unit encountered without a preceding number
            return -1;
        } else if (s[i] == ' ') {
            // Spaces are forbidden
            return -1;
        } else {
            // Other invalid characters (e.g., signs like -, ., etc.)
            return -1;
        }
    }

    // Final check for correct ordering/completeness based on rules:
    // The requirements state: "Units must appear in the order h, m, s, each at most once"
    // This implies that if a unit is present, it must be the next one in the sequence (H -> M -> S).
    // The unit_order logic above enforces the *sequence* constraint strictly based on the first unit found.
    // If 'm' is found first (unit_order=0 when processing 'm'), it returns -1, correctly failing the order check.

