    Accept formats:
    - ISO: 2025-03-07
    - British numeric: 07/03/2025 (day/month/year)
    - Short text: 7 Mar 2025 (day with or without leading zero)

    Raises ValueError for incorrect format or impossible dates.
    """
    text = text.strip()

    # 1. ISO format: YYYY-MM-DD
    try:
        return datetime.datetime.strptime(text, '%Y-%m-%d').date()
    except ValueError:
        pass

    # 2. British numeric format: DD/MM/YYYY
    try:
        return datetime.datetime.strptime(text, '%d/%m/%Y').date()
    except ValueError:
        pass

    # 3. Short text format: D MMM YYYY (e.g., 7 Mar 2025)
    # We check for the existence of spaces that suggest this format.
    parts = text.split()
    if len(parts) >= 3 and len(parts[0]) < 3 and len(parts[1]) <= 3:
        try:
            # Try D MMM YYYY (e.g., 7 Mar 2025)
            return datetime.datetime.strptime(text, '%d %b %Y').date()
        except ValueError:
            try:
                # Try DD MMM YYYY (e.g., 07 Mar 2025) - though %d handles both 7 and 07
                return datetime.datetime.strptime(text, '%d %b %Y').date()
            except ValueError:
                pass

    # If none of the above formats matched or parsing failed
    raise ValueError(f"Invalid date format: {text}")

