def normalise_order(raw: dict) -> dict:
    """
    Normalises a raw order dictionary received from a web form.
    """
    # 1. SKU validation and formatting
    if "sku" not in raw:
        raise ValueError("Missing required field: sku")
    sku = raw["sku"].strip().upper()
    if not sku:
        raise ValueError("SKU cannot be empty after stripping")

    # 2. Quantity validation and formatting
    if "qty" not in raw:
        raise ValueError("Missing required field: qty")
    try:
        qty = int(raw["qty"])
    except (ValueError, TypeError):
        raise ValueError(f"Invalid qty format: {raw['qty']}")
    if not (1 <= qty <= 99):
        raise ValueError(f"Quantity must be between 1 and 99, got {qty}")

    # 3. Unit Price validation and formatting
    if "unit_price_pence" not in raw:
        raise ValueError("Missing required field: unit_price_pence")
    try:
        unit_price_pence = int(raw["unit_price_pence"])
    except (ValueError, TypeError):
        raise ValueError(f"Invalid unit_price_pence format: {raw['unit_price_pence']}")
    if unit_price_pence < 0:
        raise ValueError(f"Unit price in pence must be 0 or greater, got {unit_price_pence}")

    # 4. Currency validation and formatting
    currency_raw = raw.get("currency")

    # Check for None, blank string, or not a string
    if not isinstance(currency_raw, str) or not currency_raw.strip():
        currency = "GBP"
    else:
        currency = currency_raw.strip().upper()
        allowed_currencies = {"GBP", "EUR", "USD"}
        if currency not in allowed_currencies:
            # If it's specified but invalid, we should raise an error 
            # based on the implied constraint that only these are allowed.
            # Since the requirement says "Only GBP, EUR and USD are allowed" 
            # we treat anything else as invalid input, raising ValueError.
            raise ValueError(f"Invalid currency '{currency}'. Allowed currencies are GBP, EUR, USD.")

    # 5. Calculate total
    total_pence = qty * unit_price_pence

    # Return the new, normalised dictionary
    return {
        "sku": sku,
        "qty": qty,
        "unit_price_pence": unit_price_pence,
        "currency": currency,
        "total_pence": total_pence
    }
