/**
 * Parses a query string into a plain JavaScript object.
 *
 * @param {string} qs The query string to parse, optionally starting with '?'.
 * @returns {Object.<string, string|string[]>} The parsed query object.
 */
function parseQuery(qs) {
    const result = {};

    if (typeof qs !== 'string') {
        return result;
    }

    // Remove leading '?' if present
    const cleanQs = qs.startsWith('?') ? qs.substring(1) : qs;

    if (cleanQs.length === 0) {
        return result;
    }

    const pairs = cleanQs.split('&');

    for (const pair of pairs) {
        if (!pair) continue; // Skip empty pairs

        let key, value;
        const separatorIndex = pair.indexOf('=');

        if (separatorIndex === -1) {
            key = pair;
            value = "";
        } else {
            key = pair.substring(0, separatorIndex);
            value = pair.substring(separatorIndex + 1);
        }

        // Decode: '+' as space, then percent-decode
        const decodedKey = decodeURIComponent(key.replace(/\+/g, ' '));
        const decodedValue = decodeURIComponent(value.replace(/\+/g, ' '));

        if (Object.prototype.hasOwnProperty.call(result, decodedKey)) {
            // Key already exists
            if (Array.isArray(result[decodedKey])) {
                result[decodedKey].push(decodedValue);
            } else {
                // Convert existing string to array and push new value
                result[decodedKey] = [result[decodedKey], decodedValue];
            }
        } else {
            // New key
            result[decodedKey] = decodedValue;
        }
    }

    return result;
}
```

