function deepMerge(base, override) {
  const result = Array.isArray(base) ? [...base] : (typeof base === 'object' && base !== null ? { ...base } : {});

  if (override === undefined) {
    return result;
  }

  for (const key in override) {
    if (Object.prototype.hasOwnProperty.call(override, key)) {
      const overrideValue = override[key];
      const baseValue = base ? base[key] : undefined;

      if (overrideValue === undefined) {
        continue; // Ignore undefined in override
      }

      if (baseValue && overrideValue &&
          typeof baseValue === 'object' && baseValue !== null && !Array.isArray(baseValue) &&
          typeof overrideValue === 'object' && overrideValue !== null && !Array.isArray(overrideValue)) {
        // Recursive merge for plain objects
        result[key] = deepMerge(baseValue, overrideValue);
      } else {
        // Replacement (for primitives, arrays, null, or if base was not an object)
        // We must deep clone the override value to ensure immutability of inputs
        result[key] = Array.isArray(overrideValue) ? [...overrideValue] :
                      (typeof overrideValue === 'object' && overrideValue !== null ? deepClone(overrideValue) : overrideValue);
      }
    }
  }
  return result;
}

/**
 * Helper function to perform a deep clone of values that need to be copied entirely (like arrays or objects being replaced).
 * This ensures the result structure is independent of the input structure.
 * @param {*} obj The object/array to clone.
 * @returns {*} The deep clone.
 */
function deepClone(obj) {
  if (typeof obj !== 'object' || obj === null) {
    return obj;
  }
  if (Array.isArray(obj)) {
    return obj.map(item => deepClone(item));
  }
  const clonedObj = {};
  for (const key in obj) {
    if (Object.prototype.hasOwnProperty.call(obj, key)) {
      clonedObj[key] = deepClone(obj[key]);
    }
  }
  return clonedObj;
}
