        i++;

        // 3. Validate unit
        if (unit_char != 'h' && unit_char != 'm' && unit_char != 's') {
            // Unknown unit or invalid character
            return -1;
        }

        // 4. Check order and repetition
        if (encountered_units.count(unit_char)) {
            // Repeated unit
            return -1;
