        'jul': 7, 'aug': 8, 'sep': 9, 'oct': 10, 'nov': 11, 'dec': 12
    }

    # Pattern: optional digit(s) month_abbrev year
    pattern = r'^(\d{1,2})\s+(\w{3})\s+(\d{4})$'
    match = re.match(pattern, text, re.IGNORECASE)

    if not match:
        raise ValueError(f"Date format not recognized in '{text}'")

    day_str, month_str, year_str = match.groups()
    day = int(day_str)
    month_name_lower = month_str.lower()
    year = int(year_str)

    if month_name_lower not in months:
        raise ValueError(f"Invalid month name '{month_str}'")

    month = months[month_name_lower]

