function deepMerge(base, override) {
  if (typeof base !== 'object' || base === null || typeof override !== 'object' || override === null) {
    return override;
  }

  const result = {};

  // Copy all keys from base first
  for (const key in base) {
    if (base.hasOwnProperty(key)) {
      result[key] = base[key];
    }
  }

  // Process keys from override
  for (const key in override) {
    if (override.hasOwnProperty(key)) {
      const baseVal = result[key];
      const overrideVal = override[key];

      // Undefined is ignored, Null replaces, others merge or replace based on type
      if (overrideVal === undefined) {
        continue; 
      } else if (baseVal !== undefined && typeof baseVal === 'object' && 
                 typeof overrideVal === 'object' && 
                 !Array.isArray(baseVal) && !Array.isArray(overrideVal)) {
        // Recursive merge for plain objects
        result[key] = deepMerge(baseVal, overrideVal);
      } else {
        // Replace value (includes arrays and primitives)
        result[key] = overrideVal;
      }
    }
  }

  return result;
}
