def parse_date(text: str) -> datetime.date:
    text = text.strip()

    # ISO format: 2025-03-07
    try:
        return datetime.strptime(text, "%Y-%m-%d").date()
    except ValueError:
        pass

    # British numeric: 07/03/2025 (DD/MM/YYYY)
    try:
        return datetime.strptime(text, "%d/%m/%Y").date()
    except ValueError:
        pass

    # Short text: 7 Mar 2025 or 07 Mar 2025
    # Match optional day with padding, three-letter month, year
    pattern = r"(\d{1,2})\s+(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\s+(\d{4})"
    match = re.match(pattern, text, re.IGNORECASE)

    if match:
        day_str, month_str, year_str = match.groups()
        day = int(day_str)
        month_names = {
            "jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6,
            "jul": 7, "aug": 8, "sep": 9, "oct": 10, "nov": 11, "dec": 12
        }
        month = month_names[month_str.lower()]
        year = int(year_str)

        try:
            return datetime(year, month, day).date()
        except ValueError:
            pass

    raise ValueError(f"Unable to parse date from: {text}")
