    pattern = r"^(\d+)?\s+(\w{3})\s+(\d{4})$"
    match = re.match(pattern, text, re.IGNORECASE)

    if not match:
        raise ValueError(f"Date format not recognized")

    day_str, month_str, year_str = match.groups()

    # Validate and parse components
    try:
        # Parse day (handle optional leading zero)
        if day_str:
            day = int(day_str)
        else:
            day = 1

        # Parse month name
        months = {
            "jan": 1, "feb": 2, "mar": 3, "apr": 4, "may": 5, "jun": 6,
            "jul": 7, "aug": 8, "sep": 9, "oct": 10, "nov": 11, "dec": 12
        }
        month = months[month_str.lower()]

        year = int(year_str)

        # Construct datetime to validate date logic (e.g., Feb 31)
