    if not sku:
        raise ValueError("SKU must not be empty after stripping")

    # Process Qty
    try:
        qty_str = str(raw["qty"]).strip()
        if not qty_str:
            raise ValueError("Qty must not be empty after stripping")
        qty = int(qty_str)
        if not (1 <= qty <= 99):
            raise ValueError("Qty must be between 1 and 99 inclusive")
    except (ValueError, TypeError):
        raise ValueError("Qty must be a valid integer between 1 and 99")

    # Process Unit Price
    try:
        price_val = raw["unit_price_pence"]
        if not isinstance(price_val, (int, float)):
            raise ValueError("Unit price pence must be numeric")
        unit_price_pence = int(round(float(price_val)))
        if unit_price_pence < 0:
            raise ValueError("Unit price pence must be 0 or more")
    except (ValueError, TypeError):
        raise ValueError("Unit price pence must be a valid non-negative number")

    # Process Currency
    currency = raw.get("currency", "")
    if currency is not None:
        currency = str(currency).strip().upper()

    allowed_currencies = {"GBP", "EUR", "USD"}
    if currency in ("", None):
        final_currency = "GBP"
    elif currency not in allowed_currencies:
        raise ValueError(f"Currency must be GBP, EUR, or USD, got '{currency}'")
    else:
        final_currency = currency

    # Calculate Total
    total_pence = qty * unit_price_pence

    return {
        "sku": sku,
        "qty": qty,
        "unit_price_pence": unit_price_pence,
        "currency": final_currency,
        "total_pence": total_pence
    }
