function parseQuery(qs) {
  const result = {};

  // Normalize input: remove leading '?', split by '&', filter empty strings
  const pairs = qs.replace(/^\?/, '').split('&').filter(pair => pair.length > 0);

  for (const pair of pairs) {
    // Find the first '=' to separate key and value
    const eqIndex = pair.indexOf('=');

    if (eqIndex === -1) {
      // Key without '=': key exists, value is empty string
      const key = decodeURIComponent(pair);
      if (key.length > 0) { // Skip if the key itself is effectively empty after decoding (though logic suggests valid keys usually have length)
        if (!result[key]) result[key] = [];
        result[key].push('');
      }
    } else {
      const key = decodeURIComponent(pair.substring(0, eqIndex));
      const value = decodeURIComponent(pair.substring(eqIndex + 1));

      // Skip empty pairs (e.g., if decoding results in an empty string)
      if (key.length === 0 || value.length === 0) {
        continue;
      }

      if (!result[key]) result[key] = [];
      result[key].push(value);
    }
  }

  // Convert arrays to strings for single-occurrence keys, or keep as arrays if multiple
  const finalObj = {};
  for (const [k, v] of Object.entries(result)) {
    if (Array.isArray(v) && v.length === 1) {
      finalObj[k] = v[0];
    } else {
      finalObj[k] = v;
    }
  }

  return finalObj;
