    except (ValueError, AttributeError):
        raise ValueError("Qty must be a valid integer")

    if qty < 1 or qty > 99:
        raise ValueError("Qty must be between 1 and 99 inclusive")

    # Normalize Unit Price
    try:
        unit_price_pence = int(raw["unit_price_pence"])
    except (ValueError, AttributeError):
        raise ValueError("Unit price pence must be a valid integer")

    if unit_price_pence < 0:
        raise ValueError("Unit price pence must be zero or more")

    # Normalize Currency
    currency = raw.get("currency", "")
    currency = currency.strip().upper() if currency else ""

    if currency not in ("GBP", "EUR", "USD"):
        raise ValueError("Currency must be GBP, EUR, or USD (or missing)")

    # Calculate Total
    total_pence = qty * unit_price_pence

    return {
        "sku": sku,
        "qty": qty,
        "unit_price_pence": unit_price_pence,
        "currency": currency,
        "total_pence": total_pence
    }
