    // Skip empty pairs (e.g., from '&&' or trailing '&')
    if (!pair || pair.trim() === '') continue;

    const splitIndex = pair.indexOf('=');
    const key = splitIndex === -1 ? pair : pair.slice(0, splitIndex);
    const value = splitIndex === -1 ? '' : pair.slice(splitIndex + 1);

    // Decode + to space and then percent-decode
    let decodedKey = key.replace(/\+/g, ' ');
    try {
      decodedKey = decodeURIComponent(decodedKey);
    } catch (e) {
      // Handle malformed percent-encoding gracefully
      decodedKey = decodeURIComponent(key.replace(/\+/g, ' '), { strict: false });
    }

    let decodedValue;
    try {
      decodedValue = decodeURIComponent(value.replace(/\+/g, ' '));
    } catch (e) {
      // Handle malformed percent-encoding gracefully
      decodedValue = decodeURIComponent(value.replace(/\+/g, ' '), { strict: false });
    }

    if (result.hasOwnProperty(decodedKey)) {
      if (!Array.isArray(result[decodedKey])) {
        result[decodedKey] = [result[decodedKey]];
      }
      result[decodedKey].push(decodedValue);
    } else {
      result[decodedKey] = decodedValue;
    }
  }

  return result;
