/**
 * Checks if a value is a plain object (and not null or an array).
 * @param {*} obj - The value to check.
 * @returns {boolean} True if the value is a plain object.
 */
const isPlainObject = (obj) => {
  return typeof obj === 'object' && obj !== null && !Array.isArray(obj);
};

/**
 * Deeply merges two configuration objects.
 * Returns a new object ensuring immutability.
 *
 * @param {Object} base The base configuration object.
 * @param {Object} override The object containing overrides.
 * @returns {Object} A new merged configuration object.
 */
const deepMerge = (base, override) => {
  if (!isPlainObject(base) || !isPlainObject(override)) {
    // If inputs are not plain objects, we cannot merge recursively,
    // but based on the prompt, we assume they are. This is a safeguard.
    return { ...base, ...override };
  }

  const result = { ...base };

  for (const key in override) {
    if (Object.prototype.hasOwnProperty.call(override, key)) {
      const baseValue = base[key];
      const overrideValue = override[key];

      // Ignore undefined in override
      if (overrideValue === undefined) {
        continue;
      }

      // Handle deep merge for plain objects
      if (
        isPlainObject(baseValue) &&
        isPlainObject(overrideValue)
      ) {
        // Recursive call, ensuring deep cloning of nested structures
        result[key] = deepMerge(baseValue, overrideValue);
      } else {
        // Replacement logic:
        // 1. If overrideValue is null, it replaces the base value.
        // 2. If overrideValue is not an object (primitive, array, null), it replaces the base value.
        // 3. If baseValue was primitive/array and overrideValue is object, it replaces (standard assignment).
        // Crucially, we must clone the override value to ensure deep immutability of the result.
        if (Array.isArray(overrideValue)) {
          result[key] = [...overrideValue];
        } else if (isPlainObject(overrideValue)) {
          // Deep clone new object to prevent reference sharing
          result[key] = deepMerge({}, overrideValue);
        } else {
          // Primitives or null
          result[key] = overrideValue;
        }
      }
    }
  }

  return result;
};
```

This function performs a deep merge while strictly maintaining immutability. It uses `isPlainObject` to determine when recursive merging is necessary. Arrays and non-object types in `override` always replace the corresponding values in `base`. `undefined` values in `override` are skipped, preserving the `base` value. To guarantee that the resulting object shares no references with the inputs, deep cloning is used whenever an object or array from `override` is incorporated.

