/**
 * Parses a query string into a plain object.
 *
 * @param {string} qs The query string (e.g., "key1=value1&key2&key1=value2").
 * @returns {Object<string, string | string[]>} The parsed query object.
 */
function parseQuery(qs) {
    const result = {};

    if (!qs) {
        return result;
    }

    // Remove leading '?' if present
    const cleanQs = qs.startsWith('?') ? qs.substring(1) : qs;

    // Split by '&' to get individual pairs
    const pairs = cleanQs.split('&);

    for (let i = 0; i < pairs.length; i++) {
        const pair = pairs[i];

        // Skip empty pairs (e.g., from '&&' or trailing '&')
        if (!pair) {
            continue;
        }

        // Split by the FIRST '=' only
        const parts = pair.split('=');

        // Decode '+' to space, then decode the URI component for both key and value
        const rawKey = parts[0].replace(/\+/g, ' ');
        const key = decodeURIComponent(rawKey);

        let value = "";
        if (parts.length > 1) {
            // Rejoin the rest of the parts in case the value contained '='
            const rawValue = parts.slice(1).join('=');
            value = decodeURIComponent(rawValue.replace(/\+/g, ' '));
        }

        // Handle the storage logic (single value vs. array)
        if (result.hasOwnProperty(key)) {
            if (Array.isArray(result[key])) {
                // Key already an array, push new value
                result[key].push(value);
            } else {
                // Key exists as a single string, convert to array and add new value
                result[key] = [result[key], value];
            }
        } else {
            // New key
            result[key] = value;
        }
    }

    return result;
}
