def normalise_order(raw: dict) -> dict:
    """
    Normalizes a raw order dictionary into a standardized format.
    """
    # 1. SKU normalization and validation
    sku = raw["sku"]
    if not isinstance(sku, str):
        raise ValueError("sku must be a string")
    sku_stripped = sku.strip()
    if not sku_stripped:
        raise ValueError("sku cannot be empty after stripping")
    sku_norm = sku_stripped.upper()

    # 2. Quantity normalization and validation
    qty_raw = raw["qty"]
    try:
        qty_norm = int(qty_raw)
    except (ValueError, TypeError):
        raise ValueError(f"qty must be convertible to an integer, received: {qty_raw}")

    if not (1 <= qty_norm <= 99):
        raise ValueError(f"qty must be between 1 and 99, received: {qty_norm}")

    # 3. Unit Price normalization and validation
    try:
        unit_price_norm = int(raw["unit_price_pence"])
    except (ValueError, TypeError):
        raise ValueError("unit_price_pence must be an integer")

    if unit_price_norm < 0:
        raise ValueError("unit_price_pence must be 0 or greater")

    # 4. Currency normalization and validation
    currency_raw = raw.get("currency")
    allowed_currencies = {"GBP", "EUR", "USD"}

    if currency_raw is None or str(currency_raw).strip() == "":
        currency_norm = None
    else:
        currency_stripped = str(currency_raw).strip().upper()
        if currency_stripped not in allowed_currencies:
            # Check if it's a known valid currency (though requirements imply strict check)
            raise ValueError(f"Invalid currency: {currency_raw}. Must be one of {allowed_currencies}")
        currency_norm = currency_stripped

    # 5. Total calculation
    total_norm = qty_norm * unit_price_norm

    return {
        "sku": sku_norm,
        "qty": qty_norm,
        "unit_price_pence": unit_price_norm,
        "currency": currency_norm,
        "total_pence": total_norm
    }
