import datetime

def parse_date(text: str) -> datetime.date:
    """
    Parses a date string from one of three specific formats:
    ISO (YYYY-MM-DD), British numeric (DD/MM/YYYY), or Short text (D MMM YYYY).

    Args:
        text: The date string to parse.

    Returns:
