    try:
        return datetime.datetime.strptime(text, "%Y-%m-%d").date()
    except ValueError:
        pass

    # 2. British Numeric Format (DD/MM/YYYY)
    try:
        # strptime is strict about order, so we specify day/month/year
        return datetime.datetime.strptime(text, "%d/%m/%Y").date()
    except ValueError:
        pass

    # 3. Short Text Format (D MMM YYYY)
    # %b handles abbreviated month names like 'Mar'
    try:
        return datetime.datetime.strptime(text, "%d %b %Y").date()
    except ValueError:
        # Try without leading zero for day (e.g., "7 Mar 2025")
        try:
            return datetime.datetime.strptime(text, "%#d %b %Y").date()
        except ValueError:
            # Fallback for systems where %d doesn't handle no leading zero
            # This handles the '7 Mar 2025' case explicitly if %d failed
            try:
                return datetime.datetime.strptime(text, "%d %b %Y").date()
            except ValueError:
