/**
 * Parses a query string into a plain JavaScript object.
 * @param {string} qs The query string, possibly including a leading '?'.
 * @returns {Object<string, string | string[]>} The parsed query parameters.
 */
function parseQuery(qs) {
    const result = {};

    // Remove leading '?' if present
    const cleanQs = qs.startsWith('?') ? qs.substring(1) : qs;

    if (!cleanQs) {
        return result;
    }

    const pairs = cleanQs.split('&');

    for (const pair of pairs) {
        // Skip empty pairs (from && or trailing &)
        if (!pair) {
            continue;
        }

        const [keyEncoded, ...rest] = pair.split('=');
        const valueEncoded = rest.length > 0 ? rest.join('=') : '';

        // 1. Decode + as space, then percent-decode
        const decodePlus = (str) => str.replace(/\+/g, ' ');
        const decode = (str) => decodeURIComponent(decodePlus(str));

        const key = decode(keyEncoded);
        const value = decode(valueEncoded);

        if (key === '') continue;

        // 2. Handle uniqueness (Array vs String)
        if (result.hasOwnProperty(key)) {
            if (Array.isArray(result[key])) {
                // Key already exists and is an array, push new value
                result[key].push(value);
            } else {
                // Key exists as a string, convert to array
                result[key] = [result[key], value];
            }
        } else {
            // First time seeing this key
            result[key] = value;
        }
    }

    return result;
}
```

This function first cleans the input by removing a potential leading `?`. It then splits the string by `&` to get individual pairs, skipping any empty pairs. For each pair, it splits only on the *first* `=` to separate the key and the rest of the string as the value. It applies decoding: replacing `+` with spaces, followed by `decodeURIComponent` for both key and value. Finally, it populates the result object, ensuring that if a key is encountered again, its value is appended to an array, or the single string value is converted into an array.

