/**
 * Deeply merges two objects.
 * Returns a new object, ensuring no shared references with inputs.
 *
 * @param {object} base The base configuration object.
 * @param {object} override The overriding configuration object.
 * @returns {object} The merged object.
 */
function deepMerge(base, override) {
    const result = { ...base };

    if (typeof override !== 'object' || override === null || Array.isArray(override)) {
        // If override is not a mergeable object, return a deep copy of base (or override if base wasn't deep-copied)
        // Since we initialized result = { ...base }, it's a shallow copy. We must deep copy to ensure immutability.
        return deepClone(base);
    }

    for (const key in override) {
        if (Object.prototype.hasOwnProperty.call(override, key)) {
            const overrideValue = override[key];
            const baseValue = base ? base[key] : undefined;

            // 1. Skip undefined values in override
            if (overrideValue === undefined) {
                continue;
            }

            // 2. Check if both values are plain objects (and not null or arrays)
            const isPlainObject = (obj) => 
                obj && typeof obj === 'object' && !Array.isArray(obj) && obj.constructor === Object;

            if (isPlainObject(baseValue) && isPlainObject(overrideValue)) {
                // Recursive merge for plain objects
                result[key] = deepMerge(baseValue, overrideValue);
            } else {
                // For primitives, arrays, or if base/override is not a plain object, override replaces base.
                // We must deep clone the override value to ensure the result doesn't hold a reference to the input.
                result[key] = deepClone(overrideValue);
            }
        }
    }

    return result;
}

/**
 * Helper function to perform a deep clone of a value.
 * Handles primitives, arrays, and plain objects recursively.
 * @param {*} obj The value to clone.
 * @returns {*} The cloned value.
 */
function deepClone(obj) {
    if (obj === null || typeof obj !== 'object') {
        return obj;
    }
    if (Array.isArray(obj)) {
        return obj.map(deepClone);
    }
    if (obj.constructor !== Object) {
        // Handle other object types if necessary, but for service config, we stick to plain objects/arrays
        return obj;
    }

    const clonedObj = {};
    for (const key in obj) {
        if (Object.prototype.hasOwnProperty.call(obj, key)) {
            clonedObj[key] = deepClone(obj[key]);
        }
    }
    return clonedObj;
}
```

The `deepMerge` function merges `override` into a copy of `base`. It uses a recursive helper, `deepClone`, to ensure that every object or array placed into the new result is a unique copy, thereby preventing mutation of the input objects. It handles the specified logic: recursing only on plain objects, replacing non-object types, ignoring `undefined` overrides, and preserving base-only keys.

