    int unit_stage = 0; // 0: hours, 1: minutes, 2: seconds

    while (i < s.length()) {
        // 1. Check for digits
        size_t start = i;
        while (i < s.length() && std::isdigit(static_cast<unsigned char>(s[i]))) {
