        if (unit == 'h') {
            if (unit_stage != 0) return -1; // Wrong order or repeated
            total_seconds += val * 3600;
            unit_stage = 1;
        } else if (unit == 'm') {
            if (unit_stage != 1) return -1;
            total_seconds += val * 60;
            unit_stage = 2;
        } else if (unit == 's') {
            if (unit_stage != 2) return -1;
            total_seconds += val;
            unit_stage = 3;
