function deepMerge(base, override) {
  const isObject = (obj) => obj && typeof obj === 'object' && !Array.isArray(obj);

  // Handle cases where base is not an object or is null
  if (!isObject(base)) {
    if (override === undefined) return base;
    return isObject(override) ? deepMerge({}, override) : (override === undefined ? base : override);
  }

  const result = { ...base };

  for (const key in override) {
    if (Object.prototype.hasOwnProperty.call(override, key)) {
      const val = override[key];

      if (val === undefined) {
        continue;
      }

      if (isObject(val) && isObject(base[key])) {
        result[key] = deepMerge(base[key], val);
      } else if (Array.isArray(val)) {
        // Create a deep copy of the array
        result[key] = val.map(item => (isObject(item) ? deepMerge({}, item) : (Array.isArray(item) ? [...item] : item)));
      } else if (isObject(val)) {
        // Deep copy of an object that doesn't exist in base
        result[key] = deepMerge({}, val);
      } else {
        // Primitive values (strings, numbers, null, etc.)
        result[key] = val;
      }
    }
