long long parse_duration(const std::string& s) {
    if (s.empty()) return -1;

    long long total_seconds = 0;
    size_t i = 0;
    size_t n = s.length();

    // Track which units have been seen to prevent repeats and ensure order
    bool seen_h = false;
    bool seen_m = false;
    bool seen_s = false;

    while (i < n) {
        // Check for spaces or signs immediately
        if (std::isspace(s[i]) || (s[i] == '-' || s[i] == '+')) return -1;

        // Find the numeric part
        size_t start = i;
        while (i < n && std::isdigit(s[i])) {
            i++;
        }

        // Validation: Must have digits and must not be at the end of string
        if (start == i || i == n) return -1;

        std::string num_str = s.substr(start, i - start);
        long long val = std::stoll(num_str);

        // Identify the unit
        char unit = s[i];
        if (unit == 'h') {
            if (seen_h) return -1; // Repeated unit
            total_seconds += val * 3600;
            seen_h = true;
        } else if (unit == 'm') {
            if (seen_h || seen_m) return -1; // Wrong order or repeated
            total_seconds += val * 60;
            seen_m = true;
        } else if (unit == 's') {
            if (seen_h || seen_m || seen_s) return -1; // Wrong order or repeated
            total_seconds += val;
            seen_s = true;
        } else {
            return -1; // Unknown unit
        }

        // Move past the unit character
        i++;
    }

    return total_seconds;
}
```

### Explanation
- **Validation**: The function checks for invalid characters (spaces, signs), ensures every number is followed by a unit, and ensures units are not repeated or out of order (`h` $\to$ `m` $\to$ `s`).
- **Logic**: It iterates through the string, parsing digits into a `long long` and then identifying the subsequent character as the unit multiplier.
- **Complexity**: $O(n)$ where $n$ is the length of the string.

