function deepMerge(base, override) {
  // Helper to check if a value is a plain object
  const isPlainObject = (obj) => {
    return obj !== null && typeof obj === 'object' && !Array.isArray(obj);
  };

  // Deep clone helper to ensure no shared references
  const deepClone = (val) => {
    if (Array.isArray(val)) {
      return val.map(item => deepClone(item));
    }
    if (isPlainObject(val)) {
      const clone = {};
      for (const key in val) {
        if (Object.prototype.hasOwnProperty.call(val, key)) {
          clone[key] = deepClone(val[key]);
        }
      }
      return clone;
    }
    return val;
  };

  // Initialize result with a deep clone of base
  const result = deepClone(base);

  for (const key in override) {
    if (Object.prototype.hasOwnProperty.call(override, key)) {
      const overrideVal = override[key];

      // Skip undefined values
      if (overrideVal === undefined) continue;

      const baseVal = result[key];

      if (isPlainObject(overrideVal) && isPlainObject(baseVal)) {
        // Recursively merge plain objects
        result[key] = deepMerge(baseVal, overrideVal);
      } else {
        // Replace with a deep clone of the override value
        // This covers arrays, nulls, and primitives
        result[key] = deepClone(overrideVal);
      }
    }
  }

  return result;
}
