function parseQuery(qs) {
  const result = {};
  if (!qs) return result;

  // Remove leading '?' if present
  const str = qs.startsWith('?') ? qs.slice(1) : qs;

  // Split into pairs and filter out empty strings (handles && and trailing &)
  const pairs = str.split('&').filter(Boolean);

  for (const pair of pairs) {
    const eqIndex = pair.indexOf('=');
    let rawKey, rawValue;

    if (eqIndex === -1) {
      rawKey = pair;
      rawValue = "";
    } else {
      rawKey = pair.slice(0, eqIndex);
      rawValue = pair.slice(eqIndex + 1);
    }

    // Helper to decode '+' as space and then percent-decode
    const decode = (s) => decodeURIComponent(s.replace(/\+/g, ' '));

    const key = decode(rawKey);
    const value = decode(rawValue);

    if (Object.prototype.hasOwnProperty.call(result, key)) {
      if (Array.isArray(result[key])) {
        result[key].push(value);
      } else {
        result[key] = [result[key], value];
      }
    } else {
      result[key] = value;
    }
  }

  return result;
}
