function deepMerge(base, override) {
  // Helper to check if a value is a plain object
  const isObject = (val) => 
    val !== null && typeof val === 'object' && !Array.isArray(val);

  // Handle cases where base or override are not objects (e.g. primitive values)
  // If override is undefined, we return a deep clone of base.
  if (override === undefined) {
    return deepClone(base);
  }

  // If override is not an object, or is an array, it replaces base entirely
  if (!isObject(override)) {
    return deepClone(override);
  }

  const result = {};

  // Get all unique keys from both objects
  const allKeys = new Set([...Object.keys(base || {}), ...Object.keys(override)]);

  for (const key of allKeys) {
    const baseVal = base && base[key];
    const overVal = override[key];

    if (overVal === undefined) {
      // Keep base value if override is undefined
      result[key] = deepClone(baseVal);
    } else if (isObject(baseVal) && isObject(overVal)) {
      // Recursively merge if both are plain objects
      result[key] = deepMerge(baseVal, overVal);
    } else {
      // Override replaces base (covers null, arrays, and primitives)
      result[key] = deepClone(overVal);
    }
  }

  return result;
}

// Helper to ensure deep independence (no shared references)
function deepClone(val) {
  if (val === null || typeof val !== 'object') {
    return val;
  }

  if (Array.isArray(val)) {
    return val.map(item => deepClone(item));
  }

  const clone = {};
  for (const key in val) {
    if (Object.prototype.hasOwnProperty.call(val, key)) {
      clone[key] = deepClone(val[key]);
    }
  }
  return clone;
}
```

