  // return a deep clone of the override or base based on the logic
  if (!isObject(base) || !isObject(override)) {
    if (override === undefined) return JSON.parse(JSON.stringify(base));
    return JSON.parse(JSON.stringify(override));
  }

  const result = { ...base };

  for (const key in override) {
    if (Object.prototype.hasOwnProperty.call(override, key)) {
      const valOverride = override[key];

      if (valOverride === undefined) {
        continue;
