        // to ensure the result doesn't share references with the input.
        result[key] = (Array.isArray(valOverride)) 
          ? [...valOverride.map(item => (isObject(item) ? deepMerge({}, item) : item))]
          : (isObject(valOverride) ? deepMerge({}, valOverride) : valOverride);
