  const isObject = (obj) => 
    obj !== null && 
    typeof obj === 'object' && 
    !Array.isArray(obj);

  // Handle non-object inputs or nulls to ensure we always return a new copy
  if (!isObject(base) || !isObject(override)) {
    return isObject(override) ? JSON.parse(JSON.stringify(override)) : 
           (base !== undefined ? JSON.parse(JSON.stringify(base)) : {});
  }

  const result = { ...base };

  for (const key in override) {
    if (Object.prototype.hasOwnProperty.call(override, key)) {
      const overrideVal = override[key];
      const baseVal = base[key];

      if (overrideVal === undefined) {
        continue;
      }

      if (isObject(overrideVal) && isObject(baseVal)) {
        result[key] = deepMerge(baseVal, overrideVal);
      } else {
        // If it's an array or primitive, perform a deep clone of the override value
        if (Array.isArray(overrideVal)) {
          result[key] = overrideVal.map(item => 
            (isObject(item) || Array.isArray(item)) ? JSON.parse(JSON.stringify(item)) : item
          );
        } else if (isObject(overrideVal)) {
          result[key] = JSON.parse(JSON.stringify(overrideVal));
        } else {
          result[key] = overrideVal;
        }
      }
    }
  }

  return result;
}
