        if (!std::isdigit(static_cast<unsigned char>(s[i]))) {
            return -1;
        }

        // Extract number
        size_t start = i;
        while (i < n && std::isdigit(static_cast<unsigned char>(s[i]))) {
            i++;
        }

        // Check if number is followed by a unit
        if (i >= n) return -1; 
        char unit = s[i];

        long long value = std::stoll(s.substr(start, i - start));

        if (unit == 'h') {
            if (last_unit_type != 0 && last_unit_type != 1) return -1;
            total_seconds += value * 3600;
            last_unit_type = 1;
        } else if (unit == 'm') {
            if (last_unit_type != 0 && last_unit_type != 2) return -1;
            total_seconds += value * 60;
            last_unit_type = 2;
        } else if (unit == 's') {
            if (last_unit_type != 0 && last_unit_type != 3) return -1;
            total_seconds += value;
            last_unit_type = 3;
        } else {
            return -1;
        }

        // Move past the unit character
        i++;

        // Ensure no trailing characters after a unit-pair unless it's the start of a new number
        if (i < n && !std::isdigit(static_cast<unsigned char>(s[i]))) {
            return -1;
        }
    }

    return total_seconds;
}
