function deepMerge(base, override) {
  const isObject = (val) => val !== null && typeof val === 'object' && !Array.isArray(val);

  // Handle non-object types or null/undefined
  if (!isObject(base) || !isObject(override)) {
    return override === undefined ? (isObject(base) ? deepMerge({}, base) : base) : (isObject(override) ? deepMerge({}, override) : override);
  }

  const result = {};

  // Get all unique keys from both objects
  const allKeys = new Set([...Object.keys(base), ...Object.keys(override)]);

  for (const key of allKeys) {
    const baseVal = base[key];
    const overrideVal = override[key];

    if (overrideVal === undefined) {
      // Keep base value, but deep clone it to ensure no shared references
      if (isObject(baseVal)) {
        result[key] = deepMerge({}, baseVal);
      } else if (Array.isArray(baseVal)) {
        result[key] = [...baseVal];
      } else {
        result[key] = baseVal;
      }
    } else if (isObject(baseVal) && isObject(overrideVal)) {
      // Recursively merge if both are plain objects
      result[key] = deepMerge(baseVal, overrideVal);
    } else if (Array.isArray(overrideVal)) {
      // Replace with a clone of the array
      result[key] = [...overrideVal];
    } else if (isObject(overrideVal)) {
      // Replace with a deep clone of the override object
      result[key] = deepMerge({}, overrideVal);
    } else {
      // Replace with primitive value (including null)
      result[key] = overrideVal;
    }
  }

  return result;
}
```

