long long parse_duration(const std::string& s) {
    if (s.empty()) return -1;

    long long total_seconds = 0;
    size_t i = 0;
    int unit_state = 0; // 0: looking for h, 1: looking for m, 2: looking for s

    while (i < s.length()) {
