        if (num_str.empty()) return -1; // Should not happen due to isdigit check

        // The next character must be the unit
        if (i >= s.length()) return -1; // Number without unit
        char unit = s[i];
        i++;

        long long value = std::stoll(num_str);

        if (unit == 'h') {
            if (unit_state != 0) return -1; // Wrong order or repeated
            total_seconds += value * 3600;
            unit_state = 1;
        } else if (unit == 'm') {
            if (unit_state != 1) return -1; // Wrong order or repeated
            total_seconds += value * 60;
            unit_state = 2;
        } else if (unit == 's') {
            if (unit_state != 2) return -1; // Wrong order or repeated
            total_seconds += value;
            unit_state = 3;
        } else {
            return -1; // Unknown unit
        }
    }

    return total_seconds;
}
