#include <string>

long long parse_duration(const std::string& s) {
    if (s.empty()) return -1;

    long long total = 0;
    int order = 0;   // expected unit: 0=h, 1=m, 2=s
    bool any_unit = false;

    size_t i = 0;
    while (i < s.size()) {
        char c = s[i];

        // parse the number of digits that follows
        if (c >= '0' && c <= '9') {
            long long value = 0;
            while (i < s.size() && s[i] >= '0' && s[i] <= '9') {
                value = value * 10 + (s[i] - '0');
                ++i;
            }
            // a number must be followed by a unit -> no digit may be the last char
            if (i == s.size()) return -1;

            // consume the unit
            char u = s[i++];
            int want = 0;   // h=0, m=1, s=2
            if (u == 'h') {
                if (order != 0) return -1;          // wrong order / repeated
                order = 1; any_unit = true;
            } else if (u == 'm') {
                if (order != 1) return -1;
                order = 2; any_unit = true;
            } else if (u == 's') {
                if (order != 2) return -1;
                order = 3; any_unit = true;
            } else {
                return -1;                            // unknown unit
            }

            total += value * want;                    // h=3600, m=60, s=1
        } else {
            // not a digit: must be a unit char (already handled above)
            return -1;                                // space or any other sign/char
        }
    }

    if (!any_unit) return -1;                          // no units at all
    return total;
}
```

