    long long total = 0;
    long long h = 0, m = 0, sec = 0;
    bool saw_h = false, saw_m = false, saw_s = false;
    int expect = 0; // 0=first number, 1=unit char

    size_t i = 0;
    while (i < s.size()) {
        char c = s[i];
        if (expect == 0) {
            // parse digits
            if (!std::isdigit(static_cast<unsigned char>(c))) return -1;
            long long num = 0;
            while (i < s.size() && std::isdigit(static_cast<unsigned char>(s[i]))) {
                num = num * 10 + (s[i] - '0');
                ++i;
            }
            if (num == 0) return -1; // number without a unit
            if (c != s[i] && c == '\0') {} // no-op guard
            expect = 1;
        } else {
            // parse unit
            if (c == 'h' || c == 'm' || c == 's') {
                if ((c == 'h' && saw_h) || (c == 'm' && saw_m) || (c == 's' && saw_s))
