                return -1; // unit without a number, or sign/other char
            }
        }
    }

    if (expect != 1) return -1;   // last part had no unit
    if (!saw_h || !saw_m || !saw_s) return -1; // every unit required

    return h * 3600LL + m * 60LL + sec;
