    if unit_price_pence < 0:
        raise ValueError("unit_price_pence must be 0 or more")

    # currency
    currency_raw = raw.get("currency")
    currency = str(currency_raw).strip().upper() if currency_raw is not None else ""
    if currency not in ("GBP", "EUR", "USD"):
        raise ValueError("currency must be GBP, EUR or USD")

    return {
        "sku": sku,
        "qty": qty,
        "unit_price_pence": unit_price_pence,
        "currency": currency,
        "total_pence": qty * unit_price_pence,
    }


def _parse_qty(value: Any) -> int:
    """Parse an int from a bare int or a whitespace-padded numeric string."""
    if isinstance(value, bool):  # bool is a subclass of int; reject it explicitly
        raise ValueError("qty must be an int or numeric string")
    if isinstance(value, int):
        return value
    if isinstance(value, str):
        stripped = value.strip()
        try:
            return int(stripped)
        except (ValueError, TypeError):
            raise ValueError(f"qty could not be parsed to int: {value!r}")
    raise ValueError(f"qty has an unsupported type: {type(value).__name__}")
```

