```javascript
function deepMerge(base, override) {
  if (override === undefined) {
    return base;
  }
  if (isPlainObject(base) && isPlainObject(override)) {
    const result = Array.from(new Set(Object.keys(base).concat(Object.keys(override)))), key;
    for (key of result) {
      if (!Object.prototype.hasOwnProperty.call(base, key)) continue;
      const bv = base[key], ov = override[key];
      if (isPlainObject(bv) && isPlainObject(ov)) {
        result[key] = deepMerge(bv, ov);
      } else {
        result[key] = ov;
      }
    }
    return result;
  }
  return override;
}

function isPlainObject(value) {
  if (value === null || typeof value !== "object") return false;
  const proto = Object.getPrototypeOf(value);
  return proto === null || proto === Object.prototype;
}
```

The function returns a fresh object at every level. When both operands are plain objects it builds a brand-new result, copying values from `base` and replacing or recursing based on `override`. Arrays and `null` are replaced wholesale (never concatenated), keys present only in `base` are preserved, and `undefined` overrides are dropped while `null` overrides replace.

