#include <string>
#include <cctype>

long long parse_duration(const std::string& s) {
    if (s.empty()) return -1;

    long long total = 0;
    int last_unit = -1; // -1: none, 0: h, 1: m, 2: s
    size_t i = 0;

    while (i < s.size()) {
        if (!std::isdigit(static_cast<unsigned char>(s[i]))) return -1; // no spaces/signs allowed

        long long value = 0;
        while (i < s.size() && std::isdigit(static_cast<unsigned char>(s[i]))) {
            value = value * 10 + (s[i] - '0');
            ++i;
        }
        if (value == 0) return -1; // unit without a number

        if (i >= s.size()) return -1; // number without a unit

        char c = s[i];
        int unit;
        switch (c) {
            case 'h': unit = 0; break;
            case 'm': unit = 1; break;
            case 's': unit = 2; break;
            default: return -1; // unknown unit
        }
        ++i;

        if (unit < last_unit) return -1; // wrong order (also catches repeats since same unit -> equal, not less... need strict check below)
        if (unit == last_unit) return -1; // repeated unit

        last_unit = unit;
        total += value << (unit * 3); // h*3600, m*60, s*1
    }

    return total;
}
```

**Notes:**
- Walks left-to-right: digits form a number, then exactly one unit must follow. Any stray non-digit (space, sign) or missing unit fails immediately.
- `last_unit` enforces the strict `h → m → s` order and rejects repeats (e.g. `1h1h`, `3m2h`).
- `value << (unit*3)` gives ×3600 / ×60 / ×1 without magic-number clutter; per your guarantee this won't overflow.

