    else:
        currency = str(currency).strip().upper()
        if currency not in ALLOWED_CURRENCIES:
            raise ValueError(f"invalid 'currency': {currency!r}")

    return {
        "sku": sku,
        "qty": qty,
        "unit_price_pence": price,
        "currency": currency,
        "total_pence": qty * price,
    }


def _to_int(value, *, name, min_value, max_value):
    """Parse an int from something like 3, '3', or ' 3 ', raising ValueError on failure."""
    text = str(value).strip()
    if not text.lstrip("+-"):   # rejects blank / sign-only strings
        raise ValueError(f"'{name}' must be an integer")
    try:
        result = int(text)
    except ValueError:
        raise ValueError(f"'{name}' is not a valid integer: {value!r}")
    if min_value is not None and result < min_value:
        raise ValueError(f"'{name}' must be >= {min_value}")
    if max_value is not None and result > max_value:
        raise ValueError(f"'{name}' must be <= {max_value}")
    return result


