```javascript
function deepMerge(base, override) {
  if (override === undefined) return base;

  const result = Array.isArray(base) || Array.isArray(override)
    ? Array.isArray(override) ? [...override] : [...base]
    : Array.isArray(base) ? [...base] : typeof override === 'object' && override !== null
      ? { ...override }
      : override;

  if (result === base || result === override) return result;

  if (isPlainObject(base) && isPlainObject(override)) {
    const merged = { ...(Array.isArray(base) ? {} : base) };
    for (const key of Object.keys(override)) {
      if (override[key] === undefined) continue;
      merged[key] = deepMerge(
        Array.isArray(base) ? undefined : base,
        override[key],
      );
    }
    return merged;
  }

  return result;
}

function isPlainObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}
```

`deepMerge` returns a fresh object for each merge step, so neither input nor the output shares nested state. It recurses only when both sides are plain objects; arrays and other types (including `null`) replace outright, while `undefined` override values are skipped to keep the base value.

