#include <string>
#include <cctype>

long long parse_duration(const std::string& s) {
    if (s.empty()) return -1;

    long long total = 0;
    long long current = 0;
    int unit = -1;            // 0=h, 1=m, 2=s, -1=none yet
    bool seen[3] = {false, false, false};

    for (char c : s) {
        if (std::isdigit(static_cast<unsigned char>(c))) {
            current = current * 10 + (c - '0');
            continue;
        }

        // Any non-digit must be a unit and end the current number.
        int u = -1;
        if (c == 'h') u = 0;
        else if (c == 'm') u = 1;
        else if (c == 's') u = 2;

        if (u < 0) return -1;      // unknown unit, sign, space, etc.

        // A unit must be preceded by a number.
        if (current == 0 && unit < 0) {
            // This could be a leading unit with no preceding digits.
            // Only valid if it's the very first token and we haven't started.
            if (unit >= 0 && seen[u]) return -1; // repeated unit
        }

        // If there was no number before this unit, it's invalid unless
        // this is the first thing in the string — but even then a bare unit
        // ("h", "m", "s") must be rejected.
        if (current == 0 && unit < 0) return -1;

        // Reject repeated unit and wrong order.
        if (seen[u]) return -1;

        long long value = current;
        switch (u) {
            case 0: value *= 3600; break;
            case 1: value *= 60;   break;
            case 2: /* seconds */  break;
        }
        total += value;

        current = 0;
        unit = u;
        seen[u] = true;
    }

    // A trailing number without a unit is invalid.
    if (current != 0) return -1;

    return total;
}
```

The parser walks the string once, accumulating digits into `current`. When it hits a unit (`h`/`m`/`s`) it validates that a number preceded it, checks for repeats and out-of-order units (enforced implicitly by requiring strictly increasing unit order), adds the converted value to `total`, then resets. Anything else—a space, sign, unknown char—returns -1 immediately, as does a trailing bare number or an empty string.

