from datetime import date


def parse_date(text: str) -> date:
    text = text.strip()

    # ISO format: YYYY-MM-DD
    if "-" in text:
        try:
            year, month, day = map(int, text.split("-"))
            return date(year, month, day)
        except ValueError:
            raise

    # British numeric format: DD/MM/YYYY
    if "/" in text:
        parts = text.split("/")
        if len(parts) == 3:
            try:
                day, month, year = map(int, parts)
                return date(year, month, day)
            except ValueError:
                raise

    # Short text format: D Mon YYYY (e.g. "7 Mar 2025")
    words = text.split()
    if len(words) == 3:
        try:
            day = int(words[0])
            year = int(words[2])
            month = _month_name_to_number(words[1])
            return date(year, month, day)
        except (ValueError, KeyError):
            raise

    raise ValueError(f"Unrecognized date format: {text!r}")


def _month_name_to_number(name: str) -> int:
    months = {
        "jan": 1, "feb": 2, "mar": 3, "apr": 4,
        "may": 5, "jun": 6, "jul": 7, "aug": 8,
        "sep": 9, "oct": 10, "nov": 11, "dec": 12,
    }
    try:
        return months[name.lower()]
    except KeyError:
        raise ValueError(f"Unrecognized month name: {name!r}")
```

