function parseQuery(qs) {
  const result = {};

  if (!qs || typeof qs !== "string") return result;

  // Strip a single leading '?' if present, then split on '&'.
  const body = qs.startsWith("?") ? qs.slice(1) : qs;
  const pairs = body.split("&");

  for (const pair of pairs) {
    if (!pair) continue; // skip empty pairs from '&&' or trailing '&'

    const eq = pair.indexOf("=");
    let rawKey;
    let rawValue = "";

    if (eq === -1) {
      rawKey = pair; // no '=' -> value is ""
    } else {
      rawKey = pair.slice(0, eq);
      rawValue = pair.slice(eq + 1);
    }

    // Decode '+' as space first, then percent-decode.
    const key = decodeURIComponent(rawKey.replace(/\+/g, " "));
    const value = decodeURIComponent(rawValue.replace(/\+/g, " "));

    if (!(key in result)) {
      result[key] = value;
    } else if (Array.isArray(result[key])) {
      result[key].push(value);
    } else {
      // Existing scalar value means the key appeared more than once.
      result[key] = [result[key], value];
    }
  }

  return result;
}
```

The function splits on `&`, treats the first `=` as the separator, and skips blank pairs. Each key/value is decoded by turning `+` into a space before percent-decoding. A key seen for the first time becomes a string; once it recurs, subsequent values are collected into an array (and any earlier scalar is promoted to include itself).

