function deepMerge(base, override) {
  const isPlainObject = (v) =>
    v !== null && typeof v === "object" && !Array.isArray(v);

  if (!isPlainObject(base) || !isPlainObject(override)) {
    return isPlainObject(override) ? deepMerge({}, override) : cloneOverride(override);
  }

  const result = {};

  for (const key of Object.keys(base)) {
    if (!(key in override)) {
      result[key] = cloneDeep(base[key]);
    }
  }

  for (const key of Object.keys(override)) {
    if (override[key] === undefined) continue; // keep base value

    const baseVal = base[key];
    if (isPlainObject(baseVal) && isPlainObject(override[key])) {
      result[key] = deepMerge(cloneDeep(baseVal), cloneDeep(override[key]));
    } else {
      result[key] = cloneOverride(override[key]);
    }
  }

  return result;
}

function cloneDeep(value) {
  if (Array.isArray(value)) return value.map(cloneDeep);
  if (value !== null && typeof value === "object") {
    const out = {};
    for (const k of Object.keys(value)) out[k] = cloneDeep(value[k]);
    return out;
  }
  return value;
}

function cloneOverride(value) {
  if (Array.isArray(value)) return value.map(cloneDeep);
  if (value !== null && typeof value === "object") {
    return cloneDeep(value); // plain object, so deep-copy it
  }
  return value;
}
```

The helper `cloneDeep` recursively copies plain objects and arrays, while `cloneOverride` handles non-object override values (numbers, strings, booleans, `null`, `undefined`).

