#include <string>

long long parse_duration(const std::string& s) {
    if (s.empty()) return -1;
    long long total = 0;
    int expected = 'h';          // next unit we want to see
    for (std::size_t i = 0; i < s.size(); ++i) {
        char c = s[i];
        if (c >= '0' && c <= '9') {
            long long value = 0;
            while (i < s.size() && s[i] >= '0' && s[i] <= '9') {
                value = value * 10 + (s[i] - '0');
                ++i;
            }
            if (i == s.size()) return -1;   // number without a unit
            char u = s[i];
            long long seconds;
            if (u == expected) {
                switch (expected) {
                    case 'h': seconds = value * 3600; break;
                    case 'm': seconds = value * 60;   break;
                    default:  seconds = value;        break;
                }
                total += seconds;
                ++expected;                  // h -> m -> s
            } else {
                return -1;                   // wrong order / unknown unit
            }
        } else if (c == ' ') {
            return -1;                       // spaces not allowed
        } else {
            return -1;                       // sign or other junk
        }
    }
    return total;
}
```

Reads each numeric run, multiplies by the factor for its unit, and advances `expected` from `h` to `m` to `s`; anything out of order (or a trailing number with no unit) is rejected.

