import datetime
import re

def parse_date(text: str) -> datetime.date:
    """
    Parse a date string in one of three accepted formats:
      - ISO:            2025-03-07
      - British:       07/03/2025  (day/month/year)
      - Short text:   7 Mar 2025   (day with optional leading zero, 3-letter month)

    Raises ValueError for any other input or impossible dates.
    """
    s = text.strip()
    if not s:
        raise ValueError("Empty string")

    # Try ISO format
    m = re.fullmatch(r'(\d{4})-(\d{2})-(\d{2})', s)
    if m:
        y, mo, d = int(m.group(1)), int(m.group(2)), int(m.group(3))
        try:
            return datetime.date(y, mo, d)
        except ValueError:
            raise

    # Try British numeric format: DD/MM/YYYY
    m = re.fullmatch(r'(\d{2})/(\d{2})/(\d{4})', s)
    if m:
        d, mo, y = int(m.group(1)), int(m.group(2)), int(m.group(3))
        try:
            return datetime.date(y, mo, d)
        except ValueError:
            raise

    # Try short text format: D Mon YYYY or DD Mon YYYY
    m = re.fullmatch(r'(\d{1,2}) ([A-Za-z]{3}) (\d{4})', s)
    if m:
        d_str, mon_str, y_str = m.group(1), m.group(2).capitalize(), m.group(3)
        month_map = {
            'Jan': 1, 'Feb': 2, 'Mar': 3, 'Apr': 4,
            'May': 5, 'Jun': 6, 'Jul': 7, 'Aug': 8,
            'Sep': 9, 'Oct': 10, 'Nov': 11, 'Dec': 12
        }
        if mon_str not in month_map:
            raise ValueError(f"Unknown month: {mon_str}")
        mo = month_map[mon_str]
        d = int(d_str)
        y = int(y_str)
        try:
            return datetime.date(y, mo, d)
        except ValueError:
            raise

    raise ValueError(f"Unrecognized date format: {text!r}")
```

The function tries each of the three formats in order using `re.fullmatch` to ensure exact structure, then validates via `datetime.date` which naturally rejects impossible dates like `31/02/2025`.

