from datetime import datetime
import re

def parse_date(text: str) -> datetime.date:
    """
    Parses a date string from three specific formats used in invoicing:
    1. ISO: YYYY-MM-DD
    2. British numeric: DD/MM/YYYY
    3. Short text: D/Mon YYYY (e.g., 7 Mar 2025)

    Raises ValueError for invalid formats or impossible dates.
    """
    text = text.strip()
    if not text:
        raise ValueError("Empty input")

    # Try ISO format first (YYYY-MM-DD)
    try:
        return datetime.strptime(text, "%Y-%m-%d").date()
    except ValueError:
        pass

    # Try British numeric format (DD/MM/YYYY)
    # We use a regex to ensure it matches the pattern strictly before attempting parsing
    if re.match(r"^\d{2}/\d{2}/\d{4}$", text):
        try:
            return datetime.strptime(text, "%d/%m/%Y").date()
        except ValueError:
            # This catches impossible dates like 31/02/2025
            raise

    # Try short text format (D/Mon YYYY)
    # Month names must be exactly 3 letters and capitalized first letter
    match = re.match(r"^(\d{1,2})\s+([A-Z][a-z]{2})\s+(\d{4})$", text)
    if match:
        day_str, month_str, year_str = match.groups()
        try:
            return datetime.strptime(f"{day_str} {month_str} {year_str}", "%d %b %Y").date()
        except ValueError:
            # This catches impossible dates or invalid month names
            raise

    raise ValueError(f"Unable to parse date: {text}")
