function deepMerge(base, override) {
  // Helper to check if a value is a plain object (not array, not null, not primitive)
  const isPlainObject = (val) => val != null && typeof val === 'object' && Array.isArray(val) === false;

  // Helper to create a deep copy of an object to ensure no shared references
  const clone = (obj) => {
    if (obj == null || typeof obj !== 'object') return obj;
    if (Array.isArray(obj)) return obj.map(clone);
    const cloned = {};
    for (const key in obj) {
      if (Object.prototype.hasOwnProperty.call(obj, key)) {
        cloned[key] = clone(obj[key]);
      }
    }
    return cloned;
  };

  // Start with a deep copy of base to ensure we never modify it and result is isolated
  const result = clone(base);

  if (!isPlainObject(override) || !isPlainObject(result)) {
    // If either isn't a plain object, we can't merge recursively in the standard way.
    // However, based on requirements, if override key exists and isn't an object, it replaces.
    // But since we are iterating keys of override, this logic is handled inside the loop mostly.
    // This check is primarily to handle cases where base itself might not be an object after clone (unlikely given clone logic but safe).
    return result; 
  }

  for (const key in override) {
    if (!Object.prototype.hasOwnProperty.call(override, key)) continue;

    const overrideVal = override[key];
    const baseVal = result[key];

    // Requirement: undefined in override is ignored (keep base value)
    if (overrideVal === undefined) {
      continue;
    }

    // Requirement: If both are plain objects, merge recursively.
    // Otherwise, override replaces base (including arrays).
    if (isPlainObject(baseVal) && isPlainObject(overrideVal)) {
      result[key] = deepMerge(baseVal, overrideVal);
    } else {
      // Clone the override value to ensure the result doesn't share reference with override input
      result[key] = clone(overrideVal);
    }
  }

  return result;
}
```

This function creates a completely independent copy of the configuration. It recursively merges nested plain objects while replacing arrays, primitives, and `null` values directly from the `override`. Keys present only in `base` are preserved, and `undefined` keys in `override` are skipped.

