from datetime import datetime

def parse_date(text: str) -> datetime.date:
    """
    Parses a date string into a datetime.date object.

    Supported formats:
    - ISO: 2025-03-07
    - British numeric: 07/03/2025 (day/month/year)
    - Short text: 7 Mar 2025 (English three-letter month; day with or without a leading zero)

    Raises ValueError for invalid formats or impossible dates.
    Uses only the standard library.
    """
    text = text.strip()

    # Month name mapping
    months = {
        'jan': 1, 'feb': 2, 'mar': 3, 'apr': 4, 'may': 5, 'jun': 6,
        'jul': 7, 'aug': 8, 'sep': 9, 'oct': 10, 'nov': 11, 'dec': 12
    }

    # Try ISO format first (YYYY-MM-DD)
    try:
        return datetime.strptime(text, "%Y-%m-%d").date()
    except ValueError:
        pass

    # Try British numeric format (DD/MM/YYYY)
    try:
        return datetime.strptime(text, "%d/%m/%Y").date()
    except ValueError:
        pass

    # Try short text format (D Mon YYYY or DD Mon YYYY)
    # Split by space to get potential parts
    parts = text.split()

    if len(parts) != 3:
        raise ValueError(f"Invalid date format: {text}")

    day_part, month_part, year_part = parts

    # Validate year part (should be 4 digits)
    try:
        year = int(year_part)
        if not (1 <= year <= 9999):
            raise ValueError(f"Invalid year: {year_part}")
    except ValueError:
        raise ValueError(f"Invalid date format: {text}")

    # Validate and parse month part
    month_str = month_part.lower()
    if month_str not in months:
        raise ValueError(f"Invalid month name: {month_part}")
    month = months[month_str]

    # Validate day part
    try:
        day = int(day_part)
        if not (1 <= day <= 31):
            raise ValueError(f"Invalid day: {day_part}")
    except ValueError:
        raise ValueError(f"Invalid date format: {text}")

    # Create date object and let it validate the combination
    try:
        return datetime(year, month, day).date()
    except ValueError as e:
        raise ValueError(f"Invalid date combination: {text}") from e

