function parseQuery(qs) {
  if (typeof qs !== 'string') return {};

  // Remove leading '?' if present
  const cleanQs = qs.startsWith('?') ? qs.slice(1) : qs;

  // Split by '&' to get pairs
  const pairs = cleanQs.split('&');

  const result = {};

  for (const pair of pairs) {
    // Skip empty pairs (from && or trailing &)
    if (!pair || pair.trim() === '') continue;

    // Find the FIRST '=' to separate key and value
    const eqIndex = pair.indexOf('=');

    let key, value;

    if (eqIndex === -1) {
      // Key without '=' gets empty string value
      key = decodeURIComponent(pair.replace(/\+/g, ' '));
      value = '';
    } else {
      key = decodeURIComponent(pair.slice(0, eqIndex).replace(/\+/g, ' '));
      value = decodeURIComponent(pair.slice(eqIndex + 1).replace(/\+/g, ' '));
    }

    // Handle aggregation of duplicate keys
    if (key in result) {
      const existingValue = result[key];
      if (Array.isArray(existingValue)) {
        existingValue.push(value);
      } else {
        result[key] = [existingValue, value];
      }
    } else {
      result[key] = value;
    }
  }

  return result;
}
```

