function deepMerge(base, override) {
  return mergeObject({}, base, override);

  function isPlainObject(value) {
    return value != null && typeof value === 'object' && !Array.isArray(value);
  }

  function mergeObject(target, source1, source2) {
    // Iterate over keys in the override object (source2)
    for (const key in source2) {
      if (!Object.prototype.hasOwnProperty.call(source2, key)) continue;

      const val1 = target[key];
      const val2 = source2[key];
      const isOverrideUndefined = val2 === undefined;

      // If the override value is explicitly undefined, ignore it and keep base (target) value
      if (isOverrideUndefined) {
        continue;
      }

      // If both values are plain objects, merge recursively
      if (isPlainObject(val1) && isPlainObject(val2)) {
        target[key] = mergeObject({}, val1, val2);
      } else {
        // Otherwise, override value replaces base value (including null and arrays)
        target[key] = val2;
      }
    }

    return target;
  }
}
