    if brit_match:
        try:
            return datetime.strptime(text, '%d/%m/%Y').date()
        except ValueError:
            raise

    # Format 3: Short text (D Mon YYYY or DD Mon YYYY)
    # Regex captures optional leading zero for day and the 3-letter month
    short_match = re.match(r'^(\d{1,2})\s+(Jan|Feb|Mar|Apr|May|Jun|Jul|Aug|Sep|Oct|Nov|Dec)\s+(\d{4})$', text)
    if short_match:
        try:
            day_str, month_str, year_str = short_match.groups()
            # Ensure the day string is padded to 2 digits for strptime consistency if needed, 
            # but %d handles both single and double digits.
