      key = pair;
      value = '';
    } else {
      key = pair.slice(0, eqIndex);
      value = pair.slice(eqIndex + 1);
    }

    // Decode '+' as space, then percent-decode
    const decodedKey = decodeURIComponent(key.replace(/\+/g, ' '));
    const decodedValue = decodeURIComponent(value.replace(/\+/g, ' '));

    if (decodedKey === '') continue; // Skip pairs with empty keys after decoding

    if (result.hasOwnProperty(decodedKey)) {
      // If key already exists and is a string, convert to array
      if (typeof result[decodedKey] === 'string') {
        result[decodedKey] = [result[decodedKey]];
      }
      // Append value to array
      result[decodedKey].push(decodedValue);
    } else {
      result[decodedKey] = decodedValue;
    }
  }

  return result;
