    if iso_match:
        try:
            year, month, day = int(iso_match.group(1)), int(iso_match.group(2)), int(iso_match.group(3))
            return datetime(year, month, day).date()
        except ValueError:
            raise ValueError(f"Invalid ISO date: {text}")

    # Format 2: British Numeric (DD/MM/YYYY)
    brit_match = re.match(r'^(\d{1,2})/(\d{1,2})/(\d{4})$', text)
    if brit_match:
        try:
            day, month, year = int(brit_match.group(1)), int(brit_match.group(2)), int(brit_match.group(3))
            return datetime(year, month, day).date()
        except ValueError:
            raise ValueError(f"Invalid British date: {text}")

    # Format 3: Short text (D Mon YYYY)
    # Regex for: optional space, digits (1-2), space, 3-letter month, space, 4-digit year
    short_match = re.match(r'^(\d{1,2})\s+([A-Za-z]{3})\s+(\d{4})$', text)
    if short_match:
        day_str, month_str, year_str = short_match.groups()
        try:
            day = int(day_str)
            year = int(year_str)
            # Map month names to numbers manually (standard library months)
            months = {
                'jan': 1, 'feb': 2, 'mar': 3, 'apr': 4, 'may': 5, 'jun': 6,
                'jul': 7, 'aug': 8, 'sep': 9, 'oct': 10, 'nov': 11, 'dec': 12
            }
            month = months.get(month_str.lower())
            if month is None:
                raise ValueError(f"Unknown month: {month_str}")
            return datetime(year, month, day).date()
        except ValueError:
            raise ValueError(f"Invalid short date: {text}")

    raise ValueError(f"Unrecognized date format: {text}")
