function parseQuery(qs) {
  if (!qs || typeof qs !== 'string') return {};

  // Remove leading/trailing whitespace and optional leading '?'
  const str = qs.trim().replace(/^\?/, '');

  // Split by '&' but handle empty strings gracefully
  const pairs = str.split('&').filter(p => p.length > 0);

  const result = {};

  for (const pair of pairs) {
    const eqIndex = pair.indexOf('=');

    if (eqIndex === -1) {
      // Key without '=' gets empty string value
      const key = decodeURIComponent(pair.replace(/\+/g, ' '));
      if (!result[key]) result[key] = "";
    } else {
      const key = pair.slice(0, eqIndex).replace(/\+/g, ' ');
      let value = pair.slice(eqIndex + 1);

      // Decode percent-encoded characters and convert '+' to space
      try {
        value = decodeURIComponent(value.replace(/\+/g, ' '));
      } catch (e) {
        // In case of malformed percent-encoding, return as is or skip
        continue;
      }

      if (!result[key]) {
        result[key] = value;
      } else if (Array.isArray(result[key])) {
        result[key].push(value);
      } else {
        // Convert existing single value to array and push new one
        result[key] = [result[key], value];
      }
    }
  }

  return result;
}
