  const isPlainObject = (val) =>
    val !== null &&
    typeof val === 'object' &&
    !Array.isArray(val);

  // If the override is undefined, ignore it (return base as-is for this branch)
  if (override === undefined) {
    return base;
  }

  // If both are plain objects, merge recursively
  if (isPlainObject(base) && isPlainObject(override)) {
    const result = {};
    // Copy all keys from base first
    for (const key in base) {
      if (Object.prototype.hasOwnProperty.call(base, key)) {
        result[key] = deepMerge(base[key], override[key]);
      }
    }
    // Overwrite with keys from override that are not undefined
    for (const key in override) {
      if (Object.prototype.hasOwnProperty.call(override, key)) {
        const overrideVal = override[key];
        // If the value is explicitly undefined in override, skip it (keep base)
        if (overrideVal === undefined) continue;

        result[key] = deepMerge(base[key], overrideVal);
      }
    }
    return result;
  }

  // For anything else (primitives, arrays, null), override replaces base
  // This includes cases where one is an object and the other isn't
  return override;
}
