function deepMerge(base, override) {
  // Helper to check if a value is a plain object
  const isObject = (val) => val !== null && typeof val === 'object' && !Array.isArray(val);

  // Deep clone function to ensure no shared references
  const deepClone = (val) => {
    if (Array.isArray(val)) {
      return val.map(item => deepClone(item));
    } else if (isObject(val)) {
      const clone = {};
      for (const key in val) {
        clone[key] = deepClone(val[key]);
      }
      return clone;
    }
    return val;
  };

  // Start with a deep clone of the base to ensure immutability
  const result = deepClone(base);

  for (const key in override) {
    const overrideValue = override[key];

    // Ignore undefined values in override
    if (overrideValue === undefined) {
      continue;
    }

    const baseValue = result[key];

    if (isObject(baseValue) && isObject(overrideValue)) {
      // If both are plain objects, merge recursively
      result[key] = deepMerge(baseValue, overrideValue);
    } else {
      // Otherwise (including arrays and null), replace with a deep clone of override
      result[key] = deepClone(overrideValue);
    }
  }

  return result;
}
```

### Explanation
- **Immutability**: The function uses a `deepClone` helper to ensure that the `result` object and all its nested structures are entirely new instances, preventing side effects on the original `base` or `override` objects.
- **Recursive Merging**: It checks if both values are "plain objects" (not arrays, not null) to decide whether to recurse or replace.
- **Rule Handling**:
  - **Arrays**: Treated as primitive values; they are replaced rather than merged.
  - **Undefined**: Explicitly skipped using `continue`.
  - **Null**: Treated as a standard replacement value.
  - **Missing Keys**: Keys only in `base` are preserved via the initial `deepClone(base)`.

