long long parse_duration(const std::string& s) {
    if (s.empty()) return -1;

    long long total_seconds = 0;
    size_t i = 0;
    int last_unit_priority = 4; // 3: h, 2: m, 1: s, 0: none

    while (i < s.length()) {
        // Check if we are starting a number (must be digits)
        if (i >= s.length() || !std::isdigit(s[i])) {
            return -1;
        }

        // Parse the number
        long long value = 0;
        while (i < s.length() && std::isdigit(s[i])) {
            value = value * 10 + (s[i] - '0');
            i++;
        }

        // After number, there must be a unit
        if (i >= s.length()) return -1;

        char unit = s[i];
        int current_priority = 0;

        if (unit == 'h') current_priority = 3;
        else if (unit == 'm') current_priority = 2;
        else if (unit == 's') current_priority = 1;
        else return -1; // Unknown unit

        // Check unit order (h > m > s) and prevent repeats
        if (current_priority >= last_unit_priority) {
            return -1;
        }

        // Add to total
        if (current_priority == 3) total_seconds += value * 3600;
        else if (current_priority == 2) total_seconds += value * 60;
        else if (current_priority == 1) total_seconds += value;

        last_unit_priority = current_priority;
        i++; // Move past the unit
    }

    // If we ended and didn't process any units (e.g., "123") or 
    // didn't consume the whole string (though logic above prevents most)
    if (last_unit_priority == 4) return -1;

    return total_seconds;
}
