long long parse_duration(const std::string& s) {
    if (s.empty()) return -1;

    std::string_view sv(s);
    long long total_seconds = 0;
    char last_unit = ' '; // Start with a dummy to track order
    // Define valid order: h < m < s
    auto is_valid_order = [](char prev, char curr) {
        if (prev == 'h') return curr == 'm' || curr == 's';
        if (prev == 'm') return curr == 's';
        if (prev == 's') return false; // s is last
        return true; // first unit
    };

    size_t i = 0;
    while (i < sv.size()) {
        // 1. Parse Number
        size_t start = i;
        while (i < sv.size() && std::isdigit(static_cast<unsigned char>(sv[i]))) {
            i++;
        }

        // Error: No digits found or digits at the end with no unit
        if (i == start || i == sv.size()) return -1;

        long long value = 0;
        auto num_part = sv.substr(start, i - start);
        // Using from_chars for fast, safe parsing
        auto [ptr, ec] = std::from_chars(num_part.data(), num_part.data() + num_part.size(), value);
        if (ec != std::errc()) return -1;

        // 2. Parse Unit
        char unit = sv[i];
        if (unit != 'h' && unit != 'm' && unit != 's') return -1;

        // Check order and repetition
        if (unit == last_unit || !is_valid_order(last_unit, unit)) {
            // Note: if last_unit is ' ', it's the first unit, so it passes
            if (last_unit != ' ') return -1;
        }
        // Special case: if it's the first unit, we don't check against dummy ' ' in is_valid_order
        // but we need to ensure the sequence h -> m -> s is respected.
        // The logic above handles it: h can be followed by m or s. m by s.

        // Re-evaluating order logic: 
        // Allowed: h, m, s. 
        // If current is 'm', prev must be 'h' or nothing.
        // If current is 's', prev must be 'h', 'm' or nothing.
        // If current is 'h', prev must be nothing.
        if (unit == 'm' && last_unit != 'h' && last_unit != ' ') return -1;
        if (unit == 's' && last_unit != 'm' && last_unit != 'h' && last_unit != ' ') return -1;
        if (unit == 'h' && last_unit != ' ') return -1;

        if (unit == 'h') total_seconds += value * 3600;
        else if (unit == 'm') total_seconds += value * 60;
        else if (unit == 's') total_seconds += value;

        last_unit = unit;
        i++; // Move past unit
    }

    // If we finished the loop but last_unit wasn't set, it was invalid (handled at start)
    return total_seconds;
}
