def normalise_order(raw: dict) -> dict:
    """
    Normalises raw order dictionary data.
    Raises ValueError for missing required keys or invalid values.
    """
    # 1. Validate and normalize SKU
    if "sku" not in raw:
        raise ValueError("Missing SKU")
    sku = str(raw["sku"]).strip().upper()
    if not sku:
        raise ValueError("SKU cannot be empty")

    # 2. Validate and normalize QTY
    if "qty" not in raw:
        raise ValueError("Missing qty")
    try:
        qty = int(str(raw["qty"]).strip())
    except (ValueError, TypeError):
        raise ValueError("qty must be an integer")
    if not (1 <= qty <= 99):
        raise ValueError("qty must be between 1 and 99")

    # 3. Validate and normalize Unit Price
    if "unit_price_pence" not in raw:
        raise ValueError("Missing unit_price_pence")
    try:
        unit_price = int(str(raw["unit_price_pence"]).strip())
    except (ValueError, TypeError):
        raise ValueError("unit_price_pence must be an integer")
    if unit_price < 0:
        raise ValueError("unit_price_pence cannot be negative")

    # 4. Validate and normalize Currency
    currency_raw = raw.get("currency")
    if not currency_raw or not str(currency_raw).strip():
        currency = "GBP"
    else:
        currency = str(currency_raw).strip().upper()
        if currency not in {"GBP", "EUR", "USD"}:
            raise ValueError("Invalid currency")

    # 5. Calculate Total
    total_pence = qty * unit_price

    return {
        "sku": sku,
        "qty": qty,
        "unit_price_pence": unit_price,
        "currency": currency,
        "total_pence": total_pence
    }
