function parseQuery(qs) {
  const result = {};
  if (!qs) return result;

  // Remove leading '?' if present
  const search = qs.startsWith('?') ? qs.slice(1) : qs;
  if (!search) return result;

  // Split by '&' and filter out empty strings (handles && or trailing &)
  const pairs = search.split('&');

  for (let i = 0; i < pairs.length; i++) {
    const pair = pairs[i];
    if (!pair) continue;

    // Find the first '=' to separate key and value
    const index = pair.indexOf('=');
    let key, value;

    if (index === -1) {
      // Key without '='
      key = pair;
      value = "";
    } else {
      key = pair.substring(0, index);
      value = pair.substring(index + 1);
    }

    // Helper to decode '+' as space and then percent-decode
    const decode = (str) => decodeURIComponent(str.replace(/\+/g, ' '));

    const decodedKey = decode(key);
    const decodedValue = decode(value);

    // Handle multiple occurrences of the same key
    if (Object.prototype.hasOwnProperty.call(result, decodedKey)) {
      if (Array.isArray(result[decodedKey])) {
        result[decodedKey].push(decodedValue);
      } else {
        result[decodedKey] = [result[decodedKey], decodedValue];
      }
    } else {
      result[decodedKey] = decodedValue;
    }
  }

  return result;
}
```

