function deepMerge(base, override) {
  // Helper to check if a value is a plain object
  const isObject = (val) => 
    val !== null && typeof val === 'object' && !Array.isArray(val);

  // Helper to perform deep cloning to ensure no references are shared
  const deepClone = (val) => {
    if (Array.isArray(val)) {
      return val.map(item => deepClone(item));
    } else if (isObject(val)) {
      const clone = {};
      for (const key in val) {
        clone[key] = deepClone(val[key]);
      }
      return clone;
    }
    return val;
  };

  // Start with a deep clone of the base to ensure immutability
  const result = deepClone(base);

  for (const key in override) {
    const baseValue = result[key];
    const overrideValue = override[key];

    // Rule: ignore undefined values in override
    if (overrideValue === undefined) {
      continue;
    }

    // Rule: if both are plain objects, merge recursively
    if (isObject(baseValue) && isObject(overrideValue)) {
      result[key] = deepMerge(baseValue, overrideValue);
    } else {
      // Rule: otherwise replace (including arrays and null)
      // We deepClone the overrideValue to ensure the result shares no references
      result[key] = deepClone(overrideValue);
    }
  }

  return result;
}
```

**Explanation:**
- **Immutability:** The function uses a `deepClone` helper to ensure that the resulting object contains entirely new references for all nested objects and arrays, preventing side effects on the original `base` or `override` objects.
- **Logic:** It iterates through the `override` keys. If both values are plain objects, it recurses. If they are not (e.g., one is an array or a primitive), the `override` value replaces the base.
- **Edge Cases:** `undefined` is explicitly skipped, while `null` is treated as a valid replacement value. Arrays are treated as primitives (replaced, not merged) per your requirements.

