import datetime
import re

def parse_date(text: str) -> datetime.date:
    """
    Parses a date string into a datetime.date object.
    Supported formats:
    - ISO: 2025-03-07
    - British: 07/03/2025
    - Short text: 7 Mar 2025
    """
    clean_text = text.strip()

    # Format 1: ISO (YYYY-MM-DD)
    try:
        return datetime.datetime.strptime(clean_text, "%Y-%m-%d").date()
    except ValueError:
        pass

    # Format 2: British Numeric (DD/MM/YYYY)
    # We check format structure with regex first to avoid misinterpreting DD/MM/YYYY as MM/DD/YYYY
    if re.fullmatch(r"\d{2}/\d{2}/\d{4}", clean_text):
        try:
            return datetime.datetime.strptime(clean_text, "%d/%m/%Y").date()
        except ValueError:
            raise ValueError(f"Invalid date in British numeric format: {clean_text}")

    # Format 3: Short text (D MMM YYYY)
    # Matches "7 Mar 2025" or "07 Mar 2025"
    if re.fullmatch(r"\d{1,2} [A-Z][a-z]{2} \d{4}", clean_text):
        try:
            return datetime.datetime.strptime(clean_text, "%d %b %Y").date()
        except ValueError:
            raise ValueError(f"Invalid date in short text format: {clean_text}")

    raise ValueError(f"Date format not recognized or invalid date: {text}")
