function parseQuery(qs) {
  const result = {};
  if (!qs) return result;

  // Remove leading '?' if present
  const str = qs.startsWith('?') ? qs.slice(1) : qs;
  if (!str) return result;

  const pairs = str.split('&');

  for (const pair of pairs) {
    if (!pair) continue; // Skip empty pairs (e.g., '&&' or trailing '&')

    // Find the first '=' to separate key and value
    const eqIndex = pair.indexOf('=');
    let keyRaw, valRaw;

    if (eqIndex === -1) {
      keyRaw = pair;
      valRaw = "";
    } else {
      keyRaw = pair.slice(0, eqIndex);
      valRaw = pair.slice(eqIndex + 1);
    }

    // Helper to decode: replace '+' with space, then percent-decode
    const decode = (s) => decodeURIComponent(s.replace(/\+/g, ' '));

    const key = decode(keyRaw);
    const value = decode(valRaw);

    if (Object.prototype.hasOwnProperty.call(result, key)) {
      // If key exists, ensure it is an array and push new value
      if (Array.isArray(result[key])) {
        result[key].push(value);
      } else {
        result[key] = [result[key], value];
      }
    } else {
      // First time seeing this key
      result[key] = value;
    }
  }

  return result;
}
