long long parse_duration(const std::string& s) {
    if (s.empty()) return -1;

    // Regex captures groups: (number)(unit)
    // Uses a non-capturing group for the repetition to ensure the whole string is matched
    static const std::regex pattern(R"(^((?:\d+h)?(?:\d+m)?(?:\d+s)?)$)");
    std::smatch match;

    // First, validate overall structure and order via regex
    if (!std::regex_match(s, match)) {
        return -1;
    }

    // The regex above allows an empty match (if no digits are provided), 
    // but the prompt implies at least one part is needed.
    if (s.find_first_of("0123456789") == std::string::npos) {
        return -1;
    }

    long long total_seconds = 0;
    std::string remaining = s;

    // Units to look for in order
    const std::vector<std::pair<char, int>> units = {{'h', 3600}, {'m', 60}, {'s', 1}};

    for (auto const& [unit_char, multiplier] : units) {
        size_t pos = remaining.find(unit_char);
        if (pos != std::string::npos) {
            std::string num_part = remaining.substr(0, pos);

            // Check if there's a number before the unit
            if (num_part.empty()) return -1;

            // Convert to long long (problem guarantees no overflow)
            try {
                long long val = std::stoll(num_part);
                total_seconds += val * multiplier;
            } catch (...) {
                return -1;
            }

            // Remove the processed part (number + unit) from the string
            remaining.erase(0, pos + 1);
        }
    }

    // If characters remain, it means there was trailing garbage or invalid order
    if (!remaining.empty()) {
        return -1;
    }

    return total_seconds;
}
