long long parse_duration(const std::string& s) {
    if (s.empty()) return -1;

    size_t pos = 0;
    size_t len = s.size();

    long long total_seconds = 0;
    int last_unit_order = 3; // 2 for h, 1 for m, 0 for s. Start with 3 to allow any first unit.

    while (pos < len) {
        // Parse number
        size_t num_start = pos;
        if (pos >= len || !std::isdigit(static_cast<unsigned char>(s[pos]))) {
            return -1; // No digit at start of part
        }

        while (pos < len && std::isdigit(static_cast<unsigned char>(s[pos]))) {
            pos++;
        }

        if (pos == num_start) {
            return -1; // No digits consumed
        }

        long long number = 0;
        for (size_t i = num_start; i < pos; ++i) {
            number = number * 10 + (s[i] - '0');
        }

        // Parse unit
        if (pos >= len) {
            return -1; // Number without unit
        }

        char unit = s[pos];
        pos++;

        long long seconds = 0;
        int unit_order;

        switch (unit) {
            case 'h':
                seconds = number * 3600;
                unit_order = 2;
                break;
            case 'm':
                seconds = number * 60;
                unit_order = 1;
                break;
            case 's':
                seconds = number;
                unit_order = 0;
                break;
            default:
                return -1; // Unknown unit
        }

        // Check order: units must be in decreasing order of significance (h, m, s)
        if (unit_order >= last_unit_order) {
            return -1; // Wrong order or repeated unit (same order)
        }

        last_unit_order = unit_order;
        total_seconds += seconds;
    }

    return total_seconds;
}
