import datetime
import re


def parse_date(text: str) -> datetime.date:
    """
    Parse a date string from one of three supported formats:
    - ISO: 2025-03-07
    - British numeric: 07/03/2025 (day/month/year)
    - Short text: 7 Mar 2025 (English three-letter month; day with or without a leading zero)

    Surrounding whitespace is allowed. Any other input, including impossible dates,
    raises ValueError.
    """
    if not isinstance(text, str):
        raise ValueError("Input must be a string")

    text = text.strip()

    # Try ISO format: YYYY-MM-DD
    try:
        return datetime.date.fromisoformat(text)
    except (ValueError, AttributeError):
        pass

    # Try British numeric: DD/MM/YYYY
    british_match = re.fullmatch(r'(\d{2})/(\d{2})/(\d{4})', text)
    if british_match:
        day, month, year = map(int, british_match.groups())
        try:
            return datetime.date(year, month, day)
        except ValueError:
            raise ValueError(f"Invalid date: {text}")

    # Try short text: D MMM YYYY or DD MMM YYYY (e.g., "7 Mar 2025", "07 Mar 2025")
    short_match = re.fullmatch(r'(\d{1,2})\s+([A-Za-z]{3})\s+(\d{4})', text)
    if short_match:
        day_str, month_str, year_str = short_match.groups()
        # Validate the month abbreviation (case-insensitive)
        try:
            month_num = datetime.datetime.strptime(month_str.strip(), '%b').month
        except ValueError:
            raise ValueError(f"Invalid month abbreviation: {month_str}")
        day = int(day_str)
        year = int(year_str)
        try:
            return datetime.date(year, month_num, day)
        except ValueError:
            raise ValueError(f"Invalid date: {text}")

    raise ValueError(f"Unable to parse date: '{text}'. Supported formats: ISO (YYYY-MM-DD), British numeric (DD/MM/YYYY), Short text (D MMM YYYY)")
```

