function deepMerge(base, override) {
    if (base === null || base === undefined || typeof base !== 'object') {
        return cloneDeep(override);
    }
    if (override === null || override === undefined || typeof override !== 'object') {
        return cloneDeep(base);
    }

    const result = {};

    // Copy all keys from base
    for (const key of Object.keys(base)) {
        result[key] = cloneDeep(base[key]);
    }

    // Merge/replace with keys from override
    for (const key of Object.keys(override)) {
        const baseVal = base[key];
        const overrideVal = override[key];

        // undefined in override is ignored
        if (overrideVal === undefined) {
            continue;
        }

        // Both are plain objects -> recursive merge
        if (
            baseVal !== null &&
            typeof baseVal === 'object' &&
            !Array.isArray(baseVal) &&
            overrideVal !== null &&
            typeof overrideVal === 'object' &&
            !Array.isArray(overrideVal)
        ) {
            result[key] = deepMerge(baseVal, overrideVal);
        } else {
            // Override replaces (including arrays, null, primitives)
            result[key] = cloneDeep(overrideVal);
        }
    }

    return result;
}

function cloneDeep(value) {
    if (value === null || value === undefined) {
        return value;
    }
    if (Array.isArray(value)) {
        return value.map(item => cloneDeep(item));
    }
    if (typeof value === 'object') {
        const result = {};
        for (const key of Object.keys(value)) {
            result[key] = cloneDeep(value[key]);
        }
        return result;
    }
    // Primitive values are immutable, so just return them
    return value;
}
