long long parse_duration(const std::string& s) {
    if (s.empty()) return -1;

    size_t pos = 0;
    size_t len = s.size();

    long long total_seconds = 0;
    bool has_h = false, has_m = false, has_s = false;

    while (pos < len) {
        // Parse number
        if (pos >= len || !std::isdigit(static_cast<unsigned char>(s[pos]))) {
            return -1; // No digit at start of a part, or empty string handled above
        }

        long long num = 0;
        while (pos < len && std::isdigit(static_cast<unsigned char>(s[pos]))) {
            num = num * 10 + (s[pos] - '0');
            pos++;
        }

        // Parse unit
        if (pos >= len) {
            return -1; // Number without a unit
        }

        char unit = s[pos];
        pos++;

        switch (unit) {
            case 'h':
                if (has_h) return -1; // Repeated unit
                has_h = true;
                total_seconds += num * 3600;
                break;
            case 'm':
                if (has_m) return -1; // Repeated unit
                // Must come after h or be the first unit, but not after s
                if (has_s) return -1;
                has_m = true;
                total_seconds += num * 60;
                break;
            case 's':
                if (has_s) return -1; // Repeated unit
                if (has_h || has_m) {
                    // s can come after h or m
                } else {
                    // s as first unit is allowed? The problem says order h, m, s.
                    // "Units must appear in the order h, m, s" implies you can have just s.
                    // Let's allow s alone or after others.
                }
                has_s = true;
                total_seconds += num;
                break;
            default:
                return -1; // Unknown unit
        }
    }

    // Check that we consumed the entire string (pos == len)
    if (pos != len) {
        return -1;
    }

