def parse_date(text: str) -> datetime.date:
    """Parse a date string in ISO, British numeric, or Short text format."""
    # Strip surrounding whitespace
    text = text.strip()

    # Try ISO format: YYYY-MM-DD
    try:
        dt = datetime.strptime(text, "%Y-%m-%d")
        return dt.date()
    except ValueError:
        pass

    # Try British numeric format: DD/MM/YYYY
    try:
        dt = datetime.strptime(text, "%d/%m/%Y")
        return dt.date()
    except ValueError:
        pass

    # Try short text format: D MMM YYYY or DD MMM YYYY (e.g., "7 Mar 2025" or "07 Mar 2025")
    try:
        dt = datetime.strptime(text, "%d %b %Y")
        return dt.date()
    except ValueError:
        pass

    # If none of the formats matched, raise ValueError
    raise ValueError(f"Unable to parse date: '{text}'")
