function parseQuery(qs) {
  if (typeof qs !== 'string') return {};

  // Remove leading '?' if present
  if (qs.startsWith('?')) {
    qs = qs.substring(1);
  }

  const result = {};

  // Split by '&'
  const pairs = qs.split('&');

  for (let i = 0; i < pairs.length; i++) {
    const pair = pairs[i];

    // Skip empty pairs
    if (pair === '') continue;

    // Find the first '=' to split key and value
    const eqIndex = pair.indexOf('=');

    let key, value;

    if (eqIndex === -1) {
      // No '=' found: key is the whole string, value is ""
      key = pair;
      value = '';
    } else {
      key = pair.substring(0, eqIndex);
      value = pair.substring(eqIndex + 1);
    }

    // Decode '+' as space first, then percent-decode
    const decode = (str) => {
      return decodeURIComponent(str.replace(/\+/g, ' '));
    };

    const decodedKey = decode(key);
    const decodedValue = decode(value);

    // Handle duplicate keys
    if (result.hasOwnProperty(decodedKey)) {
      const existing = result[decodedKey];
      if (Array.isArray(existing)) {
        existing.push(decodedValue);
      } else {
        result[decodedKey] = [existing, decodedValue];
      }
    } else {
      result[decodedKey] = decodedValue;
    }
  }

  return result;
}
```

This function parses a query string into an object according to the specified rules: it handles optional leading `?`, splits on `&`, uses the first `=` to separate keys and values, decodes `+` as spaces followed by percent-decoding, assigns empty strings for keys without `=`, groups duplicate keys into arrays, and skips empty pairs.

