function deepMerge(base, override) {
  if (base === null || base === undefined || typeof base !== 'object') {
    return JSON.parse(JSON.stringify(override));
  }
  if (override === null || override === undefined || typeof override !== 'object') {
    return JSON.parse(JSON.stringify(base));
  }

  const result = {};

  // Copy all keys from base first
  for (const key of Object.keys(base)) {
    result[key] = deepClone(base[key]);
  }

  // Merge/override with keys from override
  for (const key of Object.keys(override)) {
    const overrideVal = override[key];

    // Ignore undefined values in override
    if (overrideVal === undefined) {
      continue;
    }

    const baseVal = base[key];

    // If both are plain objects (not null, not array), merge recursively
    if (
      isPlainObject(baseVal) && 
      isPlainObject(overrideVal)
    ) {
      result[key] = deepMerge(baseVal, overrideVal);
    } else {
      // Otherwise, replace with override value (deep clone it to avoid sharing references)
      result[key] = deepClone(overrideVal);
    }
  }

  return result;
}

function isPlainObject(value) {
  if (value === null || typeof value !== 'object') {
    return false;
  }
  const proto = Object.getPrototypeOf(value);
  return proto === null || proto === Object.prototype;
}

function deepClone(obj) {
  if (obj === null || obj === undefined || typeof obj !== 'object') {
    return obj;
  }
  if (Array.isArray(obj)) {
    return obj.map(item => deepClone(item));
  }
  const cloned = {};
  for (const key of Object.keys(obj)) {
    cloned[key] = deepClone(obj[key]);
  }
  return cloned;
}
```

This implementation ensures complete immutability by deep cloning all values. It recursively merges plain objects while replacing arrays, `null`, and primitive values from the override. Undefined values in the override are skipped, preserving the base value. All nested structures are independently cloned to prevent shared references between inputs and output.

