#include <string>
#include <cctype>

long long parse_duration(const std::string& s) {
    if (s.empty()) return -1;

    size_t i = 0;
    long long total_seconds = 0;
    bool seen_h = false;
    bool seen_m = false;
    bool seen_s = false;

    while (i < s.size()) {
        // Parse number: must start with a digit, no signs allowed
        if (!std::isdigit(s[i])) return -1;

        long long num = 0;
        while (i < s.size() && std::isdigit(s[i])) {
            num = num * 10 + (s[i] - '0');
            i++;
        }

        // Must be followed by a unit
        if (i >= s.size()) return -1;

        char unit = s[i];
        switch (unit) {
            case 'h':
                if (seen_h) return -1; // repeated unit
                seen_h = true;
                total_seconds += num * 3600;
                i++;
                break;
            case 'm':
                if (seen_m) return -1; // repeated unit
                // Must come after h or at start, but not after s
                if (seen_s) return -1;
                seen_m = true;
                total_seconds += num * 60;
                i++;
                break;
            case 's':
                if (seen_s) return -1; // repeated unit
                // Must come after h and/or m, but that's fine
                seen_s = true;
                total_seconds += num;
                i++;
                break;
            default:
                return -1; // unknown unit
        }
    }

    // At least one part must have been parsed
    if (total_seconds == 0 && !seen_h && !seen_m && !seen_s) {
        return -1;
    }

    return total_seconds;
}
```

