    typeof v === 'object' && v !== null && !Array.isArray(v);

  const mergeRec = (b, o) => {
    // result starts as shallow clone of base to avoid mutating it
    const res = { ...(b ?? {}) };

    // process override keys
    for (const key of Object.keys(o ?? {})) {
      const oVal = o[key];
