import re
from datetime import datetime, date

def parse_date(text: str) -> date:
    """Parse a date string in one of three strict formats.

    Accepted formats:
        1) ISO:        2025-03-07
        2) British numeric: 07/03/2025 (day/month/year, leading zeros optional)
        3) Short text:   7 Mar 2025 or 07 Mar 2025

    Surrounding whitespace is ignored. Any other format or an impossible
    date (e.g. 31/02/2025) raises ValueError.
    """
    s = text.strip()

    # ISO format
    iso = re.fullmatch(r'(\d{4})-(\d{2})-(\d{2})', s)
    if iso:
        y, m, d = map(int, iso.groups())
        try:
            return date(y, m, d)
        except ValueError as exc:
            raise ValueError(f"Invalid date: {text}") from exc

    # British numeric format
    br = re.fullmatch(r'(\d{1,2})/(\d{1,2})/(\d{4})', s)
    if br:
        d, m, y = map(int, br.groups())
        try:
            return date(y, m, d)
        except ValueError as exc:
            raise ValueError(f"Invalid date: {text}") from exc

    # Short text format
    st = re.fullmatch(r'(\d{1,2}) (\w{3}) (\d{4})', s, re.IGNORECASE)
    if st:
        d, mon, y = st.groups()
        try:
            dt = datetime.strptime(f"{d} {mon} {y}", "%d %b %Y")
            return dt.date()
        except ValueError as exc:
            raise ValueError(f"Invalid date: {text}") from exc

    raise ValueError(f"Unrecognized date format: {text}")    
