function parseQuery(qs) {
  if (!qs) return {};

  // strip leading ?
  if (qs[0] === '?') qs = qs.slice(1);

  const result = {};

  for (const part of qs.split('&')) {
    if (!part) continue;               // skip empty pairs

    // split at first '='
    const idx = part.indexOf('=');
    let keyStr, valStr;
    if (idx === -1) {                 // no '='
      keyStr = part;
      valStr = '';
    } else {
      keyStr = part.slice(0, idx);
      valStr = part.slice(idx + 1);
    }

