    const key = decodeURIComponent(keyStr.replace(/\+/g, ' '));
    const value = decodeURIComponent(valStr.replace(/\+/g, ' '));

    // store in object with array logic
    if (Object.prototype.hasOwnProperty.call(result, key)) {
      const current = result[key];
      if (Array.isArray(current)) {
        current.push(value);
      } else {
        result[key] = [current, value];
      }
    } else {
      result[key] = value;
    }
  }

  return result;
}
