/**
 * Deeply merge two configuration objects.
 * @param {Object} base    - The base configuration.
 * @param {Object} override - The overriding configuration.
 * @returns {Object} A new merged object.
 */
function deepMerge(base, override) {
  const result = {};

  // Helper to check plain objects (not Array, not null)
  const isPlainObject = (x) =>
    typeof x === 'object' && x !== null && !Array.isArray(x);

  // Merge keys from base
  for (const key of Object.keys(base)) {
    const bVal = base[key];
    if (Object.prototype.hasOwnProperty.call(override, key)) {
      const oVal = override[key];

      // Skip undefined (keep base)
      if (oVal === undefined) {
        result[key] = clone(bVal);
        continue;
      }

      // Recursively merge if both are plain objects
      if (isPlainObject(bVal) && isPlainObject(oVal)) {
        result[key] = deepMerge(bVal, oVal);
        continue;
      }

      // For all other cases, use override value
      result[key] = clone(oVal);
    } else {
      // Key only in base
      result[key] = clone(bVal);
    }
  }

  // Add any keys that exist only in override
  for (const key of Object.keys(override)) {
    if (Object.prototype.hasOwnProperty.call(base, key)) continue; // already handled
    const oVal = override[key];
    if (oVal !== undefined) {
      result[key] = clone(oVal);
    }
  }

  return result;

  /** Deep clone of a value (object, array, primitive). */
  function clone(val) {
    if (Array.isArray(val)) {
      return val.map(clone); // clone: wrapper for deep copy
    }
    if (isPlainObject(val)) {
      return deepMerge({}, val);
    }
    return val;
  }

  /** Wrapper recursion for array elements (deep clone). */
  function clone(x) {
    if (Array.isArray(x)) return x.map(clone);
    if (isPlainObject(x)) return deepMerge({}, x);
    return x;
  }
}
```

**Explanation**

* `deepMerge` creates a new object, never mutating inputs.  
* For each key in `override`, `undefined` keeps the base value; otherwise,
  if both values are plain objects, a recursive merge is performed; in all other
  cases the override value replaces the base.  
* The helper `clone` (via `clone`) performs a deep copy of objects and arrays
  to guarantee that the returned object shares no nested structure with the inputs.

