/**
 * Parse a raw query string into an object.
 * The function handles normalization of +, percent-encoding, repeated keys and missing values.
 *
 * @param {string} qs Raw query string, may start with ? or not.
 * @returns {Object} Plain object literal.
 */
function parseQuery(qs) {
  if (typeof qs !== 'string') return {};

  // Strip leading '?' if present
  if (qs.startsWith('?')) qs = qs.slice(1);

  const result = {};

  if (qs.length === 0) return result;

  const pairs = qs.split('&');
  for (let pair of pairs) {
    if (pair === '') continue; // Skip empty pairs

    let key, valueStr;

    const idx = pair.indexOf('=');
    if (idx === -1) {
      // No '=': key only
      key = pair;
      valueStr = '';
    } else {
      key = pair.slice(0, idx);
      valueStr = pair.slice(idx + 1);
    }

    // Decode + and percent-encoding
    const decode = (s) => decodeURIComponent(s.replace(/\+/g, ' '));
    const decodedKey = decode(key);
    const decodedValue = decode(valueStr);

    if (Object.prototype.hasOwnProperty.call(result, decodedKey)) {
      const existing = result[decodedKey];
      if (Array.isArray(existing)) {
        existing.push(decodedValue);
      } else {
        result[decodedKey] = [existing, decodedValue];
      }
    } else {
      result[decodedKey] = decodedValue;
    }
  }

  return result;
}
```

