long long parse_duration(const std::string& s) {
    if (s.empty()) return -1;

    std::regex re(R"((\d+)h)?((\d+)m)?((\d+)s)?");
    std::smatch m;
    if (!std::regex_full_match(s, m, re)) return -1;

    long long h = m[2].matched ? std::stoll(m[2]) : 0;
    long long m_ = m[4].matched ? std::stoll(m[4]) : 0;
    long long s_ = m[6].matched ? std::stoll(m[6]) : 0;

    // check that at least one part exists
    if (h == 0 && m_ == 0 && s_ == 0) return -1;

    // detect repeated unit or missing unit between one another
    if ((m[2].matched && !m[3].matched && m[4].matched) || // h present but m missing yet s present
        (m[4].matched && !m[5].matched && m[6].matched)    // m present but s missing
        )
        return -1;

    // Ensure proper order by verifying that we didn't skip any earlier unit
    if (m[3].matched || m[5].matched) // m_ matched but h missing; s_ matched but h or m missing
        return -1;

    return h * 3600 + m_ * 60 + s_;
}
