import re
from datetime import date, datetime

def parse_date(text: str) -> date:
    """
    Parse a date string in one of three accepted formats and return a
    datetime.date object. Raises ValueError for any other format or an
    impossible date.
    """
    s = text.strip()
    if not s:
        raise ValueError("empty input")

    # ISO 2025-03-07
    m = re.fullmatch(r"(?P<y>\d{4})-(?P<m>\d{2})-(?P<d>\d{2})", s)
    if m:
        year, month, day = map(int, (m.group("y"), m.group("m"), m.group("d")))
        try:
            return date(year, month, day)
        except ValueError as exc:
            raise ValueError(f"date {s!r} is invalid: {exc}") from None

    # British numeric 07/03/2025
    m = re.fullmatch(r"(?P<d>\d{2})/(?P<m>\d{2})/(?P<y>\d{4})", s)
    if m:
        day, month, year = map(int, (m.group("d"), m.group("m"), m.group("y")))
        try:
            return date(year, month, day)
        except ValueError as exc:
            raise ValueError(f"date {s!r} is invalid: {exc}") from None

    # Short text 7 Mar 2025
    try:
        dt = datetime.strptime(s, "%d %b %Y")
        return dt.date()
    except Exception:
        pass

    raise ValueError(f"'{text}' is not in an accepted date format")
