function parseQuery(qs) {
  if (typeof qs !== 'string') return {};

  // Remove leading '?' if present
  qs = qs.startsWith('?') ? qs.slice(1) : qs;

  const out = {};

  for (const part of qs.split('&')) {
    if (part === '') continue;           // skip empty pairs

    // Find the first '='
    const idx = part.indexOf('=');
    let rawKey, rawVal;
    if (idx === -1) {                    // no '='
      rawKey = part;
      rawVal = '';
    } else {
      rawKey = part.slice(0, idx);
      rawVal = part.slice(idx + 1);
    }

    // Replace '+' and percent‑decode
    const key = decodeURIComponent(rawKey.replace(/\+/g, ' '));
    const val = decodeURIComponent(rawVal.replace(/\+/g, ' '));

    if (out.hasOwnProperty(key)) {
      // already present – need an array
      if (Array.isArray(out[key]))
        out[key].push(val);
      else
        out[key] = [out[key], val];
    } else
      out[key] = val;
  }

  return out;
}
```

*The function strips an optional leading `?`, splits on `&`, handles duplicate keys by storing arrays, and decodes both `+` and percent‐encodings without using `URLSearchParams`.*

```javascript
/**
 * Deeply merge two service configuration objects.
 *
 * @param {Object} base      Original configuration.
 * @param {Object} override  Values that should override the base.
 * @returns {Object}        New object containing the merged result.
 */
function deepMerge(base, override) {
  // helper to test plain objects (not arrays, not null)
  const isPlainObject = (v) =>
    typeof v === 'object' && v !== null && !Array.isArray(v);

  // clone value recursively (used to avoid sharing references)
  const cloneValue = (val) => {
    if (Array.isArray(val)) return val.map(cloneValue);
    if (isPlainObject(val)) return deepMerge(val, {}); // merge with empty to clone
    return val; // primitives, functions, etc.
  };

  // create result object (does not share references)
  const result = {};

  // copy keys from base
  for (const key in base) {
    if (Object.prototype.hasOwnProperty.call(base, key)) {
      result[key] = cloneValue(base[key]);
    }
  }

  // override keys
  for (const key in override) {
    if (Object.prototype.hasOwnProperty.call(override, key)) {
      const overrideVal = override[key];
      if (overrideVal === undefined) continue; // ignore undefined

      const baseVal = base[key];

      if (isPlainObject(overrideVal) && isPlainObject(baseVal)) {
        // both are plain objects → merge recursively
        result[key] = deepMerge(baseVal, overrideVal);
      } else {
        // otherwise override (arrays or other types)
        result[key] = cloneValue(overrideVal);
      }
    }
  }

  return result;
}
```

**Explanation**  
* `deepMerge` copies all keys from `base`.  
* For every key in `override` an `undefined` is ignored; everything else replaces the base value.  
* When both values are plain objects (neither arrays nor `null`), it merges them recursively.  
* Arrays, primitives, functions, etc. are copied by value, ensuring the result never shares references with the inputs.

