#include <string>
#include <cctype>

long long parse_duration(const std::string& s) {
    if (s.empty()) return -1;

    // disallow spaces or signs anywhere
    for (char c : s) {
        if (std::isspace(static_cast<unsigned char>(c)) || c=='+' || c=='-')
            return -1;
    }

    int seen = 0;          // bitmask for h,m,s
    int last = -1;          // last unit index
    long long total = 0;    // seconds
    std::size_t i = 0;

    while (i < s.size()) {
        // parse a non‑empty number
        if (!std::isdigit(static_cast<unsigned char>(s[i]))) return -1;
        std::size_t start = i;
        while (i < s.size() && std::isdigit(static_cast<unsigned char>(s[i]))) ++i;
        long long num = std::stoll(s.substr(start, i - start));

        if (i >= s.size()) return -1;         // must be followed by a unit
        char unit = s[i++];
        int idx = -1;
        if (unit == 'h') idx = 0;
        else if (unit == 'm') idx = 1;
        else if (unit == 's') idx = 2;
        else return -1;                       // unknown unit

        if (seen & (1 << idx)) return -1;    // repeated unit
        if (idx < last) return -1;           // wrong order
        seen |= 1 << idx;
        last = idx;

        // add to total seconds
        if (idx==0) total += num * 3600;
        else if (idx==1) total += num * 60;
        else total += num;                   // seconds
    }

    return total;
}
```

The function scans the string, checking for spaces, signs, and ensuring the
units appear in the `h → m → s` order, at most once, and that each unit is
preceded by a number. It returns the computed number of seconds or –1 on
any format error.

