from datetime import date
from datetime import datetime


def parse_date(text: str) -> date:
    """Parse an invoice date from one of three accepted formats.

    Accepted formats (surrounding whitespace ignored):
      * ISO            -> '2025-03-07'
      * British numeric-> '07/03/2025' (day/month/year)
      * Short text     -> '7 Mar 2025' (English 3-letter month)

    Any other input, or an impossible date (e.g. 31/02/2025), raises ValueError.
    """
    if not isinstance(text, str):
        raise ValueError(f"Expected str, got {type(text).__name__}")

    stripped = text.strip()
    if not stripped:
        raise ValueError("empty date string")

    # 1. ISO: YYYY-MM-DD
    try:
        return date.fromisoformat(stripped)
    except ValueError:
        pass

    # 2. British numeric: DD/MM/YYYY
    if len(stripped) == 10 and stripped.count("/") == 2:
        try:
            day, month, year = (int(part) for part in stripped.split("/"))
            return date(year, month, day)
        except ValueError:
            pass

    # 3. Short text: D MMM YYYY (English three-letter month)
    parts = stripped.split()
    if len(parts) == 3 and parts[2].isdigit():
        try:
            day = int(parts[0])
            month = datetime.strptime(parts[1], "%b").month
            year = int(parts[2])
            return date(year, month, day)
        except (ValueError, OverflowError):
            pass

    raise ValueError(f"Unrecognized or invalid date: {text!r}")

```

The function tries each format in turn, converting to a real `date` (so impossible dates like `31/02/2025` fail naturally). If none match, it raises `ValueError`. Note that `%b` parsing is locale-dependent, so the short-text format assumes a default English locale.

