```javascript
function deepMerge(base, override) {
  const isPlainObject = (v) =>
    v !== null &&
    typeof v === "object" &&
    !Array.isArray(v) &&
    typeof Object.getPrototypeOf(v) === "object";

  if (
    override === undefined ||
    !isPlainObject(base) ||
    !isPlainObject(override)
  ) {
    // undefined overrides are ignored; anything else replaces the base value.
    return override;
  }

  const result = {};
  for (const key of Object.keys(base)) {
    result[key] = base[key];
  }
  for (const key of Object.keys(override)) {
    if (key in result) {
      result[key] = deepMerge(result[key], override[key]);
    } else {
      result[key] = override[key];
    }
  }
  // Strip keys that are undefined in override (base kept).
  for (const key of Object.keys(result)) {
    if (result[key] === undefined) {
      delete result[key];
    }
  }
  return result;
}
```

The function creates a fresh object at every level. Plain-object merging recurses; arrays, `null`, and other values are replaced wholesale. `undefined` in `override` is skipped so the base value survives, while `null` replaces it. Keys unique to `base` are copied over, and since each level is rebuilt, no nested object or array is shared with the inputs.

