#include <string>
#include <cctype>

long long parse_duration(const std::string& s) {
    long long total = 0;
    long long value = 0;
    char unit = '\0';
    bool have_unit = false;

    auto consume = [&](char expected) -> bool {
        if (s.empty() || s.back() != expected) return false;
        s.pop_back();
        have_unit = true;
        unit = expected;
        return true;
    };

    for (size_t i = 0; i < s.size(); ++i) {
        char c = s[i];
        if (!std::isdigit(static_cast<unsigned char>(c))) return -1;
        value = value * 10 + (c - '0');
        if (!consume('h') && !consume('m') && !consume('s')) return -1;
        total += value * (unit == 'h' ? 3600LL : unit == 'm' ? 60LL : 1LL);
        value = 0;
    }

    if (s.empty() || !have_unit) return -1;
    return total;
}
```

