```javascript
function deepMerge(base, override) {
  return merge(base, override);

  function merge(a, b) {
    // Start from a copy of the base so we never mutate it.
    const result = Array.isArray(a) ? [] : { ...a };

    // b is undefined -> nothing to merge; keep base value.
    if (b === undefined) return result;

    // b is null -> replace with null.
    if (b === null) {
      result = null;
      return result;
    }

    // If b is an array, replace entirely (no concatenation).
    if (Array.isArray(b)) {
      result = [...b];
      return result;
    }

    // If a is not a plain object but b is, b replaces a.
    if (!isPlainObject(a)) {
      result = { ...b };
      return result;
    }

    // Both are plain objects -> merge key by key.
    for (const key of Object.keys(b)) {
      const baseVal = a[key];
      const overrideVal = b[key];

      if (isPlainObject(baseVal) && isPlainObject(overrideVal)) {
        result[key] = merge(baseVal, overrideVal);
      } else {
        result[key] = overrideVal;
      }
    }

    return result;
  }

  function isPlainObject(value) {
    return (
      value !== null &&
      typeof value === 'object' &&
      !Array.isArray(value)
    );
  }
}
```

The recursion builds a fresh object at every level, so the result never shares nested references with the inputs and mutating it can't affect them. Arrays are replaced wholesale, `undefined` is skipped, and `null` replaces.

One note: `isPlainObject` treats any non-null, non-array object as plain. If your configs could contain class instances or special objects you want to treat as leaf values, tighten the check to verify the prototype is `Object`.

