#include <string>
#include <cctype>

long long parse_duration(const std::string& s) {
    long long total = 0;
    int order = 0;          // 0=h, 1=m, 2=s
    bool any = false;

    std::size_t i = 0;
    while (i < s.size()) {
        // No spaces or signs allowed anywhere.
        if (std::isspace(static_cast<unsigned char>(s[i])) ||
            std::issigned(s[i]))
            return -1;

        // Read the whole number of digits.
        std::size_t start = i;
        while (i < s.size() && std::isdigit(static_cast<unsigned char>(s[i])))
            ++i;
        if (i == start)            // number without a unit
            return -1;
        long long value = 0;
        for (std::size_t j = start; j < i; ++j)
            value = value * 10 + (s[j] - '0');

        // Read exactly one unit character.
        if (i >= s.size())
            return -1;
        char unit = s[i++];
        if (unit != 'h' && unit != 'm' && unit != 's')
            return -1;

        any = true;

        int u = (unit == 'h') ? 0 : (unit == 'm') ? 1 : 2;
        if (u < order)             // unit out of order (h,m,s)
            return -1;
        order = u;

        long long mult = (long long)1 << (2 * u);  // h=3600, m=60, s=1
        total += value * mult;
    }

    return any ? total : -1;      // empty string
}
```

The loop reads a number then a single unit per part, rejecting spaces, signs, missing numbers or units, unknown units, and any unit appearing before `h`/`m`/`s`. It returns `-1` for empty input once the string is fully consumed.

