```javascript
function deepMerge(base, override) {
  const result = {};

  // Copy own enumerable keys from base
  for (const key of Object.keys(base)) {
    result[key] = base[key];
  }

  // Copy own enumerable keys from override
  for (const key of Object.keys(override)) {
    const overrideValue = override[key];

    // undefined is ignored; keep the base value
    if (overrideValue === undefined) {
      continue;
    }

    const baseValue = base[key];

    // Recursively merge only when both values are non-null plain objects
    if (
      isPlainObject(baseValue) &&
      isPlainObject(overrideValue)
    ) {
      result[key] = deepMerge(baseValue, overrideValue);
    } else {
      // null and everything else replace the base value
      result[key] = overrideValue;
    }
  }

  return result;
}

function isPlainObject(value) {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}
```

The function iterates over each input's own enumerable keys, copying values into a fresh result object. When both values at a key are non-null plain objects, it recurses; otherwise the override value replaces the base value (including `null`). `undefined` in the override is skipped so the base value is retained. Because every assignment creates a new object/array, the inputs and the result are fully independent.

