long long parse_duration(const std::string& s) {
    long long total = 0;
    long long current = 0;
    bool seen_h = false, seen_m = false, seen_s = false;

    size_t i = 0, n = s.size();
    while (i < n) {
        // Parse digits
        while (i < n && std::isdigit((unsigned char)s[i])) {
            current = current * 10 + (s[i] - '0');
            ++i;
        }
        if (i == n) break; // no unit -> invalid

        char unit = s[i];
        if (unit == 'h' || unit == 'm' || unit == 's') {
            switch (unit) {
                case 'h':
                    if (seen_h) return -1;
                    seen_h = true;
                    total += current * 3600;
                    break;
                case 'm':
                    if (seen_m) return -1;
                    seen_m = true;
                    total += current * 60;
                    break;
                case 's':
                    if (seen_s) return -1;
                    seen_s = true;
                    total += current;
                    break;
            }
            current = 0;
            ++i;
        } else {
            return -1; // unknown unit, sign, space, or empty
        }
    }

    return total;
}
```

**Notes**

- **Empty string**: the loop never runs, so `total` stays `0`. To distinguish "no input" from "valid `0h`", you'd normally want to reject an empty string explicitly. If that's important for your use case, add a guard at the top: `if (s.empty()) return -1;`.
- **Whitespace / signs**: spaces, `+`/`-`, and any non-digit/non-unit character fall into the `else` branch and return `-1`.
- **Order enforcement**: `h` → `m` → `s` is enforced by the `seen_*` flags; a repeated unit also returns `-1`, which covers both "repeated" and "out-of-order" cases.
- **Overflow**: numbers won't overflow per the spec, and `long long` accumulates comfortably.

