```javascript
function deepMerge(base, override) {
  // Both values are plain objects -> merge recursively
  if (
    base !== null &&
    typeof base === 'object' &&
    override !== null &&
    typeof override === 'object' &&
    !Array.isArray(base) &&
    !Array.isArray(override)
  ) {
    const result = { ...base };

    for (const key of Object.keys(override)) {
      const overrideValue = override[key];
      const baseValue = base[key];

      // undefined in override is ignored; keep the base value
      if (overrideValue === undefined) continue;

      // Both are plain objects -> recurse
      if (
        baseValue !== null &&
        typeof baseValue === 'object' &&
        !Array.isArray(baseValue) &&
        overrideValue !== null &&
        typeof overrideValue === 'object' &&
        !Array.isArray(overrideValue)
      ) {
        result[key] = deepMerge(baseValue, overrideValue);
      } else {
        // Otherwise override replaces base (arrays, null, primitives)
        result[key] = overrideValue;
      }
    }

    return result;
  }

  // Not both plain objects -> override replaces base entirely
  return override;
}
```

**How it works:**

- **Both plain objects** → create a shallow copy of `base`, then recurse into shared keys. The `{ ...base }` guarantees `base` isn't mutated and the result owns fresh nested objects.
- **Otherwise** (arrays, primitives, `null`, or a type mismatch) → `override` replaces `base` wholesale, so arrays are replaced, not concatenated, and `null` is honored.
- **`undefined` in `override`** → `continue` skips it, preserving the base value.
- **Keys only in `base`** → copied via `{ ...base }`.
- **`base` is `undefined`** → falls through to the final `return override`, which is correct (merging into an empty/missing base yields the override).

```cpp
#include <string>
#include <cctype>

long long parse_duration(const std::string& s) {
    long long total = 0;
    long long current = 0;
    int unit_order = -1; // -1 = none, 0 = h, 1 = m, 2 = s

    for (std::size_t i = 0; i < s.size(); ++i) {
        char c = s[i];

        // Reject spaces and any sign characters
        if (c == ' ' || c == '+' || c == '-')
            return -1;

        // A digit starts a new number part
        if (std::isdigit(static_cast<unsigned char>(c))) {
            current = 0;
            while (i + 1 < s.size() && std::isdigit(static_cast<unsigned char>(s[i + 1]))) {
                current = current * 10 + (s[i + 1] - '0');
                ++i;
            }
            continue; // the unit must follow in the next iteration
        }

        // A letter must be a valid unit
        if (c == 'h') {
            if (unit_order != -1) return -1; // repeated unit
            unit_order = 0;
            if (current == 0) return -1;     // unit without a number
            total += current * 3600;
        } else if (c == 'm') {
            if (unit_order != 0) return -1;   // wrong order or repeated
            unit_order = 1;
            if (current == 0) return -1;
            total += current * 60;
        } else if (c == 's') {
            if (unit_order != 1) return -1;   // wrong order or repeated
            unit_order = 2;
            if (current == 0) return -1;
            total += current;
        } else {
            return -1; // unknown unit
        }

        current = 0; // reset for the next number
    }

    // Empty string, number without a unit, or trailing digits => invalid
    return (s.empty() || current != 0) ? -1 : total;
}
```

The parser walks the string once. It rejects spaces and sign characters immediately, treats each run of digits as a pending value, and requires that run to be followed by a unit. Units `h`/`m`/`s` are only accepted if the previous unit matched the expected order, and a unit with no preceding number is rejected. If the string ends while digits are still pending (e.g. `1h30` or empty), it returns `-1`.

