from collections import OrderedDict

class TTLCache:
    def __init__(self, capacity: int, ttl: int):
        self.capacity = capacity
        self.ttl = ttl
        # OrderedDict maintains insertion/access order for LRU behavior
        self.cache = OrderedDict() 
        # Store as {key: (value, expiry_time)}

    def put(self, key: str, value: any, now: int) -> None:
        expiry = now + self.ttl

        if key in self.cache:
            # Update existing: move to end (MRU) and update value/expiry
            self.cache.move_to_end(key)
            self.cache[key] = (value, expiry)
        else:
            # New key logic
            if len(self.cache) >= self.capacity:
                # 1. Remove all expired entries first
                expired_keys = [k for k, v in self.cache.items() if now >= v[1]]
                for k in expired_keys:
                    del self.cache[k]

                # 2. If still full, remove LRU (the first item in OrderedDict)
                if len(self.cache) >= self.capacity:
                    self.cache.popitem(last=False)

            self.cache[key] = (value, expiry)

    def get(self, key: str, now: int) -> any:
        if key not in self.cache:
            return None

        val, expiry = self.cache[key]
        if now >= expiry:
            del self.cache[key]
            return None

        # Successful get makes it MRU
        self.cache.move_to_end(key)
        return val

    def size(self, now: int) -> int:
        count = 0
        for val, expiry in self.cache.values():
            if now < expiry:
                count += 1
        return count
```

### Explanation:
- **Data Structure**: I used `collections.OrderedDict` to track the Least Recently Used (LRU) order. The end of the dict represents the Most Recently Used (MRU) items.
- **`put` logic**: If a new key is added to a full cache, it iterates to clear expired items first. If the capacity is still exceeded, it pops from the front (`last=False`), which is the oldest/LRU entry.
- **`get` logic**: It checks for existence and expiration. If valid, it uses `move_to_end` to refresh the LRU position without updating the expiry timestamp.
- **Complexity**: `get` and `put` (for existing keys) are $O(1)$ average. `put` (for new keys in full cache) and `size` are $O(N)$ in the worst case due to the requirement to check/remove all expired entries.

