  // Helper to deep clone to ensure immutability
  const clone = (val) => {
    if (Array.isArray(val)) return val.map(clone);
    if (val !== null && typeof val === 'object') {
      const newObj = {};
      for (const key in val) {
        newObj[key] = clone(val[key]);
      }
      return newObj;
    }
    return val;
  };

  let currentDoc = clone(doc);

  for (const { op, path, value } of ops) {
    if (path === "") {
      if (op === "add") currentDoc = value;
      else if (op === "replace") {
        if (currentDoc === undefined) throw new Error("Target missing");
        currentDoc = value;
      } else throw new Error("Invalid op for root");
      continue;
    }

    const segments = path.split('/').filter((s, i) => i > 0 || s !== "");
    let current = currentDoc;

    // Navigate to the parent of the target
    for (let i = 0; i < segments.length - 1; i++) {
      const segment = decodeSegment(segments[i]);
      if (current === null || typeof current !== 'object') throw new Error("Parent missing");
      current = current[segment];
    }

    const lastSegment = decodeSegment(segments[segments.length - 1]);
    const isNumeric = /^\d+$/.test(lastSegment);
    const idx = isNumeric ? parseInt(lastSegment, 10) : null;

    if (op === "add") {
      if (Array.isArray(current)) {
        let insertIdx = idx;
        if (insertIdx === -1 || insertIdx === undefined) insertIdx = current.length;
        if (insertIdx < 0 || insertIdx > current.length) throw new Error("Index out of range");

        current.splice(insertIdx, 0, value);
      } else if (current !== null && typeof current === 'object') {
        current[lastSegment] = value;
      } else throw new Error("Add requires object or array");
    } else if (op === "remove") {
      if (Array.isArray(current)) {
        if (idx === null || idx < 0 || idx >= current.length) throw new Error("Index out of range");
        current.splice(idx, 1);
      } else if (current !== null && typeof current === 'object') {
        if (!(lastSegment in current)) throw new Error("Target missing");
        delete current[lastSegment];
      } else throw new Error("Parent missing");
    } else if (op === "replace") {
      if (Array.isArray(current)) {
        if (idx === null || idx < 0 || idx >= current.length) throw new Error("Index out of range");
        current[idx] = value;
      } else if (current !== null && typeof current === 'object') {
        if (!(lastSegment in current)) throw new Error("Target missing");
        current[lastSegment] = value;
      } else throw new Error("Parent missing");
    } else {
      throw new Error("Unknown op");
    }
  }

