import re

def satisfies(version: str, range_: str) -> bool:
    def parse_version(v_str: str):
        return tuple(map(int, v_str.split('.')))

    def compare(v1, v2):
        return (v1 > v2) - (v1 < v2)

    def check_comparator(v_tuple, comp_str):
        match = re.match(r'([<>=~^]*)(\d+\.\d+\.\d+)', comp_str.strip())
        if not match:
            return False
        ops, v_str = match.groups()
        v_target = parse_version(v_str)

        # Handle operators
        if not ops: # Implicit equality
            return v_tuple == v_target
        if ops == "=" or ops == "==":
            return v_tuple == v_target
        if ops == ">":
            return compare(v_tuple, v_target) > 0
        if ops == ">=":
            return compare(v_tuple, v_target) >= 0
        if ops == "<":
            return compare(v_tuple, v_target) < 0
        if ops == "<=":
            return compare(v_tuple, v_target) <= 0
        if ops == "~":
            # >= v.x.y and < v.(x+1).0
            return (v_tuple >= v_target and 
                    v_tuple < (v_target[0], v_target[1] + 1, 0))
        if ops == "^":
            # Logic for caret
            major, minor, patch = v_target
            if major > 0:
                # >= v.x.y and < (v+1).0.0
                return (v_tuple >= v_target and 
                        v_tuple < (major + 1, 0, 0))
            elif minor > 0:
                # >= v.x.y and < v.(x+1).0
                return (v_tuple >= v_target and 
                        v_tuple < (0, minor + 1, 0))
            else:
                # >= v.x.y and < v.x.(y+1)
                return (v_tuple >= v_target and 
                        v_tuple < (0, 0, patch + 1))
        return False

    current_v = parse_version(version)
    # Split by OR
    alternatives = range_.split("||")

    for alt in alternatives:
        # Split by spaces to get comparators
        comparators = alt.split()
        if not comparators:
            continue

        # Version satisfies the alternative if it satisfies ALL comparators
        match_all = True
        for comp in comparators:
            if not check_comparator(current_v, comp):
                match_all = False
                break

        if match_all:
            return True

    return False
