def satisfies(version: str, range_: str) -> bool:
    def parse(v: str) -> tuple[int, int, int]:
        parts = v.split(".")
        if len(parts) != 3:
            raise ValueError(f"Invalid version: {v}")
        return tuple(int(p) for p in parts)

    def cmp(a: tuple[int, int, int], b: tuple[int, int, int]) -> int:
        for x, y in zip(a, b):
            if x != y:
                return 1 if x > y else -1
        return 0

    def check(comparator: str, v: tuple[int, int, int]) -> bool:
        op = ""
        num_str = comparator
        for ch in comparator:
            if ch in "=<>~^":
                op += ch
            else:
                break
        rest = comparator[len(op):]
        t = parse(rest)

        if op == "" or op == "=":
            return cmp(v, t) == 0
        if op == ">":
            return cmp(v, t) > 0
        if op == ">=":
            return cmp(v, t) >= 0
        if op == "<":
            return cmp(v, t) < 0
        if op == "<=":
            return cmp(v, t) <= 0
        if op == "~":
            # ~M.m.p => >= M.m.p and < M.(m+1).0
            upper = (t[0], t[1] + 1, 0)
            return cmp(v, t) >= 0 and cmp(v, upper) > 0
        if op == "^":
            # ^M.m.p => >= M.m.p and < next "significant" version
            if t[0] == 0:
                if t[1] == 0:
                    upper = (0, 0, t[2] + 1)
                else:
                    upper = (0, t[1] + 1, 0)
            else:
                upper = (t[0] + 1, 0, 0)
            return cmp(v, t) >= 0 and cmp(v, upper) > 0
        raise ValueError(f"Unknown comparator: {comparator}")

    v = parse(version)
    for alt in range_.split("||"):
        alts = [c.strip() for c in alt.split()]
        if all(check(c, v) for c in alts):
            return True
    return False
