    const rawSegments = path.slice(1).split("/");
    const segments = rawSegments.map(s => s.replace(/~1/g, "/").replace(/~0/g, "~"));

    // Walk to the parent node
    let node = clone;
    for (let i = 0; i < segments.length - 1; i++) {
      const seg = segments[i];
      if (Array.isArray(node)) {
        const idx = Number(seg);
        if (!Number.isInteger(idx) || idx < 0 || idx >= node.length) {
          throw new Error(`Invalid array index: ${seg}`);
        }
        node = node[idx];
      } else if (typeof node === "object" && node !== null) {
        if (!(seg in node)) {
          throw new Error(`Parent member not found: ${seg}`);
        }
        node = node[seg];
      } else {
        throw new Error(`Cannot traverse into non-object/array at segment: ${seg}`);
      }
    }

    const lastSeg = segments[segments.length - 1];

    if (Array.isArray(node)) {
      const idx = Number(lastSeg);
      if (!Number.isInteger(idx) || idx < 0) {
        throw new Error(`Invalid array index: ${lastSeg}`);
      }

      switch (op.op) {
        case "add":
          if (idx > node.length) {
