from collections import OrderedDict

class TTLCache:
    def __init__(self, capacity: int, ttl: int):
        self.capacity = capacity
        self.ttl = ttl
        # key -> (value, expiry_time)
        self._data = OrderedDict()

    def _purge_expired(self, now: int) -> None:
        """Remove all entries expired at `now` from the cache."""
        expired_keys = [k for k, (_, exp) in self._data.items() if now >= exp]
        for k in expired_keys:
            del self._data[k]

    def put(self, key, value, now: int) -> None:
        # Update existing entry or insert new one.
        if key in self._data:
            # Move to most-recently-used position; reset expiry.
            del self._data[key]
            self._data[key] = (value, now + self.ttl)
        else:
            # Purge expired entries first when adding a new key and cache is full.
            if len(self._data) >= self.capacity:
                self._purge_expired(now)
                if len(self._data) >= self.capacity:
                    # Still full: evict least recently used.
                    del self._data[next(iter(self._data))]
            self._data[key] = (value, now + self.ttl)

    def get(self, key, now: int):
        if key not in self._data:
            return None
        value, expiry = self._data[key]
        if now >= expiry:
            del self._data[key]
            return None
        # Successful get: make most recently used, keep expiry unchanged.
        del self._data[key]
        self._data[key] = (value, expiry)
        return value

    def size(self, now: int) -> int:
        """Count non-expired entries at `now` without mutating the cache."""
        return sum(1 for _, (_, exp) in self._data.items() if now < exp)
```

The cache uses an `OrderedDict` to track recency (most recent at the end). Expired entries are lazily removed on access (`get`) and proactively purged before eviction in `put`. `size` counts live entries without side effects.

