                ok &= cmp(v, lo) >= 0 and cmp(v, hi) < 0
                continue
            elif c[0] == "^":
                p = parse(c[1:])
                if p[0] == 0:
                    hi = (p[0], p[1] + 1, 0) if p[1] > 0 else (p[0], p[1], p[2] + 1)
                else:
                    hi = (p[0] + 1, 0, 0)
                ok &= cmp(v, p) >= 0 and cmp(v, hi) < 0
                continue
            else:
                ver = parse(c)
                op = "="

            if op is None:
                raise ValueError(f"Invalid comparator: {c}")
            r = cmp(v, ver)
            if op == "=" and r != 0: ok = False
            elif op == ">" and r <= 0: ok = False
            elif op == "<" and r >= 0: ok = False
            elif op == ">=" and r < 0: ok = False
            elif op == "<=" and r > 0: ok = False
            if not ok: break
        if ok:
            return True
    return False
