function applyPatch(doc, ops) {
  // Deep-clone so we never mutate the original document.
  const clone = (v) => {
    if (Array.isArray(v)) return v.map(clone);
    if (v && typeof v === 'object') {
      const o = {};
      for (const k of Object.keys(v)) o[k] = clone(v[k]);
      return o;
    }
    return v;
  };

  let current = clone(doc);

  const decodeSegment = (seg) => seg.replace(/~1/g, '/').replace(/~0/g, '~');

  for (const { op, path, value } of ops) {
    if (op !== 'add' && op !== 'remove' && op !== 'replace') {
      throw new Error(`Unknown op: ${op}`);
    }

    if (path === '') {
      // Whole-document operations
      if (op === 'add') {
        current = clone(value);
      } else if (op === 'remove') {
        throw new Error('Cannot remove the whole document');
      } else if (op === 'replace') {
        current = clone(value);
      }
      continue;
    }

    if (!path.startsWith('/')) {
      throw new Error(`Invalid path: ${path}`);
    }

    const rawSegments = path.slice(1).split('/');
    const segments = rawSegments.map(decodeSegment);

    // Walk down to the parent of the target.
    let node = current;
    for (let i = 0; i < segments.length - 1; i++) {
      const seg = segments[i];
      if (Array.isArray(node)) {
        const idx = Number(seg);
        if (!Number.isInteger(idx) || idx < 0 || idx >= node.length) {
          throw new Error(`Invalid array index: ${seg}`);
        }
        node = node[idx];
      } else if (node && typeof node === 'object') {
        if (!Object.prototype.hasOwnProperty.call(node, seg)) {
          throw new Error(`Missing parent member: ${seg}`);
        }
        node = node[seg];
      } else {
        throw new Error(`Cannot traverse into non-object/array at segment: ${seg}`);
      }
    }

    const targetSeg = segments[segments.length - 1];

    if (Array.isArray(node)) {
      let idx;
      if (targetSeg === '-') {
        idx = node.length;
      } else {
        idx = Number(targetSeg);
        if (!Number.isInteger(idx) || idx < 0) throw new Error(`Invalid array index: ${targetSeg}`);
      }

      if (op === 'add') {
        if (idx > node.length) throw new Error(`Array index out of range: ${idx}`);
        node.splice(idx, 0, clone(value));
      } else if (op === 'remove') {
        if (idx >= node.length) throw new Error(`Array element not found at index: ${idx}`);
        node.splice(idx, 1);
      } else if (op === 'replace') {
        if (idx >= node.length) throw new Error(`Array element not found at index: ${idx}`);
        node[idx] = clone(value);
      }
    } else if (node && typeof node === 'object') {
      if (op === 'add') {
        node[targetSeg] = clone(value);
      } else if (op === 'remove') {
        if (!Object.prototype.hasOwnProperty.call(node, targetSeg)) {
          throw new Error(`Missing member to remove: ${targetSeg}`);
        }
        delete node[targetSeg];
      } else if (op === 'replace') {
        if (!Object.prototype.hasOwnProperty.call(node, targetSeg)) {
          throw new Error(`Missing member to replace: ${targetSeg}`);
        }
        node[targetSeg] = clone(value);
      }
    } else {
      throw new Error(`Target is not an object or array`);
    }
