                return v >= n and v < (n[0] + 1, 0, 0)
            elif n[1] > 0:
                # ^0.2.3 => >=0.2.3 and <0.3.0
                return v >= n and v < (0, n[1] + 1, 0)
            else:
                # ^0.0.3 => >=0.0.3 and <0.0.4
                return v >= n and v < (0, 0, n[2] + 1)
        raise ValueError(f"Unknown comparator: {cmp}")

    for alt in range_.split('||'):
        comps = [c.strip() for c in alt.split() if c.strip()]
        if all(check(c, version) for c in comps):
            return True
    return False
