def build_order(deps: dict[str, list[str]]) -> list[str]:
    # Collect all targets (keys + names appearing in dependency lists)
    targets = set(deps.keys())
    for deps_list in deps.values():
        targets.update(deps_list)

    # Build reverse adjacency: target -> list of targets that depend on it
    # Actually, we need: for each target, its dependencies (already given)
    # We'll track how many unmet dependencies each target has.

    # dep_count[target] = number of dependencies not yet built
    # dependents[target] = list of targets that depend on target (for when we build target, decrement their count)

    dep_count = {}
    dependents = {t: [] for t in targets}

    for target, deps_list in deps.items():
        dep_count[target] = len(deps_list)
        for d in deps_list:
            dependents[d].append(target)

    # Targets not in deps.keys() have no dependencies
    for t in targets:
        if t not in dep_count:
            dep_count[t] = 0

    # Use a min-heap (or sorted approach) to pick alphabetically smallest ready target
    import heapq

    # Initially, all targets with 0 deps are ready
    ready = []
    for t in targets:
        if dep_count[t] == 0:
            heapq.heappush(ready, t)

    order = []
    built = set()

    while ready:
        t = heapq.heappop(ready)
        if t in built:
            continue
        built.add(t)
        order.append(t)

        # For each target that depends on t, decrement its dep_count
        for dependent in dependents[t]:
            dep_count[dependent] -= 1
            if dep_count[dependent] == 0 and dependent not in built:
                heapq.heappush(ready, dependent)

    if len(order) != len(targets):
        raise ValueError("Cycle detected in dependencies")

    return order
```

