from collections import OrderedDict

class TTLCache:
    def __init__(self, capacity: int, ttl: int):
        self.capacity = capacity
        self.ttl = ttl
        # key -> (value, expiry)
        self._cache = OrderedDict()  # insertion order = least-recently-used first

    def put(self, key, value, now: int) -> None:
        # Remove expired entries first (only needed when adding a new key and cache is full,
        # but doing it always keeps size accurate and simplifies logic)
        self._purge_expired(now)

        if key in self._cache:
            # Update value and expiry; move to end (most recently used)
            self._cache[key] = (value, now + self.ttl)
            self._cache.move_to_end(key)
        else:
            if len(self._cache) >= self.capacity:
                # Cache is full: remove expired (already purged), then LRU
                del self._cache[next(iter(self._cache))]
            self._cache[key] = (value, now + self.ttl)

    def get(self, key, now: int):
        if key not in self._cache:
            return None
        value, expiry = self._cache[key]
        if now >= expiry:
            # Expired: remove it
            del self._cache[key]
            return None
        # Successful get: make most recently used, but do NOT change expiry
        self._cache.move_to_end(key)
        return value

    def size(self, now: int) -> int:
        self._purge_expired(now)
        return len(self._cache)

    def _purge_expired(self, now: int):
        expired = [k for k, (_, exp) in self._cache.items() if now >= exp]
        for k in expired:
            del self._cache[k]
