        ref = parse(ver_str)
        c = cmp(v, ref)
        if op == '=':
            return c == 0
        if op == '>':
            return c > 0
        if op == '<':
            return c < 0
        if op == '>=':
            return c >= 0
        if op == '<=':
            return c <= 0
        if op == '~':
            # ~1.2.3 means >=1.2.3 and <1.3.0
            upper = (ref[0], ref[1] + 1, 0)
            return cmp(v, ref) >= 0 and cmp(v, upper) < 0
        if op == '^':
            # ^1.2.3 means >=1.2.3 and <2.0.0
            # ^0.2.3 means >=0.2.3 and <0.3.0
            # ^0.0.3 means >=0.0.3 and <0.0.4
            if ref[0] == 0:
                if ref[1] == 0:
                    upper = (0, 0, ref[2] + 1)
                else:
                    upper = (0, ref[1] + 1, 0)
            else:
                upper = (ref[0] + 1, 0, 0)
            return cmp(v, ref) >= 0 and cmp(v, upper) < 0
        raise ValueError(f"Unknown comparator: {comp}")

    v = parse(version)
    for alt in range_.split('||'):
        if all(check(c, v) for c in alt.split()):
