def build_order(deps: dict[str, list[str]]) -> list[str]:
    """Return a deterministic topological ordering of build targets."""
    # Collect all targets (keys plus names that appear only in dependency lists)
    all_targets = set(deps.keys())
    for deps_list in deps.values():
        all_targets.update(deps_list)

    # Normalize: every target has an explicit dependency list (possibly empty)
    dep_map: dict[str, list[str]] = {t: list(deps.get(t, [])) for t in all_targets}

    # Kahn's algorithm with a min-heap for deterministic tie-breaking
    import heapq

    in_degree: dict[str, int] = {t: len(dep_map[t]) for t in all_targets}
    dependents: dict[str, list[str]] = {t: [] for t in all_targets}
    for target, deps_list in dep_map.items():
        for d in deps_list:
            dependents[d].append(target)

    # Start with targets that have no dependencies
    heap = [t for t in all_targets if in_degree[t] == 0]
    heapq.heapify(heap)

    order: list[str] = []
    while heap:
        target = heapq.heappop(heap)
        order.append(target)
        for dependent in dependents[target]:
            in_degree[dependent] -= 1
            if in_degree[dependent] == 0:
                heapq.heappush(heap, dependent)

    if len(order) != len(all_targets):
        raise ValueError("Cycle detected in dependency graph")

    return order
