          if (!Object.prototype.hasOwnProperty.call(node, seg)) throw new Error(`Parent does not exist at path ${path}`);
          node = node[seg];
        }
      }

      const lastSeg = segments[segments.length - 1];
      if (Array.isArray(node)) {
        const idx = parseIndex(lastSeg);
        if (idx < 0 || idx >= node.length) throw new Error(`Target does not exist`);
        node.splice(idx, 1);
      } else if (typeof node === 'object' && node !== null) {
        if (!Object.prototype.hasOwnProperty.call(node, lastSeg)) throw new Error(`Target does not exist`);
        delete node[lastSeg];
      } else {
        throw new Error(`Target does not exist`);
      }

    } else if (type === 'replace') {
      const segments = decodePath(path);
      let node = result;
      for (let i = 0; i < segments.length - 1; i++) {
        const seg = segments[i];
        if (typeof node !== 'object' || node === null) throw new Error(`Parent does not exist at path ${path}`);
        if (Array.isArray(node)) {
          const idx = parseIndex(seg);
          if (idx < 0 || idx >= node.length) throw new Error(`Array index out of range`);
          node = node[idx];
        } else {
          if (!Object.prototype.hasOwnProperty.call(node, seg)) throw new Error(`Parent does not exist at path ${path}`);
          node = node[seg];
        }
      }

      const lastSeg = segments[segments.length - 1];
      if (Array.isArray(node)) {
        const idx = parseIndex(lastSeg);
        if (idx < 0 || idx >= node.length) throw new Error(`Target does not exist`);
        node[idx] = value;
      } else if (typeof node === 'object' && node !== null) {
        if (!Object.prototype.hasOwnProperty.call(node, lastSeg)) throw new Error(`Target does not exist`);
        node[lastSeg] = value;
      } else {
        throw new Error(`Target does not exist`);
      }

    } else {
      throw new Error(`Unknown op: ${type}`);
    }
  }

  return result;
}

function decodePath(path) {
  if (!path.startsWith('/')) throw new Error(`Invalid path: ${path}`);
  const raw = path.slice(1);
  if (raw === '') return [];
  // Split on '/' but preserve escaped ~1 and ~0
  const parts = [];
  let cur = '';
  for (let i = 0; i < raw.length; i++) {
    if (raw[i] === '~') {
      if (i + 1 >= raw.length) throw new Error(`Invalid escape in path`);
      if (raw[i + 1] === '1') { cur += '/'; i++; }
      else if (raw[i + 1] === '0') { cur += '~'; i++; }
      else throw new Error(`Invalid escape in path`);
    } else if (raw[i] === '/') {
      parts.push(cur);
      cur = '';
    } else {
      cur += raw[i];
    }
  }
  parts.push(cur);
  return parts;
}

function parseIndex(seg) {
  if (!/^\d+$/.test(seg)) throw new Error(`Invalid array index: ${seg}`);
  return parseInt(seg, 10);
}
```

