        return tuple(int(x) for x in v_str.split('.'))

    def compare(v1: tuple, v2: tuple) -> int:
        if v1 < v2: return -1
        if v1 > v2: return 1
        return 0

    def check_alternative(v: tuple, alt_str: str) -> bool:
        # Split by whitespace to get individual comparators
        comparators = alt_str.strip().split()
        if not comparators:
            return False

        for comp in comparators:
            if comp.startswith(">="):
                if not compare(v, parse_version(comp[3:])) >= 0: return False
            elif comp.startswith("<="):
                if not compare(v, parse_version(comp[3:])) <= 0: return False
            elif comp.startswith(">"):
                if not compare(v, parse_version(comp[1:])) > 0: return False
            elif comp.startswith("<"):
                if not compare(v, parse_version(comp[1:])) < 0: return False
            elif comp.startswith("~"):
                v_target = parse_version(comp[2:])
                # >= target and < major.minor+1.0.0
                limit = (v_target[0], v_target[1] + 1, 0)
                if not (compare(v, v_target) >= 0 and compare(v, limit) < 0):
                    return False
            elif comp.startswith("^"):
                v_target = parse_version(comp[1:])
                # SemVer logic for caret
                if v_target[0] > 0:
                    limit = (v_target[0] + 1, 0, 0)
                elif v_target[1] > 0:
                    limit = (0, v_target[1] + 1, 0)
                else:
                    limit = (0, 0, v_target[2] + 1)
                if not (compare(v, v_target) >= 0 and compare(v, limit) < 0):
                    return False
            elif comp.startswith("="):
                if not compare(v, parse_version(comp[1:])) == 0: return False
            else:
                # Exact version match (no operator provided)
                if not compare(v, parse_version(comp)) == 0: return False
        return True

    v_tuple = parse_version(version)
    # Split by alternatives ||
    alternatives = range_.split('||')

    # Version satisfies range if it satisfies at least one alternative
    for alt in alternatives:
        if check_alternative(v_tuple, alt):
            return True

    return False
```

### Explanation:
1.  **`parse_version`**: Converts version strings into tuples of integers to allow standard Python tuple comparison (e.g., `(1, 10, 0) > (1, 9, 0)`).
2.  **`check_alternative`**: Iterates through all comparators in a single alternative. It returns `False` if any single comparator fails (logical AND), and `True` if all pass.
3.  **Operator Logic**:
    *   Standard inequalities are handled by `compare`.
    *   `~` (Tilde): Locks the Major and Minor, allowing only the Patch to increase.
    *   `^` (Caret): Follows SemVer rules. If the Major is > 0, it allows any change that doesn't increment the Major. If the Major is 0, it locks the Minor. If both are 0, it locks the Patch.
4.  **`satisfies`**: Splits the range by `||` and returns `True` if any alternative is satisfied (logical OR).

