function applyPatch(doc, ops) {
  // Deep clone to ensure doc is not modified
  const clone = (val) => {
    if (val === null || typeof val !== 'object') return val;
    if (Array.isArray(val)) return val.map(clone);
    const obj = {};
    for (const key in val) {
      if (Object.prototype.hasOwnProperty.call(val, key)) {
        obj[key] = clone(val[key]);
      }
    }
    return obj;
  };

  let newDoc = clone(doc);

  // Helper to parse JSON Pointer paths
  const parsePath = (path) => {
    if (path === "") return [];
    if (!path.startsWith("/")) throw new Error("Invalid path format");
    // Split by / but ignore the empty string before the first /
    const segments = path.slice(1).split("/");
    return segments.map(s => s.replace(/~1/g, '/').replace(/~0/g, '~'));
  };

  const getPathSegments = (path) => parsePath(path);

  for (const operation of ops) {
      const { op, path, value } = operation;
      const segments = getPathSegments(path);

      if (op === 'add' && segments.length === 0) {
          newDoc = clone(value);
          continue;
      }

      let current = newDoc;
      // Navigate to the parent of the target
      for (let i = 0; i < segments.length - 1; i++) {
          const segment = segments[i];
          if (Array.isArray(current)) {
              const idx = parseInt(segment, 10);
              if (isNaN(idx) || idx < 0 || idx >= current.length) throw new Error("Index out of range");
              current = current[idx];
          } else if (current !== null && typeof current === 'object') {
              if (!(segment in current)) throw new Error("Parent path does not exist");
              current = current[segment];
          } else {
              throw new Error("Parent path does not exist");
          }
      }

      const lastSegment = segments[segments.length - 1];

      if (op === 'add') {
          if (Array.isArray(current)) {
              let idx = lastSegment === '-' ? current.length : parseInt(lastSegment, 10);
              if (isNaN(idx) || idx < 0 || idx > current.length) throw new Error("Invalid array index");
              current.splice(idx, 0, clone(value));
          } else if (current !== null && typeof current === 'object') {
              current[lastSegment] = clone(value);
          } else {
              throw new Error("Target is not an object or array");
          }
      } else if (op === 'replace') {
          if (Array.isArray(current)) {
              const idx = parseInt(lastSegment, 10);
              if (isNaN(idx) || idx < 0 || idx >= current.length) throw new Error("Index out of range");
              current[idx] = clone(value);
          } else if (current !== null && typeof current === 'object') {
              if (!(lastSegment in current)) throw new Error("Target does not exist");
              current[lastSegment] = clone(value);
          } else {
              throw new Error("Target does not exist");
          }
      } else if (op === 'remove') {
          if (Array.isArray(current)) {
              const idx = parseInt(lastSegment, 10);
              if (isNaN(idx) || idx < 0 || idx >= current.length) throw new Error("Index out of range");
              current.splice(idx, 1);
          } else if (current !== null && typeof current === 'object') {
              if (!(lastSegment in current)) throw new Error("Target does not exist");
              delete current[lastSegment];
          } else {
              throw new Error("Target does not exist");
          }
      } else {
          throw new Error(`Unknown operation: ${op}`);
      }
  }

  return newDoc;
}
```

