        return tuple(map(int, v_str.split('.')))

    def compare(v1_tuple, v2_tuple):
        """Returns 1 if v1 > v2, -1 if v1 < v2, 0 if equal."""
        if v1_tuple > v2_tuple:
            return 1
        if v1_tuple < v2_tuple:
            return -1
        return 0

    def check_comparator(v_tuple, comp_str: str) -> bool:
