        # Handle prefix operators
        if comp_str.startswith('~'):
            target = parse_version(comp_str[1:])
            # ~1.2.3 -> >=1.2.3 and <1.3.0
            upper_bound = (target[0], target[1] + 1, 0)
            return compare(v_tuple, target) >= 0 and compare(v_tuple, upper_bound) < 0

        elif comp_str.startswith('^'):
            target = parse_version(comp_str[1:])
            # ^1.2.3 -> >=1.2.3 and <2.0.0
            # ^0.2.3 -> >=0.2.3 and <0.3.0
            # ^0.0.3 -> >=0.0.3 and <0.0.4
            if target[0] > 0:
                upper_bound = (target[0] + 1, 0, 0)
            elif target[1] > 0:
                upper_bound = (0, target[1] + 1, 0)
            else:
                upper_bound = (0, 0, target[2] + 1)
            return compare(v_tuple, target) >= 0 and compare(v_tuple, upper_bound) < 0

        elif comp_str.startswith('>='):
            return compare(v_tuple, parse_version(comp_str[2:])) >= 0
        elif comp_str.startswith('<='):
            return compare(v_tuple, parse_version(comp_str[2:])) <= 0
        elif comp_str.startswith('>'):
            return compare(v_tuple, parse_version(comp_str[1:])) > 0
        elif comp_str.startswith('<'):
            return compare(v_tuple, parse_version(comp_str[1:])) < 0
        elif comp_str.startswith('='):
            return compare(v_tuple, parse_version(comp_str[1:])) == 0
        else:
            # Exact version match without '='
            return compare(v_tuple, parse_version(comp_str)) == 0

    v_tuple = parse_version(version)

    # Split by alternatives (||)
    alternatives = range_.split('||')

    for alt in alternatives:
        # Split by spaces to get individual comparators within the alternative
        comparators = alt.split()
        if not comparators:
            continue

        # All comparators in an alternative must be True
