function applyPatch(doc, ops) {
    // Deep clone the document to avoid modifying the original
    const newDoc = JSON.parse(JSON.stringify(doc));

    for (const opObj of ops) {
        const { op, path, value } = opObj;

        if (op !== 'add' && op !== 'remove' && op !== 'replace') {
            throw new Error(`Unknown operation: ${op}`);
        }

        // Parse the path into segments
        let segments;
        if (path === '') {
            segments = [];
        } else {
            if (!path.startsWith('/')) {
                throw new Error(`Path must start with '/' or be empty`);
            }
            const rawSegments = path.slice(1).split('/');
            segments = rawSegments.map(seg => {
                // Decode JSON Pointer escapes: ~0 -> ~, ~1 -> /
                return seg.replace(/~1/g, '/').replace(/~0/g, '~');
            });
        }

        if (op === 'add') {
            applyAdd(newDoc, segments, value);
        } else if (op === 'remove') {
            applyRemove(newDoc, segments);
        } else if (op === 'replace') {
            applyReplace(newDoc, segments, value);
        }
    }

