function resolveParentAndKey(doc, segments) {
    // Navigate to the parent object/array
    let current = doc;
    for (let i = 0; i < segments.length - 1; i++) {
        const seg = segments[i];
        if (current === null || current === undefined || typeof current !== 'object') {
            throw new Error(`Cannot navigate through non-object at segment ${seg}`);
        }
        if (Array.isArray(current)) {
            const idx = parseInt(seg, 10);
            if (isNaN(idx) || idx < 0 || seg !== String(idx)) {
                throw new Error(`Invalid array index: ${seg}`);
            }
            if (idx >= current.length) {
                throw new Error(`Array index out of range: ${idx} >= ${current.length}`);
            }
            current = current[idx];
        } else {
            if (!(seg in current)) {
                throw new Error(`Property '${seg}' does not exist`);
            }
            current = current[seg];
        }
    }
    return current;
}

function applyAdd(doc, segments, value) {
    if (segments.length === 0) {
        // Replace the entire document
        return value;
    }

    const parent = resolveParentAndKey(doc, segments.slice(0, -1));
    const key = segments[segments.length - 1];

    if (Array.isArray(parent)) {
        let index;
        if (key === '-') {
            index = parent.length;
        } else {
            index = parseInt(key, 10);
            if (isNaN(index) || index < 0 || key !== String(index)) {
                throw new Error(`Invalid array index: ${key}`);
            }
            if (index > parent.length) {
                throw new Error(`Array index out of range: ${index} > ${parent.length}`);
            }
        }
        parent.splice(index, 0, value);
    } else {
        // Object
        parent[key] = value;
    }
}

