from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity: int, ttl: int):
        self.capacity = capacity
        self.ttl = ttl
        # Store entries as {key: (value, expiry_time)}
        # Use an OrderedDict to track insertion/access order for LRU eviction
        self.cache = OrderedDict()

    def _is_expired(self, key: str, now: int) -> bool:
        if key not in self.cache:
            return True
        _, expiry = self.cache[key]
        return now >= expiry

    def _remove_expired(self, now: int):
        """Remove all expired entries from the cache."""
        expired_keys = []
        for key, (value, expiry) in self.cache.items():
            if now >= expiry:
                expired_keys.append(key)

        for key in expired_keys:
            del self.cache[key]

    def put(self, key, value, now: int) -> None:
        # Calculate expiry time
        expiry = now + self.ttl

        if key in self.cache:
            # Update existing entry: move to end (most recently used) and update value/expiry
            self.cache.move_to_end(key)
            self.cache[key] = (value, expiry)
        else:
            # New key
            # If cache is full, we need to evict
            if len(self.cache) >= self.capacity:
                # First, remove all expired entries
                self._remove_expired(now)

                # After removing expired, check if still full
                if len(self.cache) >= self.capacity:
                    # Remove least recently used (first item in OrderedDict)
                    self.cache.popitem(last=False)

            # Add new entry at the end
            self.cache[key] = (value, expiry)

    def get(self, key, now: int):
        if key not in self.cache:
            return None

        _, expiry = self.cache[key]

        # Check if expired
        if now >= expiry:
            del self.cache[key]
            return None

        # Successful get: move to end (most recently used), do NOT change expiry
        self.cache.move_to_end(key)
        value, _ = self.cache[key]
        return value

    def size(self, now: int) -> int:
        """Return the number of non-expired entries."""
        # We need to count entries that are not expired at `now`
        # But we don't want to modify the cache structure here just for counting
        # However, since get/put may have left some expired entries in the cache,
        # we should filter them out for an accurate size.

        count = 0
        expired_keys = []
        for key, (value, expiry) in self.cache.items():
            if now >= expiry:
                expired_keys.append(key)
            else:
                count += 1

        # Clean up expired keys to keep cache tidy
        for key in expired_keys:
            del self.cache[key]

        return count
