def satisfies(version: str, range_: str) -> bool:
    """
    Check if a version string satisfies a range specification.

    Version format: MAJOR.MINOR.PATCH (non-negative integers)
    Range format: Alternatives separated by ||, each alternative is comparators separated by spaces.
    """
    def parse_version(v: str):
        parts = v.strip().split('.')
        return tuple(int(p) for p in parts)

    def compare_versions(v1, v2):
        """Compare two version tuples. Returns -1, 0, or 1."""
        for a, b in zip(v1, v2):
            if a < b:
                return -1
            elif a > b:
                return 1
        # All compared parts are equal, check lengths (though all should be 3)
        if len(v1) < len(v2):
            return -1
        elif len(v1) > len(v2):
            return 1
        return 0

    def satisfies_comparator(version_tuple, comparator_str):
        """Check if version satisfies a single comparator."""
        comparator_str = comparator_str.strip()

        # Determine the operator and the version part
        if comparator_str.startswith('>='):
            op = '>='
            ver_str = comparator_str[2:].strip()
        elif comparator_str.startswith('<='):
            op = '<='
            ver_str = comparator_str[2:].strip()
        elif comparator_str.startswith('>'):
            op = '>'
            ver_str = comparator_str[1:].strip()
        elif comparator_str.startswith('<'):
            op = '<'
            ver_str = comparator_str[1:].strip()
        elif comparator_str.startswith('='):
            op = '='
            ver_str = comparator_str[1:].strip()
        elif comparator_str.startswith('~'):
            op = '~'
            ver_str = comparator_str[1:].strip()
        elif comparator_str.startswith('^'):
            op = '^'
            ver_str = comparator_str[1:].strip()
        else:
            # No operator means exact match (=)
            op = '='
            ver_str = comparator_str.strip()

        target = parse_version(ver_str)

        if op == '=':
            return version_tuple == target
        elif op == '>':
            return compare_versions(version_tuple, target) > 0
        elif op == '>=':
            return compare_versions(version_tuple, target) >= 0
        elif op == '<':
            return compare_versions(version_tuple, target) < 0
        elif op == '<=':
            return compare_versions(version_tuple, target) <= 0
        elif op == '~':
            # >=target and <next minor
            if len(target) < 3:
                return False
            major, minor, patch = target
            # Next minor is (major, minor+1, 0)
            next_ver = (major, minor + 1, 0)
            return compare_versions(version_tuple, target) >= 0 and compare_versions(version_tuple, next_ver) < 0
        elif op == '^':
            # >=target and <next major (with special handling for 0.x.y)
            if len(target) < 3:
                return False
            major, minor, patch = target
            if major > 0:
                # ^1.2.3 => >=1.2.3 and <2.0.0
                upper = (major + 1, 0, 0)
            elif minor > 0:
                # ^0.2.3 => >=0.2.3 and <0.3.0
                upper = (0, minor + 1, 0)
            else:
                # ^0.0.3 => >=0.0.3 and <0.0.4
                upper = (0, 0, patch + 1)
            return compare_versions(version_tuple, target) >= 0 and compare_versions(version_tuple, upper) < 0

        return False

    # Parse the range string
    range_str = range_.strip()

    # Split by || for alternatives
    alternatives = range_str.split('||')

    version_tuple = parse_version(version)

    for alt in alternatives:
        alt = alt.strip()
        if not alt:
            continue

        # Split comparators by spaces
        comparators = alt.split()

        all_satisfied = True
        for comp in comparators:
            comp = comp.strip()
            if not comp:
                continue
            if not satisfies_comparator(version_tuple, comp):
                all_satisfied = False
                break

        if all_satisfied:
            return True

    return False
