function applyPatch(doc, ops) {
  // Deep clone the document to avoid mutating the original
  function deepClone(obj) {
    if (obj === null || typeof obj !== 'object') {
      return obj;
    }
    if (Array.isArray(obj)) {
      return obj.map(item => deepClone(item));
    }
    const cloned = {};
    for (const key of Object.keys(obj)) {
      cloned[key] = deepClone(obj[key]);
    }
    return cloned;
  }

  let result = deepClone(doc);

  for (const opObj of ops) {
    const { op, path, value } = opObj;

    if (op !== 'add' && op !== 'remove' && op !== 'replace') {
      throw new Error(`Unknown operation: ${op}`);
    }

    // Parse the path into segments
    const segments = parsePath(path);

    if (path === "") {
      // Special case: path is empty string, affects the whole document
      if (op === 'add') {
        result = value;
      } else if (op === 'remove') {
        throw new Error('Cannot remove the root document');
      } else if (op === 'replace') {
        result = value;
      }
      continue;
    }

    // Navigate to the parent, collecting the path and key for the target
    let current = result;
    let parent = null;
    let parentKey = null;
    let isArrayParent = false;

    for (let i = 0; i < segments.length - 1; i++) {
      const segment = segments[i];
      if (current === null || current === undefined) {
        throw new Error(`Path does not exist: ${path}`);
      }
      if (Array.isArray(current)) {
        const index = parseInt(segment, 10);
        if (isNaN(index) || index < 0 || index >= current.length) {
          throw new Error(`Array index out of range: ${segment}`);
        }
        parent = current;
        parentKey = index;
        isArrayParent = true;
        current = current[index];
      } else if (typeof current === 'object' && !Array.isArray(current)) {
        if (!(segment in current)) {
          throw new Error(`Property does not exist: ${segment}`);
        }
        parent = current;
        parentKey = segment;
        isArrayParent = false;
        current = current[segment];
      } else {
        throw new Error(`Cannot traverse into non-object/non-array`);
      }
    }

    // Now current is the parent, and segments[last] is the key to operate on
    const lastSegment = segments[segments.length - 1];

    if (parent === null || parent === undefined) {
      throw new Error(`Parent does not exist for path: ${path}`);
    }

    if (op === 'add') {
      if (Array.isArray(parent)) {
        let index;
        if (lastSegment === '-') {
          index = parent.length;
        } else {
          index = parseInt(lastSegment, 10);
          if (isNaN(index) || index < 0 || index > parent.length) {
            throw new Error(`Array index out of range for add: ${lastSegment}`);
          }
        }
        parent.splice(index, 0, value);
      } else if (typeof parent === 'object' && !Array.isArray(parent)) {
        parent[lastSegment] = value;
      } else {
        throw new Error(`Cannot add to non-object/non-array`);
      }
    } else if (op === 'remove') {
      if (Array.isArray(parent)) {
        const index = parseInt(lastSegment, 10);
        if (isNaN(index) || index < 0 || index >= parent.length) {
          throw new Error(`Array index out of range for remove: ${lastSegment}`);
        }
        parent.splice(index, 1);
      } else if (typeof parent === 'object' && !Array.isArray(parent)) {
        if (!(lastSegment in parent)) {
          throw new Error(`Property does not exist for remove: ${lastSegment}`);
        }
        delete parent[lastSegment];
      } else {
        throw new Error(`Cannot remove from non-object/non-array`);
      }
    } else if (op === 'replace') {
      if (Array.isArray(parent)) {
        const index = parseInt(lastSegment, 10);
        if (isNaN(index) || index < 0 || index >= parent.length) {
          throw new Error(`Array index out of range for replace: ${lastSegment}`);
        }
        parent[index] = value;
      } else if (typeof parent === 'object' && !Array.isArray(parent)) {
        if (!(lastSegment in parent)) {
          throw new Error(`Property does not exist for replace: ${lastSegment}`);
        }
        parent[lastSegment] = value;
      } else {
        throw new Error(`Cannot replace in non-object/non-array`);
      }
    }
  }

  return result;
}

function parsePath(path) {
  if (path === "") {
    return [];
  }
  // Path starts with /
  if (!path.startsWith('/')) {
    throw new Error(`Invalid path: ${path}`);
  }
  const rawSegments = path.split('/').slice(1);
  const segments = [];
  for (const segment of rawSegments) {
    // Decode ~0 -> ~ and ~1 -> /
    let decoded = segment.replace(/~1/g, '/').replace(/~0/g, '~');
    segments.push(decoded);
  }
  return segments;
}
