from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity: int, ttl: int):
        self.capacity = capacity
        self.ttl = ttl
        # Store entries as key -> (value, expiry_time)
        # Use an OrderedDict to track insertion/access order for LRU eviction
        self.cache: OrderedDict[str, tuple] = OrderedDict()

    def _is_expired(self, entry: tuple, now: int) -> bool:
        _, expiry = entry
        return now >= expiry

    def _remove_expired(self, now: int):
        """Remove all expired entries."""
        expired_keys = []
        for key, entry in self.cache.items():
            if self._is_expired(entry, now):
                expired_keys.append(key)
        for key in expired_keys:
            del self.cache[key]

    def put(self, key, value, now: int) -> None:
        expiry = now + self.ttl
        new_entry = (value, expiry)

        if key in self.cache:
            # Update existing entry and move to end (most recently used)
            self.cache[key] = new_entry
            self.cache.move_to_end(key)
        else:
            # New key
            # If cache is full, evict expired first, then LRU if still full
            if len(self.cache) >= self.capacity:
                self._remove_expired(now)

            if len(self.cache) >= self.capacity:
                # Remove least recently used (first item in OrderedDict)
                self.cache.popitem(last=False)

            self.cache[key] = new_entry

    def get(self, key, now: int):
        if key not in self.cache:
            return None

        entry = self.cache[key]
        if self._is_expired(entry, now):
            del self.cache[key]
            return None

        # Move to end (most recently used) without changing expiry
        self.cache.move_to_end(key)
        return entry[0]

    def size(self, now: int) -> int:
        # Count non-expired entries
        count = 0
        for key in list(self.cache.keys()):
            if not self._is_expired(self.cache[key], now):
                count += 1
        return count
