def satisfies(version: str, range_: str) -> bool:
    """
    Check if a version string satisfies a range specification.

    Args:
        version: A version string in MAJOR.MINOR.PATCH format.
        range_: A range specification with alternatives separated by ||.

    Returns:
        True if the version satisfies at least one alternative in the range.
    """

    def parse_version(v_str: str) -> tuple:
        parts = v_str.strip().split('.')
        return (int(parts[0]), int(parts[1]), int(parts[2]))

    def compare_versions(v1: tuple, v2: tuple) -> int:
        """Compare two version tuples. Returns -1, 0, or 1."""
        for a, b in zip(v1, v2):
            if a < b:
                return -1
            elif a > b:
                return 1
        return 0

    def satisfies_single_comparator(version_tuple: tuple, comparator_str: str) -> bool:
        """Check if version satisfies a single comparator."""
        comparator_str = comparator_str.strip()

        if not comparator_str:
            return True

        # Determine operator and version string
        if comparator_str.startswith('>='):
            op = '>='
            ver_str = comparator_str[2:].strip()
        elif comparator_str.startswith('<='):
            op = '<='
            ver_str = comparator_str[2:].strip()
        elif comparator_str.startswith('>'):
            op = '>'
            ver_str = comparator_str[1:].strip()
        elif comparator_str.startswith('<'):
            op = '<'
            ver_str = comparator_str[1:].strip()
        elif comparator_str.startswith('='):
            op = '='
            ver_str = comparator_str[1:].strip()
        else:
            # Plain version means equality
            op = '='
            ver_str = comparator_str

        target = parse_version(ver_str)

        cmp_result = compare_versions(version_tuple, target)

        if op == '=':
            return cmp_result == 0
        elif op == '>':
            return cmp_result > 0
        elif op == '>=':
            return cmp_result >= 0
        elif op == '<':
            return cmp_result < 0
        elif op == '<=':
            return cmp_result <= 0
        elif op == '~':
            # Tilde: >=target and <next minor
            if cmp_result < 0:
                return False
            # Next minor: increment minor, set patch to 0
            next_minor = (target[0], target[1] + 1, 0)
            return compare_versions(version_tuple, next_minor) < 0
        elif op == '^':
            # Caret: >=target and <next major (or next minor if major is 0, or next patch if major and minor are 0)
            if cmp_result < 0:
                return False

            major, minor, patch = target

            if major != 0:
                # Next major
                upper = (major + 1, 0, 0)
            elif minor != 0:
                # Next minor
                upper = (0, minor + 1, 0)
            else:
                # Both major and minor are 0, next patch
                upper = (0, 0, patch + 1)

            return compare_versions(version_tuple, upper) < 0

        return False

    def satisfies_alternative(version_tuple: tuple, alternative_str: str) -> bool:
        """Check if version satisfies an alternative (all comparators must be satisfied)."""
        # Split by spaces to get individual comparators
        comparators = alternative_str.split()

        for comp in comparators:
            comp = comp.strip()
            if not comp:
                continue
            if not satisfies_single_comparator(version_tuple, comp):
                return False
        return True

    # Parse the version
    version_tuple = parse_version(version)

    # Split range by || for alternatives
    alternatives = range_.split('||')

    for alt in alternatives:
        if satisfies_alternative(version_tuple, alt):
            return True

    return False
