            # First, remove all expired entries
            expired_keys = [k for k, (v, exp) in self.cache.items() if now >= exp]
            for k in expired_keys:
                del self.cache[k]

            # If still full, remove least recently used (first item in OrderedDict)
            if len(self.cache) >= self.capacity:
                self.cache.popitem(last=False)

        # Add new entry
        self.cache[key] = (value, expiry)

    def get(self, key, now: int):
        if key not in self.cache:
            return None

        value, expiry = self.cache[key]

        # Check if expired
        if now >= expiry:
            del self.cache[key]
            return None

        # Move to end (most recently used), but don't change expiry
        self.cache.move_to_end(key)
        return value

    def size(self, now: int) -> int:
        # Count non-expired entries
        count = 0
        keys_to_remove = []
        for k, (v, exp) in self.cache.items():
            if now < exp:
                count += 1
            else:
                keys_to_remove.append(k)

        # Clean up expired entries
        for k in keys_to_remove:
            del self.cache[k]

        return count
```

This implementation uses `OrderedDict` to efficiently track the least recently used (LRU) entry. The `put` method first removes expired entries before evicting the LRU if necessary. The `get` method updates the access order without changing expiry. The `size` method counts valid entries and cleans up expired ones.

