def satisfies(version: str, range_: str) -> bool:
    """
    Check if a version string satisfies a given range specification.

    Args:
        version: A version string in MAJOR.MINOR.PATCH format.
        range_: A range specification with alternatives separated by || and comparators separated by spaces.

    Returns:
        True if the version satisfies at least one alternative in the range, False otherwise.
    """
    def parse_version(v: str) -> tuple:
        parts = v.strip().split('.')
        return (int(parts[0]), int(parts[1]), int(parts[2]))

    def compare_versions(v1: tuple, v2: tuple) -> int:
        """Compare two version tuples. Returns -1, 0, or 1."""
        for a, b in zip(v1, v2):
            if a < b:
                return -1
            elif a > b:
                return 1
        return 0

    def check_comparator(version_tuple: tuple, comparator: str) -> bool:
        """Check if version satisfies a single comparator."""
        comparator = comparator.strip()
        if not comparator:
            return True

        # Extract operator and version string
        if comparator.startswith('>='):
            op = '>='
            ver_str = comparator[2:]
        elif comparator.startswith('<='):
            op = '<='
            ver_str = comparator[2:]
        elif comparator.startswith('>'):
            op = '>'
            ver_str = comparator[1:]
        elif comparator.startswith('<'):
            op = '<'
            ver_str = comparator[1:]
        elif comparator.startswith('='):
            op = '='
            ver_str = comparator[1:]
        elif comparator.startswith('~'):
            op = '~'
            ver_str = comparator[1:]
        elif comparator.startswith('^'):
            op = '^'
            ver_str = comparator[1:]
        else:
            # Plain version, treat as exact match
            op = '='
            ver_str = comparator

        ver_str = ver_str.strip()
        if not ver_str:
            return False

        target = parse_version(ver_str)

        cmp_result = compare_versions(version_tuple, target)

        if op == '=':
            return cmp_result == 0
        elif op == '>':
            return cmp_result > 0
        elif op == '>=':
            return cmp_result >= 0
        elif op == '<':
            return cmp_result < 0
        elif op == '<=':
            return cmp_result <= 0
        elif op == '~':
            # >= ver_str and < next minor (increment minor, reset patch)
            # ~1.2.3 means >=1.2.3 and <1.3.0
            upper = (target[0], target[1] + 1, 0)
            return cmp_result >= 0 and compare_versions(version_tuple, upper) < 0
        elif op == '^':
            # ^1.2.3 means >=1.2.3 and <2.0.0
            # ^0.2.3 means >=0.2.3 and <0.3.0
            # ^0.0.3 means >=0.0.3 and <0.0.4
            major, minor, patch = target
            if major != 0:
                upper = (major + 1, 0, 0)
            elif minor != 0:
                upper = (0, minor + 1, 0)
            else:
                upper = (0, 0, patch + 1)
            return cmp_result >= 0 and compare_versions(version_tuple, upper) < 0

        return False

    version_tuple = parse_version(version)

    # Split by || for alternatives
    alternatives = range_.split('||')

    for alt in alternatives:
        # Split by spaces for comparators
        comparators = alt.split()

        # Check if all comparators are satisfied
        all_satisfied = True
        for comp in comparators:
            if not check_comparator(version_tuple, comp):
                all_satisfied = False
                break

        if all_satisfied:
            return True

    return False
```

This implementation parses version strings into tuples of integers and compares them component-wise. It handles all specified comparator operators including tilde (`~`) and caret (`^`) ranges with their special zero-major/minor behavior. The function splits the range by `||` for alternatives (OR logic) and checks that all comparators in an alternative are satisfied (AND logic).

