def build_order(deps: dict[str, list[str]]) -> list[str]:
    """
    Perform topological sort on build targets with deterministic ordering.

    Args:
        deps: Dictionary mapping each target to its list of dependencies.

    Returns:
        List of targets in valid build order (dependencies before dependents).

    Raises:
        ValueError: If there is a cycle in the dependency graph.
    """
    # Collect all nodes (targets)
    all_nodes = set(deps.keys())
    for dep_list in deps.values():
        for d in dep_list:
            all_nodes.add(d)

    # Build adjacency list and in-degree count
    # We need to track dependencies for each node.
    # For topological sort, we want to know which nodes depend on a given node
    # (reverse edges) and how many dependencies each node has.

    # deps_map: node -> set of its direct dependencies
    deps_map = {}
    for node in all_nodes:
        if node in deps:
            deps_map[node] = set(deps[node])
        else:
            deps_map[node] = set()

    # Reverse adjacency: for each dependency, which nodes depend on it?
    reverse_adj: dict[str, list[str]] = {node: [] for node in all_nodes}
    in_degree: dict[str, int] = {node: 0 for node in all_nodes}

    for node, dependencies in deps_map.items():
        in_degree[node] = len(dependencies)
        for dep in dependencies:
            if dep not in reverse_adj:
                reverse_adj[dep] = []
            reverse_adj[dep].append(node)

    # Kahn's algorithm with a sorted queue for deterministic output
    import heapq

    # Start with nodes that have no dependencies (in_degree == 0)
    heap = []
    for node in all_nodes:
        if in_degree[node] == 0:
            heapq.heappush(heap, node)

    result = []

    while heap:
        node = heapq.heappop(heap)
        result.append(node)

        # For each node that depends on this node, reduce its in-degree
        for dependent in reverse_adj.get(node, []):
            in_degree[dependent] -= 1
            if in_degree[dependent] == 0:
                heapq.heappush(heap, dependent)

    if len(result) != len(all_nodes):
        raise ValueError("Dependency cycle detected")

    return result
```

This implementation uses Kahn's algorithm for topological sorting with a min-heap to ensure deterministic ordering (alphabetically smallest available target at each step). It correctly handles all targets, including those that only appear in dependency lists but not as keys in the input dictionary. If a cycle exists, fewer than all nodes will be processed, triggering a `ValueError`.

