          // Replace the entire document with the new value
          result = value;
        }
      } else if (operation === 'remove') {
        // Removing the entire document - set to null or undefined? 
        // The spec says target must exist. If we remove everything, what's left?
        // Let's throw an error as it doesn't make practical sense for a config service
        throw new Error('Cannot remove the entire document');
      }
      continue;
    }

    if (path[0] !== '/') {
      throw new Error('Path must start with / or be empty');
    }

    // Parse the path into segments
    const segments = parsePathInternal(path);

    // Navigate to the parent node and perform the operation on result
    applyOpToNode(result, operation, segments, value);
  }

  return result;
}

function parsePathInternal(path) {
  const parts = path.split('/').slice(1);
  const segments = [];

  for (const part of parts) {
    // Decode JSON Pointer escapes: ~1 -> /, ~0 -> ~
    let decoded = '';
    let i = 0;
    while (i < part.length) {
      if (part[i] === '~') {
        if (i + 1 < part.length) {
          if (part[i + 1] === '1') {
            decoded += '/';
            i += 2;
          } else if (part[i + 1] === '0') {
            decoded += '~';
            i += 2;
          } else {
            throw new Error(`Invalid escape sequence in path segment: ${part}`);
          }
        } else {
          throw new Error('Tilde at end of segment');
        }
      } else {
        decoded += part[i];
        i++;
      }
    }
    segments.push(decoded);
  }

  return segments;
}

function applyOpToNode(doc, operation, segments, value) {
  if (segments.length === 0) {
    // This shouldn't happen since we handle empty path separately above
    throw new Error('Empty path should be handled separately');
  }

  // Navigate to the parent node
  let current = doc;
  for (let i = 0; i < segments.length - 1; i++) {
    const seg = segments[i];

    if (current === null || typeof current !== 'object') {
      throw new Error(`Parent does not exist at path segment: ${seg}`);
    }

    if (Array.isArray(current)) {
      // Array index must be a non-negative integer
      if (!/^\d+$/.test(seg)) {
        throw new Error(`Invalid array index: ${seg}`);
      }
      const idx = parseInt(seg, 10);
      if (idx < 0 || idx >= current.length) {
        // For navigation purposes, if we're navigating through an array and the index is out of range,
        // it means the parent doesn't exist
        throw new Error(`Array index out of range: ${idx}`);
      }
      current = current[idx];
    } else {
      // Object
      if (!(seg in current)) {
        throw new Error(`Property does not exist: ${seg}`);
      }
      current = current[seg];
    }
  }

  const lastSeg = segments[segments.length - 1];

  if (operation === 'add') {
    if (Array.isArray(current)) {
      let idx;
      if (lastSeg === '-') {
        idx = current.length;
      } else {
        if (!/^\d+$/.test(lastSeg)) {
          throw new Error(`Invalid array index: ${lastSeg}`);
        }
        idx = parseInt(lastSeg, 10);
        if (idx < 0 || idx > current.length) {
          throw new Error(`Array index out of range: ${idx}`);
        }
      }
      current.splice(idx, 0, value);
    } else if (current !== null && typeof current === 'object') {
      // Object: set the member, replacing existing
      current[lastSeg] = value;
    } else {
      throw new Error(`Cannot add to non-object/non-array at path`);
    }
  } else if (operation === 'remove') {
    if (Array.isArray(current)) {
      if (!/^\d+$/.test(lastSeg)) {
        throw new Error(`Invalid array index: ${lastSeg}`);
      }
      const idx = parseInt(lastSeg, 10);
      if (idx < 0 || idx >= current.length) {
        throw new Error(`Array index out of range for remove: ${idx}`);
      }
      current.splice(idx, 1);
    } else if (current !== null && typeof current === 'object') {
      if (!(lastSeg in current)) {
        throw new Error(`Property does not exist for remove: ${lastSeg}`);
      }
      delete current[lastSeg];
    } else {
      throw new Error(`Cannot remove from non-object/non-array at path`);
    }
  } else if (operation === 'replace') {
    if (Array.isArray(current)) {
      if (!/^\d+$/.test(lastSeg)) {
        throw new Error(`Invalid array index: ${lastSeg}`);
      }
      const idx = parseInt(lastSeg, 10);
      if (idx < 0 || idx >= current.length) {
        throw new Error(`Array index out of range for replace: ${idx}`);
      }
      current[idx] = value;
    } else if (current !== null && typeof current === 'object') {
      if (!(lastSeg in current)) {
        throw new Error(`Property does not exist for replace: ${lastSeg}`);
      }
      current[lastSeg] = value;
    } else {
      throw new Error(`Cannot replace non-object/non-array at path`);
    }
  }
}
```

The function performs JSON Patch (RFC 6902) operations on a document without modifying the original. It deep-clones the input, parses paths with proper JSON Pointer decoding (`~0` → `~`, `~1` → `/`), and applies each operation in sequence. Errors are thrown for invalid operations, missing parents/targets, or out-of-range array indices.

