from datetime import date


def parse_date(text: str) -> date:
    """Parse a date string in ISO, British numeric, or short text format.

    Accepts:
        - ISO:         '2025-03-07'
        - British:     '07/03/2025' (day/month/year)
        - Short text:  '7 Mar 2025' (day with/without leading zero)

    Surrounding whitespace is allowed. Any other input, including
    impossible dates like '31/02/2025', raises ValueError.
    """
    if text is None:
        raise ValueError("input must be a string")

    s = text.strip()
    if not s:
        raise ValueError("input must be a string")

    # ISO: 2025-03-07
    try:
        return date.fromisoformat(s)
    except ValueError:
        pass

    # British numeric: 07/03/2025 (day/month/year)
    try:
        day, month, year = (int(part) for part in s.split("/"))
        return date(year, month, day)
    except ValueError:
        pass

    # Short text: 7 Mar 2025 (English three-letter month)
    months = {
        "jan": 1, "feb": 2, "mar": 3, "apr": 4,
        "may": 5, "jun": 6, "jul": 7, "aug": 8,
        "sep": 9, "oct": 10, "nov": 11, "dec": 12,
    }

    parts = s.split()
    if len(parts) == 3:
        day_s, mon_s, year_s = parts
        if mon_s[:3].lower() in months and day_s.isdigit() and year_s.isdigit():
            month = months[mon_s[:3].lower()]
            return date(int(year_s), month, int(day_s))

    raise ValueError(f"unrecognized date format: {text!r}")
```

The function tries each of the three formats in order. `date.fromisoformat` handles ISO and validates the date. The British format splits on `/` and constructs a `date`, which rejects impossible dates like `31/02/2025`. The short-text format maps the three-letter month abbreviation to a number and also validates via `date()`. Any input matching none of these raises `ValueError`.

Note: `date.fromisoformat` in Python < 3.11 requires the strict `YYYY-MM-DD` form (no other separators), so it won't accidentally accept malformed ISO strings.

