def normalise_order(raw: dict) -> dict:
    # sku
    try:
        sku_raw = raw["sku"]
    except KeyError:
        raise ValueError("missing 'sku'")
    if not isinstance(sku_raw, str):
        raise ValueError("'sku' must be a string")
    sku = sku_raw.strip().upper()
    if not sku:
        raise ValueError("'sku' must not be empty")

    # qty
    try:
        qty_raw = raw["qty"]
    except KeyError:
        raise ValueError("missing 'qty'")
    if isinstance(qty_raw, bool):
        raise ValueError("'qty' must be an int or numeric string")
    if isinstance(qty_raw, int):
        qty = qty_raw
    elif isinstance(qty_raw, str):
        try:
            qty = int(qty_raw.strip())
        except (ValueError, TypeError):
            raise ValueError("'qty' must be an integer")
    else:
        raise ValueError("'qty' must be an int or numeric string")
    if not (1 <= qty <= 99):
        raise ValueError("'qty' must be between 1 and 99")

    # unit_price_pence
    try:
        price_raw = raw["unit_price_pence"]
    except KeyError:
        raise ValueError("missing 'unit_price_pence'")
    if isinstance(price_raw, bool):
        raise ValueError("'unit_price_pence' must be an int")
    if isinstance(price_raw, int):
        unit_price_pence = price_raw
    elif isinstance(price_raw, str):
        try:
            unit_price_pence = int(price_raw.strip())
        except (ValueError, TypeError):
            raise ValueError("'unit_price_pence' must be an integer")
    else:
        raise ValueError("'unit_price_pence' must be an int")
    if unit_price_pence < 0:
        raise ValueError("'unit_price_pence' must be 0 or more")

    # currency
    currency_raw = raw.get("currency")
    if currency_raw is None or (isinstance(currency_raw, str) and not currency_raw.strip()):
        currency = "GBP"
    else:
        if not isinstance(currency_raw, str):
            raise ValueError("'currency' must be a string")
        currency = currency_raw.strip().upper()
    if currency not in ("GBP", "EUR", "USD"):
        raise ValueError("'currency' must be one of GBP, EUR, USD")

    total_pence = qty * unit_price_pence

    return {
        "sku": sku,
        "qty": qty,
        "unit_price_pence": unit_price_pence,
        "currency": currency,
        "total_pence": total_pence,
    }
```

