function parseQuery(qs) {
  if (typeof qs !== 'string' || qs.length === 0) {
    return {};
  }
  if (qs[0] === '?') {
    qs = qs.slice(1);
  }

  const result = {};

  const pairs = qs.split('&');
  for (const pair of pairs) {
    if (pair.length === 0) {
      continue;
    }

    const eqIndex = pair.indexOf('=');
    let rawKey, rawValue;
    if (eqIndex === -1) {
      rawKey = pair;
      rawValue = '';
    } else {
      rawKey = pair.slice(0, eqIndex);
      rawValue = pair.slice(eqIndex + 1);
    }

    const key = decodeURIComponent(rawKey.replace(/\+/g, ' '));
    const value = decodeURIComponent(rawValue.replace(/\+/g, ' '));

    if (key in result) {
      if (!Array.isArray(result[key])) {
        result[key] = [result[key]];
      }
      result[key].push(value);
    } else {
      result[key] = value;
    }
  }

  return result;
}
```

This implementation splits on `&`, finds the first `=` to separate key and value, treats keyless entries as `""`, decodes `+` to space before `decodeURIComponent`, and accumulates repeated keys into ordered arrays while skipping empty pairs.

```javascript
function deepMerge(base, override) {
  const result = {};

  for (const key of Object.keys(base)) {
    if (Object.prototype.hasOwnProperty.call(base, key)) {
      const baseVal = base[key];
      const overrideVal = override && Object.prototype.hasOwnProperty.call(override, key) ? override[key] : undefined;

      if (overrideVal !== undefined) {
        if (isPlainObject(baseVal) && isPlainObject(overrideVal)) {
          result[key] = deepMerge(baseVal, overrideVal);
        } else {
          result[key] = cloneDeep(overrideVal);
        }
      } else {
        result[key] = cloneDeep(baseVal);
      }
    }
  }

  for (const key of Object.keys(override)) {
    if (Object.prototype.hasOwnProperty.call(override, key)) {
      const overrideVal = override[key];
      if (overrideVal === undefined) continue;

      const baseVal = base && Object.prototype.hasOwnProperty.call(base, key) ? base[key] : undefined;

      if (baseVal !== undefined && isPlainObject(baseVal) && isPlainObject(overrideVal)) {
        result[key] = deepMerge(baseVal, overrideVal);
      } else {
        result[key] = cloneDeep(overrideVal);
      }
    }
  }

  return result;
}

function isPlainObject(value) {
  if (value === null || typeof value !== 'object') return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function cloneDeep(value) {
  if (Array.isArray(value)) {
    return value.map(item => cloneDeep(item));
  }
  if (isPlainObject(value)) {
    const out = {};
    for (const key of Object.keys(value)) {
      out[key] = cloneDeep(value[key]);
    }
    return out;
  }
  return value;
}
```

This implementation never mutates the inputs, recursively merges plain objects, replaces arrays and other values, treats `undefined` as "keep base" while `null` replaces, and deep-clones everything so the result shares no references with either argument.

