#include <string>

long long parse_duration(const std::string& s) {
    long long total = 0;
    long long current = 0;
    bool have_number = false;
    int last_unit = 0;  // 0: none, 1: h, 2: m, 3: s
    bool have_unit = false;
    size_t i = 0;
    const size_t n = s.size();

    const auto unit_value = [](char u) -> long long {
        if (u == 'h') return 3600;
        if (u == 'm') return 60;
        if (u == 's') return 1;
        return -1;
    };

    while (i < n) {
        char c = s[i];
        if (c >= '0' && c <= '9') {
            if (have_unit) return -1;  // digit after a unit without intervening unit
            current = current * 10 + (c - '0');
            have_number = true;
            ++i;
        } else if (c == 'h' || c == 'm' || c == 's') {
            if (!have_number) return -1;  // unit without a preceding number
            long long v = unit_value(c);
            int order = (c == 'h') ? 1 : (c == 'm') ? 2 : 3;
            if (order <= last_unit) return -1;  // wrong order or repeated unit
            total += current * v;
            last_unit = order;
            have_number = false;
            have_unit = true;
            ++i;
        } else {
            return -1;  // spaces or any other invalid character
        }
    }

    if (!have_unit) return -1;  // no complete part (e.g., bare number or empty)
    return total;
}
```

This parser walks the string char by char, tracking the last unit seen to enforce h→m→s ordering and uniqueness. Digits accumulate into the current number; a unit multiplies and adds it, then resets the number. Any space, sign, unknown character, or structural violation (unit without number, number without unit, wrong/repeated order) returns -1, as does a trailing number with no unit or an empty string.

