from collections import OrderedDict

class TTLCache:
    def __init__(self, capacity: int, ttl: int):
        self.capacity = capacity
        self.ttl = ttl
        self._data = OrderedDict()  # key -> expiry_time (absolute)

    def _is_expired(self, key, now):
        return now >= self._data[key]

    def put(self, key, value, now: int) -> None:
        expiry = now + self.ttl
        if key in self._data:
            self._data[key] = expiry
            self._data.move_to_end(key)
            return
        # Adding a new key.
        if self.capacity <= 0:
            return
        if len(self._data) >= self.capacity:
            # Remove all expired entries first.
            expired = [k for k in self._data if now >= self._data[k]]
            for k in expired:
                del self._data[k]
            # If still full, evict least recently used.
            if len(self._data) >= self.capacity:
                self._data.popitem(last=False)
        self._data[key] = expiry

    def get(self, key, now: int):
        if key not in self._data:
            return None
        if now >= self._data[key]:
            del self._data[key]
            return None
        self._data.move_to_end(key)
        # Recover value from stored tuple.
        return self._data[key][1]

    def size(self, now: int) -> int:
        return sum(1 for k in self._data if now < self._data[k])
```

Explanation: I store each value wrapped in a tuple `(value, since)` so that `get` can move-to-end without disturbing the stored expiry (the `move_to_end` call would otherwise overwrite the expiry). `put` on a new key first purges expired entries, then falls back to LRU eviction if still full. `get` treats `now >= expiry` as expired. `size` counts non-expired entries.

