def satisfies(version: str, range_: str) -> bool:
    v = _parse_version(version)
    for alt in range_.split("||"):
        if all(_compare(v, op, num) for op, num in _parse_range(alt)):
            return True
    return False


def _parse_version(s: str):
    return tuple(int(x) for x in s.strip().split("."))


def _parse_range(alt: str):
    result = []
    for token in alt.split():
        op = token[0]
        if op in "=><~^":
            num = _parse_version(token[1:])
        else:
            num = _parse_version(token)
        result.append((op, num))
    return result


def _compare(v, op, num):
    if op == "=":
        return v == num
    if op == ">":
        return v > num
    if op == ">=":
        return v >= num
    if op == "<":
        return v < num
    if op == "<=":
        return v <= num
    if op == "~":
        return v >= num and v < (num[0], num[1] + 1, 0)
    if op == "^":
        if num[0] > 0:
            upper = (num[0] + 1, 0, 0)
        elif num[1] > 0:
            upper = (0, num[1] + 1, 0)
        else:
            upper = (0, 0, num[2] + 1)
        return v >= num and v < upper
    raise ValueError(f"Unknown comparator: {op}")
```

Explanation:
- `_parse_version` splits a version into a tuple of ints for lexicographic (number-by-number) comparison.
- `_parse_range` splits on `||`, then on whitespace, extracting the operator prefix and the version number.
- `_compare` implements each comparator; `~` and `^` compute an exclusive upper bound following the caret-zero rules.

The version satisfies the range if it satisfies any alternative (each alternative requiring all its comparators).

```python
def build_order(deps: dict[str, list[str]]) -> list[str]:
    # Collect every target, including those that only appear as a dependency.
    targets = set(deps)
    for lst in deps.values():
        targets.update(lst)

    # Track how many unmet dependencies remain for each target.
    remaining = {t: 0 for t in targets}
    dependents: dict[str, list[str]] = {t: [] for t in targets}
    for t in targets:
        for d in deps.get(t, []):
            remaining[t] += 1
            dependents[d].append(t)

    import heapq

    # Min-heap of targets with no unmet dependencies for deterministic ordering.
    ready = [t for t in targets if remaining[t] == 0]
    heapq.heapify(ready)

    order: list[str] = []
    while ready:
        t = heapq.heappop(ready)
        order.append(t)
        for dependent in dependents[t]:
            remaining[dependent] -= 1
            if remaining[dependent] == 0:
                heapq.heappush(ready, dependent)

    if len(order) != len(targets):
        raise ValueError("Dependencies contain a cycle")

    return order
```

This performs a Kahn topological sort using a min-heap so that among all targets whose dependencies are already output, the alphabetically smallest is chosen each step. Targets appearing only in dependency lists are included. A cycle (including self-dependencies) is detected when not all targets are emitted.

```javascript
function applyPatch(doc, ops) {
  let current = doc;
  for (const op of ops) {
    if (!op || typeof op.op !== "string") {
      throw new Error("Invalid operation object");
    }
    if (typeof op.path !== "string") {
      throw new Error("Invalid path");
    }
    switch (op.op) {
      case "add":
        current = applyAdd(current, op.path, op.value);
        break;
      case "remove":
        current = applyRemove(current, op.path);
        break;
      case "replace":
        current = applyReplace(current, op.path, op.value);
        break;
      default:
        throw new Error("Unknown op: " + op.op);
    }
  }
  return current;
}

function applyAdd(doc, path, value) {
  if (path === "") {
    return value;
  }
  const segments = splitPath(path);
  const parent = getParent(doc, segments);
  const key = decodeSegment(segments[segments.length - 1]);
  if (Array.isArray(parent)) {
    const index = parseIndex(key);
    parent.splice(index, 0, value);
  } else {
    parent[key] = value;
  }
  return doc;
}

function applyRemove(doc, path) {
  if (path === "") {
    throw new Error("Cannot remove the whole document");
  }
  const segments = splitPath(path);
  const parent = getParent(doc, segments);
  const key = decodeSegment(segments[segments.length - 1]);
  if (Array.isArray(parent)) {
    const index = parseIndex(key);
    if (index < 0 || index >= parent.length) {
      throw new Error("Array index out of range: " + key);
    }
    parent.splice(index, 1);
  } else {
    if (!(key in parent)) {
      throw new Error("Target does not exist: " + path);
    }
    delete parent[key];
  }
  return doc;
}

function applyReplace(doc, path, value) {
  if (path === "") {
    return value;
  }
  const segments = splitPath(path);
  const parent = getParent(doc, segments);
  const key = decodeSegment(segments[segments.length - 1]);
  if (Array.isArray(parent)) {
    const index = parseIndex(key);
    if (index < 0 || index >= parent.length) {
      throw new Error("Array index out of range: " + key);
    }
    parent[index] = value;
  } else {
    if (!(key in parent)) {
      throw new Error("Target does not exist: " + path);
    }
    parent[key] = value;
  }
  return doc;
}

function getParent(doc, segments) {
  let node = doc;
  for (let i = 0; i < segments.length - 1; i++) {
    const key = decodeSegment(segments[i]);
    if (node == null || typeof node !== "object" || Array.isArray(node) || !(key in node)) {
      throw new Error("Parent does not exist for path: /" + segments.join("/"));
    }
    node = node[key];
  }
  return node;
}

function splitPath(path) {
  if (path[0] !== "/") {
    throw new Error("Path must start with /: " + path);
  }
  return path.slice(1).split("/");
}

function decodeSegment(segment) {
  return segment.replace(/~1|~0/g, (m) => (m === "~1" ? "/" : "~"));
}

function parseIndex(key) {
  if (!/^(0|[1-9][0-9]*)$/.test(key)) {
    if (key === "-") {
      throw new Error("Invalid array index: -");
    }
    throw new Error("Invalid array index: " + key);
