function deepMerge(base, override) {
  const result = {};

  for (const key of Object.keys(base)) {
    if (Object.prototype.hasOwnProperty.call(override, key)) {
      const baseVal = base[key];
      const overVal = override[key];
      if (overVal === undefined) {
        result[key] = deepClone(baseVal);
      } else if (isPlainObject(baseVal) && isPlainObject(overVal)) {
        result[key] = deepMerge(baseVal, overVal);
      } else {
        result[key] = deepClone(overVal);
      }
    } else {
      result[key] = deepClone(base[key]);
    }
  }

  for (const key of Object.keys(override)) {
    if (!Object.prototype.hasOwnProperty.call(base, key)) {
      result[key] = deepClone(override[key]);
    }
  }

  return result;
}

function isPlainObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    return false;
  }
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function deepClone(value) {
  if (Array.isArray(value)) {
    return value.map(deepClone);
  }
  if (isPlainObject(value)) {
    const out = {};
    for (const key of Object.keys(value)) {
      out[key] = deepClone(value[key]);
    }
    return out;
  }
  return value;
}
```

`deepMerge` builds a fresh object, recursively merging only plain-object values, replacing (deep-cloning) everything else, skipping `undefined` overrides, and deep-cloning all arrays/plain objects so nothing is shared with the inputs.

