#include <string>

long long parse_duration(const std::string& s) {
    long long total = 0;
    size_t i = 0, n = s.size();
    int last_unit = 0;  // 0: none, 1: h, 2: m, 3: s

    while (i < n) {
        // Parse a non-empty run of digits.
        long long num = 0;
        bool saw_digit = false;
        while (i < n && s[i] >= '0' && s[i] <= '9') {
            num = num * 10 + (s[i] - '0');
            ++i;
            saw_digit = true;
        }
        if (!saw_digit) return -1;  // no number before a unit

        // Expect exactly one unit character.
        if (i >= n) return -1;      // number without a unit
        char u = s[i];
        int unit;
        if (u == 'h')      unit = 1;
        else if (u == 'm') unit = 2;
        else if (u == 's') unit = 3;
        else               return -1;  // unknown unit
        ++i;

        if (unit <= last_unit) return -1;  // wrong order or repeated unit
        last_unit = unit;

        total += (u == 'h') ? num * 3600LL
                   : (u == 'm') ? num * 60LL
                                : num;
    }

    return total;
}
```

This walks the string expecting repeated `<digits><unit>` pairs. It rejects empty input, unknown units, a number with no unit, a unit with no number, out-of-order or repeated units, and any non-digit character (which covers spaces and signs). Units are checked to appear in strictly increasing `h < m < s` order, and the total is accumulated in seconds.

