from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity: int, ttl: int):
        self.capacity = capacity
        self.ttl = ttl
        self._expiries = OrderedDict()  # key -> expiry time (now + ttl)
        self._values = {}               # key -> value

    def put(self, key, value, now: int) -> None:
        if self.capacity <= 0:
            return
        if key in self._expiries:
            self._expiries.move_to_end(key)
        else:
            expired = [k for k, exp in self._expiries.items() if now >= exp]
            for k in expired:
                del self._expiries[k]
                del self._values[k]
            while len(self._expiries) >= self.capacity:
                old_key, _ = self._expiries.popitem(last=False)
                del self._values[old_key]
        self._expiries[key] = now + self.ttl
        self._values[key] = value

    def get(self, key, now: int):
        if key not in self._expiries:
            return None
        if now >= self._expiries[key]:
            del self._expiries[key]
            del self._values[key]
            return None
        self._expiries.move_to_end(key)
        return self._values[key]

    def size(self, now: int) -> int:
        return sum(1 for exp in self._expiries.values() if now < exp)
```

**Explanation:** The cache uses an `OrderedDict` to track expiry times (which also preserves recency order) alongside a plain dict for values. `put` updates expiry to `now + ttl` and marks the key most-recently-used; for new keys it first evicts expired entries, then LRU entries if still full. `get` returns `None` for missing/expired keys (evicting expired ones) and flips the recency flag on success without changing expiry. `size` counts non-expired entries.

