def satisfies(version: str, range_: str) -> bool:
    def parse(v: str):
        return tuple(int(p) for p in v.split('.'))

    def cmp(a, op, b):
        return {
            '>': a > b, '>=': a >= b, '<': a < b, '<=': a <= b,
            '=': a == b, '==': a == b,
        }[op]

    def satisfies_comparator(ver, op, target):
        if op == '~':
            return cmp(ver, '>=', target) and cmp(ver, '<', (target[0], target[1] + 1, 0))
        if op == '^':
            if target[0] > 0:
                upper = (target[0] + 1, 0, 0)
            elif target[1] > 0:
                upper = (0, target[1] + 1, 0)
            else:
                upper = (0, 0, target[2] + 1)
            return cmp(ver, '>=', target) and cmp(ver, '<', upper)
        return cmp(ver, op, target)

    def satisfies_alternative(ver, alternatives):
        parts = ver.split()
        for p in parts:
            op = ''
            for ch in ('>=', '<=', '~', '^', '>', '<', '='):
                if p.startswith(ch):
                    op = ch
                    break
            if op == '':
                op = '='
            target = parse(p[len(op):])
            if not satisfies_comparator(ver, op, target):
                return False
        return True

    ver = parse(version)
    for alt in range_.split('||'):
        if satisfies_alternative(ver, alt.strip()):
            return True
    return False
```

Explanation: The range is split on `||` (alternatives, any match), each alternative on whitespace (comparators, all must match). Each comparator is parsed for its operator (`>=`, `<=`, `~`, `^`, `>`, `<`, `=`, or implicit `=`), and versions are compared tuple-wise so `1.10.0 > 1.9.0`. The `~` and `^` operators build the appropriate upper bound, with `^` handling the zero-major/minor special cases.

```javascript
function applyPatch(doc, ops) {
  // Work on a deep copy so the original document is never mutated.
  let current = deepClone(doc);

  for (const op of ops) {
    const { op: operation, path, value } = op;

    // Path "" addresses the whole document.
    if (path === "") {
      if (operation === "add" || operation === "replace") {
        current = deepClone(value);
        continue;
      }
      throw new Error("Cannot " + operation + " at the root document.");
    }

    if (path[0] !== "/") {
      throw new Error("Path must start with '/': " + path);
    }

    const segments = parsePath(path);
    const last = segments.length - 1;

    for (let i = 0; i < segments.length; i++) {
      const segment = segments[i];
      const isLast = i === last;
      const parent = current;
      const key = segment;

      if (isLast) {
        applyOperation(operation, parent, key, value);
      } else {
        const next = parent[key];
        if (next === undefined || next === null || typeof next !== "object" || Array.isArray(next) === false && !isPlainObject(next)) {
          throw new Error("Parent does not exist at segment: " + segment);
        }
        current = next;
      }
    }
  }

  return current;
}

function applyOperation(operation, parent, key, value) {
  if (Array.isArray(parent)) {
    applyArrayOperation(operation, parent, key, value);
  } else {
    applyObjectOperation(operation, parent, key, value);
  }
}

function applyObjectOperation(operation, obj, key, value) {
  switch (operation) {
    case "add":
    case "replace":
      obj[key] = deepClone(value);
      return;
    case "remove":
      if (!(key in obj)) {
        throw new Error("Cannot remove missing member: " + key);
      }
      delete obj[key];
      return;
    default:
      throw new Error("Unknown operation: " + operation);
  }
}

function applyArrayOperation(operation, arr, index, value) {
  const idx = index === "-" ? arr.length : parseArrayIndex(index, arr.length);

  switch (operation) {
    case "add":
      if (idx > arr.length) {
        throw new Error("Array index out of range: " + index);
      }
      arr.splice(idx, 0, deepClone(value));
      return;
    case "replace":
      if (idx >= arr.length) {
        throw new Error("Cannot replace missing array element: " + index);
      }
      arr[idx] = deepClone(value);
      return;
    case "remove":
      if (idx >= arr.length) {
        throw new Error("Cannot remove missing array element: " + index);
      }
      arr.splice(idx, 1);
      return;
    default:
      throw new Error("Unknown operation: " + operation);
  }
}

function parseArrayIndex(index, length) {
  if (!/^[0-9]+$/.test(index)) {
    throw new Error("Array index must be a non-negative integer or '-': " + index);
  }
  const n = Number(index);
  if (!Number.isInteger(n) || n < 0) {
    throw new Error("Array index must be a non-negative integer: " + index);
  }
  return n;
}

function parsePath(path) {
  const parts = path.split("/").slice(1); // drop leading empty string
  return parts.map(decodeSegment);
}

function decodeSegment(segment) {
  return segment.replace(/~1|~0/g, (m) => (m === "~1" ? "/" : "~"));
}

function isPlainObject(value) {
  return value !== null && typeof value === "object" && !Array.isArray(value);
}

function deepClone(value) {
  if (value === null || typeof value !== "object") {
    return value;
  }
  if (Array.isArray(value)) {
    return value.map(deepClone);
  }
  const out = {};
  for (const key of Object.keys(value)) {
    out[key] = deepClone(value[key]);
  }
  return out;
}
```

Explanation:

- `applyPatch` deep-clones the input first (so `doc` is never mutated), then walks each op's path.
- Paths are split on `/`; `~1`→`/` and `~0`→`~` are decoded per segment. Empty path = root.
- Traversal descends into parents, throwing if a parent is missing; the final segment performs the op.
- `add`/`replace`/`remove` are enforced per container (object vs array), with array bounds checking and `-` meaning append.
- Any unknown op, missing parent, missing target, or out-of-range index throws an `Error`.

