function deepMerge(base, override) {
  const result = Array.isArray(base) ? [...base] : { ...base };

  for (const key of Object.keys(override)) {
    const overrideValue = override[key];

    if (overrideValue === undefined) {
      continue;
    }

    if (
      overrideValue !== null &&
      typeof overrideValue === 'object' &&
      !Array.isArray(overrideValue) &&
      base[key] !== null &&
      typeof base[key] === 'object' &&
      !Array.isArray(base[key])
    ) {
      result[key] = deepMerge(base[key], overrideValue);
    } else {
      if (
        overrideValue !== null &&
        typeof overrideValue === 'object'
      ) {
        result[key] = Array.isArray(overrideValue)
          ? [...overrideValue]
          : deepMerge({}, overrideValue);
      } else {
        result[key] = overrideValue;
      }
    }
  }

  return result;
}
```

`deepMerge` recursively merges plain objects, replaces arrays/scalars from `override`, ignores `undefined` values while keeping `null`, preserves `base`-only keys, and never mutates the inputs (it clones every nested object/array it touches).

