#include <string>

long long parse_duration(const std::string& s) {
    long long total = 0;
    int i = 0;
    const int n = static_cast<int>(s.size());
    int last = 0;  // 0 = none, 1 = h, 2 = m, 3 = s
    const long long mult[4] = {0, 3600, 60, 1};
    const char unit[4] = {' ', 'h', 'm', 's'};

    while (i < n) {
        long long num = 0;
        bool has_num = false;
        while (i < n && s[i] >= '0' && s[i] <= '9') {
            has_num = true;
            num = num * 10 + (s[i] - '0');
            ++i;
        }
        if (!has_num) {
            return -1;  // unit without a number, or trailing garbage
        }
        if (i >= n || s[i] < 'a' || s[i] > 'z') {
            return -1;  // number without a unit, or invalid character
        }
        int cur = 0;
        if (s[i] == 'h') cur = 1;
        else if (s[i] == 'm') cur = 2;
        else if (s[i] == 's') cur = 3;
        else {
            return -1;  // unknown unit
        }
        if (cur <= last) {
            return -1;  // wrong order or repeated unit
        }
        total += num * mult[cur];
        last = cur;
        ++i;
    }
    return total;
}
```

This parser walks the string, requiring a digit run before each unit, checking the unit is one of `h`/`m`/`s`, enforcing strict h→m→s ordering (so repeats and wrong orders are rejected), and rejecting any trailing non-unit characters, spaces, or signs. An empty string returns `-1` since the loop never records a valid part.

