```python
from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity: int, ttl: int):
        self._capacity = capacity
        self._ttl = ttl
        self._expiry = {}   # key -> expiry time
        self._values = OrderedDict()  # key -> value, ordered by recency

    def put(self, key, value, now: int) -> None:
        expiry = now + self._ttl
        if key in self._expiry:
            self._expiry[key] = expiry
            self._values.move_to_end(key)
        else:
            if self._capacity <= 0:
                return
            if len(self._expiry) == self._capacity:
                expired = [k for k, e in self._expiry.items() if now >= e]
                for k in expired:
                    del self._expiry[k]
                    self._values.pop(k, None)
                if len(self._expiry) == self._capacity:
                    evict, _ = self._values.popitem(last=False)
                    del self._expiry[evict]
            self._expiry[key] = expiry
            self._values[key] = value

    def get(self, key, now: int):
        if key not in self._expiry:
            return None
        if now >= self._expiry[key]:
            del self._expiry[key]
            self._values.pop(key, None)
            return None
        self._values.move_to_end(key)
        return self._values[key]

    def size(self, now: int) -> int:
        return sum(1 for e in self._expiry.values() if now < e)
```

Explanation: The cache uses an `OrderedDict` for recency order (`_values`) plus a parallel `_expiry` dict for expiry times. `put` on a new key evicts expired entries first, then the LRU if still full. `get` treats `now >= expiry` as expired, returns `None`, and refreshes recency without changing expiry. `size` counts non-expired entries.

```python
def satisfies(version: str, range_: str) -> bool:
    v = tuple(int(x) for x in version.split('.'))

    def cmp(a, b):
        return (a > b) - (a < b)

    def check(cmp_op: str, target: tuple) -> bool:
        c = cmp(v, target)
        return {
            '=': lambda: c == 0,
            '>': lambda: c > 0,
            '>=': lambda: c >= 0,
            '<': lambda: c < 0,
            '<=': lambda: c <= 0,
        }[cmp_op]()

    def parse(s: str):
        s = s.strip()
        op = ''
        if s[0] in '=<>~^':
            op = s[0]
            s = s[1:]
        return op, tuple(int(x) for x in s.split('.'))

    def check_alternative(text: str) -> bool:
        parts = [p for p in text.split() if p]
        return all(check_comparator(p) for p in parts)

    def check_comparator(text: str) -> bool:
        op, target = parse(text)
        if op == '~':
            return check('>=', target) and check('<', (target[0], target[1] + 1, 0))
        if op == '^':
            if target[0] > 0:
                return check('>=', target) and check('<', (target[0] + 1, 0, 0))
            if target[1] > 0:
                return check('>=', target) and check('<', (0, target[1] + 1, 0))
            return check('>=', target) and check('<', (0, 0, target[2] + 1))
        if op == '':
            op = '='
        return check(op, target)

    return any(check_alternative(alt) for alt in range_.split('||'))
```

Explanation: The version is parsed into a tuple of ints for lexicographic comparison. Each `||` alternative is checked independently; within an alternative, all space-separated comparators must hold. Tilde and caret ranges are expanded into two bound comparators, with caret handling the zero-major/minor special cases.

```javascript
function applyPatch(doc, ops) {
  let value = doc;

  for (const op of ops) {
    if (!op || typeof op !== 'object') {
      throw new Error('Invalid operation object');
    }
    if (!['add', 'remove', 'replace'].includes(op.op)) {
      throw new Error('Unknown op: ' + op.op);
    }
    if (typeof op.path !== 'string') {
      throw new Error('Path must be a string');
    }

    const segments = op.path === '' ? [] : splitPath(op.path);

    if (op.op === 'add') {
      if (segments.length === 0) {
        value = op.value;
        continue;
      }
      const parent = value;
      const key = segments.pop();
      const arr = Array.isArray(parent);
      const idx = arr ? (key === '-' ? parent.length : parseIndex(key, arr)) : key;

      if (arr) {
        if (idx < 0 || idx > parent.length) {
          throw new Error('Array index out of range: ' + key);
        }
        parent.splice(idx, 0, op.value);
      } else {
        parent[key] = op.value;
      }
    } else if (op.op === 'remove') {
      if (segments.length === 0) {
        throw new Error('Cannot remove the entire document');
      }
      const parent = value;
      const key = segments.pop();
      if (parent === undefined || parent === null || !(key in parent)) {
        throw new Error('Missing target for remove: ' + key);
      }
      if (Array.isArray(parent)) {
        const idx = parseIndex(key, parent);
        if (idx < 0 || idx >= parent.length) {
          throw new Error('Array index out of range: ' + key);
        }
        parent.splice(idx, 1);
      } else {
        delete parent[key];
      }
    } else { // replace
      if (segments.length === 0) {
        value = op.value;
        continue;
      }
      const parent = value;
      const key = segments.pop();
      if (parent === undefined || parent === null || !(key in parent)) {
        throw new Error('Missing target for replace: ' + key);
      }
      if (Array.isArray(parent)) {
        const idx = parseIndex(key, parent);
        if (idx < 0 || idx >= parent.length) {
          throw new Error('Array index out of range: ' + key);
        }
        parent[idx] = op.value;
      } else {
        parent[key] = op.value;
      }
    }
  }

  return value;
}

function splitPath(path) {
  if (path.charAt(0) !== '/') {
    throw new Error('Path must start with /: ' + path);
  }
  return path.slice(1).split('/').map(unescapeSegment);
}

function unescapeSegment(seg) {
  return seg.replace(/~1|~0/g, (m) => (m === '~1' ? '/' : '~'));
}

function parseIndex(key, arr) {
  if (!/^[0-9]+$/.test(key)) {
    throw new Error('Array index must be a non-negative whole number: ' + key);
  }
  const idx = Number(key);
  if (idx > arr.length) {
    throw new Error('Array index out of range: ' + key);
  }
  return idx;
}
```

The function walks the path, applying each op in order while only mutating a growing copy (`value`), leaving the original `doc` untouched. It handles JSON-pointer escaping (`~1`→`/`, `~0`→`~`), array insert/append (`-`), and throws on unknown ops, missing parents/targets, and out-of-range indices.

