from datetime import date
from datetime import time


def parse_date(text: str) -> date:
    """Parse a date string in exactly one of three supported formats.

    Raises ValueError for anything that isn't a valid date in a supported format.
    """
    text = text.strip()

    # ISO format: 2025-03-07
    try:
        return date.fromisoformat(text)
    except ValueError:
        pass

    # British numeric: 07/03/2025 (day/month/year)
    parts = text.split("/")
    if len(parts) == 3 and all(p.isdigit() for p in parts):
        day, month, year = (int(p) for p in parts)
        try:
            return date(year, month, day)
        except ValueError:
            pass

    # Short text: 7 Mar 2025 (English three-letter month, day may lack leading zero)
    try:
        parsed = date.strptime(text, "%d %b %Y")
    except ValueError:
        pass
    else:
        return parsed

    raise ValueError(f"Unrecognized or invalid date: {text!r}")
```

Explanation: The function tries each format in order and falls through to `ValueError` on failure. `date.fromisoformat` rejects impossible dates like `2025-13-40`; the tuple constructor `date(year, month, day)` rejects impossible dates like `31/02/2025`; and `strptime` with `%d` handles the optional leading zero. Note that `strptime` is somewhat lenient (e.g. it accepts `7 March 2025`), but it correctly rejects malformed month names and impossible dates.

