from typing import Any


def normalise_order(raw: dict) -> dict:
    """Return a new, normalised order dict derived from `raw`.

    Raises ValueError on any invalid or missing required value.
    """
    # --- sku ---------------------------------------------------------------
    sku_raw = raw.get("sku")
    if not isinstance(sku_raw, str):
        raise ValueError("sku must be a string")
    sku = sku_raw.strip().upper()
    if not sku:
        raise ValueError("sku must not be empty")

    # --- qty ---------------------------------------------------------------
    qty = _coerce_qty(raw.get("qty"))

    # --- unit_price_pence --------------------------------------------------
    unit_price_pence = _coerce_price(raw.get("unit_price_pence"))

    # --- currency ----------------------------------------------------------
    currency_raw = raw.get("currency")
    if isinstance(currency_raw, str) and currency_raw.strip():
        currency = currency_raw.strip().upper()
        if currency not in ("GBP", "EUR", "USD"):
            raise ValueError(f"unsupported currency: {currency_raw!r}")
    else:
        currency = "GBP"

    # --- total -------------------------------------------------------------
    total_pence = qty * unit_price_pence

    return {
        "sku": sku,
        "qty": qty,
        "unit_price_pence": unit_price_pence,
        "currency": currency,
        "total_pence": total_pence,
    }


def _coerce_qty(value: Any) -> int:
    # Reject bools explicitly (bool is a subclass of int).
    if isinstance(value, bool):
        raise ValueError("qty must be an int or numeric string")

    if isinstance(value, int):
        qty = value
    elif isinstance(value, str) and value.strip():
        try:
            qty = int(value.strip())
        except ValueError:
            # Could be a float-like string; try that before giving up.
            try:
                qty = int(float(value.strip()))
            except ValueError:
                raise ValueError(f"invalid qty: {value!r}")
    else:
        raise ValueError(f"missing or invalid qty: {value!r}")

    if not 1 <= qty <= 99:
        raise ValueError(f"qty out of range (1-99): {qty}")
    return qty


def _coerce_price(value: Any) -> int:
    if isinstance(value, bool):
        raise ValueError("unit_price_pence must be an int or numeric string")

    if isinstance(value, int):
        price = value
    elif isinstance(value, str) and value.strip():
        try:
            price = int(value.strip())
        except ValueError:
            try:
                price = int(float(value.strip()))
            except ValueError:
                raise ValueError(f"invalid unit_price_pence: {value!r}")
    else:
        raise ValueError(f"missing or invalid unit_price_pence: {value!r}")

    if price < 0:
        raise ValueError(f"unit_price_pence must be >= 0: {price}")
    return price
```

Explanation:

- A **new dict** is built at the end, so `raw` is never mutated.
- Each required field is validated via small helpers; anything missing/blank/`None`/wrong-type raises `ValueError` (never `KeyError`, thanks to `.get()`).
- `sku` must be a non-empty string after stripping; `qty` accepts `int` or numeric strings (including `" 3 "`) and must land in 1–99; `unit_price_pence` must be ≥ 0.
- `currency` is upper-cased/stripped when a non-blank string is present and must be one of `GBP`/`EUR`/`USD`, defaulting to `"GBP"` otherwise.
- `total_pence` is simply `qty * unit_price_pence`.

