#include <string>

long long parse_duration(const std::string& s) {
    long long total = 0;
    long long num = 0;
    int have_num = 0;
    int last = -1;
    bool any = false;

    static const int unit_rank[256] = { -1 };
    int ranks[256];
    ranks['h'] = 0; ranks['m'] = 1; ranks['s'] = 2;

    for (size_t i = 0; i < s.size(); ++i) {
        char c = s[i];
        if (c >= '0' && c <= '9') {
            num = num * 10 + (c - '0');
            have_num = 1;
        } else if (c == 'h' || c == 'm' || c == 's') {
            if (!have_num) return -1;
            int r = ranks[(unsigned char)c];
            if (r <= last) return -1;
            last = r;
            switch (r) {
                case 0: total += num * 3600LL; break;
                case 1: total += num * 60LL; break;
                case 2: total += num; break;
            }
            num = 0;
            have_num = 0;
            any = 1;
        } else {
            return -1;
        }
    }
    if (!have_num && any) return -1;
    return have_num ? -1 : total;
}
```

The function scans left to right, accumulating digits into `num` and, on encountering a unit, validating that a number preceded it and that the unit's rank (h=0, m=1, s=2) strictly increases. Any space or other character returns -1. A trailing number with no unit, or a unit with no number, also returns -1; otherwise the total seconds are returned.

```python
from dataclasses import dataclass


@dataclass
class Page:
    number: int
    items: list
    has_next: bool


class Paginator:
    """Splits a list of search results into 1-based pages."""

    def __init__(self, items: list, page_size: int):
        if page_size < 1:
            raise ValueError("page_size must be >= 1")
        self.items = items
        self.page_size = page_size

    @property
    def page_count(self) -> int:
        return (len(self.items) + self.page_size - 1) // self.page_size

    def get_page(self, number: int) -> Page:
        if number < 1 or number > max(self.page_count, 1):
            raise ValueError(f"page {number} out of range")
        start = (number - 1) * self.page_size
        end = start + self.page_size
        return Page(
            number=number,
            items=self.items[start:end],
            has_next=number < self.page_count,
        )
```

The bug was in `page_count`, which used floor division (`len // page_size`), causing it to undercount by one whenever the list length wasn't an exact multiple of the page size (e.g., 10 items with page size 4 should yield 3 pages, not 2); the fix uses ceiling division `(len + page_size - 1) // page_size`.

