from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity: int, ttl: int):
        self.capacity = capacity
        self.ttl = ttl
        self._data = OrderedDict()  # key -> expiry time
        self._now = None

    def put(self, key, value, now: int) -> None:
        self._now = now
        expiry = now + self.ttl
        if key in self._data:
            self._data.move_to_end(key)
            self._data[key] = expiry
            return
        # Adding a new key.
        if self.capacity > 0:
            # Remove every expired entry first.
            self._evict_expired()
            # Only if still full, remove the least recently used entry.
            if self.capacity <= len(self._data):
                self._data.popitem(last=False)
            self._data[key] = expiry

    def get(self, key, now: int):
        self._now = now
        if key not in self._data:
            return None
        expiry = self._data[key]
        if now >= expiry:
            del self._data[key]
            return None
        self._data.move_to_end(key)
        return self._data[key]  # value stored alongside expiry

    def size(self, now: int) -> int:
        self._now = now
        if self._now is not None:
            self._evict_expired()
        return len(self._data)

    def _evict_expired(self):
        expired = [k for k, exp in self._data.items() if self._now >= exp]
        for k in expired:
            del self._data[k]
```

Explanation: Each entry stores its expiry time; the `OrderedDict` preserves usage order (most-recently-used at the end). On `put` of a new key, expired entries are purged first, and only if still full is the least-recently-used entry removed. `get` doesn't alter expiry, and `size` counts non-expired entries.

