def _cmp_key(v: str):
    return tuple(int(x) for x in v.split('.'))


def _compare(a: str, b: str) -> int:
    ka, kb = _cmp_key(a), _cmp_key(b)
    return (ka > kb) - (ka < kb)


def _satisfies_comparator(version: str, comp: str) -> bool:
    text = comp.strip()
    if text.startswith('~'):
        base = text[1:]
        return _cmp_key(version) >= _cmp_key(base) and _cmp_key(version) < _cmp_key(base.rsplit('.', 1)[0] + '.0')
    if text.startswith('^'):
        base = text[1:]
        parts = base.split('.')
        if len(parts) < 2:
            parts += ['0'] * (2 - len(parts))
        if parts[0] != '0':
            upper = str(int(parts[0]) + 1) + '.0.0'
        elif parts[1] != '0':
            upper = '0.' + str(int(parts[1]) + 1) + '.0'
        else:
            upper = '0.0.' + str(int(parts[2]) + 1)
        return _cmp_key(version) >= _cmp_key(base) and _cmp_key(version) < _cmp_key(upper)

    for op in ('>=', '<=', '=', '>', '<'):
        if text.startswith(op):
            base = text[len(op):]
            c = _compare(version, base)
            if op == '>=': return c >= 0
            if op == '<=': return c <= 0
            if op == '=': return c == 0
            if op == '>': return c > 0
            if op == '<': return c < 0

    return _compare(version, text) == 0


def satisfies(version: str, range_: str) -> bool:
    for alt in range_.split('||'):
        if all(_satisfies_comparator(version, comp) for comp in alt.split()):
            return True
    return False
```

Explanation: Versions are split into integer tuples and compared component-wise. Each `||` alternative is checked independently (any match satisfies); within an alternative, every space-separated comparator must match. `~` caps at the next minor, while `^` caps at the next major (or minor/patch when the leading component is `0`). Only the standard library is used.

```javascript
function applyPatch(doc, ops) {
  // Work on a deep clone so the original document is never mutated.
  let current = clone(doc);

  for (const op of ops) {
    if (!op || typeof op.op !== 'string' || !('path' in op)) {
      throw new Error('Invalid operation');
    }

    const { op: operation, path, value } = op;

    if (path === '') {
      applyWhole(current, operation, value);
      current = current; // whole-doc replacement already handled
      continue;
    }

    if (typeof path !== 'string' || path.charAt(0) !== '/') {
      throw new Error('Invalid path');
    }

    const segments = parsePath(path);
    applySegmented(current, segments, operation, value);
  }

  return current;
}

function applyWhole(doc, operation, value) {
  switch (operation) {
    case 'add':
    case 'replace':
      return value; // whole document replaced
    case 'remove':
      throw new Error('Cannot remove the whole document');
    default:
      throw new Error('Unknown operation: ' + operation);
  }
}

function applySegmented(current, segments, operation, value) {
  switch (operation) {
    case 'add':
      add(current, segments, value);
      break;
    case 'remove':
      remove(current, segments);
      break;
    case 'replace':
      replace(current, segments, value);
      break;
    default:
      throw new Error('Unknown operation: ' + operation);
  }
}

function add(parent, segments, value) {
  const key = segments[0];

  if (segments.length === 1) {
    // Target is the parent itself.
    if (Array.isArray(parent)) {
      const index = resolveArrayIndex(parent, key);
      if (index > parent.length) {
        throw new Error('Array index out of range');
      }
      parent.splice(index, 0, clone(value));
    } else if (parent !== null && typeof parent === 'object') {
      parent[key] = clone(value);
    } else {
      throw new Error('Cannot add to a non-container');
    }
    return;
  }

  // Navigate to the parent of the target.
  const target = getContainer(parent, key, false);
  add(target, segments.slice(1), value);
}

function remove(parent, segments) {
  const key = segments[0];

  if (segments.length === 1) {
    if (Array.isArray(parent)) {
      const index = resolveArrayIndex(parent, key);
      parent.splice(index, 1);
    } else if (parent !== null && typeof parent === 'object') {
      if (!(key in parent)) {
        throw new Error('Target does not exist');
      }
      delete parent[key];
    } else {
      throw new Error('Cannot remove from a non-container');
    }
    return;
  }

  const target = getContainer(parent, key, true);
  remove(target, segments.slice(1));
}

function replace(parent, segments, value) {
  const key = segments[0];

  if (segments.length === 1) {
    if (Array.isArray(parent)) {
      const index = resolveArrayIndex(parent, key);
      parent[index] = clone(value);
    } else if (parent !== null && typeof parent === 'object') {
      if (!(key in parent)) {
        throw new Error('Target does not exist');
      }
      parent[key] = clone(value);
    } else {
      throw new Error('Cannot replace in a non-container');
    }
    return;
  }

  const target = getContainer(parent, key, true);
  replace(target, segments.slice(1), value);
}

// Returns the child container at `key`, throwing if it doesn't exist or isn't an
// object/array. For `add`, the parent may not exist yet (except for arrays, where
// an out-of-range index is still an error).
function getContainer(parent, key, mustExist) {
  if (parent === null || typeof parent !== 'object') {
    throw new Error('Parent does not exist');
  }

  if (Array.isArray(parent)) {
    const index = resolveArrayIndex(parent, key);
    if (index > parent.length) {
      throw new Error('Array index out of range');
    }
    // Arrays never need pre-creation; a valid index here is fine.
    return parent;
  }

  if (mustExist && !(key in parent)) {
    throw new Error('Parent does not exist');
  }

  const child = parent[key];
  if (mustExist && (child === null || typeof child !== 'object')) {
    throw new Error('Parent does not exist');
  }

  return parent;
}

function resolveArrayIndex(arr, key) {
  if (!/^(0|[1-9][0-9]*)$/.test(key)) {
    throw new Error('Invalid array index: ' + key);
  }
  const index = Number(key);
  if (index > arr.length) {
    throw new Error('Array index out of range');
  }
  return index;
}

function parsePath(path) {
  const parts = path.split('/').slice(1); // drop leading empty string
  return parts.map(decodeSegment);
}

function decodeSegment(segment) {
  return segment.replace(/~(.)/g, (_, c) => (c === '1' ? '/' : c === '0' ? '~' : c));
}

function clone(value) {
  if (value === null || typeof value !== 'object') {
    return value;
  }
  if (Array.isArray(value)) {
    return value.map(clone);
  }
  const out = {};
  for (const k of Object.keys(value)) {
    out[k] = clone(value[k]);
  }
  return out;
}
```

Explanation: `applyPatch` deep-clones the document first, so the original is never mutated. It then applies each op in order: `""` paths replace the whole document; otherwise the path is split into segments (decoding `~1`→`/`, `~0`→`~`) and walked down. `add` inserts into arrays (index may equal length, `-` appends), sets object members, or replaces the doc; `remove`/`replace` require the target to exist. Array indices must be non-negative integers within range, and any other invalid input throws an `Error`.

