from datetime import date


def parse_date(text: str) -> date:
    """Parse an invoice date from ISO, British numeric, or short text formats.

    Raises ValueError for any input that is not one of the supported formats
    or that does not represent a real calendar date.
    """
    text = text.strip()

    # ISO: 2025-03-07
    try:
        return date.fromisoformat(text)
    except ValueError:
        pass

    # British numeric: 07/03/2025 (day/month/year)
    parts = text.split("/")
    if len(parts) == 3 and all(p.isdigit() for p in parts):
        day_str, month_str, year_str = parts
        try:
            return date(int(year_str), int(month_str), int(day_str))
        except ValueError:
            pass

    # Short text: 7 Mar 2025 (English three-letter month)
    tokens = text.split()
    if len(tokens) == 3:
        day_str, month_str, year_str = tokens
        if day_str.isdigit() and len(month_str) == 3 and year_str.isdigit():
            try:
                return date.fromisoformat(f"{year_str}-{month_str.title()}-{day_str.zfill(2)}")
            except ValueError:
                pass

    raise ValueError(f"Unrecognized or invalid date: {text!r}")
