function deepMerge(base, override) {
  const result = {};
  for (const key of Object.keys(base)) {
    result[key] = deepClone(base[key]);
  }
  for (const key of Object.keys(override)) {
    const overrideVal = override[key];
    if (overrideVal === undefined) continue;
    const baseVal = base[key];
    if (
      isPlainObject(baseVal) &&
      isPlainObject(overrideVal)
    ) {
      result[key] = deepMerge(baseVal, overrideVal);
    } else {
      result[key] = deepClone(overrideVal);
    }
  }
  return result;
}

function isPlainObject(value) {
  if (value === null || typeof value !== 'object' || Array.isArray(value)) {
    return false;
  }
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function deepClone(value) {
  if (Array.isArray(value)) {
    return value.map(deepClone);
  }
  if (isPlainObject(value)) {
    const obj = {};
    for (const key of Object.keys(value)) {
      obj[key] = deepClone(value[key]);
    }
    return obj;
  }
  return value;
}
```

This implementation recursively merges while deep-cloning all values, ensuring the result shares no references with the inputs. `undefined` values are skipped, `null` replaces, arrays replace (via clone), and plain objects merge recursively.

