#include <string>

long long parse_duration(const std::string& s) {
    long long total = 0;
    long long current = 0;
    bool has_number = false;
    int prev = 3;  // h=3, m=2, s=1; track last unit for ordering

    int i = 0;
    const int n = static_cast<int>(s.size());

    while (i < n) {
        char c = s[i];
        if (c >= '0' && c <= '9') {
            current = current * 10 + (c - '0');
            has_number = true;
            ++i;
        } else if (c == 'h' || c == 'm' || c == 's') {
            if (!has_number) return -1;
            int unit = (c == 'h') ? 3 : (c == 'm') ? 2 : 1;
            if (unit >= prev) return -1;
            prev = unit;
            if (c == 'h') total += current * 3600;
            else if (c == 'm') total += current * 60;
            else total += current;
            current = 0;
            has_number = false;
            ++i;
        } else {
            return -1;
        }
    }

    if (!has_number) return -1;  // trailing digits without a unit
    return total;
}
