def satisfies(version: str, range_: str) -> bool:
    def parse(v: str):
        return tuple(int(x) for x in v.split('.'))

    def cmp(a, b):
        return (a > b) - (a < b)

    def check(v, op, target):
        c = cmp(parse(v), parse(target))
        if op == '=':
            return c == 0
        if op == '>':
            return c > 0
        if op == '>=':
            return c >= 0
        if op == '<':
            return c < 0
        if op == '<=':
            return c <= 0
        if op == '~':
            return c >= 0 and (parse(v)[0], parse(v)[1]) < (parse(target)[0], parse(target)[1] + 1)
        if op == '^':
            mv, mt = parse(v), parse(target)
            if mt[0] > 0:
                upper = (mt[0] + 1, 0, 0)
            elif mt[1] > 0:
                upper = (0, mt[1] + 1, 0)
            else:
                upper = (0, 0, mt[2] + 1)
            return c >= 0 and cmp(mv, upper) < 0
        raise ValueError(f"Unknown comparator: {op}")

    def check_alternative(v, alts):
        return all(check(v, op, target) for op, target in alts)

    for alternative in range_.split('||'):
        tokens = alternative.split()
        alts = []
        i = 0
        while i < len(tokens):
            t = tokens[i]
            if t[0] in '>=<!^~':
                op = t[0]
                target = t[1:]
            else:
                op = '='
                target = t
            alts.append((op, target))
            i += 1
        if check_alternative(version, alts):
            return True
    return False
```

Explanation: I split the range on `||`, then each alternative into comparator tokens. Each token's leading operator (`>`, `=`, etc.) is parsed, defaulting to `=`. Comparisons use tuple comparison so `1.10.0 > 1.9.0`. The `~` and `^` operators compute upper bounds exactly per the rules, including the special zero-major/minor cases for `^`. A version satisfies the range if it passes at least one alternative.

```python
def build_order(deps: dict[str, list[str]]) -> list[str]:
    # Collect every target, including those that only appear as a dependency.
    targets = set(deps)
    for ds in deps.values():
        targets.update(ds)

    # Track how many dependencies are still unmet for each target.
    remaining = {t: set() for t in targets}
    for t in targets:
        for d in deps.get(t, []):
            remaining[t].add(d)

    # Kahn's algorithm with a deterministic tie-break.
    done: list[str] = []
    available = sorted(t for t in targets if not remaining[t])

    while available:
        t = available.pop(0)
        done.append(t)
        # For each target that depends on t, remove t from its unmet set.
        newly = []
        for other in targets:
            if t in remaining[other]:
                remaining[other].discard(t)
                if not remaining[other] and other not in done:
                    newly.append(other)
        if newly:
            available.extend(newly)
            available.sort()

    if len(done) != len(targets):
        raise ValueError("dependency cycle detected")

    return done
```

This performs a topological sort using Kahn's algorithm, always picking the alphabetically smallest available target. A cycle (including self-dependencies) is detected when not all targets can be emitted. Note the inner loop is O(n²) per removal, so it's fine for small graphs but would need a reverse adjacency list for large inputs.

