  function splitPath(path) {
    if (path === '') return [];
    if (path[0] !== '/') {
      throw new Error('Invalid path: must start with / or be empty');
    }
    return path
      .substring(1)
      .split('/')
      .map(decodeSegment);
  }

  function getValue(target, segments) {
    let cur = target;
    for (const seg of segments) {
      if (cur === undefined || cur === null || typeof cur !== 'object') {
        throw new Error('Parent does not exist at ' + seg);
      }
      cur = cur[seg];
    }
    return cur;
  }

  function setValue(target, segments, value) {
    if (segments.length === 0) {
      return value;
    }
    const [first, ...rest] = segments;

    let arr = isArr(target);
    let obj = isObj(target);
    if (!arr && !obj) {
      throw new Error('Cannot descend into non-object at ' + first);
    }

    const clone = arr ? target.slice() : { ...target };

    if (rest.length === 0) {
      clone[first] = value;
      return clone;
    }

    if (first === '-') {
      if (!arr) {
        throw new Error('Cannot append to non-array');
      }
      clone.push(setValue(target, rest, value));
      return clone;
    }

    if (arr) {
      const idx = Number(first);
      if (!/^\d+$/.test(first) || String(idx) !== first || idx >= clone.length) {
        throw new Error('Array index out of range at ' + first);
      }
    }

    clone[first] = setValue(clone[first], rest, value);
    return clone;
  }

  function removeValue(target, segments) {
    const [first, ...rest] = segments;

    if (rest.length === 0) {
      if (isArr(target)) {
        const idx = Number(first);
        if (!/^\d+$/.test(first) || String(idx) !== first || idx >= target.length) {
          throw new Error('Array index out of range at ' + first);
        }
        return target.filter((_, i) => i !== idx);
      }
      if (!isObj(target)) {
        throw new Error('Cannot remove from non-container');
      }
      if (!(first in target)) {
        throw new Error('Target does not exist for remove: ' + first);
      }
      const clone = { ...target };
      delete clone[first];
      return clone;
    }

    let cur = target;
    for (let i = 0; i < rest.length; i++) {
      const seg = rest[i];
      const next = cur[seg];
      if (next === undefined || next === null || typeof next !== 'object') {
        throw new Error('Parent does not exist at ' + seg);
      }
      cur = next;
    }

    const last = rest[rest.length - 1];
    if (isArr(cur)) {
      const idx = Number(last);
      if (!/^\d+$/.test(last) || String(idx) !== last || idx >= cur.length) {
        throw new Error('Array index out of range at ' + last);
      }
    } else if (!isObj(cur)) {
      throw new Error('Cannot descend into non-object');
    }

    if (cur === undefined || cur === null || typeof cur !== 'object') {
      throw new Error('Parent does not exist');
    }

    if (isArr(cur)) {
      const idx = Number(last);
      cur = cur.slice();
      cur.splice(idx, 1);
    } else if (!(last in cur)) {
      throw new Error('Target does not exist for remove: ' + last);
    } else {
      cur = { ...cur };
      delete cur[last];
    }

    return setValue(target, rest, cur);
  }

  for (const op of ops) {
    const { op: operation, path, value } = op;
    const segments = splitPath(path);

    if (operation === 'add') {
      result = setValue(result, segments, value);
    } else if (operation === 'replace') {
      if (segments.length === 0) {
        result = value;
      } else {
        const existing = getValue(result, segments);
        if (existing === undefined || !(segments[segments.length - 1] in getValue(result, segments.slice(0, -1) || {}))) {
          throw new Error('Target does not exist for replace');
        }
        result = setValue(result, segments, value);
      }
    } else if (operation === 'remove') {
      result = removeValue(result, segments);
    } else {
      throw new Error('Unknown op: ' + operation);
    }
  }

  return result;
}
```

Explanation:

- **Immutability**: Every mutation produces a cloned array/object (`slice`, spread), so the original `doc` is never touched. The root is replaced via a local `result` variable.
- **Paths**: `""` → whole doc; otherwise split on `/` after decoding `~1`→`/`, `~0`→`~`.
- **add**: `setValue` handles object set, array insert (index must be `< length`, or append at end), `-` append, and root replacement.
- **remove**: deletes object member or array element (shifting later elements up), validating existence.
- **replace**: requires the target to exist, then sets it.
- **Validation**: unknown op, missing parents, missing targets, and out-of-range indices all throw `Error`. Array indices are validated as non-negative whole numbers via regex.

```python
import re

def satisfies(version: str, range_: str) -> bool:
    """
    Check if a semantic‑style version satisfies a range expression.
    """
    # helper: convert version string to tuple of ints
    def to_tuple(v: str):
        parts = [int(x) for x in v.split('.')]
        while len(parts) < 3:
            parts.append(0)
        return tuple(parts)

    # compare two version tuples
    def compare(v1, v2):
        return (v1 > v2) - (v1 < v2)

    # parse a single comparator expression into a predicate
    def parse_comp(comp: str):
        comp = comp.strip()
        if not comp:
            return lambda v: True
        match = re.match(r'^(=?)?([><]=?|~|\^)?(\d+(\.\d+){0,2})$', comp)
        if not match:
            raise ValueError(f"Invalid comparator: {comp!r}")

        op_eq, op_rel, v_string, _ = match.groups()
        target = to_tuple(v_string)

        def eq(v):
            return v == target

        def ge(v):
            return compare(v, target) >= 0

        def le(v):
            return compare(v, target) <= 0

        def gt(v):
            return compare(v, target) > 0

        def lt(v):
            return compare(v, target) < 0

        def tilde(v):
            # >= target and < v.minor+1.patch=0
            major, minor, patch = target
            upper = (major, minor + 1, 0)
            return ge(v) and lt(v, upper)

        def caret(v):
            major, minor, patch = target
            if major == 0:
                if minor == 0:
                    upper = (0, 0, patch + 1)
                else:
                    upper = (0, minor + 1, 0)
            else:
                upper = (major + 1, 0, 0)
            return ge(v) and lt(v, upper)

        if op_eq:
            return eq
        if op_rel == '>=':
            return ge
        if op_rel == '<=':
            return le
        if op_rel == '>':
            return gt
        if op_rel == '<':
            return lt
        if op_rel == '~':
            return tilde
        if op_rel == '^':
            return caret
        if op_rel is None and comp[0] in ('>', '<', '='):
            # case like ">1.2.3" with extra spaces
            return parse_comp(comp[1:].strip())
        # exact version
        return eq

    # build list of predicates for a single alternative
    def parse_alternative(text: str):
        comps = [c for c in text.split() if c]
        return [parse_comp(c) for c in comps]

    # split by "||" (allow spaces around)
    alternatives = [p.strip() for p in re.split(r'\s*\|\|\s*', range_)]
    version_tuple = to_tuple(version)

    for alt in alternatives:
        predicates = parse_alternative(alt)
        if all(pred(version_tuple) for pred in predicates):
            return True
    return False
```

**Explanation**

* `to_tuple` converts the string into `(major, minor, patch)`, padding missing parts with
  zero.  
* `compare` returns -1, 0, 1 based on tuple ordering.  
* `parse_comp` creates a predicate for each comparator.  
  * `=` or exact version → equality.  
  * `>`, `<`, `>=`, `<=` → numeric comparison.  
  * `~` → compatible with same minor (`>=target && <new_minor`).  
  * `^` → compatible with same major (`>=target && <major+1`).  Special handling for
    leading zeros.  
* Alternatives are split by spaces; each must be satisfied (`all`).  
* `||` separates alternatives; any satisfied alternative makes the entire range true.  

The function uses only the standard library and handles all required syntaxes.

```javascript
// Apply JSON‑Patch style ops without mutating the original document.
// Throws Error on any invalid op, path or index.
function applyPatch(doc, ops) {
  // deep clone the original doc to preserve immutability
  const clone = JSON.parse(JSON.stringify(doc));

  // helper to walk to parent object/array and last key/index
  const walk = (root, path) => {
    if (path === '') return { parent: null, key: null, value: root };
    const parts = path.slice(1).split('/');
    let cur = root;
    for (let i = 0; i < parts.length - 1; i++) {
      const part = parts[i].replace(/~1/g, '/').replace(/~0/g, '~');
      if (Array.isArray(cur)) {
        if (part === '-') {
          throw new Error('Invalid array index "-" in intermediate position');
        }
        const idx = Number(part);
        if (Number.isNaN(idx) || !Number.isInteger(idx) || idx < 0 || idx >= cur.length) {
          throw new Error(`Array index out of range: ${part}`);
        }
        cur = cur[idx];
      } else if (cur && typeof cur === 'object') {
        if (!(part in cur)) throw new Error(`Missing intermediate key: ${part}`);
        cur = cur[part];
      } else {
        throw new Error(`Non‑existent parent on path: ${path}`);
      }
    }
    const lastPart = parts[parts.length - 1].replace(/~1/g, '/').replace(/~0/g, '~');
    return { parent: cur, key: lastPart };
  };

  ops.forEach(({ op, path, value }) => {
    if (!['add', 'remove', 'replace'].includes(op)) throw new Error(`Unknown op: ${op}`);

    if (path === '') {
      if (op === 'add') { clone.value = value; return; }
      if (op === 'replace') { clone.value = value; return; }
      if (op === 'remove') { throw new Error('Cannot remove whole document'); }
    }

    const { parent, key } = walk(clone, path);

    if (Array.isArray(parent)) {
      let idx;
      if (key === '-') idx = parent.length;
      else {
        idx = Number(key);
        if (Number.isNaN(idx) || !Number.isInteger(idx)) throw new Error(`Invalid array index: ${key}`);
      }
      if (op === 'add') {
        if (idx < 0 || idx > parent.length) throw new Error(`Array index out of range: ${key}`);
        parent.splice(idx, 0, value);
      } else if (op === 'remove' || op === 'replace') {
        if (idx < 0 || idx >= parent.length) throw new Error(`Array index out of range: ${key}`);
        if (op === 'remove') parent.splice(idx, 1);
        else parent[idx] = value;
      } else throw new Error(`Unsupported op ${op} on array`);
    } else if (parent && typeof parent === 'object') {
      if (op === 'add' || op === 'replace') parent[key] = value;
      else if (op === 'remove') {
        if (!(key in parent)) throw new Error(`Missing target for remove: ${path}`);
        delete parent[key];
      } else throw new Error(`Unsupported op ${op} on object`);
    } else {
      throw new Error(`Parent is not an object/array for path: ${path}`);
    }
  });

  return clone;
}
```

**Explanation**  
*clone* is a deep copy to guarantee the original doc isn’t modified.  
`walk()` navigates to the parent of the targeted property (or array element) and returns that parent and key/index.  
Operations are applied according to the rules, with bounds checks for arrays and existence checks for objects.  
Any fault throws an `Error`.

```python
import re
from functools import total_ordering
from typing import Tuple, List


@total_ordering
class Version:
    """Represent a semantic version without prerelease/build."""

    def __init__(self, major: int, minor: int, patch: int):
        self.major, self.minor, self.patch = major, minor, patch

    @classmethod
    def parse(cls, s: str) -> "Version":
        """Parse 'MAJOR.MINOR.PATCH'."""
        major, minor, patch = map(int, s.split("."))
        return cls(major, minor, patch)

    def __lt__(self, other: "Version") -> bool:
        return (self.major, self.minor, self.patch) < (
            other.major,
            other.minor,
            other.patch,
        )

    def __eq__(self, other: object) -> bool:
        if not isinstance(other, Version):
            return NotImplemented
        return (self.major, self.minor, self.patch) == (
            other.major,
            other.minor,
            other.patch,
        )

    def __hash__(self) -> int:
        return hash((self.major, self.minor, self.patch))


def _compare(v1: Version, op: str, v2: Version) -> bool:
    if op == ">":
        return v1 > v2
    if op == ">=":
        return v1 >= v2
    if op == "<":
        return v1 < v2
    if op == "<=":
        return v1 <= v2
    if op == "=" or op == "":
        return v1 == v2
    raise ValueError(f"unknown operator {op!r}")


def _satisfy_single(v: Version, token: str) -> bool:
    token = token.strip()
    if not token:
        return True
    # operator extraction
    m = re.match(r"(?P?<operator>[-=<>~^]?)?(.+)", token)
    op, rest = m.group(1), m.group(2)
    if op is None:
        op = ""
    # special operators: '~', '^'
    if op == "~":
        base = Version.parse(rest)
        next_minor = base.minor + 1
        return _compare(v, ">=", base) and _compare(v, "<", Version(base.major, next_minor, 0))
    if op == "^":
        base = Version.parse(rest)
        if base.major != 0:
            upper = Version(base.major + 1, 0, 0)
        elif base.minor != 0:
            upper = Version(0, base.minor + 1, 0)
        else:
            upper = Version(0, 0, base.patch + 1)
        return _compare(v, ">=", base) and _compare(v, "<", upper)
    # bare version or '=version'
    if op in ("", "="):
        base = Version.parse(rest)
        return _compare(v, "=", base)
    # relational operators
    return _compare(v, op, Version.parse(rest))


def satisfies(version: str, range_: str) -> bool:
    """
    Return True iff the given version string satisfies the range expression.
    """
    v = Version.parse(version)

    # split alternatives by '||'
    alternatives: List[Tuple[str]] = [
        tuple(part.strip() for part in alt.split()) for alt in re.split(r"\s*\|\|\s*", range_)
    ]

    for alt in alternatives:
        if all(_satisfy_single(v, comp) for comp in alt):
            return True
    return False
```

*Explanation:*  
The code parses the semantic version into a `Version` object that supports comparison.  
Each comparator token is examined: relational operators, `~`, `^`, or plain equality.  
Special operators compute the appropriate upper bound based on the rules given.  
The range string is split on `||` (allowing surrounding spaces) into alternatives; an alternative is a conjunction of comparators. The function returns `True` if any alternative matches.

```javascript
function applyPatch(doc, ops) {
  // deep copy so original is untouched
  const newDoc = JSON.parse(JSON.stringify(doc));

  const escape = s => s.replace(/~1/g, '/').replace(/~0/g, '~');

  for (const { op, path, value } of ops) {
    const segments = path === '' ? [] : path.split('/').slice(1).map(escape);
    // navigate to parent of target
    let parent = newDoc;
    for (let i = 0; i < segments.length - 1; i++) {
      const seg = segments[i];
      if (Array.isArray(parent)) {
        if (seg === '-') throw new Error(`Invalid array index '${seg}'`);
        const idx = Number(seg);
        if (!Number.isInteger(idx) || idx < 0 || idx >= parent.length)
          throw new Error(`Array index out of range '${seg}'`);
        parent = parent[idx];
      } else if (parent && typeof parent === 'object') {
        if (!(seg in parent)) throw new Error(`Missing parent '${segments.slice(0, i+1).join('/')}'`);
        parent = parent[seg];
      } else {
        throw new Error(`Non‑existing path '${segments.slice(0, i+1).join('/')}'`);
      }
    }

    const target = segments[segments.length - 1];
    if (op === 'add') {
      if (parent === undefined) throw new Error(`Cannot add to non‑existing parent`);
      if (Array.isArray(parent)) {
        if (target === '-') {
          parent.push(value);
        } else {
          const idx = Number(target);
          if (!Number.isInteger(idx) || idx < 0 || idx > parent.length)
            throw new Error(`Array index out of range '${target}'`);
          parent.splice(idx, 0, value);
        }
      } else if (parent && typeof parent === 'object') {
        parent[target] = value;
      } else if (path === '') {
        // replace whole document
        Object.assign(newDoc, value);
      } else {
        throw new Error(`Target parent not an object or array`);
      }
    } else if (op === 'remove') {
      if (parent === undefined) throw new Error(`Cannot remove from non‑existing parent`);
      if (Array.isArray(parent)) {
        if (target === '-') throw new Error(`'-' not allowed for remove`);
        const idx = Number(target);
        if (!Number.isInteger(idx) || idx < 0 || idx >= parent.length)
          throw new Error(`Array index out of range '${target}'`);
        parent.splice(idx, 1);
      } else if (parent && typeof parent === 'object') {
        if (!(target in parent)) throw new Error(`Target missing for remove`);
        delete parent[target];
      } else {
        throw new Error(`Target parent not an object or array`);
      }
    } else if (op === 'replace') {
      if (parent === undefined) throw new Error(`Cannot replace on non‑existing parent`);
      if (Array.isArray(parent)) {
        if (target === '-') throw new Error(`'-' not allowed for replace`);
        const idx = Number(target);
        if (!Number.isInteger(idx) || idx < 0 || idx >= parent.length)
          throw new Error(`Array index out of range '${target}'`);
        parent[idx] = value;
      } else if (parent && typeof parent === 'object') {
        if (!(target in parent)) throw new Error(`Target missing for replace`);
        parent[target] = value;
      } else {
        throw new Error(`Target parent not an object or array`);
      }
    } else {
      throw new Error(`Unknown op '${op}'`);
    }
  }

  return newDoc;
