The function parses RFC‑6901–style JSON Patches: parses the path, unescapes segments, navigates to the parent, and applies `add`, `remove`, or `replace`. Errors are thrown for every invalid situation, and the original document is left untouched because we start from a deep clone.

```python
import re
from dataclasses import dataclass
from typing import List, Tuple

@dataclass(frozen=True, slots=True)
class Version:
    major: int
    minor: int
    patch: int

    @classmethod
    def from_str(cls, s: str) -> "Version":
        maj, min, pat = map(int, s.strip().split("."))
        return cls(maj, min, pat)

    def __lt__(self, other: "Version") -> bool:
        return (self.major, self.minor, self.patch) < (other.major, other.minor, other.patch)
    def __le__(self, other: "Version") -> bool:
        return (self.major, self.minor, self.patch) <= (other.major, other.minor, other.patch)
    def __eq__(self, other: object) -> bool:
        return isinstance(other, Version) and (self.major, self.minor, self.patch) == (other.major, other.minor, other.patch)

def _match_op(op: str, v: Version, target: Version) -> bool:
    if op == "=" or op == "":
        return v == target
    if op == ">":
        return v > target
    if op == ">=":
        return v >= target
    if op == "<":
        return v < target
    if op == "<=":
        return v <= target

    # caret and tilde use ranges
    if op == "~":
        upper = Version(target.major, target.minor + 1, 0)
        return v >= target and v < upper
    if op == "^":
        if target.major > 0:
            upper = Version(target.major + 1, 0, 0)
        elif target.minor > 0:
            upper = Version(0, target.minor + 1, 0)
        else:
            upper = Version(0, 0, target.patch + 1)
        return v >= target and v < upper
    raise ValueError(f"unknown operator: {op}")

def _parse_comparator(compar: str) -> Tuple[str, Version]:
    m = re.match(r"(\^|~|>=|<=|>|<|=)?\s*(\d+\.\d+\.\d+)", compar)
    if not m:
        raise ValueError(f"bad comparator: {compar}")
    op, ver = m.group(1) or "", Version.from_str(m.group(2))
    return op, ver

def satisfies(v: str, rng: str) -> bool:
    """Return True if version `v` satisfies the constraint `rng`."""
    target = Version.from_str(v)

    # split alternatives
    alternatives = [a.strip() for a in rng.split("||")]
    for alt in alternatives:
        # split comparators
        comps = [c.strip() for c in alt.split() if c]
        ok = True
        for comp in comps:
            op, ver = _parse_comparator(comp)
            if not _match_op(op, target, ver):
                ok = False
                break
        if ok:
            return True
    return False
```

### How it works
1. **`Version`** represents a version with tuple‑based comparison.
2. **`_parse_comparator`** parses a comparator string into an operator and a `Version` object.
3. **`_match_op`** checks the operator (`=`, `>`, `>=`, `<`, `<=`, `~`, `^`) against the target version, converting `~` and `^` to ranges.
4. The public `satisfies` function splits the range into alternatives (`||`), then into comparators, and requires all comparators of an alternative to be satisfied. If any alternative passes, it returns `True`.

```javascript
function applyPatch(doc, ops) {
  // deep clone so original doc is untouched
  const cloneDeep = (x) => {
    if (x === null || typeof x !== 'object') return x;
    if (Array.isArray(x)) return x.map(cloneDeep);
    const o = {};
    for (const k in x) o[k] = cloneDeep(x[k]); // eslint-disable-line no-restricted-syntax
    return o;
  };
  let result = cloneDeep(doc);

  // split a single operation path into segments
  const splitPath = (path) => {
    if (path === '') return [];
    if (!path.startsWith('/')) throw new Error('Invalid path');
    const segs = path.slice(1).split('/').map(s => s.replace(/~1/g, '/').replace(/~0/g, '~'));
    return segs;
  };

  const getParent = (root, segs) => {
    let cur = root;
    for (let i = 0; i < segs.length - 1; i++) {
      const s = segs[i];
      if (Array.isArray(cur)) {
        if (!/^\d+$/.test(s)) throw new Error('Invalid array index');
        const idx = parseInt(s, 10);
        if (idx < 0 || idx >= cur.length) throw new Error('Index out of range');
        cur = cur[idx];
      } else if (cur && typeof cur === 'object') {
        if (!(s in cur)) throw new Error('Parent does not exist');
        cur = cur[s];
      } else throw new Error('Parent does not exist');
    }
    return cur;
  };

  for (const {op, path, value} of ops) {
    const segs = splitPath(path);
    const key = segs[segs.length - 1];
    const parent = segs.length === 0 ? {root: result} : getParent(result, segs);

    switch (op) {
      case 'add':
        if (segs.length === 0) {
          result = value;
          break;
        }
        if (Array.isArray(parent)) {
          if (key === '-') {
            parent.push(value);
          } else if (/^\d+$/.test(key)) {
            const idx = parseInt(key, 10);
            if (idx < 0 || idx > parent.length) throw new Error('Index out of range');
            parent.splice(idx, 0, value);
          } else throw new Error('Invalid array index');
        } else if (parent && typeof parent === 'object') {
          parent[key] = value;
        } else throw new Error('Parent does not exist');
        break;
      case 'remove':
        if (segs.length === 0) throw new Error('Cannot remove the whole document');
        if (Array.isArray(parent)) {
          if (!/^\d+$/.test(key)) throw new Error('Invalid array index');
          const idx = parseInt(key, 10);
          if (idx < 0 || idx >= parent.length) throw new Error('Index out of range');
          parent.splice(idx, 1);
        } else if (parent && typeof parent === 'object') {
          if (!(key in parent)) throw new Error('Target does not exist');
          delete parent[key];
        } else throw new Error('Target does not exist');
        break;
      case 'replace':
        if (segs.length === 0) {
          result = value;
          break;
        }
        if (Array.isArray(parent)) {
          if (!/^\d+$/.test(key)) throw new Error('Invalid array index');
          const idx = parseInt(key, 10);
          if (idx < 0 || idx >= parent.length) throw new Error('Index out of range');
          parent[idx] = value;
        } else if (parent && typeof parent === 'object') {
          if (!(key in parent)) throw new Error('Target does not exist');
          parent[key] = value;
        } else throw new Error('Target does not exist');
        break;
      default:
        throw new Error('Unknown operation');
    }
  }

  return result;
}
```

**Explanation**  
The function deep‑clones `doc` to keep it unchanged.  
Paths are parsed into segments, with `~1` → `/` and `~0` → `~`.  
For each operation we locate the parent node (or treat whole doc as the target).  
`add` inserts or sets, `remove` deletes an existing key/array element, and `replace`
updates an existing value. Errors are thrown for any policy violation.

```javascript
/**
 * Apply a set of JSON‑Patch like operations to an immutable JSON document.
 * @param {any} doc  The original JSON value (object/array/primitive).
 * @param {Array<{op:string,path:string,value:any}>} ops  Operations to apply in order.
 * @returns {any}   The new document after all operations.
 * @throws {Error} On any invalid operation.
 */
function applyPatch(doc, ops) {
    // Helper: deep clone (shallow enough for primitives, arrays, and objects)
    const clone = (v) => {
        if (Array.isArray(v)) return v.map(clone);
        if (v && typeof v === 'object') return Object.assign(Object.create(null), v);
        return v; // primitives
    };

    // Helper: unescape segment per RFC 6901
    const unescape = s => s.replace(/~1/g, '/').replace(/~0/g, '~');

    // Helper: parse a path into segments
    const parsePath = path => {
        if (path === '') return []; // whole document
        if (!path.startsWith('/')) throw new Error(`Invalid path "${path}".`);
        return path.substring(1).split('/').map(unescape);
    };

    // Walk the path and return the parent object/array and the final key/index
    const walk = (root, parts) => {
        let cur = root;
        for (let i = 0; i < parts.length - 1; i++) {
            const part = parts[i];
            if (Array.isArray(cur)) {
                const idx = parseIntIndex(part, cur.length);
                if (idx >= cur.length) throw new Error(`Array index out of range.`);
                cur = cur[idx];
            } else if (cur && typeof cur === 'object') {
                if (!(part in cur)) throw new Error(`Missing parent property "${part}".`);
                cur = cur[part];
            } else throw new Error(`Attempted to index non‑object/array.`, part);
        }
        const last = parts[parts.length - 1];
        return [cur, last];
    };

    // Convert array index specifiers; '+' for length, '-' for append
    const parseIntIndex = (s, len) => {
        if (s === '-') return len; // append
        const n = Number(s);
        if (!Number.isInteger(n) || n < 0) throw new Error(`Invalid array index "${s}".`);
        return n;
    };

    let target = clone(doc); // work on a copy

    ops.forEach((opObj, i) => {
        const { op, path, value } = opObj;
        const parts = parsePath(path);
        // For whole document we treat parent=null, key=parts (empty)
        if (parts.length === 0) {
            if (op === 'add') { target = value; return; }
            if (op === 'remove' || op === 'replace')
                throw new Error(`Cannot ${op} the whole document.`);
            throw new Error(`Unknown operation "${op}".`);
        }

        const [parent, key] = walk(target, parts);

        const isArray = Array.isArray(parent);
        const idx = isArray ? parseIntIndex(key, parent.length) : key;

        switch (op) {
            case 'add':
                if (isArray) {
                    if (idx > parent.length) throw new Error(`Array index out of range.`);
                    parent.splice(idx, 0, clone(value));
                } else {
                    parent[idx] = clone(value);
                }
                break;

            case 'remove':
                if (isArray) {
                    if (idx >= parent.length) throw new Error(`Array index out of range.`);
                    parent.splice(idx, 1);
                } else {
                    if (!(idx in parent)) throw new Error(`Missing target for remove.`);
                    delete parent[idx];
                }
                break;

            case 'replace':
                if (isArray) {
                    if (idx >= parent.length) throw new Error(`Array index out of range.`);
                    parent[idx] = clone(value);
                } else {
                    if (!(idx in parent)) throw new Error(`Missing target for replace.`);
                    parent[idx] = clone(value);
                }
                break;

            default:
                throw new Error(`Unknown operation "${op}".`);
        }
    });

    return target;
}
```

**Explanation**  
* The function never mutates the original `doc`: it deep‑clones it first.  
* Paths are parsed according to the RFC 6901 escaping rules.  
* For array indices the special `-` token means “append”; any other index must be
  a non‑negative integer and is validated against the array length.  
* Operations are applied in order; each `add`, `remove` or `replace` touches
  either an object member or an array element, performing the required
  splice or assignment.  
* Errors are thrown for unknown operations, missing parents, out‑of‑range
  indices, or when a `remove`/`replace` target does not exist.

