import re
from typing import List, Tuple

def _parse_ver(v: str) -> Tuple[int, int, int]:
    """Parse MAJOR.MINOR.PATCH into a tuple of ints."""
    parts = v.split(".")
    if len(parts) != 3 or any(not p.isdigit() for p in parts):
        raise ValueError(f"invalid version: {v}")
    return tuple(map(int, parts))

def _cmp(v1: Tuple[int, int, int], v2: Tuple[int, int, int]) -> int:
    """Return -1 if v1<v2, 0 if equal, 1 if v1>v2."""
    return (v1 > v2) - (v1 < v2)

def _in_range(v: Tuple[int, int, int], op: str, ref: Tuple[int, int, int]) -> bool:
    comp = _cmp(v, ref)
    if op == "==": return comp == 0
    if op == ">=": return comp >= 0
    if op == "<=": return comp <= 0
    if op == ">":  return comp > 0
    if op == "<":  return comp < 0
    raise ValueError(f"unknown operator {op}")

def _parse_comparator(s: str) -> Tuple[str, Tuple[int, int, int]]:
    """Return (operator, reference_version)."""
    s = s.strip()
    if not s:
        raise ValueError("empty comparator")
    # exact match
    if s[0] in "=<>":
        if s.startswith("=="):
            op = "=="; v = s[2:]
        else:
            op = s[0]; v = s[1:]
    elif s[0] in "#@~^":
        op = s[0]; v = s[1:]
    else:
        # plain version
        op = "=="; v = s
    ref = _parse_ver(v)
    return op, ref

def _range_op(v: Tuple[int, int, int], op: str, ref: Tuple[int, int, int]) -> bool:
    # Wrap _in_range for ^ and ~
    if op == "~":
        # >= ref and < next minor 0
        next = (ref[0], ref[1]+1, 0)
        return _in_range(v, ">=", ref) and _in_range(v, "<", next)
    if op == "^":
        # Next major 0 -> next major 1
        next = (ref[0]+1, 0, 0) if ref[0] > 0 else (ref[0], ref[1]+1, 0) if ref[1] > 0 else (ref[0], ref[1], ref[2]+1)
        return _in_range(v, ">=", ref) and _in_range(v, "<", next)
    if op == "==":
        return v == ref
    if op in ("<", "<=", ">", ">="):
        return _in_range(v, op, ref)
    raise ValueError(f"unknown operator {op}")

def satisfies(version: str, range_: str) -> bool:
    v = _parse_ver(version)

    # Split alternatives on ||
    alternatives = [a.strip() for a in re.split(r"\s*\|\|\s*", range_) if a.strip()]
    if not alternatives:
        return False

    for alt in alternatives:
        comparators = [c.strip() for c in alt.split() if c.strip()]
        if all(_range_op(v, * _parse_comparator(c)) for c in comparators):
            return True
    return False
```

The function parses the version into three integers and compares lexicographically. It splits the range on `||`, trimming spaces. Each alternative’s comparators are checked; all must hold for that alternative. Comparators `~` and `^` are expanded to explicit lower and upper bounds based on the major/minor/patch logic described. Only the standard library is used.

