    // Deep‑clone the source document (plain JSON only).
    let result = JSON.parse(JSON.stringify(doc));

    // Utility to decode a single path segment (~1 → /, ~0 → ~)
    const decode = seg => seg.replace(/~1/g, '/').replace(/~0/g, '~');

    // Resolve parent object/array and the last key/index for a path.
    const resolve = (root, path) => {
        if (path === '') return { parent: null, key: null, value: root }; // whole document

        const segs = path.split('/').slice(1).map(decode);
        let curr = root;
        for (let i = 0; i < segs.length - 1; i++) {
            const key = segs[i];
            if (Array.isArray(curr)) {
                if (key === '-') throw new Error(`Invalid array index '${key}'`);
                const idx = Number(key);
                if (!Number.isInteger(idx) || idx < 0 || idx >= curr.length)
                    throw new Error(`Array index out of range: ${key}`);
                curr = curr[idx];
            } else if (curr !== null && typeof curr === 'object') {
                if (!(key in curr)) throw new Error(`Path does not exist: ${segs.slice(0, i + 1).join('/')}`);
                curr = curr[key];
            } else {
                throw new Error(`Parent is not an object or array at ${segs.slice(0, i + 1).join('/')}`);
            }
        }
        return { parent: curr, key: segs[segs.length - 1], value: curr };
    };

    // Main loop
    for (const { op, path, value } of ops) {
        if (!op) throw new Error('Missing operation verb');
        switch (op) {
            case 'add': {
                if (path === '') {
                    result = value;
                    break;
                }
                const { parent, key } = resolve(result, path);
                if (Array.isArray(parent)) {
                    if (key === '-') {
                        parent.push(value);
                    } else {
                        const idx = Number(key);
                        if (!Number.isInteger(idx) || idx < 0 || idx > parent.length)
                            throw new Error(`Array index out of range: ${key}`);
                        parent.splice(idx, 0, value);
