            case 'remove': {
                if (path === '') throw new Error('Cannot remove the entire document');
                const { parent, key } = resolve(result, path);
                if (Array.isArray(parent)) {
                    if (key === '-') throw new Error('Cannot remove the “-” placeholder');
                    const idx = Number(key);
                    if (!Number.isInteger(idx) || idx < 0 || idx >= parent.length)
                        throw new Error(`Array index out of range: ${key}`);
                    parent.splice(idx, 1);
                } else if (parent !== null && typeof parent === 'object') {
                    if (!(key in parent)) throw new Error(`Target does not exist: ${path}`);
                    delete parent[key];
                } else {
                    throw new Error(`Parent of remove path is not an object or array: ${path}`);
                }
                break;
            }
            case 'replace': {
                if (path === '') throw new Error('Cannot replace the entire document');
                const { parent, key } = resolve(result, path);
                if (Array.isArray(parent)) {
                    if (key === '-') throw new Error('Cannot replace the “-” placeholder');
                    const idx = Number(key);
                    if (!Number.isInteger(idx) || idx < 0 || idx >= parent.length)
                        throw new Error(`Array index out of range: ${key}`);
                    parent[idx] = value;
                } else if (parent !== null && typeof parent === 'object') {
                    if (!(key in parent)) throw new Error(`Target does not exist: ${path}`);
                    parent[key] = value;
                } else {
                    throw new Error(`Parent of replace path is not an object or array: ${path}`);
                }
                break;
            }
            default:
                throw new Error(`Unknown operation: ${op}`);
        }
    }

    return result;
}
