/**
 * Applies a sequence of patch operations to a JSON document.
 *
 * @param {any} doc The initial JSON document.
 * @param {Array<{op: string, path: string, value?: any}>} ops An array of operations.
 * @returns {any} The new document.
 * @throws {Error} If any operation is invalid.
 */
function applyPatch(doc, ops) {
    // Deep copy the document to ensure the original is not modified
    const newDoc = JSON.parse(JSON.stringify(doc));

    /**
     * Resolves a path string into an array of segments, handling special tokens.
     * @param {string} path The path string.
     * @returns {string[]} An array of resolved path segments.
     */
    const resolvePath = (path) => {
        if (path === "") return [];

        // Replace ~1 (/) with a placeholder, then split by /
        // Then replace ~0 (~) with a placeholder, and filter out empty strings
        const segments = path
            .replace(/~/g, (match) => {
                if (match === '~1') return '/';
                if (match === '~0') return '~~'; // Placeholder for literal ~
                return match;
            })
            .split('/');

        return segments.map(seg => {
            if (seg === '') return '';
            if (seg.startsWith('~~')) return '~';
            return seg;
        });
    };

    /**
     * Navigates the document structure based on resolved segments.
     * @param {any} currentDoc The current node being navigated.
     * @param {string[]} segments The segments to traverse.
     * @param {boolean} isInsert Determines if we should stop at the parent (true) or the target (false).
     * @returns {{node: any, parent: any, key: string|number|null}}
     */
    const navigate = (currentDoc, segments, isInsert) => {
        let current = currentDoc;
        let parent = null;
        let key = null;

        for (let i = 0; i < segments.length; i++) {
            const segment = segments[i];
            const nextIsInsert = isInsert && (i === segments.length - 1);

            if (typeof current === 'object' && current !== null && !Array.isArray(current)) {
                // Object traversal
                if (segment === '') {
                    // Path segment is empty, usually means navigating to root object, which shouldn't happen in path traversal
                    if (isInsert) {
                        return { node: current, parent: null, key: segment };
                    }
                    // If segment is empty and we are deep, it's ambiguous/invalid in typical JS object pathing,
                    // but for robustness, we treat it as a literal key if it exists.
                    key = '';
                    if (current[key] === undefined) {
                        throw new Error("Parent object does not contain specified key.");
                    }
                    parent = current;
                    current = current[key];
                } else if (typeof segment === 'string' && !isNaN(parseInt(segment))) {
                    // Array access via string representation of index
                    const index = parseInt(segment);
                    if (Array.isArray(current) && index >= 0 && index < current.length) {
                        parent = current;
                        current = current[index];
                        key = index;
                    } else {
                        throw new Error(`Array index ${index} out of bounds or target is not an array.`);
                    }
                } else if (typeof current === 'object' && current !== null && current[segment] !== undefined) {
                    // Normal object key access
                    parent = current;
                    key = segment;
                    current = current[segment];
                } else {
                    throw new Error(`Parent object does not contain specified key or index.`);
                }

            } else if (Array.isArray(current)) {
                // Array traversal
                const index = parseInt(segment);
                if (!isNaN(index) && index >= 0 && index < current.length) {
                    parent = current;
                    current = current[index];
                    key = index;
                } else if (segment === '-' && i === segments.length - 1) {
                     // Special handling for 'append' if path segment is '-'
                     if (isInsert) {
                         return { node: current, parent: current, key: 'append' };
                     } else {
                         throw new Error("Cannot use '-' for removal/replace; only valid for addition.");
                     }
                }
                else {
                    throw new Error(`Array index ${segment} out of bounds or target is not an array.`);
                }
            } else {
                // Current node is not navigable (e.g., primitive value)
                throw new Error(`Parent node encountered a primitive value while attempting to navigate further.`);
            }

            if (nextIsInsert) {
                return { node: current, parent: parent, key: segment };
            }
        }

        return { node: current, parent: parent, key: key };
    };


    ops.forEach(({ op, path, value }) => {
        let segments = resolvePath(path);

        // --- Special Case: Root operation ("") ---
        if (path === "") {
            if (op === 'add') {
                // Add to root
                if (typeof value !== 'object' || value === null) {
                    // If adding a primitive to the root, it replaces the whole document
                    Object.assign(newDoc, value);
                    // Note: For primitives, JSON.parse(JSON.stringify) might not perfectly restore types (like Date), 
                    // but for general JSON values, this works for replacement/setting the whole structure.
                    // Since the prompt implies JSON value, we treat primitives as the new root.
                    // If doc was {a:1} and value is 5, newDoc becomes 5.
                    newDoc = value; 
                }
            } else if (op === 'replace' || op === 'remove') {
                throw new Error(`Operation ${op} cannot be performed on the entire document structure via path "" except for 'add'.`);
            }
            return;
        }

        // --- General Path Operations ---

        if (op === 'add') {
            if (typeof value === 'object' && value !== null && path !== "") {
                 // For object/array insertion, we need the PARENT node
                const result = navigate(newDoc, segments, true);
                const { node: parent, key } = result;

                if (parent.op === 'append') {
                    parent.push(value);
                } else if (typeof parent === 'object' && parent !== null && !Array.isArray(parent)) {
                    parent[key] = value;
                } else if (Array.isArray(parent) && typeof key === 'number') {
                    // Index provided (or implicit if path ends in index)
                    if (key < 0 || key > parent.length) {
                        throw new Error(`Array index ${key} out of bounds for insertion.`);
                    }
                    parent.splice(key, 0, value);
                } else {
                    throw new Error("Cannot add value: Parent structure is invalid for insertion.");
                }
            } else {
                // If value is primitive, it behaves like 'replace' if target exists, or an error if trying to add a primitive to a non-existent path.
                // Since "add" on primitive to non-existent target is ill-defined, we treat it as an attempt to set a value.
                const result = navigate(newDoc, segments, false);
                const { node: target, parent, key } = result;
                if (parent) {
                    if (Array.isArray(parent)) {
                        if (typeof key === 'number') {
                            // Overwrite array element if it exists (though 'add' implies insertion)
                            // If index is within bounds, we replace, otherwise throw error
                            if (key < 0 || key >= parent.length) {
                                throw new Error(`Array index ${key} out of bounds for replacement via add.`);
                            }
                            parent[key] = value;
                        } else {
                             throw new Error("Invalid path segment for array element.");
                        }
                    } else {
                        parent[key] = value;
                    }
                } else if (segments.length === 1) {
                     // If the first segment leads to a non-existent object/array structure, this is likely invalid for 'add'
                    throw new Error("Cannot add value: Target parent does not exist.");
                }
            }
        } 
        else if (op === 'remove') {
            const result = navigate(newDoc, segments, false);
            const { parent, key } = result;

            if (!parent) {
                throw new Error("Target for removal does not exist.");
            }

            if (Array.isArray(parent)) {
                const index = parseInt(key);
                if (isNaN(index) || index < 0 || index >= parent.length) {
                    throw new Error(`Array index ${key} out of bounds for removal.`);
                }
                parent.splice(index, 1);
            } else if (typeof parent === 'object' && parent !== null && key !== null) {
                delete parent[key];
            } else {
                throw new Error("Target for removal is not a reachable object or array element.");
            }
        } 
        else if (op === 'replace') {
            const result = navigate(newDoc, segments, false);
            const { parent, key } = result;

            if (!parent || (Array.isArray(parent) && typeof key !== 'number') || (!Array.isArray(parent) && key === null)) {
                throw new Error("Target for replacement does not exist.");
            }

            if (Array.isArray(parent)) {
                parent[key] = value;
            } else {
                parent[key] = value;
            }
        } 
        else {
            throw new Error(`Unknown operation: ${op}`);
        }
    });

    return newDoc;
}
