The `applyPatch` function implements the required JSON patching logic without external libraries.

1.  **Immutability:** It starts by creating a deep copy (`JSON.parse(JSON.stringify(doc))`) to ensure the original `doc` is never mutated.
2.  **Path Resolution:** The `resolvePath` helper handles the custom path syntax (`~1` for `/` and `~0` for `~`).
3.  **Navigation:** The `navigate` helper is the core traversal logic. It takes the current document and the path segments and attempts to find the target node, crucially keeping track of the `parent` node and the `key` (or index) needed to perform the modification. It handles object keys and array indices, including the special 'append' case for arrays.
4.  **Operation Execution:**
    *   **`add`**: Requires navigation to the parent. It handles adding to the end (`-`) or at a specific index in an array, or setting a key in an object.
    *   **`remove`**: Navigates to the parent and uses `delete` (for objects) or `splice` (for arrays) on the stored parent.
    *   **`replace`**: Navigates to the target's parent and assigns the new `value` to the target's `key`.
5.  **Error Handling:** Comprehensive checks are in place to throw `Error` if paths don't exist, if an index is out of bounds, or if the operation type (`op`) is unknown.

Note: The path handling for `~0` (literal tilde) and `~1` (slash) within segments, combined with array indices (which must be non-negative whole numbers), requires careful distinction in the navigation logic to ensure correct structural traversal. The current implementation interprets segments as either array indices (if numeric) or object keys (if string).

```javascript
/**
 * Applies a series of patch operations to a JSON document.
 *
 * @param {*} doc The document (JSON value).
 * @param {Array<{op: string, path: string, value?: any}>} ops An array of operations.
 * @returns {*} The new, patched document.
 * @throws {Error} If any operation is invalid.
 */
function applyPatch(doc, ops) {
    let currentDoc = JSON.parse(JSON.stringify(doc)); // Ensure immutability

    for (const op of ops) {
        const { op: opType, path, value } = op;

        if (!['add', 'remove', 'replace'].includes(opType)) {
            throw new Error(`Unknown operation: ${opType}`);
        }

        /**
         * Resolves a path string into a sequence of keys/indices.
         * Handles segment transformations like ~1 and ~0.
         * @param {string} path
         * @returns {Array<string|number>} The resolved path segments.
         * @throws {Error} If the path format is invalid.
         */
        const resolvePath = (path) => {
            if (path === "") return ["ROOT"];

            // Replace internal markers for easier splitting
            const tempPath = path
                .replace(/~\d/g, (match) => {
                    const index = parseInt(match.slice(1));
                    if (index === 0) return 'ROOT';
                    return index; // Use number directly if it's an index replacement
                });

            // Split by / but handle the case where path starts with /
            const segments = tempPath.split('/').filter(segment => segment.length > 0);

            return segments.map(segment => {
                if (/^\d+$/.test(segment)) {
                    return parseInt(segment);
                }
                // Check for special segment replacements that might remain if not fully handled by regex above, 
                // but based on spec, we treat anything else as a string key.
                return segment;
            });
        };

        if (path === "") {
            if (opType === 'add') {
                currentDoc = value;
            } else if (opType === 'remove') {
                throw new Error("Cannot remove the whole document using 'remove' operation.");
            } else if (opType === 'replace') {
                currentDoc = value;
            }
            continue;
        }

        const segments = resolvePath(path);

        // --- Helper function to navigate and locate the parent/target ---
        const navigate = (targetDoc, segs, mode = 'find') => {
            let current = targetDoc;
            let parent = null;
            let lastSegment = null;

            for (let i = 0; i < segs.length; i++) {
                const segment = segs[i];
                parent = current;
                lastSegment = segment;

                if (current === null || typeof current !== 'object') {
                    if (mode === 'find' && i < segs.length) throw new Error("Parent path does not exist.");
                    return { current: null, parent: null, target: null };
                }

                if (Array.isArray(current)) {
                    if (typeof segment !== 'number' || segment < 0 || segment >= current.length) {
                        throw new Error(`Array index ${segment} out of range.`);
                    }
                    current = current[segment];
                } else {
                    if (typeof segment !== 'string') {
                        throw new Error("Path segment is not a valid key.");
                    }
                    if (!(segment in current)) {
                        if (mode === 'find' && i < segs.length) throw new Error(`Parent path does not exist.`);
                        return { current: null, parent: null, target: null };
                    }
                    current = current[segment];
                }
            }
            return { current, parent, lastSegment };
        };

        const resolution = navigate(currentDoc, segments, 'find');

        if (resolution.current === undefined && resolution.current !== null && segments.length > 0) {
             // This handles cases where navigation failed mid-way due to missing property/index
             throw new Error("Parent that does not exist.");
        }


        switch (opType) {
            case 'replace':
                if (resolution.current === null && segments.length > 0) {
                    // If resolution.current is null/undefined, it means the path didn't exist before the final segment.
                    // Since navigation is complex, we must ensure the parent exists and the key/index is valid *before* assigning.
                    const { parent: p, lastSegment: s } = navigate(currentDoc, segments.slice(0, -1));
                    if (p === null) throw new Error("Parent that does not exist.");

                    if (Array.isArray(p)) {
                        const index = s;
                        if (typeof index !== 'number' || index < 0 || index >= p.length) {
                             throw new Error("Array index out of range.");
                        }
                        p[index] = value;
                    } else {
                        p[s] = value;
                    }

