import re

def _parse_version(version: str) -> tuple[int, int, int]:
    """Parses a 'MAJOR.MINOR.PATCH' version string into a tuple of integers."""
    parts = version.split('.')
    if len(parts) != 3:
        raise ValueError(f"Invalid version format: {version}")
    try:
        return tuple(map(int, parts))
    except ValueError:
        raise ValueError(f"Version parts must be integers: {version}")

def _compare_versions(v1: tuple[int, int, int], v2: tuple[int, int, int], operator: str) -> bool:
    """Compares two version tuples based on a given operator."""
    if operator == '=' or operator == '==':
        return v1 == v2

    if operator == '>':
        return v1 > v2
    if operator == '>=':
        return v1 >= v2
    if operator == '<':
        return v1 < v2
    if operator == '<=':
        return v1 <= v2

    # This case should ideally not be reached if parsing is correct
    raise ValueError(f"Unknown comparison operator: {operator}")

def _check_comparator(version: tuple[int, int, int], comparator_str: str) -> bool:
    """Checks if the version satisfies a single comparator string."""

    # Regex to separate the operator and the version part (e.g., '>=1.2.3')
    match = re.match(r'([<>!=~^]+)(.*)', comparator_str.strip())

    if not match:
        # If no operator found, treat it as an exact version match
        return version == _parse_version(comparator_str.strip())

    operator = match.group(1).strip()
    version_str = match.group(2).strip()

    try:
        target_v = _parse_version(version_str)
    except ValueError:
        # Should not happen with valid input structure
        return False

    if operator == '~':
        # ~1.2.3: >=1.2.3 and <1.3.0
        major, minor, patch = target_v
        next_minor_v = _parse_version(f"{major}.{minor+1}.0")
        return _compare_versions(version, target_v, '>=') and _compare_versions(version, next_minor_v, '<')

    elif operator == '^':
        # ^1.2.3: >=1.2.3 and <2.0.0
        major, minor, patch = target_v

        if major > 0:
            # Standard SemVer: >=1.2.3 and <2.0.0
            next_major_v = _parse_version(f"{major+1}.0.0")
            return _compare_versions(version, target_v, '>=') and _compare_versions(version, next_major_v, '<')
        elif major == 0 and minor > 0:
            # ^0.2.3: >=0.2.3 and <0.3.0
            next_minor_v = _parse_version(f"{major}.{minor+1}.0")
            return _compare_versions(version, target_v, '>=') and _compare_versions(version, next_minor_v, '<')
        elif major == 0 and minor == 0 and patch > 0:
            # ^0.0.3: >=0.0.3 and <0.0.4
            next_patch_v = _parse_version(f"{major}.{minor}.{patch+1}")
            return _compare_versions(version, target_v, '>=') and _compare_versions(version, next_patch_v, '<')
        else:
             # Should be covered by above cases if version parsing is correct, handle safety
            next_major_v = _parse_version(f"{major+1}.0.0")
            return _compare_versions(version, target_v, '>=') and _compare_versions(version, next_major_v, '<')

    # Standard relational operators: >, >=, <, <=
    return _compare_versions(version, target_v, operator)

def satisfies(version: str, range_: str) -> bool:
    """
    Checks if a package version satisfies a specified range.
    """
    try:
        v_tuple = _parse_version(version)
    except ValueError:
        # If the input version is malformed, it cannot satisfy any range
        return False

    # 1. Split range by '||' (alternatives)
    alternatives = [alt.strip() for alt in range_.split('||') if alt.strip()]

    # The version satisfies the range if it satisfies at least one alternative
    for alternative_str in alternatives:
        # 2. Split alternative by spaces (comparators)
        comparators = [comp.strip() for comp in alternative_str.split() if comp.strip()]

        # The version must satisfy ALL comparators in this alternative
        all_comparators_satisfied = True
        for comparator in comparators:
            if not _check_comparator(v_tuple, comparator):
                all_comparators_satisfied = False
                break

        if all_comparators_satisfied:
            return True

    return False
```

The `satisfies` function implements the required logic by parsing the version and range according to the specified rules.

1.  **Version Parsing (`_parse_version`)**: Converts the `MAJOR.MINOR.PATCH` string into a comparable tuple of integers.
2.  **Range Handling**: It splits the input `range_` string by `||` to get a list of alternatives. It returns `True` if the version satisfies *any* alternative.
3.  **Alternative Handling**: Each alternative is split by spaces to yield a list of comparators. The version must satisfy *all* comparators in a single alternative for that alternative to be considered met.
4.  **Comparator Checking (`_check_comparator`)**: This function uses regular expressions to separate the operator (e.g., `>=`, `~`, `^`) from the target version string. It then uses specific logic to handle standard comparisons (`>`, `<`, etc.) and the specialized semantic versioning logic for `~` (tilde) and `^` (caret), carefully handling the zero-major cases as defined.

