from collections import deque
from typing import Dict, List, Set

def build_order(deps: dict[str, list[str]]) -> list[str]:
    # Identify all targets (keys + those appearing in values)
    all_targets = set(deps.keys())
    for target, dependent_list in deps.items():
        all_targets.update(dependent_list)

    # Build in-degree map and adjacency list
    in_degree: Dict[str, int] = {target: 0 for target in all_targets}
    graph: Dict[str, Set[str]] = {target: set() for target in all_targets}

    for target, dependents in deps.items():
        # target depends on dependents, so edges go from dependents -> target
        for dep in dependents:
            if dep not in all_targets:
                raise ValueError(f"Unknown dependency '{dep}'")
            graph[dep].add(target)
            in_degree[target] += 1

    # Initialize queue with targets having no dependencies (alphabetically sorted)
    queue = deque(sorted([t for t in all_targets if in_degree[t] == 0]))

    result: List[str] = []

    while queue:
        current = queue.popleft()
        result.append(current)

        # Find targets that depend on the current one and decrease their in-degree
        for target, neighbors in graph.items():
            if current in neighbors:
                in_degree[target] -= 1
                if in_degree[target] == 0:
                    # Insert maintaining sorted order
                    inserted = False
                    for i in range(len(queue)):
                        if queue[i] > target:
                            queue.insert(i, target)
                            inserted = True
                            break
                    if not inserted:
                        queue.append(target)

    if len(result) != len(all_targets):
        raise ValueError("Cycle detected in dependencies")

    return result
