      newDoc = ops[0].value;
    } else {
      const target = getAt(newDoc, pathSegments.slice(0, -1));
      if (target === null || target === undefined) throw new Error("Parent does not exist");

      const parentArr = Array.isArray(target);
      let insertIndex = -1;
      const idxStr = ops[0].path;

      if (parentArr) {
