    const target = getAt(newDoc, pathSegments);
    if (target === null || target === undefined) throw new Error("Target does not exist");
    removeAt(newDoc, pathSegments);
  } else if (op === "replace") {
    const target = getAt(newDoc, pathSegments);
    if (target === null || target === undefined) throw new Error("Target does not exist");
    setAt(newDoc, pathSegments, ops[0].value);
  } else {
    throw new Error("Unknown operation: " + op);
