/**
 * Parses a path string into an array of path segments.
 * Handles special characters: ~1 for '/' and ~0 for '~'.
 * @param {string} path
 * @returns {string[]}
 */
function parsePath(path) {
    if (path === "") return [""];

    // Replace escaped characters before splitting
    let processedPath = path
        .replace(/~1/g, '/') // ~1 is '/'
        .replace(/~0/g, '~'); // ~0 is '~'

    // Split by '/', filtering out empty strings resulting from leading/trailing slashes
    const segments = processedPath.split('/').filter(segment => segment !== "");
    return segments;
}

/**
 * Navigates to the parent object/array of the target path, returning the parent and the key/index.
 * @param {any} doc - The document to traverse.
 * @param {string[]} segments - The path segments.
 * @returns {{parent: any, key: string|number, depth: number}}
 * @throws {Error} If the path is invalid or a parent does not exist.
 */
function navigateToParent(doc, segments) {
    if (segments.length === 0) {
        // This should only happen for path "" which is handled as a special case or root access
        return { parent: doc, key: "", depth: 0 };
    }

    let current = doc;
    const parentSegments = segments.slice(0, -1);
    const key = segments[segments.length - 1];
    let parent = doc;

    // Traverse to the parent container
    for (let i = 0; i < parentSegments.length; i++) {
        const seg = parentSegments[i];

        if (typeof current !== 'object' || current === null) {
            throw new Error("Parent does not exist or is not an object/array at path segment: " + seg);
        }

        const isArray = Array.isArray(current);
        const isNumber = !isNaN(Number(seg));

        if (isArray) {
            const index = Number(seg);
            if (index < 0 || !Number.isInteger(index) || index >= current.length) {
                throw new Error(`Array index out of range: ${seg}`);
            }
            parent = current[index];
        } else {
            if (typeof current[seg] === 'undefined') {
                throw new Error("Parent does not exist at path segment: " + seg);
            }
            parent = current[seg];
        }
        current = parent;
    }

    return { parent: current, key: key, depth: segments.length };
}


/**
 * Applies a series of patches to a document.
 * 
 * @param {any} doc - The initial JSON value document.
 * @param {Array<{op: 'add'|'remove'|'replace', path: string, value?: any}>} ops - Array of operations.
 * @returns {any} The new document.
 */
function applyPatch(doc, ops) {
    // Deep clone the document to ensure the original is not modified
    const currentDoc = JSON.parse(JSON.stringify(doc));

    for (const op of ops) {
        const { op: operation, path, value } = op;

        if (!['add', 'remove', 'replace'].includes(operation)) {
            throw new Error(`Unknown operation: ${operation}`);
        }

        if (path === "") {
            if (operation === 'replace' || operation === 'add') {
                // Replace/Add to the whole document
                currentDoc[operation === 'replace' ? 'value' : 'temp'] = value;
                currentDoc = value;
            } else if (operation === 'remove') {
                throw new Error("Cannot remove the entire document via path ''");
            } else {
                // 'add' with path "" implies adding a property? Based on spec, only replace/add works on whole doc.
                // We treat add "" as setting the whole doc if value is present.
                if (operation === 'add' && value !== undefined) {
                    currentDoc = value;
                } else {
                    throw new Error("Operation 'add' requires a value when path is ''");
                }
            }
            continue;
        }

        const segments = parsePath(path);
        let parentContainer, key, index;

        try {
            // 1. Handle path traversal to find the parent context
            const navigationResult = navigateToParent(currentDoc, segments);
            parentContainer = navigationResult.parent;
            key = segments[segments.length - 1];

            // 2. Special handling for array indices if the key looks like a number
            index = Number(key);
            const isArray = Array.isArray(parentContainer);
            const isNumericKey = !isNaN(index) && Number.isInteger(index);

            // If the parent is an array, the key *must* be a valid array index.
            if (isArray && !isNumericKey) {
                 throw new Error("Path segment targeting an array must be a non-negative whole number.");
            }

            if (!isArray && isNumericKey) {
                // If the parent is an object, we treat the numeric key as a string key
                index = key;
            }

        } catch (e) {
            throw new Error(`Invalid path or parent not found for operation ${operation} at path ${path}. Reason: ${e.message}`);
        }

        // 3. Apply the operation
        switch (operation) {
            case 'add':
                if (Array.isArray(parentContainer)) {
                    if (typeof index === 'number') {
                        if (index < 0) {
                            // - means append, but in JS slice/splice, a negative index is relative to the end
                            // We handle - as special case for append
                            if (index === -1 && currentDoc.length === 0) {
                                currentDoc = [value];
                                continue;
                            } else if (index < -currentDoc.length) {
                                throw new Error("Array index out of range");
                            }
                            // Standard splice handles negative indices (e.g., -1 is last element)
                        }
                        if (index > parentContainer.length) {
                             throw new Error("Array index out of range");
                        }

                        parentContainer.splice(index, 0, value);
                    } else {
                        // This case should ideally not be reached if logic above is perfect, but for safety:
                        throw new Error(`Invalid index for array 'add' operation: ${key}`);
                    }
                } else { // Object
                    parentContainer[key] = value;
                }
                break;

            case 'remove':
                if (Array.isArray(parentContainer)) {
                    const idx = Number(key);
                    if (idx < 0 || idx >= parentContainer.length) {
                        throw new Error("Array index out of range");
                    }
                    parentContainer.splice(idx, 1);
                } else { // Object
                    if (typeof parentContainer[key] === 'undefined') {
                         throw new Error("Target must exist for remove operation.");
                    }
                    delete parentContainer[key];
                }
                break;

            case 'replace':
                if (Array.isArray(parentContainer)) {
                    const idx = Number(key);
                     if (idx < 0 || idx >= parentContainer.length) {
                        throw new Error("Array index out of range");
                    }
                    // Must exist check (implicitly handled if index is in range, but better safe)
                    if (parentContainer[idx] === undefined) {
                         throw new Error("Target must exist for replace operation.");
                    }
                    parentContainer[idx] = value;
                } else { // Object
                    if (typeof parentContainer[key] === 'undefined') {
                        throw new Error("Target must exist for replace operation.");
                    }
                    parentContainer[key] = value;
                }
                break;
        }
    }

    return currentDoc;
}
