    if operator == '==':
        return v1 == v2
    elif operator == '!=':
        return v1 != v2
    elif operator == '>':
        return v1 > v2
    elif operator == '>=':
        return v1 >= v2
    elif operator == '<':
        return v1 < v2
    elif operator == '<=':
        return v1 <= v2
    else:
        raise ValueError(f"Unknown operator: {operator}")

