        return False


def satisfies(version: str, range_: str) -> bool:
    """
    Checks if a given version string satisfies a version range string.
    """
    try:
        v_parts = parse_version(version)
    except ValueError:
        return False # Invalid input version

    # 1. Split range into alternatives (||)
    alternatives = [alt.strip() for alt in range_.split('||')]

    # If the range string is empty or only whitespace, it vacuously fails or succeeds depending on interpretation. 
    # Assuming a non-empty range means we must satisfy at least one alternative.
    if not alternatives:
        return False

    # 2. Check if version satisfies at least one alternative
    for alternative in alternatives:
        # 3. Split alternative into comparators (space separated)
        comparators = [comp.strip() for comp in alternative.split() if comp.strip()]

        if not comparators:
