        # 4. Check if version satisfies ALL comparators in this alternative
        alternative_satisfied = True
        for comparator in comparators:
            if not satisfies_comparator(v_parts, comparator):
                alternative_satisfied = False
                break

        # If the version satisfies this alternative, the whole range is satisfied
        if alternative_satisfied:
            return True

    # If no alternative was satisfied
    return False
