from collections import deque
from typing import Dict, List

def build_order(deps: dict[str, list[str]]) -> list[str]:
    # Step 1: Collect all unique targets (both keys and values in deps)
    all_targets = set(deps.keys())
    for target in deps.values():
        all_targets.update(target)

    # Step 2: Build the graph and calculate in-degrees
    # In-degree here represents the number of unprocessed dependencies
    in_degree = {target: 0 for target in all_targets}
    dependents = {target: [] for target in all_targets}

    for target, dependencies in deps.items():
        if len(dependencies) == 0:
            continue
        for dep in dependencies:
            if dep not in all_targets:
                # This case shouldn't happen based on problem description logic 
                # but if it does, we treat it as a dependency that exists.
                pass
            in_degree[target] += 1
            dependents[dep].append(target)

    # Step 3: Initialize queue with targets having no dependencies (alphabetically sorted)
    queue = deque(sorted([target for target, degree in in_degree.items() if degree == 0]))

    result = []

    while queue:
        current_target = queue.popleft()
        result.append(current_target)

        # Process dependents of the current target
        # Sort dependents to ensure deterministic order when adding to queue
        for dependent in sorted(dependents[current_target]):
            in_degree[dependent] -= 1
            if in_degree[dependent] == 0:
                queue.append(dependent)

    # Step 4: Check for cycles
    if len(result) != len(all_targets):
        raise ValueError("Cycle detected in dependencies")

    return result
```

The function first identifies all unique targets involved (both those defining dependencies and those being depended upon). It then constructs a graph tracking in-degrees (number of unmet dependencies) and lists of dependents. Using Kahn's algorithm for topological sorting, it processes targets with zero in-degree, adding them to the result list and decrementing the in-degree of their dependents. To ensure determinism, it sorts both the initial queue and the newly added nodes before proceeding. Finally, if the resulting list is shorter than the total number of unique targets, a cycle exists, raising a `ValueError`.

