```python
from collections import OrderedDict

class TTLCache:
    def __init__(self, capacity: int, ttl: int):
        self.capacity = capacity
        self.ttl = ttl
        # Stores {key: (value, expiry_time, access_count)}
        # Using OrderedDict to maintain insertion order for LRU logic
        self.cache = OrderedDict()

    def _cleanup_expired(self, now: int) -> None:
        """Remove all expired entries and shrink the dict to capacity if needed."""
        # Remove expired entries first
        expired_keys = [k for k in self.cache.keys() if now >= self.cache[k][1]]
        for k in expired_keys:
            del self.cache[k]

        # If still full after cleanup, remove LRU (oldest) entry
        while len(self.cache) > self.capacity:
            self.cache.popitem(last=False)

    def put(self, key, value, now: int) -> None:
        if key in self.cache:
            # Update existing entry
            _, expiry, _ = self.cache[key]
            # If it's already valid, we just update the value and make it MRU
            # The expiry time remains as set during previous put/get unless now > expiry
            # However, logic says "expiry time becomes now + ttl". 
            # Re-reading: "The entry's expiry time becomes now + ttl" implies refresh on put.
            self.cache[key] = (value, now + self.ttl)
        else:
            # New key
            if len(self.cache) >= self.capacity:
                self._cleanup_expired(now)

            self.cache[key] = (value, now + self.ttl)

    def get(self, key, now: int):
        if key not in self.cache:
            return None

        value, expiry = self.cache[key]

        # Check expiration
        if now >= expiry:
            del self.cache[key]
            return None

        # Update to Most Recently Used (move to end of OrderedDict)
        self.cache.move_to_end(key)
        return value

    def size(self, now: int) -> int:
        count = 0
        for k in self.cache:
            if now < self.cache[k][1]:
                count += 1
        return count
```

This implementation uses `OrderedDict` to efficiently track insertion order for the Least Recently Used (LRU) eviction policy while also storing expiry times. The `put` method refreshes the TTL on every write, and both `get` and `size` correctly handle expiration checks based on the provided `now`. When the cache is full, it first evicts all expired entries before removing the oldest non-expired entry.

