        return (int(parts[0]), int(parts[1]), int(parts[2]))

    def compare(v1: Tuple[int, int, int], v2: Tuple[int, int, int]) -> int:
        if v1 > v2: return 1
        if v1 < v2: return -1
        return 0

    def satisfies_comparator(ver_tuple: Tuple[int, int, int], comp_str: str) -> bool:
        comp_str = comp_str.strip()
        op = ''
        ver_part = ''

        for char in comp_str:
            if char.isdigit():
                break
            op += char

        if not op or not ver_part:
            return False

        ver_part = comp_str[op:].strip()

        try:
            target_ver = parse_version(ver_part)
        except ValueError:
            return False

        # Handle tilde (~)
        if op == '~':
            if compare(ver_tuple, target_ver) != 1: return False
            next_major = target_ver[0]
            next_minor = target_ver[1]
            next_patch = target_ver[2] + 1
            upper_bound = (next_major, next_minor, next_patch)
            return compare(ver_tuple, upper_bound) == -1

        # Handle caret (^)
        if op == '^':
            major = target_ver[0]
            if major == 0:
                minor = target_ver[1]
                if minor == 0:
                    upper_bound = (major, minor, target_ver[2] + 1)
                else:
                    upper_bound = (major, minor + 1, 0)
            else:
                upper_bound = (major + 1, 0, 0)

            if compare(ver_tuple, target_ver) != 1: return False
            return compare(ver_tuple, upper_bound) == -1

        # Handle operators
        if op == '=':
            return compare(ver_tuple, target_ver) == 0
        elif op == '>=':
            return compare(ver_tuple, target_ver) >= 0
        elif op == '<=':
            return compare(ver_tuple, target_ver) <= 0
        elif op == '>':
            return compare(ver_tuple, target_ver) > 0
        elif op == '<':
            return compare(ver_tuple, target_ver) < 0

        # No operator means exact match (handled by = logic or implicit strict? 
        # Prompt says "1.2.3" is exactly that version, so treat as equality)
        return compare(ver_tuple, target_ver) == 0

    def satisfies_alternative(alternative_str: str) -> bool:
        comparators = alternative_str.split()
        for comp in comparators:
            if not satisfies_comparator(parse_version(version), comp):
                return False
        return True

    alternatives = range_.split('||')
    for alt in alternatives:
        if satisfies_alternative(alt.strip()):
