def build_order(deps: dict[str, list[str]]) -> list[str]:
    # Collect all unique targets (both keys and values in deps)
    all_targets = set(deps.keys())
    for dependencies in deps.values():
        all_targets.update(dependencies)

    # Ensure every target has an entry in deps (even if empty), to handle leaf nodes uniformly
    for target in all_targets:
        if target not in deps:
            deps[target] = []

    output = []
    in_degree = {target: 0 for target in all_targets}

    # Calculate in-degrees based on dependencies
    for target, dependencies in deps.items():
        for dep in dependencies:
            if dep not in all_targets:
                raise ValueError(f"Unknown dependency: {dep}")
            in_degree[target] += 1

    # Use a sorted list to maintain deterministic order (alphabetical)
    # We re-sort after each extraction to satisfy the "smallest available" rule dynamically
    available = [target for target, degree in in_degree.items() if degree == 0]

    while available:
        # Sort to get the alphabetically smallest target
        available.sort()
        current_target = available.pop(0)
        output.append(current_target)

        # Decrease in-degree for targets that depend on the current one
        for other_target, dependencies in deps.items():
            if current_target in dependencies:
                in_degree[other_target] -= 1
                if in_degree[other_target] == 0:
                    available.append(other_target)

    # Check for cycles: if not all targets are in output, there's a cycle
    if len(output) != len(all_targets):
        raise ValueError("Cycle detected in dependencies")

    return output
