import re

def satisfies(version: str, range_: str) -> bool:
    """
    Check if a version string satisfies a given version range.

    Args:
        version (str): Version in MAJOR.MINOR.PATCH format.
        range_ (str): Version range with alternatives separated by '||'.

    Returns:
        bool: True if the version satisfies at least one alternative in the range.
    """
    def parse_version(v: str) -> tuple[int, int, int]:
        parts = v.strip().split('.')
        return (int(parts[0]), int(parts[1]), int(parts[2]))

    def compare(v1: tuple[int, int, int], v2: tuple[int, int, int]) -> int:
        if v1 < v2:
            return -1
        elif v1 > v2:
            return 1
        return 0

    def check_exact(version_tuple: tuple[int, int, int], target: str) -> bool:
        if not target.startswith('='):
            target = '=' + target
        target_tuple = parse_version(target[1:])
        return compare(version_tuple, target_tuple) == 0

    def check_greater_equal(version_tuple: tuple[int, int, int], target: str) -> bool:
        target_tuple = parse_version(target)
        return compare(version_tuple, target_tuple) >= 0

    def check_less_equal(version_tuple: tuple[int, int, int], target: str) -> bool:
        target_tuple = parse_version(target)
        return compare(version_tuple, target_tuple) <= 0

    def check_greater(version_tuple: tuple[int, int, int], target: str) -> bool:
        target_tuple = parse_version(target)
        return compare(version_tuple, target_tuple) > 0

    def check_less(version_tuple: tuple[int, int, int], target: str) -> bool:
        target_tuple = parse_version(target)
        return compare(version_tuple, target_tuple) < 0

    def check_tilde(version_tuple: tuple[int, int, int], target: str) -> bool:
        target_tuple = parse_version(target)
        upper = (target_tuple[0], target_tuple[1] + 1, 0)
        return compare(version_tuple, target_tuple) >= 0 and compare(version_tuple, upper) < 0

    def check_caret(version_tuple: tuple[int, int, int], target: str) -> bool:
        target_tuple = parse_version(target)

        # Determine the upper bound based on major/minor/zero rules
        if target_tuple[0] == 0 and target_tuple[1] == 0:
            # ^0.0.x -> >=0.0.x and <0.0.(x+1)
            upper = (0, 0, target_tuple[2] + 1)
        elif target_tuple[0] == 0:
            # ^0.x.y -> >=0.x.y and <0.(x+1).0
            upper = (0, target_tuple[1] + 1, 0)
        else:
            # ^X.Y.Z -> >=X.Y.Z and <(X+1).0.0
            upper = (target_tuple[0] + 1, 0, 0)

        return compare(version_tuple, target_tuple) >= 0 and compare(version_tuple, upper) < 0

    def evaluate_alternative(alternative: str) -> bool:
        alternative = alternative.strip()
        if not alternative:
            return False

        comparators = [c.strip() for c in alternative.split()]
        version_tuple = parse_version(version)

        for comp in comparators:
            comp = comp.strip()
            if not comp:
                continue

            # Handle caret operator with special cases
            if comp.startswith('^'):
                if not check_caret(version_tuple, comp[1:]):
                    return False
            # Handle tilde operator
            elif comp.startswith('~'):
                if not check_tilde(version_tuple, comp[1:]):
                    return False
            # Handle equality operator (explicit or implicit)
            elif comp.startswith('=') and len(comp) > 1:
                if not check_exact(version_tuple, comp):
                    return False
            # Handle greater than or equal
            elif comp.startswith('>='):
                if not check_greater_equal(version_tuple, comp[2:]):
                    return False
            # Handle less than or equal
            elif comp.startswith('<='):
                if not check_less_equal(version_tuple, comp[2:]):
                    return False
            # Handle greater than
            elif comp.startswith('>'):
                if not check_greater(version_tuple, comp[1:]):
                    return False
            # Handle less than
            elif comp.startswith('<'):
                if not check_less(version_tuple, comp[1:]):
                    return False
            else:
                # Implicit equality for version strings without operator prefix
                if not check_exact(version_tuple, comp):
                    return False

        return True

    def evaluate_range(range_str: str) -> bool:
        alternatives = re.split(r'\|\|', range_str.strip())
        for alt in alternatives:
            if evaluate_alternative(alt):
                return True
        return False

    return evaluate_range(range_)
