                # Exact match, handle empty string as invalid but safe to skip if needed, 
                # though problem implies valid comparators. If '=' is present:
                ver = parse_version(comp[1:] if comp.startswith('=') else comp)
                conditions.append(('eq', ver))
            elif comp.startswith('~'):
                ver = parse_version(comp[1:])
                upper_ver = list(ver)
                upper_ver[2] += 1
                upper_ver = tuple(upper_ver)
                # ~1.2.3 -> >=1.2.3 and <1.3.0
                conditions.append(('ge', ver))
                conditions.append(('lt', upper_ver))
            elif comp.startswith('^'):
