from typing import Dict, List

def build_order(deps: dict[str, list[str]]) -> list[str]:
    # Collect all unique targets (both keys and values in deps)
    all_targets = set(deps.keys())
    for target_list in deps.values():
        all_targets.update(target_list)

    # Build a complete dependency map including targets with no dependencies
    # Default to empty list if a target is only found as a dependency
    full_deps: dict[str, list[str]] = {}
    for t in all_targets:
        if t in deps:
            full_deps[t] = sorted(deps[t])  # Sort to ensure deterministic processing order internally
        else:
            full_deps[t] = []

    # Detect cycles using DFS states: 0=unvisited, 1=in_progress, 2=finished
    state: dict[str, int] = {t: 0 for t in all_targets}
    result: List[str] = []

    def visit(target: str) -> None:
        if state[target] == 2:
            return
        if state[target] == 1:
            raise ValueError("Cycle detected")

        state[target] = 1
        for dep in full_deps[target]:
            visit(dep)
        state[target] = 2
        result.append(target)

    # Process targets in sorted order to ensure deterministic output at each step
    for target in sorted(all_targets):
        if state[target] == 0:
            visit(target)

    return result
