        targetInfo = resolvePath(doc, parentPath);
        const arr = targetInfo.value;
        if (!Array.isArray(arr)) throw new Error(`Parent for add '-' must be an array`);
        const idx = arr.length;

        // Create a new array with the value inserted
        const newArr = [...arr];
        newArr.splice(idx, 0, value);
        targetInfo.parent[targetInfo.key] = newArr;
        continue;
      }

      targetInfo = resolvePath(doc, path);

      if (!targetInfo.exists) {
        throw new Error(`Parent does not exist for add operation at path "${path}"`);
      }

      const { parent, key } = targetInfo;
      if (Array.isArray(parent)) {
        // Insert before index. If value is undefined, we still insert it as null? 
        // The prompt says "INSERT the value". Usually JSON Patch inserts the provided value.
        // However, if value is undefined in JS object literal, it's omitted.
        // We assume 'value' property exists and is not undefined unless explicitly set to null/undefined.
        const idx = typeof key === 'number' ? key : parseInt(key, 10);
        if (idx < 0 || idx > parent.length) {
            throw new Error(`Invalid array index for add: ${path}`);
        }
        // Create new array
        const newArr = [...parent];
        newArr.splice(idx, 0, value);
        parent[key] = newArr;
      } else {
        // Object set
        if (key === undefined) throw new Error("Invalid key for object add");
        parent[key] = value;
      }
    } 
    else if (operation === 'remove') {
      targetInfo = resolvePath(doc, path);

      if (!targetInfo.exists) {
        throw new Error(`Target does not exist for remove operation at path "${path}"`);
      }

      const { parent, key } = targetInfo;
      if (Array.isArray(parent)) {
        // Remove by index
        const idx = typeof key === 'number' ? key : parseInt(key, 10);
        parent.splice(idx, 1);
      } else {
        // Remove object member
        if (key === undefined) throw new Error("Invalid key for object remove");
        delete parent[key];
      }
    } 
    else if (operation === 'replace') {
      targetInfo = resolvePath(doc, path);

      if (!targetInfo.exists) {
        throw new Error(`Target does not exist for replace operation at path "${path}"`);
      }

      const { parent, key } = targetInfo;
      if (Array.isArray(parent)) {
        const idx = typeof key === 'number' ? key : parseInt(key, 10);
        parent[key] = value; // Replace element in place (which is a reference update in our clone logic effectively)
      } else {
        if (key === undefined) throw new Error("Invalid key for object replace");
        parent[key] = value;
      }
    }
  }

  return result;
}
