from collections import OrderedDict

class TTLCache:
    def __init__(self, capacity: int, ttl: int):
        if capacity <= 0 or ttl <= 0:
            raise ValueError("capacity and ttl must be positive integers")
        self.capacity = capacity
        self.ttl = ttl
        # OrderedDict maintains insertion order; we will manipulate it to track LRU
        # Key: str, Value: (data_value, expiry_time)
        self._cache = OrderedDict()

    def _is_expired(self, key: str, now: int) -> bool:
        if key not in self._cache:
            return True
        _, expiry = self._cache[key]
        return now >= expiry

    def _remove_expired_entries(self, now: int):
        """Removes all expired entries from the cache."""
        keys_to_remove = [key for key in self._cache if self._is_expired(key, now)]
        for key in keys_to_remove:
            del self._cache[key]

    def put(self, key: str, value, now: int) -> None:
        # First, remove any expired entries
        self._remove_expired_entries(now)

        if key in self._cache:
            # Update existing entry
            expiry = now + self.ttl
            self._cache[key] = (value, expiry)
            # Move to end to mark as most recently used
            self._cache.move_to_end(key)
        else:
            # New entry
            if len(self._cache) >= self.capacity:
                # Cache is full; remove the least recently used item (first item)
                # Note: expired entries were already removed, so the first item is valid LRU
                if self._cache:
                    self._cache.popitem(last=False)

            expiry = now + self.ttl
            self._cache[key] = (value, expiry)

    def get(self, key: str, now: int):
        if key not in self._cache or self._is_expired(key, now):
            return None

        # Move to end to mark as most recently used without changing expiry
        self._cache.move_to_end(key)
        return self._cache[key][0]

    def size(self, now: int) -> int:
        return sum(1 for key in self._cache if not self._is_expired(key, now))
```

This implementation uses `collections.OrderedDict` to efficiently track insertion order and LRU behavior. The `_remove_expired_entries` method ensures that expired items are cleaned up before checking capacity constraints during a `put` operation, adhering strictly to the requirement that eviction only happens after removing expired entries if the cache remains full.

