/**
 * Applies a list of JSON Patch operations to a document without modifying the original.
 * 
 * @param {any} doc - The source JSON document.
 * @param {Array<{op: string, path: string, value?: any}>} ops - Array of patch operations.
 * @returns {any} - The new patched document.
 * @throws {Error} - If an operation is invalid or the target doesn't exist.
 */
function applyPatch(doc, ops) {
  // Helper to resolve path segments (handling ~0 and ~1)
  function getSegments(path) {
    if (path === '') return [];
    return path.split('/').map(seg => {
      if (seg === '~0') return '~';
      if (seg === '~1') return '/';
      return seg;
    });
  }

  // Helper to get value at path, throwing if not found
  function getValue(targetDoc, segments) {
    let current = targetDoc;
    for (const seg of segments) {
      if (current === null || current === undefined) {
        throw new Error(`Missing parent at path: ${segments.join('/')}`);
      }
      if (typeof current !== 'object') {
        throw new Error(`Cannot navigate into non-object/array at path: ${segments.join('/')}`);
      }
      if (Array.isArray(current)) {
        const idx = parseInt(seg, 10);
        if (isNaN(idx) || !Number.isInteger(idx) || idx < 0) {
          throw new Error(`Invalid array index in path: ${seg}`);
        }
        if (idx >= current.length) {
          throw new Error(`Array index out of range at path: ${segments.join('/')}`);
        }
        current = current[idx];
      } else {
        if (!(seg in current)) {
          throw new Error(`Missing member '${seg}' at path: ${segments.join('/')}`);
        }
        current = current[seg];
      }
    }
    return current;
  }

  // Helper to set value at path, creating parents if needed (except for the final target check logic)
  function setValue(targetDoc, segments, value) {
    let current = targetDoc;
    for (let i = 0; i < segments.length - 1; i++) {
      const seg = segments[i];
      if (!current || typeof current !== 'object') {
        throw new Error(`Cannot navigate into non-object/array at path: ${segments.slice(0, i+1).join('/')}`);
      }

      if (Array.isArray(current)) {
        const idx = parseInt(seg, 10);
        if (isNaN(idx) || !Number.isInteger(idx) || idx < 0) {
          throw new Error(`Invalid array index in path: ${seg}`);
        }
        if (!(idx in current)) {
           // This shouldn't happen for intermediate nodes in a valid path to an existing object,
           // but if we are creating parents for 'add', we might need to handle it.
           // However, the prompt implies standard JSON Patch where parents must exist unless 
           // the operation is adding to the root. For deep adds, parents usually exist or 
           // we assume the structure allows navigation. 
           // Actually, strict JSON Patch requires parents to exist for add/remove/replace on objects.
           // Exception: 'add' can create an object if the path doesn't exist? No, standard RFC 6902 says 
           // "If the destination is not a valid array or object, then an error is returned."
           // So parents must exist.
           throw new Error(`Parent does not exist at path: ${segments.slice(0, i+1).join('/')}`);
        }
        current = current[idx];
      } else {
        if (!(seg in current)) {
          throw new Error(`Missing member '${seg}' at path: ${segments.join('/')}`);
        }
        current = current[seg];
      }
    }

    const lastSeg = segments[segments.length - 1];
    const parent = targetDoc; // Re-evaluated to ensure we are modifying the right instance

    if (Array.isArray(parent)) {
      const idx = parseInt(lastSeg, 10);
      if (isNaN(idx) || !Number.isInteger(idx) || idx < 0) {
        throw new Error(`Invalid array index in path: ${lastSeg}`);
      }
      // For arrays, we just assign. If it's an 'add' with '-', the caller handles insertion logic 
      // before calling this? No, the prompt says "INSERT ... before the given index".
      // My helper above is for direct assignment. I need to handle the '-' case specifically in the main loop.
      // Let's refactor: The setValue function will only be called if the parent exists and the final step 
      // is a standard set. For 'add' with array, we handle insertion explicitly.

      if (lastSeg === '-') {
        parent.push(value);
      } else {
        parent[parseInt(lastSeg, 10)] = value;
      }
    } else {
      parent[lastSeg] = value;
    }
  }

  // Deep clone to ensure immutability of original doc
  function deepClone(obj) {
    if (obj === null || typeof obj !== 'object') return obj;
    if (Array.isArray(obj)) {
      return obj.map(item => deepClone(item));
    }
    const cloned = {};
    for (const key in obj) {
      if (Object.prototype.hasOwnProperty.call(obj, key)) {
        cloned[key] = deepClone(obj[key]);
      }
    }
    return cloned;
  }

  // Start with a copy
  let result = deepClone(doc);

  for (const op of ops) {
    const { op: operation, path, value } = op;

    if (!['add', 'remove', 'replace'].includes(operation)) {
      throw new Error(`Unknown operation: ${operation}`);
    }

    const segments = getSegments(path);

    if (operation === 'add') {
      // Special case for root document
      if (path === '') {
        result = value;
        continue;
      }

      let target = getValue(result, segments);

      if (Array.isArray(target)) {
        const lastSeg = segments[segments.length - 1];
        if (lastSeg === '-') {
          target.push(value);
        } else {
          const idx = parseInt(lastSeg, 10);
          // Insert before index. If idx == length, push.
          if (idx > target.length) {
            throw new Error(`Array index out of range for insertion at path: ${path}`);
          }
          target.splice(idx, 0, value);
        }
      } else {
        // Object member add/replaces existing
        result = setValue(result, segments, value);
      }

    } else if (operation === 'remove') {
      let target = getValue(result, segments);

      if (Array.isArray(target)) {
        const lastSeg = segments[segments.length - 1];
        if (lastSeg === '-') {
          throw new Error("Cannot use '-' for remove operation");
        }
        const idx = parseInt(lastSeg, 10);
        target.splice(idx, 1);
      } else {
        delete result[segments.join('/')]; // Helper logic needed here or re-use getValue/setValue structure
        // Since we need to delete from the original reference chain to keep parents intact in result:
        let current = result;
        for (let i = 0; i < segments.length - 1; i++) {
          const seg = segments[i];
          if (Array.isArray(current)) {
            current = current[seg];
          } else {
            current = current[seg];
          }
        }
        // Last segment
        const lastSeg = segments[segments.length - 1];
        if (Array.isArray(current)) {
           const idx = parseInt(lastSeg, 10);
           current.splice(idx, 1);
        } else {
           delete current[lastSeg];
        }
      }

    } else if (operation === 'replace') {
      // Replace requires the target to exist. We cannot create parents.
      // getValue already throws if path doesn't exist or parent is missing.
      let target = getValue(result, segments);

      if (Array.isArray(target)) {
        const lastSeg = segments[segments.length - 1];
        const idx = parseInt(lastSeg, 10);
        target[idx] = value;
      } else {
        result = setValue(result, segments, value);
      }
    }
  }

  return result;
}
