def normalise_order(raw: dict) -> dict:
    """
    Normalises a raw order dictionary into a standardised format.

    Args:
        raw: A dictionary containing order details.

    Returns:
        A new dictionary with keys: sku, qty, unit_price_pence, currency, total_pence.

    Raises:
        ValueError: If any required field is missing or invalid.
    """
    # --- SKU ---
    if "sku" not in raw:
        raise ValueError("Missing 'sku'")

    sku_raw = raw["sku"]
    if not isinstance(sku_raw, str):
        raise ValueError("'sku' must be a string")

    sku_stripped = sku_raw.strip()
    if not sku_stripped:
        raise ValueError("'sku' is empty after stripping")

    sku_upper = sku_stripped.upper()

    # --- QTY ---
    if "qty" not in raw:
        raise ValueError("Missing 'qty'")

    qty_raw = raw["qty"]
    try:
        # Try to convert to int; handle string representations with whitespace
        if isinstance(qty_raw, str):
            qty_int = int(qty_raw.strip())
        elif isinstance(qty_raw, (int, float)):
            # If it's a float that is an integer value (e.g. 3.0), convert to int
            if qty_raw != int(qty_raw):
                raise ValueError("'qty' must be an integer value")
            qty_int = int(qty_raw)
        else:
            raise ValueError("'qty' must be a string or number")
    except (ValueError, TypeError):
        raise ValueError(f"Invalid 'qty': {raw['qty']}")

    if qty_int < 1 or qty_int > 99:
        raise ValueError("'qty' must be between 1 and 99 inclusive")

    # --- UNIT PRICE PENCE ---
    if "unit_price_pence" not in raw:
        raise ValueError("Missing 'unit_price_pence'")

    price_raw = raw["unit_price_pence"]
    try:
        if isinstance(price_raw, str):
            price_int = int(float(price_raw.strip()))
        elif isinstance(price_raw, (int, float)):
            if price_raw < 0:
                raise ValueError("'unit_price_pence' must be >= 0")
            if price_raw != int(price_raw):
                # Allow floats like 1.0 but not 1.5? The spec says "as an int", 
                # so let's accept integers or float equivalents of integers.
                raise ValueError("'unit_price_pence' must be a whole number")
            price_int = int(price_raw)
        else:
            raise ValueError("'unit_price_pence' must be a string or number")
    except (ValueError, TypeError):
        raise ValueError(f"Invalid 'unit_price_pence': {raw['unit_price_pence']}")

    if price_int < 0:
        raise ValueError("'unit_price_pence' must be >= 0")

    # --- CURRENCY ---
    currency_raw = raw.get("currency")

    if currency_raw is None or (isinstance(currency_raw, str) and not currency_raw.strip()):
        currency_final = "GBP"
    elif isinstance(currency_raw, str):
        currency_stripped = currency_raw.strip().upper()
        if currency_stripped in ("GBP", "EUR", "USD"):
            currency_final = currency_stripped
        else:
            raise ValueError(f"'currency' must be one of GBP, EUR, USD; got '{currency_raw}'")
    else:
        # If currency is not a string (and not None/blank), it's invalid
        raise ValueError("'currency' must be a string or missing/blank")

    # --- TOTAL PENCE ---
    total_pence = qty_int * price_int

    return {
        "sku": sku_upper,
        "qty": qty_int,
        "unit_price_pence": price_int,
        "currency": currency_final,
        "total_pence": total_pence,
    }
