function parseQuery(qs) {
    // Remove leading '?' if present
    if (qs.startsWith('?')) {
        qs = qs.substring(1);
    }

    // If empty, return empty object
    if (!qs || qs.length === 0) {
        return {};
    }

    const result = {};

    // Split by '&' to get individual pairs
    const pairs = qs.split('&');

    for (const pair of pairs) {
        // Skip empty pairs (from && or trailing &)
        if (pair.length === 0) {
            continue;
        }

        // Find the first '=' to split key and value
        const eqIndex = pair.indexOf('=');

        let key, value;
        if (eqIndex === -1) {
            // No '=' found: key is the whole string, value is ""
            key = pair;
            value = '';
        } else {
            key = pair.substring(0, eqIndex);
            value = pair.substring(eqIndex + 1);
        }

        // Decode '+' as space first
        const decodePlus = (str) => str.replace(/\+/g, ' ');

        // Then percent-decode
        const decodedKey = decodeURIComponent(decodePlus(key));
        const decodedValue = decodeURIComponent(decodePlus(value));

        // Handle multiple values for the same key
        if (result.hasOwnProperty(decodedKey)) {
            // If it's already an array, push to it
            if (Array.isArray(result[decodedKey])) {
                result[decodedKey].push(decodedValue);
            } else {
                // Convert existing string value to array with both values
                result[decodedKey] = [result[decodedKey], decodedValue];
            }
        } else {
            result[decodedKey] = decodedValue;
