function deepMerge(base, override) {
    if (override === undefined || override === null) {
        return JSON.parse(JSON.stringify(base));
    }

    // If base is not a plain object or override is not a plain object, replace
    if (!isPlainObject(base) || !isPlainObject(override)) {
        return JSON.parse(JSON.stringify(override));
    }

    const result = {};

    // Copy all keys from base first
    for (const key of Object.keys(base)) {
        result[key] = deepClone(base[key]);
    }

    // Merge/override with keys from override
    for (const key of Object.keys(override)) {
        const overrideVal = override[key];

        // undefined in override is ignored
        if (overrideVal === undefined) {
            continue;
        }

        const baseVal = base[key];

        // If both values are plain objects, merge recursively
        if (isPlainObject(baseVal) && isPlainObject(overrideVal)) {
            result[key] = deepMerge(baseVal, overrideVal);
        } else {
            // Otherwise, override replaces base (including arrays, null, etc.)
            result[key] = deepClone(overrideVal);
        }
    }

    return result;
}

function isPlainObject(value) {
    if (value === null || typeof value !== 'object') {
        return false;
    }
    const proto = Object.getPrototypeOf(value);
    return proto === null || proto === Object.prototype;
}

function deepClone(value) {
    if (value === null || typeof value !== 'object') {
        return value;
    }
    // Use JSON stringify/parse for deep cloning plain objects and arrays
    return JSON.parse(JSON.stringify(value));
}
