#include <string>
#include <cctype>

long long parse_duration(const std::string& s) {
    if (s.empty()) return -1;

    long long total_seconds = 0;
    size_t i = 0;
    size_t n = s.length();

    // Track which units have been seen to prevent duplicates and enforce order
    bool seen_h = false;
    bool seen_m = false;
    bool seen_s = false;

    while (i < n) {
        // Check for spaces anywhere
        if (std::isspace(static_cast<unsigned char>(s[i]))) return -1;

        // Parse the number part
        size_t start = i;
        if (!std::isdigit(static_cast<unsigned char>(s[i]))) {
            // Either unit without number, or unexpected character
            return -1;
        }
        while (i < n && std::isdigit(static_cast<unsigned char>(s[i]))) {
            i++;
        }
        if (i == start) {
            // No digits consumed
            return -1;
        }

        // Extract the number string and convert to long long
        std::string num_str = s.substr(start, i - start);
        long long value = 0;
        for (char c : num_str) {
            value = value * 10 + (c - '0');
        }

        // Check if we've reached the end of string
        if (i >= n) {
            // Number without a unit at the end
            return -1;
        }

        // Parse the unit character
        char unit = s[i];
        i++;

        long long seconds = 0;
        switch (unit) {
            case 'h':
                if (seen_h) return -1; // Duplicate hour
                seen_h = true;
                seconds = value * 3600;
                break;
            case 'm':
                if (seen_m) return -1; // Duplicate minute
                if (seen_s) return -1; // Minutes after seconds is wrong order
                seen_m = true;
                seconds = value * 60;
                break;
            case 's':
                if (seen_s) return -1; // Duplicate second
                seen_s = true;
                seconds = value;
                break;
            default:
                return -1; // Unknown unit
        }

        total_seconds += seconds;
    }

    return total_seconds;
}
