function applyPatch(doc, ops) {
  // Deep clone the document to avoid modifying the original
  function deepClone(obj) {
    if (obj === null || typeof obj !== 'object') {
      return obj;
    }
    if (Array.isArray(obj)) {
      return obj.map(item => deepClone(item));
    }
    const cloned = {};
    for (const key of Object.keys(obj)) {
      cloned[key] = deepClone(obj[key]);
    }
    return cloned;
  }

  let current = deepClone(doc);

  for (const opEntry of ops) {
    const { op, path, value } = opEntry;

    if (op !== 'add' && op !== 'remove' && op !== 'replace') {
      throw new Error(`Unknown operation: ${op}`);
    }

    // Parse the path
    let segments;
    if (path === "") {
      segments = [];
    } else {
      if (!path.startsWith('/')) {
        throw new Error('Path must start with /');
      }
      const parts = path.split('/').slice(1); // Remove empty string before first /
      segments = parts.map(p => decodeSegment(p));
    }

    if (op === 'add') {
      add(current, segments, value);
    } else if (op === 'remove') {
      remove(current, segments);
    } else if (op === 'replace') {
      replace(current, segments, value);
    }
  }

  return current;
}

