    if "sku" not in raw or raw["sku"] is None:
        raise ValueError("sku is missing")
    sku = str(raw["sku"]).strip().upper()
    if not sku:
        raise ValueError("sku is empty after stripping")

    # Validate and extract qty
    if "qty" not in raw or raw["qty"] is None:
        raise ValueError("qty is missing")
    try:
