    except (ValueError, TypeError):
        raise ValueError("qty cannot be converted to int")
    if qty < 1 or qty > 99:
        raise ValueError("qty must be between 1 and 99 inclusive")

    # Validate and extract unit_price_pence
    if "unit_price_pence" not in raw or raw["unit_price_pence"] is None:
        raise ValueError("unit_price_pence is missing")
    try:
        unit_price_pence = int(raw["unit_price_pence"])
    except (ValueError, TypeError):
        raise ValueError("unit_price_pence cannot be converted to int")
    if unit_price_pence < 0:
        raise ValueError("unit_price_pence must be 0 or more")

    # Validate and extract currency
    currency_raw = raw.get("currency")
    if currency_raw is None or str(currency_raw).strip() == "":
        currency = "GBP"
    else:
        currency = str(currency_raw).strip().upper()
        if currency not in ("GBP", "EUR", "USD"):
            raise ValueError(f"Invalid currency: {currency}")

    total_pence = qty * unit_price_pence

    return {
        "sku": sku,
        "qty": qty,
        "unit_price_pence": unit_price_pence,
        "currency": currency,
        "total_pence": total_pence,
    }
