function deepMerge(base, override) {
    if (base === null || typeof base !== 'object') {
        return JSON.parse(JSON.stringify(override));
    }
    if (override === null || typeof override !== 'object') {
        return JSON.parse(JSON.stringify(base));
    }

    const result = {};

    // Copy all keys from base first
    for (const key of Object.keys(base)) {
        result[key] = deepClone(base[key]);
    }

    // Merge keys from override
    for (const key of Object.keys(override)) {
        const overrideVal = override[key];

        // If override value is undefined, ignore it
        if (overrideVal === undefined) {
            continue;
        }

        const baseVal = base[key];

        // If both values are plain objects (not arrays, not null), merge recursively
        if (
            baseVal !== null &&
            typeof baseVal === 'object' &&
            !Array.isArray(baseVal) &&
            overrideVal !== null &&
            typeof overrideVal === 'object' &&
            !Array.isArray(overrideVal)
        ) {
            result[key] = deepMerge(baseVal, overrideVal);
        } else {
            // Override value replaces base value (deep cloned to ensure no shared references)
            result[key] = deepClone(overrideVal);
        }
    }

    return result;
}

function deepClone(obj) {
    if (obj === null || typeof obj !== 'object') {
        return obj;
    }
    if (Array.isArray(obj)) {
        return obj.map(item => deepClone(item));
    }
    const clone = {};
    for (const key of Object.keys(obj)) {
        clone[key] = deepClone(obj[key]);
    }
    return clone;
}
