            return -1; // No digits consumed
        }

        // Parse unit
        if (pos >= len) {
            return -1; // Number without a unit
        }
        char unit = s[pos];
        pos++;

        int unit_order = -1;
        long long multiplier = 0;

        switch (unit) {
            case 'h':
                unit_order = 0;
                multiplier = 3600;
                break;
            case 'm':
                unit_order = 1;
                multiplier = 60;
                break;
            case 's':
                unit_order = 2;
                multiplier = 1;
                break;
            default:
                return -1; // Unknown unit
        }

        // Check order: units must appear in h, m, s order, each at most once
        if (unit_order <= last_unit_order) {
            return -1; // Wrong order or repeated unit
        }
        last_unit_order = unit_order;

        // Parse the number as long long
        std::string num_str = s.substr(num_start, pos - num_start);
        long long value = 0;
        for (char c : num_str) {
            value = value * 10 + (c - '0');
        }

        total_seconds += value * multiplier;
    }

    // Must have consumed at least one unit to be valid
    if (last_unit_order == -1) {
        return -1;
    }

    return total_seconds;
}
```

This function parses duration strings like `1h30m` by iterating through segments of digits followed by a single unit character (`h`, `m`, or `s`). It validates that units appear in strict order (hours, then minutes, then seconds), each at most once, with no spaces or signs. If any validation fails, it returns `-1`. Otherwise, it computes and returns the total seconds.

