def satisfies(version: str, range_: str) -> bool:
    """
    Check if a version string satisfies a range specification.

    Args:
        version: A version string in MAJOR.MINOR.PATCH format (e.g., "1.2.3")
        range_: A range specification with alternatives separated by || and comparators separated by spaces

    Returns:
        True if the version satisfies at least one alternative in the range, False otherwise
    """

    def parse_version(ver_str):
        """Parse a version string into a tuple of integers."""
        parts = ver_str.strip().split('.')
        return tuple(int(p) for p in parts)

    def compare_versions(v1, v2):
        """Compare two version tuples. Returns -1, 0, or 1."""
        for a, b in zip(v1, v2):
            if a < b:
                return -1
            elif a > b:
                return 1
        # All compared parts are equal, check length
        if len(v1) < len(v2):
            return -1
        elif len(v1) > len(v2):
            return 1
        return 0

    def check_comparator(version_tuple, comparator_str):
        """Check if a version satisfies a single comparator."""
        comparator_str = comparator_str.strip()

        if not comparator_str:
            return True

        # Determine the operator and the version string
        if comparator_str.startswith('>='):
            op = '>='
            ver_str = comparator_str[2:]
        elif comparator_str.startswith('<='):
            op = '<='
            ver_str = comparator_str[2:]
        elif comparator_str.startswith('>'):
            op = '>'
            ver_str = comparator_str[1:]
        elif comparator_str.startswith('<'):
            op = '<'
            ver_str = comparator_str[1:]
        elif comparator_str.startswith('='):
            op = '='
            ver_str = comparator_str[1:]
        elif comparator_str.startswith('~'):
            op = '~'
            ver_str = comparator_str[1:]
        elif comparator_str.startswith('^'):
            op = '^'
            ver_str = comparator_str[1:]
        else:
            # Plain version means exactly that version (implicit =)
            op = '='
            ver_str = comparator_str

        ver_tuple = parse_version(ver_str)

        cmp_result = compare_versions(version_tuple, ver_tuple)

        if op == '=':
            return cmp_result == 0
        elif op == '>':
            return cmp_result > 0
        elif op == '>=':
            return cmp_result >= 0
        elif op == '<':
            return cmp_result < 0
        elif op == '<=':
            return cmp_result <= 0
        elif op == '~':
            # ~1.2.3 means >=1.2.3 and <1.3.0
            if cmp_result < 0:
                return False
            # Check upper bound: must be less than major.minor+1.patch
            upper = (ver_tuple[0], ver_tuple[1] + 1, 0)
            upper_cmp = compare_versions(version_tuple, upper)
            return upper_cmp < 0
        elif op == '^':
            # ^1.2.3 means >=1.2.3 and <2.0.0
            if cmp_result < 0:
                return False
            # Determine the upper bound based on major/minor zeros
            if ver_tuple[0] != 0:
                # Major is non-zero: upper bound is next major version
                upper = (ver_tuple[0] + 1, 0, 0)
            elif ver_tuple[1] != 0:
                # Major is zero, minor is non-zero: upper bound is next minor version
                upper = (0, ver_tuple[1] + 1, 0)
            else:
                # Both major and minor are zero: upper bound is next patch version
                upper = (0, 0, ver_tuple[2] + 1)
            upper_cmp = compare_versions(version_tuple, upper)
            return upper_cmp < 0

        return False

    def check_alternative(version_tuple, alternative_str):
        """Check if a version satisfies all comparators in an alternative."""
        comparators = alternative_str.split()
        for comp in comparators:
            if not check_comparator(version_tuple, comp):
                return False
        return True

    # Parse the range string by splitting on ||
    alternatives = range_.split('||')

    version_tuple = parse_version(version)

    for alt in alternatives:
        if check_alternative(version_tuple, alt):
            return True

    return False
```

