function applyPatch(doc, ops) {
  // Deep clone the document to avoid modifying the original
  function deepClone(obj) {
    if (obj === null || typeof obj !== 'object') {
      return obj;
    }
    if (Array.isArray(obj)) {
      return obj.map(item => deepClone(item));
    }
    const cloned = {};
    for (const key of Object.keys(obj)) {
      cloned[key] = deepClone(obj[key]);
    }
    return cloned;
  }

  let result = deepClone(doc);

  for (const opEntry of ops) {
    const { op, path, value } = opEntry;

    if (!['add', 'remove', 'replace'].includes(op)) {
      throw new Error(`Unknown operation: ${op}`);
    }

    // Parse the path
    const segments = parsePath(path);

    if (path === '') {
      // Special case: "" means the whole document
      if (op === 'add') {
        result = value;
      } else if (op === 'replace') {
        // Target must exist (it does, since we have a doc)
        result = value;
      } else if (op === 'remove') {
        // Removing the whole document? The target must exist.
        // After removal, what is the document? Typically undefined or null.
        // Let's set result to undefined/removed. But since we need to return a JSON value,
        // let's consider that removing "" means the document becomes undefined.
        // However, subsequent ops might reference it. Let's set result to undefined.
        result = undefined;
      } else {
        throw new Error(`Unknown operation: ${op}`);
      }
      continue;
    }

    // For non-empty paths, navigate to the parent and apply the op
    const currentResult = getAtPath(result, segments.slice(0, -1));
    const lastSegment = segments[segments.length - 1];

    if (currentResult === undefined || currentResult === null) {
      throw new Error(`Parent does not exist at path ${path}`);
    }

    if (Array.isArray(currentResult)) {
      // Handle array operations
      let index;
      if (lastSegment === '-') {
        index = currentResult.length;
      } else {
        if (!/^\d+$/.test(lastSegment)) {
          throw new Error(`Invalid array index: ${lastSegment}`);
        }
        index = parseInt(lastSegment, 10);
      }

      if (index < 0 || index > currentResult.length) {
        throw new Error(`Array index out of range: ${index}`);
      }

      if (op === 'add') {
        currentResult.splice(index, 0, value);
      } else if (op === 'remove') {
        if (index >= currentResult.length) {
          throw new Error(`Array index out of range for remove: ${index}`);
        }
        currentResult.splice(index, 1);
      } else if (op === 'replace') {
        if (index >= currentResult.length) {
          throw new Error(`Array index out of range for replace: ${index}`);
        }
        currentResult[index] = value;
      }
    } else if (typeof currentResult === 'object' && currentResult !== null) {
      // Handle object operations
      const key = decodeSegment(lastSegment);

      if (op === 'add') {
        currentResult[key] = value;
      } else if (op === 'remove') {
        if (!(key in currentResult)) {
          throw new Error(`Key not found: ${key}`);
        }
        delete currentResult[key];
      } else if (op === 'replace') {
        if (!(key in currentResult)) {
          throw new Error(`Key not found: ${key}`);
        }
        currentResult[key] = value;
      }
    } else {
      throw new Error(`Target is not an object or array`);
    }
  }

  return result;
}

function parsePath(path) {
  if (path === '') {
    return [];
  }
  // Path starts with /, so split by / and filter out empty strings from leading/trailing slashes
  const parts = path.split('/');
  // First element is empty because of leading /
  if (parts[0] !== '') {
    throw new Error(`Path must start with /`);
  }
  // Remove the first empty string
  const segments = parts.slice(1);
  return segments.map(decodeSegment);
}

function decodeSegment(segment) {
  // Replace ~1 with / and ~0 with ~
  let decoded = segment.replace(/~1/g, '/').replace(/~0/g, '~');
  return decoded;
}

function getAtPath(obj, segments) {
  if (segments.length === 0) {
    return obj;
  }
  const [first, ...rest] = segments;
  if (obj === undefined || obj === null) {
    return undefined;
  }
  if (Array.isArray(obj)) {
    const index = parseInt(first, 10);
    if (isNaN(index) || index < 0 || index >= obj.length) {
      return undefined;
    }
    return getAtPath(obj[index], rest);
  } else if (typeof obj === 'object') {
    if (!(first in obj)) {
      return undefined;
    }
    return getAtPath(obj[first], rest);
  } else {
    return undefined;
  }
}
