def normalise_order(raw: dict) -> dict:
    """
    Normalise a raw order dict into a new dict with exactly these keys:
    sku, qty, unit_price_pence, currency, total_pence.

    Raises ValueError for invalid or missing values.
    """
    # --- SKU ---
    if "sku" not in raw or raw["sku"] is None:
        raise ValueError("Missing or null 'sku'")
    sku = str(raw["sku"]).strip()
    if not sku:
        raise ValueError("Empty or whitespace-only 'sku'")
    sku = sku.upper()

    # --- QTY ---
    if "qty" not in raw or raw["qty"] is None:
        raise ValueError("Missing or null 'qty'")
    try:
        qty_str = str(raw["qty"]).strip()
        qty = int(qty_str)
    except (ValueError, TypeError):
        raise ValueError(f"Invalid 'qty': {raw['qty']}")
    if qty < 1 or qty > 99:
        raise ValueError(f"Qty must be between 1 and 99 inclusive, got {qty}")

    # --- UNIT PRICE PENCE ---
    if "unit_price_pence" not in raw or raw["unit_price_pence"] is None:
        raise ValueError("Missing or null 'unit_price_pence'")
    try:
        unit_price_pence = int(raw["unit_price_pence"])
    except (ValueError, TypeError):
        raise ValueError(f"Invalid 'unit_price_pence': {raw['unit_price_pence']}")
    if unit_price_pence < 0:
        raise ValueError(f"unit_price_pence must be >= 0, got {unit_price_pence}")

    # --- CURRENCY ---
    currency_raw = raw.get("currency")
    if currency_raw is None or str(currency_raw).strip() == "":
        currency = "GBP"
    else:
        currency = str(currency_raw).strip().upper()
        if currency not in ("GBP", "EUR", "USD"):
            raise ValueError(f"Invalid currency: {currency_raw}")

    # --- TOTAL PENCE ---
    total_pence = qty * unit_price_pence

    return {
        "sku": sku,
        "qty": qty,
        "unit_price_pence": unit_price_pence,
        "currency": currency,
        "total_pence": total_pence,
    }
```

