function parseQuery(qs) {
  // Remove leading '?' if present
  if (typeof qs !== 'string' || qs.length === 0) {
    return {};
  }

  if (qs.startsWith('?')) {
    qs = qs.substring(1);
  }

  const result = {};

  // Split by '&' to get pairs
  const pairs = qs.split('&');

  for (const pair of pairs) {
    // Skip empty pairs (from && or trailing &)
    if (pair === '') {
      continue;
    }

    // Find the first '=' to split key and value
    const eqIndex = pair.indexOf('=');

    let key, value;

    if (eqIndex === -1) {
      // Key without '=' gets value ""
      key = pair;
      value = '';
    } else {
      key = pair.substring(0, eqIndex);
      value = pair.substring(eqIndex + 1);
    }

    // Decode: first replace '+' with space, then percent-decode
    const decodedKey = decodeURIComponent(key.replace(/\+/g, ' '));
    const decodedValue = decodeURIComponent(value.replace(/\+/g, ' '));

    // Handle duplicate keys
    if (decodedKey in result) {
      // If it's already an array, push; otherwise convert to array
      if (Array.isArray(result[decodedKey])) {
        result[decodedKey].push(decodedValue);
      } else {
        result[decodedKey] = [result[decodedKey], decodedValue];
      }
    } else {
      result[decodedKey] = decodedValue;
    }
  }

  return result;
}
```

