function deepMerge(base, override) {
    // Helper to check if a value is a plain object (not null, not array, not primitive)
    function isPlainObject(value) {
        return (
            value !== null &&
            typeof value === 'object' &&
            !Array.isArray(value) &&
            Object.prototype.toString.call(value) === '[object Object]'
        );
    }

    // Helper to deep clone a value
    function deepClone(value) {
        if (value === null || value === undefined) {
            return value;
        }
        if (Array.isArray(value)) {
            return value.map(item => deepClone(item));
        }
        if (isPlainObject(value)) {
            const cloned = {};
            for (const key of Object.keys(value)) {
                cloned[key] = deepClone(value[key]);
            }
            return cloned;
        }
        // For primitives, just return the value
        return value;
    }

    // Clone base first to avoid mutation
    const result = deepClone(base);

    for (const key of Object.keys(override)) {
        const overrideValue = override[key];

        // If override value is undefined, ignore it (keep base value)
        if (overrideValue === undefined) {
            continue;
        }

        const baseValue = result[key];

        // If both values are plain objects, merge recursively
        if (isPlainObject(baseValue) && isPlainObject(overrideValue)) {
            result[key] = deepMerge(baseValue, overrideValue);
        } else {
            // Otherwise, replace with override value (deep cloned to avoid sharing references)
            result[key] = deepClone(overrideValue);
        }
    }

    return result;
}
```

