long long parse_duration(const std::string& s) {
    if (s.empty()) return -1;

    size_t pos = 0;
    long long total_seconds = 0;
    int last_unit = 0; // 0: none, 1: h, 2: m, 3: s

    while (pos < s.size()) {
        // Parse number
        size_t start = pos;
        if (!std::isdigit(s[pos])) return -1; // No digit at start

        long long num = 0;
        while (pos < s.size() && std::isdigit(s[pos])) {
            num = num * 10 + (s[pos] - '0');
            pos++;
        }

        // Check if we consumed any digits
        if (pos == start) return -1;

        // Must be followed by a unit
        if (pos >= s.size()) return -1; // Number without unit

        char unit = s[pos];
        int current_unit;

        switch (unit) {
            case 'h': current_unit = 1; break;
            case 'm': current_unit = 2; break;
            case 's': current_unit = 3; break;
            default: return -1; // Unknown unit
        }

        // Check order: units must be in increasing order (h < m < s)
        if (current_unit <= last_unit) return -1; // Wrong order or repeated

        last_unit = current_unit;
        pos++; // Skip the unit character

        // Add to total
        switch (current_unit) {
            case 1: total_seconds += num * 3600; break;
            case 2: total_seconds += num * 60; break;
            case 3: total_seconds += num; break;
        }
    }

    return total_seconds;
}
