function deepMerge(base, override) {
    // Create a deep clone of base to start with
    const result = deepClone(base);

    // Iterate over keys in override
    for (const key of Object.keys(override)) {
        const baseVal = result[key];
        const overrideVal = override[key];

        // If override value is undefined, skip it
        if (overrideVal === undefined) {
            continue;
        }

        // Check if both values are plain objects (not arrays, not null)
        const baseIsPlainObject = baseVal !== null && typeof baseVal === 'object' && !Array.isArray(baseVal);
        const overrideIsPlainObject = overrideVal !== null && typeof overrideVal === 'object' && !Array.isArray(overrideVal);

        if (baseIsPlainObject && overrideIsPlainObject) {
            // Recursively merge
            result[key] = deepMerge(baseVal, overrideVal);
        } else {
            // Override replaces base value
            result[key] = deepClone(overrideVal);
        }
    }

    return result;
}

function deepClone(obj) {
    if (obj === null || typeof obj !== 'object') {
        return obj;
    }
    if (Array.isArray(obj)) {
        return obj.map(item => deepClone(item));
    }
    const cloned = {};
    for (const key of Object.keys(obj)) {
        cloned[key] = deepClone(obj[key]);
    }
    return cloned;
}
