#include <string>
#include <cctype>

long long parse_duration(const std::string& s) {
    if (s.empty()) return -1;

    size_t i = 0;
    const size_t n = s.size();

    long long total_seconds = 0;
    bool has_h = false;
    bool has_m = false;
    bool has_s = false;

    while (i < n) {
        // Parse number: must have at least one digit, no signs, no leading zeros issues but digits only
        if (!std::isdigit(s[i])) {
            return -1; // Expected a digit but found something else
        }

        long long num = 0;
        while (i < n && std::isdigit(s[i])) {
            num = num * 10 + (s[i] - '0');
            ++i;
        }

        // Now expect a unit character
        if (i >= n) {
            return -1; // Number without a unit
        }

        char unit = s[i];
        ++i;

        switch (unit) {
            case 'h':
                if (has_h) return -1; // Repeated unit
                has_h = true;
                total_seconds += num * 3600;
                break;
            case 'm':
                if (has_m) return -1;
                if (has_s) return -1; // Wrong order: m after s
                has_m = true;
                total_seconds += num * 60;
                break;
            case 's':
                if (has_s) return -1;
                has_s = true;
                total_seconds += num;
                break;
            default:
                return -1; // Unknown unit
        }
    }

    // Ensure we consumed the entire string
    return total_seconds;
}
```

This function parses a duration string by iterating through digits and expecting a following unit character (`h`, `m`, or `s`). It validates that units appear in the correct order (hours, then minutes, then seconds), are not repeated, and that every number is followed by a valid unit. If the entire string is consumed and all constraints are met, it returns the total seconds; otherwise, it returns -1.

