import collections


class TTLCache:
    def __init__(self, capacity: int, ttl: int):
        self.capacity = capacity
        self.ttl = ttl
        # Use an OrderedDict to maintain insertion order (for LRU) and allow O(1) operations
        # We'll store expiry times in a separate dict for clarity, or embed in the value.
        # Let's store (value, expiry) as value in the OrderedDict.
        self.cache = collections.OrderedDict()

    def put(self, key, value, now: int) -> None:
        expiry = now + self.ttl
        if key in self.cache:
            # Update existing key: move to end (most recently used) and update value/expiry
            self.cache.move_to_end(key)
            self.cache[key] = (value, expiry)
        else:
            # New key
            if len(self.cache) >= self.capacity:
                # First, remove all expired entries
                expired_keys = [k for k, (v, exp) in self.cache.items() if now >= exp]
                for k in expired_keys:
                    del self.cache[k]

                # If still full, remove LRU (first item)
                if len(self.cache) >= self.capacity:
                    self.cache.popitem(last=False)

            # Add new entry at the end
            self.cache[key] = (value, expiry)

    def get(self, key, now: int):
        if key not in self.cache:
            return None

        value, expiry = self.cache[key]

        # Check if expired
        if now >= expiry:
            del self.cache[key]
            return None

        # Move to end (most recently used)
        self.cache.move_to_end(key)
        return value

    def size(self, now: int) -> int:
        count = 0
        keys_to_remove = []
        for key, (value, expiry) in self.cache.items():
            if now >= expiry:
                keys_to_remove.append(key)
            else:
                count += 1

        # Remove expired entries
        for k in keys_to_remove:
            del self.cache[k]

        return count
```

This implementation uses `collections.OrderedDict` to efficiently manage the LRU ordering. The `put` method first cleans up expired entries when adding a new key to a full cache, then evicts the LRU entry if still full. The `get` method checks expiration, updates access order, and returns the value or `None`. The `size` method counts non-expired entries and removes expired ones for consistency.

