function parseQuery(qs) {
  if (!qs || qs === '') return {};

  // Remove leading '?' if present
  if (qs.startsWith('?')) {
    qs = qs.substring(1);
  }

  const result = {};

  // Split by '&'
  const pairs = qs.split('&');

  for (const pair of pairs) {
    // Skip empty pairs
    if (pair === '') continue;

    // Split on the first '=' only
    const eqIndex = pair.indexOf('=');
    let key, value;

    if (eqIndex === -1) {
      // No '=' found: key is the whole string, value is ""
      key = pair;
      value = '';
    } else {
      key = pair.substring(0, eqIndex);
      value = pair.substring(eqIndex + 1);
    }

    // Decode: replace '+' with space first, then percent-decode
    const decode = (str) => {
      return decodeURIComponent(str.replace(/\+/g, ' '));
    };

    const decodedKey = decode(key);
    const decodedValue = decode(value);

    // Handle single vs multiple values for the same key
    if (!(decodedKey in result)) {
      result[decodedKey] = decodedValue;
    } else {
      // If it's already a string, convert to array
      if (typeof result[decodedKey] === 'string') {
        result[decodedKey] = [result[decodedKey], decodedValue];
      } else {
        // Already an array, push new value
        result[decodedKey].push(decodedValue);
      }
    }
  }

  return result;
}
