function deepMerge(base, override) {
    if (override === null || typeof override !== 'object') {
        return base;
    }

    const result = {};

    // Copy all keys from base first
    for (const key of Object.keys(base)) {
        if (typeof base[key] === 'object' && base[key] !== null && !Array.isArray(base[key])) {
            result[key] = deepCopy(base[key]);
        } else {
            result[key] = base[key];
        }
    }

    // Merge/override with keys from override
    for (const key of Object.keys(override)) {
        const overrideVal = override[key];

        // Skip undefined values in override
        if (overrideVal === undefined) {
            continue;
        }

        const baseVal = base[key];

        // If both are plain objects (not arrays, not null), merge recursively
        if (
            typeof baseVal === 'object' &&
            baseVal !== null &&
            !Array.isArray(baseVal) &&
            typeof overrideVal === 'object' &&
            overrideVal !== null &&
            !Array.isArray(overrideVal)
        ) {
            result[key] = deepMerge(baseVal, overrideVal);
        } else {
            // Otherwise, replace with override value (deep copy if object/array)
            if (typeof overrideVal === 'object' && overrideVal !== null) {
                result[key] = deepCopy(overrideVal);
            } else {
                result[key] = overrideVal;
            }
        }
    }

    return result;
}

function deepCopy(obj) {
    if (obj === null || typeof obj !== 'object') {
        return obj;
    }

    if (Array.isArray(obj)) {
        return obj.map(item => deepCopy(item));
    }

    const copy = {};
    for (const key of Object.keys(obj)) {
        copy[key] = deepCopy(obj[key]);
    }
    return copy;
}
