long long parse_duration(const std::string& s) {
    if (s.empty()) return -1;

    long long total_seconds = 0;
    size_t pos = 0;
    size_t len = s.length();

    int seen_h = 0;
    int seen_m = 0;
    int seen_s = 0;

    while (pos < len) {
        // Parse the number part
        if (!std::isdigit(static_cast<unsigned char>(s[pos]))) {
            return -1; // No digit where expected
        }

        long long num = 0;
        while (pos < len && std::isdigit(static_cast<unsigned char>(s[pos]))) {
            num = num * 10 + (s[pos] - '0');
            ++pos;
        }

        // Check for spaces after the number
        if (pos < len && s[pos] == ' ') {
            return -1;
        }

        // Parse the unit part
        if (pos >= len) {
            return -1; // Number without a unit
        }

        char unit = s[pos];
        ++pos;

        switch (unit) {
            case 'h':
                if (seen_h) return -1; // Repeated unit
                seen_h = 1;
                total_seconds += num * 3600;
                break;
            case 'm':
                if (seen_m) return -1;
                seen_m = 1;
                total_seconds += num * 60;
                break;
            case 's':
                if (seen_s) return -1;
                seen_s = 1;
                total_seconds += num;
                break;
            default:
                return -1; // Unknown unit
        }

        // After consuming a part, if there are more characters, they must start with a digit
        if (pos < len) {
            if (!std::isdigit(static_cast<unsigned char>(s[pos]))) {
                return -1;
            }
        }
    }

    // Validate order: h must come before m, m must come before s
    // This is ensured by the fact that we see them in sequence.
    // But we need to check that if m was seen, h was also seen (if h exists)
    // Actually, the requirement is units appear in order h, m, s.
    // So if we have 'm', we must have had 'h' before it? No, '45s' is valid without h or m.
    // '1h0m5s' is valid. '1m5s' is valid (no h). '1s' is valid.
    // '2m1h' is invalid because m comes before h? No, the order is h, m, s.
    // So if we see a unit, all previous units in the sequence must have been seen if they exist?
    // Let's re-read: "Units must appear in the order h, m, s, each at most once"
    // This means the string should match regex: (\d+h)?(\d+m)?(\d+s)?
    // So we need to check that we don't skip a unit.

    // Check if any unit is missing in the middle
    if (seen_m && !seen_h) return -1;
    if (seen_s && !seen_m) return -1;

    return total_seconds;
}
