from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity: int, ttl: int):
        self.capacity = capacity
        self.ttl = ttl
        # OrderedDict to maintain insertion order (LRU behavior)
        # Each value is a tuple: (expiry_time, actual_value)
        self.cache = OrderedDict()

    def put(self, key, value, now: int) -> None:
        expiry = now + self.ttl

        # If key already exists, update it and move to end (most recently used)
        if key in self.cache:
            self.cache[key] = (expiry, value)
            self.cache.move_to_end(key)
            return

        # New key: check capacity
        if len(self.cache) >= self.capacity:
            # First, remove all expired entries
            keys_to_remove = [k for k, (exp, _) in self.cache.items() if now >= exp]
            for k in keys_to_remove:
                del self.cache[k]

            # If still full, remove LRU (first item)
            if len(self.cache) >= self.capacity:
                self.cache.popitem(last=False)

        self.cache[key] = (expiry, value)

    def get(self, key, now: int):
        if key not in self.cache:
            return None

        expiry, value = self.cache[key]

        # Check if expired
        if now >= expiry:
            del self.cache[key]
            return None

        # Move to end (most recently used)
        self.cache.move_to_end(key)
        return value

    def size(self, now: int) -> int:
        count = 0
        keys_to_remove = []
        for k, (exp, _) in self.cache.items():
            if now < exp:
                count += 1
            else:
                keys_to_remove.append(k)

        # Clean up expired entries
        for k in keys_to_remove:
            del self.cache[k]

        return count
