def satisfies(version: str, range_: str) -> bool:
    """
    Check if a version string satisfies a range specification.

    Args:
        version: A version string in MAJOR.MINOR.PATCH format.
        range_: A range specification with alternatives separated by ||.

    Returns:
        True if the version satisfies at least one alternative in the range.
    """
    # Parse the version into components
    try:
        major, minor, patch = map(int, version.split('.'))
    except ValueError:
        return False

    version_tuple = (major, minor, patch)

    # Split by || to get alternatives
    alternatives = range_.split('||')

    for alt in alternatives:
        if _check_alternative(version_tuple, alt.strip()):
            return True

    return False


def _check_alternative(version_tuple: tuple, alt: str) -> bool:
    """Check if version satisfies all comparators in an alternative."""
    # Split by spaces to get individual comparators
    comparators = alt.split()

    for comp in comparators:
        comp = comp.strip()
        if not _check_comparator(version_tuple, comp):
            return False

    return True


def _parse_version(ver_str: str) -> tuple:
    """Parse a version string into a tuple of integers."""
    parts = ver_str.split('.')
    if len(parts) != 3:
        raise ValueError(f"Invalid version format: {ver_str}")
    return tuple(int(p) for p in parts)


def _check_comparator(version_tuple: tuple, comp: str) -> bool:
    """Check if version satisfies a single comparator."""
    # Remove leading = if present
    if comp.startswith('='):
        comp = comp[1:]

    # Determine operator and version
    if comp.startswith('>='):
        op = '>='
        ver_str = comp[2:]
    elif comp.startswith('<='):
        op = '<='
        ver_str = comp[2:]
    elif comp.startswith('>'):
        op = '>'
        ver_str = comp[1:]
    elif comp.startswith('<'):
        op = '<'
        ver_str = comp[1:]
    elif comp.startswith('~'):
        op = '~'
        ver_str = comp[1:]
    elif comp.startswith('^'):
        op = '^'
        ver_str = comp[1:]
    else:
        # Plain version means exact match (equivalent to =)
        op = '='
        ver_str = comp

    target = _parse_version(ver_str)

    if op == '=':
        return version_tuple == target
    elif op == '>':
        return version_tuple > target
    elif op == '>=':
        return version_tuple >= target
    elif op == '<':
        return version_tuple < target
    elif op == '<=':
        return version_tuple <= target
    elif op == '~':
        # ~1.2.3 means >=1.2.3 and <1.3.0
        if not (version_tuple >= target):
            return False
        # Upper bound: increment minor, set patch to 0
        upper = (target[0], target[1] + 1, 0)
        return version_tuple < upper
    elif op == '^':
        # ^1.2.3 means >=1.2.3 and <2.0.0
        # ^0.2.3 means >=0.2.3 and <0.3.0
        # ^0.0.3 means >=0.0.3 and <0.0.4
        if not (version_tuple >= target):
            return False

        major, minor, patch = target

        if major != 0:
            # ^X.Y.Z where X > 0: <(X+1).0.0
            upper = (major + 1, 0, 0)
        elif minor != 0:
            # ^0.Y.Z where Y > 0: <0.(Y+1).0
            upper = (0, minor + 1, 0)
        else:
            # ^0.0.Z: <0.0.(Z+1)
            upper = (0, 0, patch + 1)

        return version_tuple < upper

    return False
```

This implementation parses versions as tuples of integers for proper numeric comparison. It handles all comparator types including `~` (tilde) and `^` (caret) with their specific rules for zero major/minor versions. The range is split by `||` into alternatives, and a version satisfies the range if it meets at least one alternative's set of comparators.

