function applyPatch(doc, ops) {
  // Deep clone the document to avoid mutating the original
  const newDoc = JSON.parse(JSON.stringify(doc));

  for (const opEntry of ops) {
    const { op, path, value } = opEntry;

    if (op !== 'add' && op !== 'remove' && op !== 'replace') {
      throw new Error(`Unknown operation: ${op}`);
    }

    // Parse the path into segments
    const segments = parsePath(path);

    if (path === "") {
      // Whole document replacement/addition
      if (op === 'add') {
        return value;
      } else if (op === 'replace') {
        return value;
      } else if (op === 'remove') {
        // Removing the whole document? Return undefined or null? Let's say undefined.
        return undefined;
      }
    }

    // Navigate to the parent, collecting path as we go
    let current = newDoc;
    let parent = null;
    let parentKey = null;

    for (let i = 0; i < segments.length - 1; i++) {
      const seg = segments[i];
      if (current === null || current === undefined) {
        throw new Error(`Parent does not exist at path ${segments.slice(0, i + 1).join('/')}`);
      }

      if (Array.isArray(current)) {
        const idx = parseInt(seg, 10);
        if (isNaN(idx) || idx < 0 || seg !== String(idx)) {
          throw new Error(`Invalid array index: ${seg}`);
        }
        if (idx >= current.length) {
          throw new Error(`Array index out of range: ${idx} >= ${current.length}`);
        }
        parent = current;
        parentKey = idx;
        current = current[idx];
      } else if (typeof current === 'object' && current !== null) {
        if (!(seg in current)) {
          throw new Error(`Property does not exist: ${seg}`);
        }
        parent = current;
        parentKey = seg;
        current = current[seg];
      } else {
        throw new Error(`Cannot traverse through non-object/array`);
      }
    }

    // Now current is the target, parent and parentKey are set
    const lastSeg = segments[segments.length - 1];

    if (Array.isArray(parent)) {
      const idx = parseInt(lastSeg, 10);
      if (isNaN(idx) || idx < 0 || lastSeg !== String(idx)) {
        throw new Error(`Invalid array index: ${lastSeg}`);
      }

      if (op === 'add') {
        if (idx > parent.length) {
          throw new Error(`Array index out of range for add: ${idx} > ${parent.length}`);
        }
        // Handle '-' as append
        let insertIdx = idx;
        if (lastSeg === '-') {
          insertIdx = parent.length;
        }
        parent.splice(insertIdx, 0, value);
      } else if (op === 'remove') {
        if (idx >= parent.length) {
          throw new Error(`Array index out of range for remove: ${idx} >= ${parent.length}`);
        }
        parent.splice(idx, 1);
      } else if (op === 'replace') {
        if (idx >= parent.length) {
          throw new Error(`Array index out of range for replace: ${idx} >= ${parent.length}`);
        }
        parent[idx] = value;
      }
    } else if (typeof parent === 'object' && parent !== null) {
      if (op === 'add') {
        parent[lastSeg] = value;
      } else if (op === 'remove') {
        if (!(lastSeg in parent)) {
          throw new Error(`Property does not exist for remove: ${lastSeg}`);
        }
        delete parent[lastSeg];
      } else if (op === 'replace') {
        if (!(lastSeg in parent)) {
          throw new Error(`Property does not exist for replace: ${lastSeg}`);
        }
        parent[lastSeg] = value;
      }
    } else {
      throw new Error(`Parent is not an object or array`);
    }
  }

  return newDoc;
}

function parsePath(path) {
  if (path === "") {
    return [];
  }
  // Path starts with /
  if (!path.startsWith('/')) {
    throw new Error(`Path must start with / or be empty`);
  }
  const rawSegments = path.split('/');
  // First element is empty string because of leading /
  rawSegments.shift();

  return rawSegments.map(seg => {
    // Decode ~1 -> / and ~0 -> ~
    return seg.replace(/~1/g, '/').replace(/~0/g, '~');
  });
}
