        if (i >= n || !std::isdigit(static_cast<unsigned char>(s[i]))) return -1;
        long long num = 0;
        while (i < n && std::isdigit(static_cast<unsigned char>(s[i]))) {
            num = num * 10 + (s[i] - '0');
            ++i;
        }

        // Read unit
        if (i >= n) return -1;
        char unit = s[i++];
        if (unit == 'h') {
            if (saw_h) return -1;
            saw_h = true;
            total += num * 3600;
        } else if (unit == 'm') {
            if (saw_m) return -1;
            saw_m = true;
            total += num * 60;
        } else if (unit == 's') {
            if (saw_s) return -1;
            saw_s = true;
            total += num;
        } else {
            return -1;
        }
    }

    return total;
}
```

The function parses the string sequentially: at each step it reads a digit sequence followed by exactly one of `h`, `m`, or `s`. It tracks which units have been seen to enforce the h→m→s ordering and prevent repeats. Any deviation (missing number/unit, unknown character, spaces, signs) returns -1.

