```python
class TTLCache:
    def __init__(self, capacity: int, ttl: int):
        self.capacity = capacity
        self.ttl = ttl
        self._data = {}  # key -> (value, expiry)
        self._order = []  # list of keys in LRU order (oldest first)

    def put(self, key, value, now: int) -> None:
        expiry = now + self.ttl
        if key in self._data:
            self._data[key] = (value, expiry)
            self._order.remove(key)
        else:
            if len(self._data) >= self.capacity:
                # First remove all expired entries
                expired_keys = [k for k in self._order if now >= self._data[k][1]]
                for k in expired_keys:
                    del self._data[k]
                    self._order.remove(k)
                # If still full, evict LRU
                if len(self._data) >= self.capacity:
                    lru = self._order.pop(0)
                    del self._data[lru]
            self._data[key] = (value, expiry)
        self._order.append(key)

    def get(self, key, now: int):
        if key not in self._data:
            return None
        value, expiry = self._data[key]
        if now >= expiry:
            del self._data[key]
            self._order.remove(key)
            return None
        # Move to most recently used
        self._order.remove(key)
        self._order.append(key)
        return value

    def size(self, now: int) -> int:
        return sum(1 for k, (v, expiry) in self._data.items() if now < expiry)
```

The implementation uses a dict for O(1) lookups and a list to track LRU order. On `put` of a new key when full, expired entries are purged first, then the LRU entry is evicted if still needed. `get` updates usage order without changing expiry.

