def build_order(deps: dict[str, list[str]]) -> list[str]:
    all_targets = set(deps.keys())
    for target_deps in deps.values():
        for d in target_deps:
            all_targets.add(d)

    # Initialize in-degree and adjacency
    in_degree = {t: 0 for t in all_targets}
    dependents = {t: [] for t in all_targets}  # t -> list of targets that depend on t

    for target, target_deps in deps.items():
        for d in target_deps:
            dependents[d].append(target)
            in_degree[target] += 1

    import heapq
    heap = [t for t in all_targets if in_degree[t] == 0]
    heapq.heapify(heap)

    result = []
    while heap:
        current = heapq.heappop(heap)
        result.append(current)
        for dep in dependents[current]:
            in_degree[dep] -= 1
            if in_degree[dep] == 0:
                heapq.heappush(heap, dep)

    if len(result) != len(all_targets):
        raise ValueError("Dependency cycle detected")

    return result
```

This uses Kahn's algorithm with a min-heap to ensure deterministic alphabetical ordering. Targets are processed only after all their dependencies have been output, and a `ValueError` is raised if a cycle prevents all targets from being included.

