    # unit_price_pence
    try:
        upp_raw = raw["unit_price_pence"]
    except KeyError:
        raise ValueError("missing unit_price_pence")
    try:
        unit_price_pence = int(upp_raw)
    except (ValueError, TypeError):
        raise ValueError("unit_price_pence is not a valid integer")
    if unit_price_pence < 0:
        raise ValueError("unit_price_pence must be >= 0")

    # currency
