long long parse_duration(const std::string& s) {
    if (s.empty()) return -1;

    long long total = 0;
    int unit_order = 0; // 0=h, 1=m, 2=s

    size_t i = 0;
    while (i < s.size()) {
        // Parse number
        if (i >= s.size() || !std::isdigit(static_cast<unsigned char>(s[i]))) {
            return -1; // no number before unit or at end
        }
        long long num = 0;
        while (i < s.size() && std::isdigit(static_cast<unsigned char>(s[i]))) {
