            ++i;
        }

        // Parse unit
        if (i >= s.size()) return -1; // number without unit
        char unit = s[i++];
        int order = -1;
        long long multiplier = 0;
        if (unit == 'h') {
            order = 0;
            multiplier = 3600;
        } else if (unit == 'm') {
            order = 1;
            multiplier = 60;
        } else if (unit == 's') {
            order = 2;
            multiplier = 1;
        } else {
            return -1; // unknown unit
        }

        if (order < unit_order) return -1; // wrong order or repeated unit
        if (order == unit_order) return -1; // repeated unit
        unit_order = order;
        total += num * multiplier;
    }

    return total;
}
