            return version_tuple >= v and version_tuple < upper
        elif comp.startswith('>='):
            return version_tuple >= parse_version(comp[2:])
        elif comp.startswith('>'):
            return version_tuple > parse_version(comp[1:])
        elif comp.startswith('<='):
            return version_tuple <= parse_version(comp[2:])
        elif comp.startswith('<'):
            return version_tuple < parse_version(comp[1:])
        elif comp.startswith('='):
            return version_tuple == parse_version(comp[1:])
        else:
            return version_tuple == parse_version(comp)

