    all_targets = set(deps.keys())
    for dlist in deps.values():
        for d in dlist:
            all_targets.add(d)

    # Build adjacency and in-degree
    # For each target, we need its dependencies (things that must come before it)
    # We'll use Kahn's algorithm with a min-heap for deterministic ordering

    import heapq

