function applyPatch(doc, ops) {
  function decodeSegment(seg) {
    return seg.replace(/~1/g, '/').replace(/~0/g, '~');
  }

  function parsePath(path) {
    if (path === '') return [];
    if (path[0] !== '/') throw new Error('Invalid path');
    const segments = path.split('/').slice(1);
    return segments.map(decodeSegment);
  }

  function cloneDeep(obj) {
    if (obj === null || typeof obj !== 'object') return obj;
    if (Array.isArray(obj)) {
      return obj.map(item => cloneDeep(item));
    }
    const result = {};
    for (const key of Object.keys(obj)) {
      result[key] = cloneDeep(obj[key]);
    }
    return result;
  }

  let current = cloneDeep(doc);

  for (const opObj of ops) {
    const { op, path, value } = opObj;
    const segments = parsePath(path);

    if (op === 'add') {
      if (segments.length === 0) {
        current = value;
        continue;
      }
      let parent = current;
      for (let i = 0; i < segments.length - 1; i++) {
        const seg = segments[i];
        if (parent === null || typeof parent !== 'object') {
          throw new Error('Parent does not exist');
        }
        if (Array.isArray(parent)) {
          const idx = Number(seg);
          if (!Number.isInteger(idx) || idx < 0) {
            throw new Error('Invalid array index');
          }
          if (idx >= parent.length) {
            throw new Error('Parent does not exist');
          }
          parent = parent[idx];
        } else {
          if (!(seg in parent)) {
            throw new Error('Parent does not exist');
          }
          parent = parent[seg];
        }
      }
      const lastSeg = segments[segments.length - 1];
      if (Array.isArray(parent)) {
        let idx;
        if (lastSeg === '-') {
          idx = parent.length;
        } else {
          idx = Number(lastSeg);
          if (!Number.isInteger(idx) || idx < 0 || idx > parent.length) {
            throw new Error('Array index out of range');
          }
        }
        parent.splice(idx, 0, value);
      } else {
        parent[lastSeg] = value;
      }
    } else if (op === 'remove') {
      if (segments.length === 0) {
        throw new Error('Cannot remove whole document');
      }
      let parent = current;
      for (let i = 0; i < segments.length - 1; i++) {
        const seg = segments[i];
        if (parent === null || typeof parent !== 'object') {
          throw new Error('Parent does not exist');
        }
        if (Array.isArray(parent)) {
          const idx = Number(seg);
          if (!Number.isInteger(idx) || idx < 0 || idx >= parent.length) {
            throw new Error('Invalid array index');
          }
          parent = parent[idx];
        } else {
          if (!(seg in parent)) {
            throw new Error('Target does not exist');
          }
          parent = parent[seg];
        }
      }
      const lastSeg = segments[segments.length - 1];
      if (Array.isArray(parent)) {
        const idx = Number(lastSeg);
        if (!Number.isInteger(idx) || idx < 0 || idx >= parent.length) {
          throw new Error('Array index out of range');
        }
        parent.splice(idx, 1);
      } else {
        if (!(lastSeg in parent)) {
          throw new Error('Target does not exist');
        }
        delete parent[lastSeg];
      }
    } else if (op === 'replace') {
      if (segments.length === 0) {
        current = value;
        continue;
      }
      let parent = current;
      for (let i = 0; i < segments.length - 1; i++) {
        const seg = segments[i];
        if (parent === null || typeof parent !== 'object') {
          throw new Error('Parent does not exist');
        }
        if (Array.isArray(parent)) {
          const idx = Number(seg);
          if (!Number.isInteger(idx) || idx < 0 || idx >= parent.length) {
            throw new Error('Invalid array index');
          }
          parent = parent[idx];
        } else {
          if (!(seg in parent)) {
            throw new Error('Target does not exist');
          }
          parent = parent[seg];
        }
      }
      const lastSeg = segments[segments.length - 1];
      if (Array.isArray(parent)) {
        const idx = Number(lastSeg);
        if (!Number.isInteger(idx) || idx < 0 || idx >= parent.length) {
          throw new Error('Array index out of range');
