function deepMerge(base, override) {
  const result = {};
  for (const key of Object.keys(base)) {
    if (Object.prototype.hasOwnProperty.call(override, key)) {
      const bVal = base[key];
      const oVal = override[key];
      if (oVal === undefined) {
        result[key] = deepClone(bVal);
      } else if (bVal !== null && typeof bVal === 'object' && !Array.isArray(bVal) &&
                 oVal !== null && typeof oVal === 'object' && !Array.isArray(oVal)) {
        result[key] = deepMerge(bVal, oVal);
      } else {
        result[key] = deepClone(oVal);
      }
    } else {
      result[key] = deepClone(base[key]);
    }
  }
  for (const key of Object.keys(override)) {
    if (!Object.prototype.hasOwnProperty.call(base, key) && override[key] !== undefined) {
      result[key] = deepClone(override[key]);
    }
  }
  return result;
}

function deepClone(obj) {
  if (obj === null || typeof obj !== 'object') return obj;
  if (Array.isArray(obj)) return obj.map(deepClone);
  const clone = {};
  for (const key of Object.keys(obj)) {
    clone[key] = deepClone(obj[key]);
  }
  return clone;
}
```

This implementation recursively merges plain objects while deeply cloning all values to ensure no shared references with the inputs. `undefined` values in `override` are skipped, while `null` replaces normally. Arrays and non-object values from `override` replace base values rather than being concatenated or merged.

