long long parse_duration(const std::string& s) {
    if (s.empty()) return -1;

    long long total = 0;
    size_t i = 0;
    int last_unit = 0; // 0=h, 1=m, 2=s

    while (i < s.size()) {
        // Parse number
        if (i >= s.size() || !std::isdigit(static_cast<unsigned char>(s[i]))) {
            return -1; // unit without number or unexpected character
        }
        long long num = 0;
        while (i < s.size() && std::isdigit(static_cast<unsigned char>(s[i]))) {
            num = num * 10 + (s[i] - '0');
            ++i;
        }

        // Parse unit
        if (i >= s.size()) return -1; // number without unit
        char unit = s[i++];
        int unit_val;
        if (unit == 'h') unit_val = 0;
        else if (unit == 'm') unit_val = 1;
        else if (unit == 's') unit_val = 2;
        else return -1; // unknown unit

        if (unit_val < last_unit) return -1; // wrong order
        if (unit_val == last_unit) return -1; // repeated unit
        last_unit = unit_val;

        if (unit == 'h') total += num * 3600;
        else if (unit == 'm') total += num * 60;
        else total += num;
    }

    return total;
}
