from collections import OrderedDict

class TTLCache:
    def __init__(self, capacity: int, ttl: int):
        self.capacity = capacity
        self.ttl = ttl
        self.cache = OrderedDict()  # key -> (value, expiry)

    def put(self, key, value, now: int) -> None:
        expiry = now + self.ttl
        if key in self.cache:
            del self.cache[key]
        elif len(self.cache) >= self.capacity:
            self.cache.popitem(last=False)
        self.cache[key] = (value, expiry)

    def get(self, key, now: int):
        if key not in self.cache:
            return None
        value, expiry = self.cache[key]
        if now >= expiry:
            del self.cache[key]
            return None
        # Move to end (most recently used)
        self.cache.move_to_end(key)
        return value

    def size(self, now: int) -> int:
        expired_keys = [k for k, (v, expiry) in self.cache.items() if now >= expiry]
        for k in expired_keys:
            del self.cache[k]
        return len(self.cache)
```

The cache uses an `OrderedDict` to track insertion/access order. On `put`, expired entries are not proactively removed—only when the cache is full and a new key needs space do we evict expired entries first, then LRU if still full. `get` checks expiry on access and moves hit keys to the end. `size` purges expired entries before counting.

