def build_order(deps: dict[str, list[str]]) -> list[str]:
    # Collect all targets
    all_targets = set(deps.keys())
    for target_deps in deps.values():
        for d in target_deps:
            all_targets.add(d)

    # Build adjacency and in-degree
    # We want to output a target after all its dependencies, so edge: dep -> target
    children = {t: [] for t in all_targets}
    in_degree = {t: 0 for t in all_targets}

    for target, target_deps in deps.items():
        for d in target_deps:
            children[d].append(target)
            in_degree[target] += 1

    # Kahn's algorithm with deterministic (alphabetical) selection
    import heapq
    queue = []
    for t in all_targets:
        if in_degree[t] == 0:
            heapq.heappush(queue, t)

    result = []
    while queue:
        current = heapq.heappop(queue)
        result.append(current)
        for child in children[current]:
            in_degree[child] -= 1
            if in_degree[child] == 0:
                heapq.heappush(queue, child)

    if len(result) != len(all_targets):
        raise ValueError("Dependency cycle detected")

    return result
```

This uses Kahn's algorithm (topological sort via BFS) with a min-heap to ensure deterministic alphabetical ordering at each step. All names appearing in dependency lists are treated as targets with no explicit dependencies (in-degree starts at 0 unless something depends on them). If the graph contains a cycle, not all nodes will be processed, so we raise `ValueError`.

