function applyPatch(doc, ops) {
  // Deep clone the document to avoid mutating the original
  const copy = JSON.parse(JSON.stringify(doc));

  for (const opEntry of ops) {
    const { op, path, value } = opEntry;

    if (op !== 'add' && op !== 'remove' && op !== 'replace') {
      throw new Error('Unknown op: ' + op);
    }

    if (path === '') {
      if (op === 'add') {
        return value;
      } else if (op === 'remove') {
        // Target must exist - for root, it always exists in the current copy
        throw new Error('Cannot remove root document');
      } else if (op === 'replace') {
        return value;
      }
    }

    const segments = parsePath(path);
    let target = copy;
    let parent = null;
    let key = null;

    // Navigate to the parent of the target
    for (let i = 0; i < segments.length - 1; i++) {
      const seg = segments[i];
      if (target === null || target === undefined) {
        throw new Error('Parent does not exist at segment ' + seg);
      }
      if (Array.isArray(target)) {
        const idx = parseInt(seg, 10);
        if (isNaN(idx) || idx < 0 || idx >= target.length) {
          throw new Error('Array index out of range: ' + seg);
        }
        parent = target;
        key = idx;
        target = target[idx];
      } else if (typeof target === 'object' && target !== null) {
        parent = target;
        key = seg;
        target = target[seg];
      } else {
        throw new Error('Cannot traverse into non-object/non-array');
      }
    }

    // Now target is the final segment's value, parent/key point to it
    const lastSeg = segments[segments.length - 1];
    if (parent === null || parent === undefined) {
      throw new Error('Parent does not exist');
    }

    if (Array.isArray(parent)) {
      const idx = parseInt(lastSeg, 10);
      if (isNaN(idx) || idx < 0) {
        throw new Error('Invalid array index: ' + lastSeg);
      }

      if (lastSeg === '-') {
        // Append at end for add
        if (op === 'add') {
          parent.push(value);
        } else if (op === 'replace' || op === 'remove') {
          throw new Error('Cannot remove/replace with "-" index');
        }
      } else {
        if (op === 'add') {
          if (idx > parent.length) {
            throw new Error('Array index out of range: ' + idx);
          }
          parent.splice(idx, 0, value);
        } else if (op === 'remove') {
          if (idx >= parent.length) {
            throw new Error('Array index out of range: ' + idx);
          }
          parent.splice(idx, 1);
        } else if (op === 'replace') {
          if (idx >= parent.length) {
            throw new Error('Array index out of range: ' + idx);
          }
          parent[idx] = value;
        }
      }
    } else if (typeof parent === 'object' && parent !== null) {
      if (op === 'add') {
        parent[lastSeg] = value;
      } else if (op === 'remove') {
        if (!(lastSeg in parent)) {
          throw new Error('Target does not exist for remove');
        }
        delete parent[lastSeg];
      } else if (op === 'replace') {
        if (!(lastSeg in parent)) {
          throw new Error('Target does not exist for replace');
        }
        parent[lastSeg] = value;
      }
    } else {
      throw new Error('Cannot operate on non-object/non-array');
    }
  }

  return copy;
}

function parsePath(path) {
  // path starts with /, e.g., "/servers/0/port"
  if (path[0] !== '/') {
    throw new Error('Invalid path: must start with /');
  }
  const raw = path.substring(1);
  if (raw === '') return [];
  return raw.split('/').map(seg => {
    // Decode ~1 -> / and ~0 -> ~
    return seg.replace(/~1/g, '/').replace(/~0/g, '~');
  });
}
```

This implements JSON Patch-like operations with the specified semantics: deep-clones the input to avoid mutation, parses paths with `~0`/`~1` decoding, handles array insertion/appending with `-`, and throws on all invalid conditions (unknown ops, missing parents/targets, out-of-range indices).

