#include <string>
#include <cctype>

long long parse_duration(const std::string& s) {
    if (s.empty()) return -1;

    long long total = 0;
    int i = 0;
    int n = static_cast<int>(s.size());
    bool seen_h = false, seen_m = false, seen_s = false;

    while (i < n) {
        // Parse number
        if (i >= n || !std::isdigit(static_cast<unsigned char>(s[i]))) {
            return -1; // unit without number or unexpected character
        }
        long long num = 0;
        while (i < n && std::isdigit(static_cast<unsigned char>(s[i]))) {
            num = num * 10 + (s[i] - '0');
            ++i;
        }

        // Parse unit
        if (i >= n) return -1; // number without unit
        char unit = s[i];
        ++i;

        if (unit == 'h') {
            if (seen_h) return -1;
            seen_h = true;
            total += num * 3600;
        } else if (unit == 'm') {
            if (seen_m) return -1;
            seen_m = true;
            total += num * 60;
        } else if (unit == 's') {
            if (seen_s) return -1;
            seen_s = true;
            total += num;
        } else {
            return -1; // unknown unit
        }
    }

    return total;
}
```

