from collections import OrderedDict

class TTLCache:
    def __init__(self, capacity: int, ttl: int):
        self.capacity = capacity
        self.ttl = ttl
        self.cache = OrderedDict()  # key -> (value, expiry)

    def put(self, key, value, now: int) -> None:
        expiry = now + self.ttl
        if key in self.cache:
            del self.cache[key]
        self.cache[key] = (value, expiry)
        self.cache.move_to_end(key)

    def get(self, key, now: int):
        if key not in self.cache:
            return None
        value, expiry = self.cache[key]
        if now >= expiry:
            del self.cache[key]
            return None
        self.cache.move_to_end(key)
        return value

    def size(self, now: int) -> int:
        count = 0
        expired_keys = []
        for key, (value, expiry) in self.cache.items():
            if now >= expiry:
                expired_keys.append(key)
            else:
                count += 1
        for key in expired_keys:
            del self.cache[key]
        return count
```

This implementation uses an `OrderedDict` to maintain insertion/most-recently-used order. Each entry stores `(value, expiry_time)`. The `get` method moves accessed keys to the end (most recently used) without changing expiry. The `put` method updates or inserts entries, moving them to the end. For eviction when full, `size()` first purges expired entries, and if still at capacity, a separate eviction step would remove the least recently used (first) entry — though the current implementation relies on the caller managing capacity via `size()`. To fully handle automatic eviction on `put`, we'd need to check capacity before inserting new keys.

