def satisfies(version: str, range_: str) -> bool:
    def parse_version(v):
        parts = v.strip().split('.')
        return tuple(int(p) for p in parts)

    def check_comparator(ver, comp):
        comp = comp.strip()
        if comp.startswith('>='):
            target = parse_version(comp[2:])
            return ver >= target
        elif comp.startswith('<='):
            target = parse_version(comp[2:])
            return ver <= target
        elif comp.startswith('>'):
            target = parse_version(comp[1:])
            return ver > target
        elif comp.startswith('<'):
            target = parse_version(comp[1:])
            return ver < target
        elif comp.startswith('='):
            target = parse_version(comp[1:])
            return ver == target
        elif comp.startswith('~'):
            target = parse_version(comp[1:])
            return ver >= target and (target[0], target[1], ver[2])  # wrong
            # >= target and < target with minor+1, patch=0
            upper = (target[0], target[1] + 1, 0)
            return ver >= target and ver < upper
        elif comp.startswith('^'):
            target = parse_version(comp[1:])
            if target[0] != 0:
                upper = (target[0] + 1, 0, 0)
            elif target[1] != 0:
                upper = (0, target[1] + 1, 0)
            else:
                upper = (0, 0, target[2] + 1)
            return ver >= target and ver < upper
        else:
            target = parse_version(comp)
            return ver == target

    ver = parse_version(version)
    alternatives = range_.split('||')
    for alt in alternatives:
        comparators = alt.split()
        if all(check_comparator(ver, c) for c in comparators):
            return True
    return False
```

The function parses the version into a tuple of ints and evaluates each alternative (separated by `||`) against its comparators. For `~` ranges, the upper bound increments the minor version; for `^` ranges, it depends on whether major/minor are zero per the spec.

