def build_order(deps: dict[str, list[str]]) -> list[str]:
    # Collect all targets
    all_targets = set(deps.keys())
    for target_list in deps.values():
        for t in target_list:
            all_targets.add(t)

    # Build adjacency and in-degree
    # For each target, we need its dependencies to be processed first
    # So edge goes from dependency -> target (dependency must come before target)
    children = {t: [] for t in all_targets}
    in_degree = {t: 0 for t in all_targets}

    for target, dep_list in deps.items():
        for dep in dep_list:
            children[dep].append(target)
            in_degree[target] += 1

    # Kahn's algorithm with alphabetical tie-breaking
    import heapq
    heap = []
    for t in all_targets:
        if in_degree[t] == 0:
            heapq.heappush(heap, t)

    result = []
    while heap:
        current = heapq.heappop(heap)
        result.append(current)
        for child in children[current]:
            in_degree[child] -= 1
            if in_degree[child] == 0:
                heapq.heappush(heap, child)

    if len(result) != len(all_targets):
        raise ValueError("Cycle detected in dependencies")

    return result
```

This uses Kahn's algorithm with a min-heap to ensure deterministic alphabetical ordering at each step. Targets with no unresolved dependencies are added to the heap, and we always pick the alphabetically smallest one next. If not all targets are processed, a cycle exists and we raise `ValueError`.

