function applyPatch(doc, ops) {
    function parsePath(path) {
        if (path === "") return [];
        if (path[0] !== "/") throw new Error("Invalid path");
        const segments = path.slice(1).split("/");
        return segments.map(s => s.replace(/~1/g, '/').replace(/~0/g, '~'));
    }

    function deepClone(obj) {
        if (obj === null || typeof obj !== 'object') return obj;
        if (Array.isArray(obj)) return obj.map(deepClone);
        const clone = {};
        for (const key of Object.keys(obj)) {
            clone[key] = deepClone(obj[key]);
        }
        return clone;
    }

    let current = deepClone(doc);

    for (const opObj of ops) {
        const { op, path, value } = opObj;
        const segments = parsePath(path);

        if (op === "add") {
            if (segments.length === 0) {
                current = value;
                continue;
            }
            let parent = current;
            for (let i = 0; i < segments.length - 1; i++) {
                const seg = segments[i];
                if (parent === null || typeof parent !== 'object') {
                    throw new Error("Parent does not exist");
                }
                if (Array.isArray(parent)) {
                    const idx = parseInt(seg, 10);
                    if (isNaN(idx) || idx < 0 || idx >= parent.length) {
                        throw new Error("Array index out of range");
                    }
                    parent = parent[idx];
                } else {
                    if (!(seg in parent)) {
                        throw new Error("Parent does not exist");
                    }
                    parent = parent[seg];
                }
            }
            const lastSeg = segments[segments.length - 1];
            if (Array.isArray(parent)) {
                let idx;
                if (lastSeg === "-") {
                    idx = parent.length;
                } else {
                    idx = parseInt(lastSeg, 10);
                    if (isNaN(idx) || idx < 0 || idx > parent.length) {
                        throw new Error("Array index out of range");
                    }
                }
                parent.splice(idx, 0, value);
            } else {
                parent[lastSeg] = value;
            }
        } else if (op === "remove") {
            if (segments.length === 0) {
                throw new Error("Cannot remove whole document");
            }
            let parent = current;
            for (let i = 0; i < segments.length - 1; i++) {
                const seg = segments[i];
                if (parent === null || typeof parent !== 'object') {
                    throw new Error("Parent does not exist");
                }
                if (Array.isArray(parent)) {
                    const idx = parseInt(seg, 10);
                    if (isNaN(idx) || idx < 0 || idx >= parent.length) {
                        throw new Error("Array index out of range");
                    }
                    parent = parent[idx];
                } else {
                    if (!(seg in parent)) {
                        throw new Error("Target does not exist");
                    }
                    parent = parent[seg];
                }
            }
            const lastSeg = segments[segments.length - 1];
            if (Array.isArray(parent)) {
                const idx = parseInt(lastSeg, 10);
                if (isNaN(idx) || idx < 0 || idx >= parent.length) {
                    throw new Error("Array index out of range");
                }
                parent.splice(idx, 1);
            } else {
                if (!(lastSeg in parent)) {
                    throw new Error("Target does not exist");
                }
                delete parent[lastSeg];
            }
        } else if (op === "replace") {
            if (segments.length === 0) {
                current = value;
                continue;
            }
            let parent = current;
            for (let i = 0; i < segments.length - 1; i++) {
                const seg = segments[i];
                if (parent === null || typeof parent !== 'object') {
                    throw new Error("Parent does not exist");
                }
                if (Array.isArray(parent)) {
                    const idx = parseInt(seg, 10);
                    if (isNaN(idx) || idx < 0 || idx >= parent.length) {
                        throw new Error("Array index out of range");
                    }
                    parent = parent[idx];
                } else {
                    if (!(seg in parent)) {
                        throw new Error("Target does not exist");
                    }
                    parent = parent[seg];
                }
            }
            const lastSeg = segments[segments.length - 1];
            if (Array.isArray(parent)) {
                const idx = parseInt(lastSeg, 10);
                if (isNaN(idx) || idx < 0 || idx >= parent.length) {
                    throw new Error("Array index out of range");
                }
                parent[idx] = value;
            } else {
                if (!(lastSeg in parent)) {
                    throw new Error("Target does not exist");
                }
                parent[lastSeg] = value;
            }
        } else {
            throw new Error("Unknown op: " + op);
        }
    }

    return current;
}
```

This implements a JSON Patch-like operation engine for Node.js config documents. Key design decisions:

- **Deep clone** the input document upfront so the original is never mutated.
- **Path parsing** handles `~0` → `~` and `~1` → `/` per RFC 6901 conventions, with `""` meaning the root.
- **Three operations**: `add` inserts into arrays or sets object properties; `remove` deletes array elements or object members; `replace` updates existing values.
- **Validation**: throws `Error` for unknown ops, missing parents/targets, and out-of-range array indices (including allowing `idx === length` for `add` but not for `remove`/`replace`).
- The `-` segment for arrays is treated as append (`array.length`).

