def normalise_order(raw: dict) -> dict:
    # SKU
    try:
        sku = raw["sku"]
    except KeyError:
        raise ValueError("missing sku")
    if not isinstance(sku, str):
        raise ValueError("sku must be a string")
    sku = sku.strip().upper()
    if not sku:
        raise ValueError("sku is empty after stripping")

    # Qty
    try:
        qty_raw = raw["qty"]
    except KeyError:
        raise ValueError("missing qty")
    try:
        qty = int(str(qty_raw).strip())
    except (ValueError, TypeError):
        raise ValueError("qty is not a valid integer")
    if qty < 1 or qty > 99:
        raise ValueError("qty must be between 1 and 99")

    # Unit price
    try:
        unit_price_pence_raw = raw["unit_price_pence"]
    except KeyError:
        raise ValueError("missing unit_price_pence")
    try:
        unit_price_pence = int(unit_price_pence_raw)
    except (ValueError, TypeError):
        raise ValueError("unit_price_pence is not a valid integer")
    if unit_price_pence < 0:
        raise ValueError("unit_price_pence must be >= 0")

    # Currency
    currency_raw = raw.get("currency")
    if currency_raw is None or (isinstance(currency_raw, str) and not currency_raw.strip()):
        currency = "GBP"
    else:
        if not isinstance(currency_raw, str):
            raise ValueError("currency must be a string")
        currency = currency_raw.strip().upper()
    if currency not in ("GBP", "EUR", "USD"):
        raise ValueError("currency must be GBP, EUR, or USD")

    return {
        "sku": sku,
        "qty": qty,
        "unit_price_pence": unit_price_pence,
        "currency": currency,
        "total_pence": qty * unit_price_pence,
    }
