```python
class TTLCache:
    def __init__(self, capacity: int, ttl: int):
        self.capacity = capacity
        self.ttl = ttl
        self._data = {}  # key -> (value, expiry)
        self._order = []  # keys in LRU order (oldest first)

    def put(self, key, value, now: int) -> None:
        if key in self._data:
            # Update existing entry; move to most recently used
            idx = self._order.index(key)
            self._order.pop(idx)
        else:
            # New key: evict expired entries first
            if len(self._data) >= self.capacity:
                self._order = [k for k in self._order if now < self._data[k][1]]
                self._data = {k: self._data[k] for k in self._order}
                if len(self._data) >= self.capacity:
                    # Remove LRU (first in order)
                    lru = self._order.pop(0)
                    del self._data[lru]
        self._data[key] = (value, now + self.ttl)
        self._order.append(key)

    def get(self, key, now: int):
        if key not in self._data:
            return None
        value, expiry = self._data[key]
        if now >= expiry:
            del self._data[key]
            self._order.remove(key)
            return None
        # Move to most recently used
        self._order.remove(key)
        self._order.append(key)
        return value

    def size(self, now: int) -> int:
        expired = [k for k in self._data if now >= self._data[k][1]]
        for k in expired:
            del self._data[k]
            self._order.remove(k)
        return len(self._data)
```

Explanation: The cache uses a dict for O(1) lookups and a list to track LRU order. On `put` of a new key when full, expired entries are pruned first; only if still full is the LRU entry removed. `get` returns `None` for missing/expired keys and updates recency without changing expiry. `size` also prunes expired entries before counting.

