def satisfies(version: str, range_: str) -> bool:
    def parse_version(v: str):
        parts = v.strip().split('.')
        return tuple(int(p) for p in parts)

    def check_comparator(ver, comp):
        comp = comp.strip()
        if not comp:
            return True

        if comp.startswith('~'):
            target = parse_version(comp[1:])
            major, minor, patch = target
            return ver >= target and ver < (major, minor + 1, 0)

        if comp.startswith('^'):
            target = parse_version(comp[1:])
            major, minor, patch = target
            if major != 0:
                return ver >= target and ver < (major + 1, 0, 0)
            elif minor != 0:
                return ver >= target and ver < (0, minor + 1, 0)
            else:
                return ver >= target and ver < (0, 0, patch + 1)

        if comp.startswith('>='):
            return ver >= parse_version(comp[2:])
        if comp.startswith('<='):
            return ver <= parse_version(comp[2:])
        if comp.startswith('>') and not comp.startswith('>='):
            return ver > parse_version(comp[1:])
        if comp.startswith('<') and not comp.startswith('<='):
            return ver < parse_version(comp[1:])
        if comp.startswith('='):
            return ver == parse_version(comp[1:])

        # bare version = exact match
        return ver == parse_version(comp)

    ver = parse_version(version)
    alternatives = range_.split('||')

    for alt in alternatives:
        comparators = alt.strip().split()
        if all(check_comparator(ver, c) for c in comparators):
            return True

    return False
```

This function parses the version into a tuple of integers and evaluates each alternative (separated by `||`). For each alternative, it checks all comparators (separated by spaces), returning `True` if any alternative is fully satisfied. The tilde (`~`) and caret (`^`) operators follow semver-compatible rules with special handling for zero major/minor versions.

