def build_order(deps: dict[str, list[str]]) -> list[str]:
    # Collect all targets
    all_targets = set(deps.keys())
    for target_deps in deps.values():
        for d in target_deps:
            all_targets.add(d)

    # Build adjacency and in-degree
    # For each target, we need its dependencies to be processed first
    children = {t: [] for t in all_targets}  # dependency -> list of targets that depend on it
    in_degree = {t: 0 for t in all_targets}

    for target, target_deps in deps.items():
        for d in target_deps:
            children[d].append(target)
            in_degree[target] += 1

    # Kahn's algorithm with alphabetical tie-breaking
    import heapq
    queue = []
    for t in all_targets:
        if in_degree[t] == 0:
            heapq.heappush(queue, t)

    result = []
    while queue:
        current = heapq.heappop(queue)
        result.append(current)
        for child in children[current]:
            in_degree[child] -= 1
            if in_degree[child] == 0:
                heapq.heappush(queue, child)

    if len(result) != len(all_targets):
        raise ValueError("Dependency cycle detected")

    return result
```

This uses Kahn's algorithm with a min-heap to ensure deterministic alphabetical ordering. All targets appearing in dependency lists are included as nodes with no explicit dependencies (in-degree from `deps` entries only). A cycle is detected when not all targets are processed.

