from datetime import date
import re


def parse_date(text: str) -> date:
    """Parse an invoice date from ISO, British numeric, or short text formats."""
    text = text.strip()

    # ISO: YYYY-MM-DD
    iso_match = re.fullmatch(r'(\d{4})-(\d{2})-(\d{2})', text)
    if iso_match:
        return date(int(iso_match.group(1)), int(iso_match.group(2)), int(iso_match.group(3)))

    # British numeric: DD/MM/YYYY
    british_match = re.fullmatch(r'(\d{2})/(\d{2})/(\d{4})', text)
    if british_match:
        return date(int(british_match.group(3)), int(british_match.group(2)), int(british_match.group(1)))

    # Short text: D MM YYYY or DD MM YYYY (e.g. "7 Mar 2025" or "07 Mar 2025")
    month_map = {
        'jan': 1, 'feb': 2, 'mar': 3, 'apr': 4, 'may': 5, 'jun': 6,
        'jul': 7, 'aug': 8, 'sep': 9, 'oct': 10, 'nov': 11, 'dec': 12
    }
    short_match = re.fullmatch(r'(\d{1,2})\s+([A-Za-z]{3})\s+(\d{4})', text)
    if short_match:
        day = int(short_match.group(1))
        month_str = short_match.group(2).lower()
        year = int(short_match.group(3))
        if month_str not in month_map:
            raise ValueError(f"Invalid month: {short_match.group(2)}")
        return date(year, month_map[month_str], day)

    raise ValueError(f"Unable to parse date: {text!r}")
```

