function parseQuery(qs) {
  if (typeof qs !== 'string') return {};
  if (qs[0] === '?') qs = qs.slice(1);
  if (!qs) return {};

  const result = {};

  const pairs = qs.split('&');

  for (const pair of pairs) {
    if (pair === '') continue;

    const eqIndex = pair.indexOf('=');

    let key, value;

    if (eqIndex === -1) {
      key = pair;
      value = '';
    } else {
      key = pair.slice(0, eqIndex);
      value = pair.slice(eqIndex + 1);
    }

    // Decode + as space first
    key = key.replace(/\+/g, ' ');
    value = value.replace(/\+/g, ' ');

    // Then percent-decode
    key = decodeURIComponent(key);
    value = decodeURIComponent(value);

    if (key in result) {
      const existing = result[key];
      if (Array.isArray(existing)) {
        existing.push(value);
      } else {
        result[key] = [existing, value];
      }
    } else {
      result[key] = value;
    }
  }

  return result;
}
```

This function parses a query string into a plain object. It handles the leading `?`, splits on `&`, respects the first `=` as the key/value separator, decodes `+` as space and percent-encodes, and converts duplicate keys into arrays while keeping single occurrences as strings.

