function deepMerge(base, override) {
  const result = {};

  for (const key of Object.keys(base)) {
    result[key] = base[key];
  }

  for (const key of Object.keys(override)) {
    if (override[key] === undefined) {
      continue;
    }
    const baseVal = base[key];
    const overrideVal = override[key];
    if (
      baseVal !== null &&
      typeof baseVal === "object" &&
      !Array.isArray(baseVal) &&
      overrideVal !== null &&
      typeof overrideVal === "object" &&
      !Array.isArray(overrideVal)
    ) {
      result[key] = deepMerge(baseVal, overrideVal);
    } else {
      result[key] = overrideVal;
    }
  }

  return result;
}
```

This function creates a new object by first copying all keys from `base`, then applying keys from `override`. Keys with `undefined` in `override` are skipped (keeping the base value). For keys where both values are plain objects (not arrays, not null), it recurses to merge them. Otherwise, the override value replaces the base value. The result shares no references with either input.

