#include <string>
#include <cctype>
#include <cstdint>

long long parse_duration(const std::string& s) {
    if (s.empty()) return -1;

    int state = 0; // 0: start, 1: after h, 2: after m, 3: after s
    long long total = 0;
    long long current = 0;
    bool has_number = false;

    for (size_t i = 0; i < s.size(); ++i) {
        char c = s[i];

        if (std::isdigit(static_cast<unsigned char>(c))) {
            if (state == 0) {
                current = current * 10 + (c - '0');
                has_number = true;
            } else if (state == 1 || state == 2) {
                current = current * 10 + (c - '0');
                has_number = true;
            } else {
                return -1; // digit after 's'
            }
        } else if (c == 'h') {
            if (state == 0 && has_number) {
                total += current * 3600;
                state = 1;
                current = 0;
                has_number = false;
            } else {
                return -1;
            }
        } else if (c == 'm') {
            if (state == 1 && has_number) {
                total += current * 60;
                state = 2;
                current = 0;
                has_number = false;
            } else {
                return -1;
            }
        } else if (c == 's') {
            if (state == 2 && has_number) {
                total += current;
                state = 3;
                current = 0;
                has_number = false;
            } else if (state == 3 && has_number) {
                total += current;
                state = 3;
                current = 0;
                has_number = false;
            } else {
                return -1;
            }
        } else {
            return -1; // unknown char
        }
    }

    // At end, must have consumed a number (for the last unit or standalone)
    if (state == 0 && has_number) {
        total += current;
        state = 4; // treated as seconds
    }

    // Valid end states: 1 (h only), 2 (m only after h), 3 (s only or after m), 4 (standalone number)
    if (state == 1 || state == 2 || state == 3 || state == 4) {
        return total;
    }

    return -1;
}
```

This function parses duration strings like `1h30m`, `45s`, `2h`, or `1h0m5s` by tracking state transitions through the expected unit order (h → m → s). Each numeric segment must immediately precede a valid unit. Invalid inputs (wrong order, repeated units, spaces, signs, empty strings, or trailing digits without a unit) return `-1`.

