from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity: int, ttl: int):
        self.capacity = capacity
        self.ttl = ttl
        self.cache: OrderedDict = OrderedDict()

    def put(self, key, value, now: int) -> None:
        expiry = now + self.ttl
        if key in self.cache:
            self.cache[key] = (value, expiry)
            self.cache.move_to_end(key)
        else:
            if len(self.cache) >= self.capacity:
                self._evict(now)
            self.cache[key] = (value, expiry)

    def get(self, key, now: int):
        if key not in self.cache:
            return None
        value, expiry = self.cache[key]
        if now >= expiry:
            del self.cache[key]
            return None
        self.cache.move_to_end(key)
        return value

    def size(self, now: int) -> int:
        count = 0
        for key in list(self.cache):
            _, expiry = self.cache[key]
            if now < expiry:
                count += 1
            else:
                del self.cache[key]
        return count

    def _evict(self, now: int):
        if not self.cache:
            return
        self.cache.popitem(last=False)
```

Short explanation: The cache uses an `OrderedDict` to track insertion order (most recently used at the end). `put` updates or inserts entries with expiry `now + ttl`, evicting expired entries first then the LRU entry if needed. `get` returns `None` for missing or expired keys and moves accessed keys to the end. `size` counts non-expired entries, pruning expired ones as a side effect. All operations rely only on the standard library.

```python
def satisfies(version: str, range_: str) -> bool:
    """Check if a version satisfies a range of version constraints."""
    parts = [p.strip() for p in range_.split('||') if p.strip()]
    return any(_check_alternative(version, alt.strip()) for alt in parts)


def _check_alternative(version: str, alt: str) -> bool:
    comparators = alt.split()
    return all(_check_comparator(version, comp) for comp in comparators)


def _check_comparator(version: str, comp: str) -> bool:
    if comp.startswith('~'):
        return _check_tilde(version, comp[1:])
    if comp.startswith('^'):
        return _check_caret(version, comp[1:])
    if comp.startswith('>='):
        return _compare(version, comp[2:]) >= 0
    if comp.startswith('<='):
        return _compare(version, comp[2:]) <= 0
    if comp.startswith('>'):
        return _compare(version, comp[1:]) > 0
    if comp.startswith('<'):
        return _compare(version, comp[1:]) < 0
    return _compare(version, comp) == 0


def _compare(version: str, target: str) -> int:
    v = tuple(int(x) for x in version.split('.'))
    t = tuple(int(x) for x in target.split('.'))
    return (v > t) - (v < t)


def _check_tilde(version: str, target: str) -> bool:
    v = tuple(int(x) for x in version.split('.'))
    t = tuple(int(x) for x in target.split('.'))
    if len(t) < 2:
        t += (0, 0)
    if len(t) < 3:
        t += (0,)
    lower = (t[0], t[1], t[2])
    upper = (t[0], t[1] + 1, 0)
    return lower <= v < upper


def _check_caret(version: str, target: str) -> bool:
    v = tuple(int(x) for x in version.split('.'))
    t = tuple(int(x) for x in target.split('.'))
    if len(t) < 2:
        t += (0, 0)
    if len(t) < 3:
        t += (0,)
    lower = (t[0], t[1], t[2])
    if t[0] == 0:
        if t[1] == 0:
            upper = (0, 0, t[2] + 1)
        else:
            upper = (0, t[1] + 1, 0)
    else:
        upper = (t[0] + 1, 0, 0)
    return lower <= v < upper
```

This implementation parses the range by splitting on `||` for alternatives, then splitting each alternative on spaces for comparators. Each comparator is checked individually, and a version satisfies an alternative only if it satisfies all comparators in it. The caret (`^`) and tilde (`~`) operators are handled with the same semantics as npm semver: tilde allows patch-level changes on the last specified segment, and caret allows changes that don't modify the leftmost non-zero digit (with special handling for leading zeros).

