    dependencies = {t: set() for t in all_targets}
    for target, dep_list in deps.items():
        for dep in dep_list:
            dependents[dep].add(target)
            dependencies[target].add(dep)

    # Kahn's algorithm with sorted priority queue for determinism
    in_degree = {t: len(dependencies[t]) for t in all_targets}
    result = []
    import heapq
    ready = sorted([t for t in all_targets if in_degree[t] == 0])
    heapq.heapify(ready)

    while ready:
        target = heapq.heappop(ready)
        result.append(target)
        for dependent in dependents[target]:
            in_degree[dependent] -= 1
            if in_degree[dependent] == 0:
                heapq.heappush(ready, dependent)

    if len(result) != len(all_targets):
        raise ValueError("Cycle detected in dependencies")

    return result
```

This uses Kahn's algorithm with a min-heap to ensure deterministic topological ordering (alphabetically smallest available target at each step). All targets appearing in dependency lists are included even if they have no explicit entry in `deps`. A cycle is detected when the output list doesn't contain all targets.

```javascript
function applyPatch(doc, ops) {
  // Deep clone the document to avoid modifying the original
  const newDoc = clone(doc);
  let current = newDoc;

  for (const op of ops) {
    const { op: operation, path, value } = op;

    if (operation !== 'add' && operation !== 'remove' && operation !== 'replace') {
      throw new Error(`Unknown op: ${operation}`);
    }

    if (path === '') {
      // Apply to the whole document
      if (operation === 'add') {
        current = value;
      } else if (operation === 'remove') {
        throw new Error('Cannot remove the entire document');
      } else if (operation === 'replace') {
        current = value;
      }
      continue;
    }

    // Parse the path: starts with '/', then segments
    const segments = path.slice(1).split('/').map(decodeSegment);

    // Navigate to the parent
    let parent = current;
    let parentPath = '';
    let i = 0;

    for (i = 0; i < segments.length - 1; i++) {
      const segment = segments[i];
      parentPath += '/' + encodeSegment(segment);

      if (Array.isArray(parent)) {
        const index = parseInt(segment, 10);
        if (segment !== String(index) || index < 0 || index >= parent.length) {
          throw new Error(`Array index out of range at path ${parentPath}`);
        }
        if (index >= parent.length) {
          throw new Error(`Parent array element does not exist at path ${parentPath}`);
        }
        parent = parent[index];
      } else if (typeof parent === 'object' && parent !== null) {
        if (!(segment in parent)) {
          throw new Error(`Parent does not exist at path ${parentPath}`);
        }
        parent = parent[segment];
      } else {
        throw new Error(`Cannot navigate into non-object/array at path ${parentPath}`);
      }
    }

    // Now parent is the target parent, and segments[segments.length - 1] is the key/index
    const targetSegment = segments[segments.length - 1];

    if (Array.isArray(parent)) {
      const index = parseInt(targetSegment, 10);
      if (targetSegment !== String(index)) {
        throw new Error(`Array index must be a non-negative whole number at path ${parentPath}/${targetSegment}`);
      }

      if (index === -1) {
        // "-" means append
        if (operation === 'add') {
          parent.push(value);
        } else if (operation === 'remove') {
          parent.splice(index, 1);
        } else if (operation === 'replace') {
          parent[index] = value;
        }
      } else if (index <= parent.length) {
        // Valid index for add (can be equal to length for append)
        if (operation === 'add') {
          parent.splice(index, 0, value);
        } else if (operation === 'remove') {
          if (index >= parent.length) {
            throw new Error(`Array element does not exist at path ${parentPath}/${targetSegment}`);
          }
          parent.splice(index, 1);
        } else if (operation === 'replace') {
          if (index >= parent.length) {
            throw new Error(`Array element does not exist at path ${parentPath}/${targetSegment}`);
          }
          parent[index] = value;
        }
      } else {
        throw new Error(`Array index out of range at path ${parentPath}/${targetSegment}`);
      }
    } else if (typeof parent === 'object' && parent !== null) {
      if (operation === 'add') {
        parent[targetSegment] = value;
      } else if (operation === 'remove') {
        if (!(targetSegment in parent)) {
          throw new Error(`Object member does not exist at path ${parentPath}/${targetSegment}`);
        }
        delete parent[targetSegment];
      } else if (operation === 'replace') {
        if (!(targetSegment in parent)) {
          throw new Error(`Object member does not exist at path ${parentPath}/${targetSegment}`);
        }
        parent[targetSegment] = value;
      }
    } else {
      throw new Error(`Cannot apply operation to non-object/array at path ${parentPath}`);
    }

    // Update current for next iteration (for path "")
    if (path === '') {
      current = newDoc;
    }
  }

  return newDoc;
}

function encodeSegment(segment) {
  return segment.replace(/~/g, '~0').replace(/\//g, '~1');
}

function decodeSegment(segment) {
  return segment.replace(/~1/g, '/').replace(/~0/g, '~');
}

function clone(obj) {
  if (obj === null || typeof obj !== 'object') {
    return obj;
  }
  if (Array.isArray(obj)) {
    return obj.map(clone);
  }
  const result = {};
  for (const key of Object.keys(obj)) {
    result[key] = clone(obj[key]);
  }
  return result;
}
```

This function implements RFC 6902 JSON Patch semantics:

- **`applyPatch`** deep-clones the document, then iterates through each operation, navigating the path and applying the operation (`add`, `remove`, `replace`) in order.
- **Path parsing** handles JSON Pointer encoding (`~0` → `~`, `~1` → `/`) and array indices.
- **`add`** on arrays uses `splice(index, 0, value)` for insertion at position `index`, or `push(value)` for `"-"` (append).
- **`remove`** uses `splice(index, 1)` for arrays or `delete` for object members.
- **`replace`** directly assigns the new value.
- All invalid cases (unknown op, missing parent, missing target, out-of-range index) throw an `Error`.
- The original `doc` is never mutated since we start with a deep clone.

