from datetime import date
from typing import Optional


def parse_date(text: str) -> date:
    """Parse a date string in one of three supported formats.

    Supported formats:
        - ISO: ``2025-03-07``
        - British numeric: ``07/03/2025`` (day/month/year)
        - Short text: ``7 Mar 2025`` (English three-letter month;
          day may have a leading zero)

    Raises ``ValueError`` for any unsupported or invalid input.
    """
    text = text.strip()

    # Try ISO format first: YYYY-MM-DD
    try:
        return date.fromisoformat(text)
    except ValueError:
        pass

    # Try British numeric format: DD/MM/YYYY
    try:
        parts = text.split("/")
        if len(parts) == 3 and all(len(p) == 2 for p in parts):
            day, month, year = int(parts[0]), int(parts[1]), int(parts[2])
            return date(year, month, day)
    except ValueError:
        pass

    # Try short text format: D MMM YYYY or DD MMM YYYY
    try:
        parts = text.split()
        if len(parts) == 3:
            day = int(parts[0])
            month_str = parts[1]
            year = int(parts[2])
            # Validate month abbreviation
            months = {
                "Jan": 1, "Feb": 2, "Mar": 3, "Apr": 4,
                "May": 5, "Jun": 6, "Jul": 7, "Aug": 8,
                "Sep": 9, "Oct": 10, "Nov": 11, "Dec": 12
            }
            if month_str not in months:
                raise ValueError("Invalid month abbreviation")
            month = months[month_str]
            return date(year, month, day)
    except ValueError:
        pass

    raise ValueError(f"Unable to parse date: {text!r}")
```

