```javascript
function deepMerge(base, override) {
  if (base === null || base === undefined) {
    return isPlainObject(override) ? deepMerge({}, override) : shallowClone(override);
  }
  if (override === null || override === undefined) {
    return shallowClone(base);
  }
  if (!isPlainObject(base) || !isPlainObject(override)) {
    return shallowClone(override);
  }
  const result = {};
  for (const key of Object.keys(base)) {
    result[key] = deepMerge(base[key], override[key]);
  }
  for (const key of Object.keys(override)) {
    if (override[key] !== undefined) {
      result[key] = deepMerge(base[key], override[key]);
    }
  }
  return result;
}

function isPlainObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function shallowClone(value) {
  if (value === null || value === undefined) {
    return value;
  }
  if (Array.isArray(value)) {
    return value.map(shallowClone);
  }
  if (typeof value === 'object') {
    const result = {};
    for (const key of Object.keys(value)) {
      result[key] = shallowClone(value[key]);
    }
    return result;
  }
  return value;
}
```

This function recursively merges two configuration objects. It creates a completely new object with no shared references to the inputs. Arrays are replaced entirely (not concatenated), `undefined` values in the override are ignored (preserving the base value), while `null` values do replace. Keys present only in `base` are preserved in the result.

