#include <string>
#include <cstdint>

long long parse_duration(const std::string& s) {
    if (s.empty()) return -1;

    long long total = 0;
    size_t i = 0;
    int seen_h = 0, seen_m = 0, seen_s = 0;

    while (i < s.size()) {
        // Read a whole number (digits only)
        size_t start = i;
        if (i == s.size() || !std::isdigit(static_cast<unsigned char>(s[i]))) {
            return -1;  // no number before a unit or trailing unit
        }
        while (i < s.size() && std::isdigit(static_cast<unsigned char>(s[i]))) {
            i++;
        }
        long long num = std::stoll(s.substr(start, i - start));

        // Read the unit
        if (i == s.size()) return -1;  // number without unit
        char unit = s[i];
        if (unit != 'h' && unit != 'm' && unit != 's') return -1;

        // Check order and repetition
        switch (unit) {
            case 'h':
                if (seen_h || seen_m || seen_s) return -1;
                seen_h = 1;
                break;
            case 'm':
                if (seen_m || seen_s) return -1;
                seen_m = 1;
                break;
            case 's':
                if (seen_s) return -1;
                seen_s = 1;
                break;
        }

        switch (unit) {
            case 'h': total += num * 3600; break;
            case 'm': total += num * 60;   break;
            case 's': total += num;         break;
        }
        i++;
    }

    return total;
}
