import time
from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity: int, ttl: int):
        self.capacity = capacity
        self.ttl = ttl
        self.cache = OrderedDict()

    def put(self, key, value, now: int) -> None:
        expiry = now + self.ttl
        if key in self.cache:
            del self.cache[key]
        elif len(self.cache) == self.capacity:
            self._evict(now)
        self.cache[key] = (value, expiry)
        self.cache.move_to_end(key)

    def get(self, key, now: int):
        if key not in self.cache:
            return None
        value, expiry = self.cache[key]
        if now >= expiry:
            del self.cache[key]
            return None
        self.cache.move_to_end(key)
        return value

    def size(self, now: int) -> int:
        return sum(1 for _, (value, expiry) in self.cache.items() if now < expiry)

    def _evict(self, now: int):
        while self.cache:
            key, (value, expiry) = next(iter(self.cache.items()))
            if now < expiry:
                return
            del self.cache[key]
```

The class uses an `OrderedDict` to track usage order. `put` evicts expired entries first, then the least-recently-used if still full. `get` checks expiration, returns `None` if expired, or promotes the key to most-recently-used otherwise. `size` counts non-expired entries.

```python
def satisfies(version: str, range_: str) -> bool:
    """Check if a version satisfies a range of constraints.

    Args:
        version: A version string like "1.2.3"
        range_: A range string like ">=1.0.0 || <2.0.0"

    Returns:
        True if the version satisfies at least one alternative in the range.
    """
    alternatives = range_.split('||')
    for alt in alternatives:
        if _check_alternative(version, alt):
            return True
    return False


def _check_alternative(version: str, alt: str) -> bool:
    """Check if a version satisfies all comparators in an alternative."""
    comparators = alt.strip().split()
    return all(_check_comparator(version, comp) for comp in comparators)


def _check_comparator(version: str, comp: str) -> bool:
    """Check if a version satisfies a single comparator."""
    comp = comp.strip()
    if not comp:
        return True

    # Parse operator and version
    if comp.startswith('>='):
        op, ver = '>=', comp[2:]
    elif comp.startswith('<='):
        op, ver = '<=', comp[2:]
    elif comp.startswith('>'):
        op, ver = '>', comp[1:]
    elif comp.startswith('<'):
        op, ver = '<', comp[1:]
    elif comp.startswith('='):
        op, ver = '=', comp[1:]
    elif comp.startswith('~'):
        op, ver = '~', comp[1:]
    elif comp.startswith('^'):
        op, ver = '^', comp[1:]
    else:
        op, ver = '=', comp

    v_parts = _parse_version(version)
    r_parts = _parse_version(ver)

    if op == '=':
        return v_parts == r_parts
    elif op == '>':
        return v_parts > r_parts
    elif op == '>=':
        return v_parts >= r_parts
    elif op == '<':
        return v_parts < r_parts
    elif op == '<=':
        return v_parts <= r_parts
    elif op == '~':
        # >=1.2.3 and <1.3.0
        if v_parts < r_parts:
            return False
        upper = list(r_parts)
        upper[1] = upper[1] + 1
        upper[2] = 0
        return v_parts < tuple(upper)
    elif op == '^':
        # >=1.2.3 and <2.0.0
        if v_parts < r_parts:
            return False
        upper = list(r_parts)
        if upper[0] == 0:
            if upper[1] == 0:
                # ^0.0.3: >=0.0.3 and <0.0.4
                upper[2] = upper[2] + 1
            else:
                # ^0.2.3: >=0.2.3 and <0.3.0
                upper[1] = upper[1] + 1
                upper[2] = 0
        else:
            # ^1.2.3: >=1.2.3 and <2.0.0
            upper[0] = upper[0] + 1
            upper[1] = 0
            upper[2] = 0
        return v_parts < tuple(upper)
    return False


def _parse_version(version: str) -> tuple:
    """Parse a version string into a tuple of integers."""
    return tuple(int(x) for x in version.split('.'))
```

This implementation handles all the specified comparator types (`=`, `>`, `>=`, `<`, `<=`, `~`, `^`) and supports multiple alternatives separated by `||`. The `^` operator follows the caret versioning semantics where `^0.0.x` constrains the patch only, `^0.x.y` constrains the minor and patch, and `^x.y.z` constrains only the major version.

