def build_order(deps: dict[str, list[str]]) -> list[str]:
    # Collect all targets
    all_targets = set(deps.keys())
    for target_list in deps.values():
        for dep in target_list:
            all_targets.add(dep)

    # Build adjacency: target -> set of dependencies
    dependencies = {target: set() for target in all_targets}
    for target, target_deps in deps.items():
        dependencies[target] = set(target_deps)

    # Kahn's algorithm with deterministic ordering
    import heapq

    # Compute in-degree (number of dependencies each target has)
    in_degree = {target: len(dependencies[target]) for target in all_targets}

    # Min-heap for deterministic order
    heap = []
    for target in all_targets:
        if in_degree[target] == 0:
            heapq.heappush(heap, target)

    result = []
    while heap:
        current = heapq.heappop(heap)
        result.append(current)

        # Find all targets that depend on 'current' and reduce their in-degree
        for target in all_targets:
            if current in dependencies[target]:
                in_degree[target] -= 1
                if in_degree[target] == 0:
                    heapq.heappush(heap, target)

    if len(result) != len(all_targets):
        raise ValueError("Cycle detected in dependencies")

    return result
```

This implements Kahn's topological sort algorithm with a min-heap to ensure deterministic alphabetical ordering at each step. It collects all targets (including those only appearing as dependencies), computes in-degrees, and processes nodes with zero remaining dependencies in alphabetical order. If not all nodes are processed, a cycle exists and a `ValueError` is raised.

