  for (const op of ops) {
    const { op: operation, path, value } = op;
    if (operation !== 'add' && operation !== 'remove' && operation !== 'replace') {
      throw new Error('Unknown operation: ' + operation);
    }
    const segments = path === '' ? [] : parsePath(path);
    if (operation === 'add') {
      if (segments.length === 0) {
        result = value;
      } else {
        const target = resolveTarget(result, segments);
        const last = segments[segments.length - 1];
        if (Array.isArray(target)) {
          const idx = last === '-' ? target.length : parseInt(last, 10);
          if (isNaN(idx) || idx < 0 || idx !== Math.floor(idx)) {
            throw new Error('Invalid array index');
          }
          target.splice(idx, 0, value);
        } else if (typeof target === 'object' && target !== null) {
          target[last] = value;
        } else {
          throw new Error('Cannot add to non-object/non-array');
        }
      }
    } else if (operation === 'remove') {
      if (segments.length === 0) {
        throw new Error('Cannot remove entire document');
      }
      const target = resolveTarget(result, segments);
      const last = segments[segments.length - 1];
      if (Array.isArray(target)) {
        const idx = parseInt(last, 10);
        if (isNaN(idx) || idx < 0 || idx >= target.length || idx !== Math.floor(idx)) {
          throw new Error('Array index out of range');
        }
        target.splice(idx, 1);
      } else if (typeof target === 'object' && target !== null) {
        if (!(last in target)) {
          throw new Error('Target does not exist');
        }
        delete target[last];
      } else {
        throw new Error('Cannot remove from non-object/non-array');
      }
    } else if (operation === 'replace') {
      if (segments.length === 0) {
        result = value;
      } else {
        const target = resolveTarget(result, segments);
        const last = segments[segments.length - 1];
        if (Array.isArray(target)) {
          const idx = parseInt(last, 10);
          if (isNaN(idx) || idx < 0 || idx >= target.length || idx !== Math.floor(idx)) {
            throw new Error('Array index out of range');
          }
          target[idx] = value;
        } else if (typeof target === 'object' && target !== null) {
          if (!(last in target)) {
            throw new Error('Target does not exist');
          }
          target[last] = value;
        } else {
          throw new Error('Cannot replace on non-object/non-array');
        }
      }
    }
  }
  return result;
}

function parsePath(path) {
  const segments = [];
  const parts = path.split('/');
  for (let i = 1; i < parts.length; i++) {
    let segment = parts[i];
    segment = segment.replace(/~1/g, '/').replace(/~0/g, '~');
    segments.push(segment);
  }
  return segments;
}

function resolveTarget(doc, segments) {
  let current = doc;
  for (let i = 0; i < segments.length - 1; i++) {
    if (current === null || current === undefined || typeof current !== 'object') {
      throw new Error('Parent does not exist');
    }
    const key = segments[i];
    if (Array.isArray(current)) {
      const idx = parseInt(key, 10);
      if (isNaN(idx) || idx < 0 || idx >= current.length || idx !== Math.floor(idx)) {
        throw new Error('Array index out of range');
      }
      current = current[idx];
    } else {
      if (!(key in current)) {
        throw new Error('Parent does not exist');
      }
      current = current[key];
    }
  }
  return current;
}
