function parseQuery(qs) {
  if (typeof qs !== 'string' || qs.length === 0) return {};

  const cleaned = qs.startsWith('?') ? qs.slice(1) : qs;
  const pairs = cleaned.split('&');
  const result = {};

  for (let i = 0; i < pairs.length; i++) {
    const pair = pairs[i];
    if (pair.length === 0) continue;

    const eqIndex = pair.indexOf('=');
    let key, value;

    if (eqIndex === -1) {
      key = pair;
      value = '';
    } else {
      key = pair.slice(0, eqIndex);
      value = pair.slice(eqIndex + 1);
    }

    const decodedKey = decodeURIComponent(key.replace(/\+/g, ' '));
    const decodedValue = decodeURIComponent(value.replace(/\+/g, ' '));

    if (decodedKey in result) {
      const existing = result[decodedKey];
      if (Array.isArray(existing)) {
        existing.push(decodedValue);
      } else {
        result[decodedKey] = [existing, decodedValue];
      }
    } else {
      result[decodedKey] = decodedValue;
    }
  }

  return result;
}
```

This function handles all the specified requirements: strips a leading `?`, splits on `&`, splits key/value on the first `=`, decodes `+` as space and percent-decodes both keys and values, assigns `""` to keys without `=`, skips empty pairs, and accumulates duplicate keys into arrays in insertion order.

