#include <string>
#include <stdexcept>

long long parse_duration(const std::string& s) {
    if (s.empty()) return -1;

    long long total = 0;
    size_t pos = 0;
    bool seen_h = false, seen_m = false, seen_s = false;

    while (pos < s.size()) {
        // Check for spaces
        if (s[pos] == ' ') return -1;

        // Parse number
        size_t num_start = pos;
        if (pos < s.size() && (s[pos] == '+' || s[pos] == '-')) return -1;
        if (pos >= s.size() || !std::isdigit(s[pos])) return -1;
        while (pos < s.size() && std::isdigit(s[pos])) ++pos;

        // Check for unit
        if (pos >= s.size()) return -1;
        char unit = s[pos];
        if (unit != 'h' && unit != 'm' && unit != 's') return -1;

        long long value = std::stoll(s.substr(num_start, pos - num_start));

        // Check order and repetition
        if (unit == 'h') {
            if (seen_h || seen_m || seen_s) return -1;
            seen_h = true;
            total += value * 3600;
        } else if (unit == 'm') {
            if (seen_m || seen_s) return -1;
            if (!seen_h) return -1;
            seen_m = true;
            total += value * 60;
        } else if (unit == 's') {
            if (seen_s) return -1;
            if (!seen_h && !seen_m) return -1;
            seen_s = true;
            total += value;
        }

        ++pos;
    }

    return total;
}
```

This function parses duration strings like `1h30m`, `45s`, `1h0m5s` and returns the total seconds. It validates that units appear in the correct order (h → m → s), each at most once, with no spaces, signs, or other invalid characters. Returns `-1` for any malformed input.

