from collections import OrderedDict
from typing import Any, Optional


class TTLCache:
    def __init__(self, capacity: int, ttl: int) -> None:
        self._capacity = capacity
        self._ttl = ttl
        self._cache: OrderedDict[str, tuple] = OrderedDict()

    def put(self, key: str, value: Any, now: int) -> None:
        expiry = now + self._ttl
        if key in self._cache:
            self._cache[key] = (value, expiry)
            self._cache.move_to_end(key)
        else:
            if len(self._cache) >= self._capacity:
                expired_keys = [k for k, (v, e) in self._cache.items() if now >= e]
                if expired_keys:
                    for k in expired_keys:
                        del self._cache[k]
                if len(self._cache) >= self._capacity:
                    self._cache.popitem(last=False)
            self._cache[key] = (value, expiry)

    def get(self, key: str, now: int) -> Optional[Any]:
        if key not in self._cache:
            return None
        value, expiry = self._cache[key]
        if now >= expiry:
            del self._cache[key]
            return None
        self._cache.move_to_end(key)
        return value

    def size(self, now: int) -> int:
        return sum(1 for _, (_, e) in self._cache.items() if now < e)
```

Short explanation: `TTLCache` wraps an `OrderedDict` of `(value, expiry)` pairs. `put` evicts expired entries first, then the LRU entry if still full; `get` returns `None` on expiry or missing key and moves the key to the end on success; `size` counts entries whose expiry hasn't passed.

