function applyPatch(doc, ops) {
  // Deep clone the document to avoid mutation
  const result = JSON.parse(JSON.stringify(doc));

  for (const op of ops) {
    if (!op || typeof op !== 'object') {
      throw new Error('Invalid operation');
    }
    const { op: operation, path, value } = op;
    if (!operation || typeof operation !== 'string') {
      throw new Error('Missing or invalid op');
    }
    if (!['add', 'remove', 'replace'].includes(operation)) {
      throw new Error('Unknown op: ' + operation);
    }

    if (path === '') {
      if (operation === 'add') {
        // Replace the whole document
        Object.assign(result, value);
      } else if (operation === 'remove') {
        // Cannot remove the whole document (it's the root)
        throw new Error('Cannot remove root document');
      } else if (operation === 'replace') {
        Object.assign(result, value);
      }
      continue;
    }

    // Parse the path
    const segments = parsePath(path);
    if (segments.length === 0) {
      throw new Error('Invalid path: empty after parsing');
    }

    // Navigate to the parent
    let parent = result;
    let parentPath = '';
    for (let i = 0; i < segments.length - 1; i++) {
      const key = segments[i];
      parentPath = parentPath ? parentPath + '/' + key : key;
      if (parent === null || parent === undefined || typeof parent !== 'object') {
        throw new Error('Parent does not exist at path: ' + parentPath);
      }
      if (Array.isArray(parent)) {
        const idx = parseInt(key, 10);
        if (isNaN(idx) || idx < 0 || idx >= parent.length) {
          throw new Error('Array index out of range: ' + key + ' for array of length ' + parent.length);
        }
        parent = parent[idx];
      } else {
        if (!(key in parent)) {
          throw new Error('Parent does not exist at path: ' + parentPath);
        }
        parent = parent[key];
      }
    }

    const lastSegment = segments[segments.length - 1];
    const targetPath = parentPath ? parentPath + '/' + lastSegment : lastSegment;

    if (operation === 'add') {
      if (Array.isArray(parent)) {
        if (lastSegment === '-') {
          parent.push(value);
        } else {
          const idx = parseInt(lastSegment, 10);
          if (isNaN(idx) || idx < 0 || idx > parent.length) {
            throw new Error('Array index out of range: ' + lastSegment + ' for array of length ' + parent.length);
          }
          parent.splice(idx, 0, value);
        }
      } else if (typeof parent === 'object' && parent !== null) {
        parent[lastSegment] = value;
      } else {
        throw new Error('Cannot add to non-object/non-array parent at path: ' + targetPath);
      }
    } else if (operation === 'remove') {
      if (Array.isArray(parent)) {
        const idx = parseInt(lastSegment, 10);
        if (isNaN(idx) || idx < 0 || idx >= parent.length) {
          throw new Error('Array index out of range: ' + lastSegment + ' for array of length ' + parent.length);
        }
        parent.splice(idx, 1);
      } else if (typeof parent === 'object' && parent !== null) {
        if (!(lastSegment in parent)) {
          throw new Error('Target does not exist at path: ' + targetPath);
        }
        delete parent[lastSegment];
      } else {
        throw new Error('Cannot remove from non-object/non-array parent at path: ' + targetPath);
      }
    } else if (operation === 'replace') {
      if (Array.isArray(parent)) {
        const idx = parseInt(lastSegment, 10);
        if (isNaN(idx) || idx < 0 || idx >= parent.length) {
          throw new Error('Array index out of range: ' + lastSegment + ' for array of length ' + parent.length);
        }
        parent[idx] = value;
      } else if (typeof parent === 'object' && parent !== null) {
        if (!(lastSegment in parent)) {
          throw new Error('Target does not exist at path: ' + targetPath);
        }
        parent[lastSegment] = value;
      } else {
        throw new Error('Cannot replace in non-object/non-array parent at path: ' + targetPath);
      }
    }
  }

  return result;
}

function parsePath(path) {
  if (path === '') return [];
  if (path[0] !== '/') {
    throw new Error('Path must start with /: ' + path);
  }
  const parts = path.substring(1).split('/');
  return parts.map(part => {
    // Decode JSON Pointer escape sequences
    // ~1 -> /, ~0 -> ~
    return part.replace(/~1/g, '/').replace(/~0/g, '~');
  });
}
```

This function implements a JSON Patch (RFC 6902) engine for Node.js config services. Key design decisions:

- **Immutability**: Uses `JSON.parse(JSON.stringify(doc))` to deep-clone the input document before any mutations.
- **Path parsing**: Handles `~1` → `/` and `~0` → `~` escape sequences per the JSON Pointer spec.
- **Array operations**: `splice` is used for both insert (before index) and remove (delete element). The `-` shorthand appends.
- **Validation**: Throws `Error` for unknown ops, missing parents, out-of-range indices, and missing targets for `remove`/`replace`.
- **Root-level `add`**: Replaces the entire document by merging the value into the cloned root object.

