import re
from datetime import date


def parse_date(text: str) -> date:
    text = text.strip()

    # ISO: YYYY-MM-DD
    iso_match = re.fullmatch(r'(\d{4})-(\d{2})-(\d{2})', text)
    if iso_match:
        y, m, d = int(iso_match.group(1)), int(iso_match.group(2)), int(iso_match.group(3))
        return date(y, m, d)

    # British numeric: DD/MM/YYYY
    brit_match = re.fullmatch(r'(\d{1,2})/(\d{1,2})/(\d{4})', text)
    if brit_match:
        d, m, y = int(brit_match.group(1)), int(brit_match.group(2)), int(brit_match.group(3))
        return date(y, m, d)

    # Short text: D Mmm YYYY (English three-letter month)
    text_match = re.fullmatch(r'(\d{1,2})\s+([A-Z][a-z]{2})\s+(\d{4})', text)
    if text_match:
        d = int(text_match.group(1))
        m_str = text_match.group(2)
        y = int(text_match.group(3))
        months = {
            'Jan': 1, 'Feb': 2, 'Mar': 3, 'Apr': 4,
            'May': 5, 'Jun': 6, 'Jul': 7, 'Aug': 8,
            'Sep': 9, 'Oct': 10, 'Nov': 11, 'Dec': 12,
        }
        if m_str not in months:
            raise ValueError(f"Invalid month abbreviation: {m_str}")
        m = months[m_str]
        return date(y, m, d)

    raise ValueError(f"Unrecognized date format: {text!r}")
```

This function tries the three formats in order using `re.fullmatch` (which requires the entire string to match, so no partial matches slip through). Each successful regex match extracts the components and passes them to `date()`, which automatically validates the resulting date (e.g., `31/02/2025` raises `ValueError` because February 31 doesn't exist). If none of the patterns match, a `ValueError` is raised.

