      !Array.isArray(override[key])
    ) {
      result[key] = deepMerge(base[key], override[key]);
    } else {
      result[key] = override[key];
    }
  }

  return result;
}
```

**Explanation:** The function recursively merges two plain objects. It creates a new object, copies all keys from `base`, then processes each key from `override`: if the override value is `undefined` it is skipped; if both values are plain objects, they are merged recursively; otherwise the override value replaces the base value. Arrays are treated as non-mergeable values and are simply replaced.

```cpp
#include <string>
#include <cctype>
#include <cstdint>

long long parse_duration(const std::string& s) {
    if (s.empty()) return -1;

    long long total = 0;
    int state = 0; // 0: start, 1: after h, 2: after m, 3: after s, 4: done
    int pending = -1; // pending number for current unit

    auto flush_pending = [&]() -> bool {
        if (pending == -1) return false; // unit without number
        switch (state) {
            case 0: total += pending; return true;
            case 1: total += pending * 60; return true;
            case 2: total += pending * 3600; return true;
            default: return false;
        }
    };

    for (size_t i = 0; i < s.size(); ++i) {
        char c = s[i];
        if (std::isdigit(c)) {
            if (pending == -1) pending = 0;
            pending = pending * 10 + (c - '0');
        } else if (c == 'h') {
            if (state != 0) return -1;
            state = 1;
            if (!flush_pending()) return -1;
            pending = -1;
        } else if (c == 'm') {
            if (state != 1) return -1;
            state = 2;
            if (!flush_pending()) return -1;
            pending = -1;
        } else if (c == 's') {
            if (state != 2) return -1;
            state = 3;
            if (!flush_pending()) return -1;
            pending = -1;
        } else {
            return -1; // any other character (including spaces, signs, etc.)
        }
    }

    // Must end with a number (pending must be set) and state must be 3
    if (pending == -1) return -1;
    if (state != 3) return -1;
    total += pending;
    return total;
}
```

This function parses duration strings like `1h30m`, `45s`, `1h0m5s` into total seconds. It uses a state machine to enforce the h→m→s ordering, ensures each unit has a preceding number, rejects spaces/signs/unknown characters, and returns -1 for any invalid input.

