from collections import OrderedDict


class TTLCache:
    def __init__(self, capacity: int, ttl: int):
        self.capacity = capacity
        self.ttl = ttl
        self._cache = OrderedDict()  # key -> expiry_time

    def put(self, key, value, now: int) -> None:
        expiry = now + self.ttl
        if key in self._cache:
            self._cache[key] = expiry
            self._cache.move_to_end(key)
        else:
            self._cache[key] = expiry
            self._cache.move_to_end(key)
            if len(self._cache) > self.capacity:
                self._evict(now)

    def get(self, key, now: int):
        if key not in self._cache:
            return None
        expiry = self._cache[key]
        if now >= expiry:
            del self._cache[key]
            return None
        self._cache.move_to_end(key)
        return self._cache[key] - self.ttl  # we store expiry, return value? No.

    # Oops, I need to store value too. Let me fix.

    def __init__(self, capacity: int, ttl: int):
        self.capacity = capacity
        self.ttl = ttl
        self._cache = OrderedDict()  # key -> (expiry_time, value)

    def put(self, key, value, now: int) -> None:
        expiry = now + self.ttl
        if key in self._cache:
            self._cache[key] = (expiry, value)
            self._cache.move_to_end(key)
        else:
            self._cache[key] = (expiry, value)
            self._cache.move_to_end(key)
            if len(self._cache) > self.capacity:
                self._evict(now)

    def get(self, key, now: int):
        if key not in self._cache:
            return None
        expiry, value = self._cache[key]
        if now >= expiry:
            del self._cache[key]
            return None
        self._cache.move_to_end(key)
        return value

    def _evict(self, now: int):
        # First remove expired entries
        expired_keys = [k for k, (expiry, _) in self._cache.items() if now >= expiry]
        for k in expired_keys:
            del self._cache[k]
        # If still full, remove LRU (first item)
        if len(self._cache) > self.capacity:
            self._cache.popitem(last=False)

    def size(self, now: int) -> int:
        return sum(1 for expiry, _ in self._cache.values() if now < expiry)
```

This class implements a TTL-backed cache with LRU eviction. It uses `OrderedDict` to track insertion order (newest at end, oldest at front). On `put`, if the cache is full, it first sweeps expired entries, then if still full, evicts the LRU entry. `get` returns `None` for missing/expired keys and promotes the key to most-recently-used without changing its expiry. `size` counts only non-expired entries.

```python
def satisfies(version: str, range_: str) -> bool:
    """
    Check if a version satisfies a semver range.

    Args:
        version: A version string in MAJOR.MINOR.PATCH format.
        range_: A range string with alternatives separated by '||'.

    Returns:
        True if the version satisfies at least one alternative in the range.
    """
    def parse_version(v: str):
        parts = v.split('.')
        return tuple(int(p) for p in parts)

    def compare(v1, v2):
        """Compare two version tuples. Returns -1, 0, or 1."""
        for a, b in zip(v1, v2):
            if a < b:
                return -1
            if a > b:
                return 1
        return 0

    def satisfies_alternative(ver, alt):
        comparators = alt.strip().split()
        for comp in comparators:
            if not satisfies_comparator(ver, comp):
                return False
        return True

    def satisfies_comparator(ver, comp):
        if comp.startswith('^'):
            target = parse_version(comp[1:])
            if target[0] == 0 and target[1] == 0:
                # ^0.0.x: >=0.0.x and <0.0.(x+1)
                lower = (0, 0, target[2])
                upper = (0, 0, target[2] + 1)
            elif target[0] == 0:
                # ^0.x.y: >=0.x.y and <0.(x+1).0
                lower = (0, target[1], target[2])
                upper = (0, target[1] + 1, 0)
            else:
                # ^x.y.z: >=x.y.z and <(x+1).0.0
                lower = target
                upper = (target[0] + 1, 0, 0)
            return compare(ver, lower) >= 0 and compare(ver, upper) < 0

        elif comp.startswith('~'):
            target = parse_version(comp[1:])
            # >=x.y.z and <x.(y+1).0
            lower = target
            upper = (target[0], target[1] + 1, 0)
            return compare(ver, lower) >= 0 and compare(ver, upper) < 0

        elif comp.startswith('>='):
            target = parse_version(comp[2:])
            return compare(ver, target) >= 0

        elif comp.startswith('<='):
            target = parse_version(comp[2:])
            return compare(ver, target) <= 0

        elif comp.startswith('>'):
            target = parse_version(comp[1:])
            return compare(ver, target) > 0

        elif comp.startswith('<'):
            target = parse_version(comp[1:])
            return compare(ver, target) < 0

        elif comp.startswith('='):
            target = parse_version(comp[1:])
            return compare(ver, target) == 0

        else:
            # bare version means ==
            target = parse_version(comp)
            return compare(ver, target) == 0

    ver = parse_version(version)
    alternatives = range_.split('||')
    for alt in alternatives:
        if satisfies_alternative(ver, alt):
            return True
    return False
```

This implementation handles all the specified comparator types (`=`, `>`, `>=`, `<`, `<=`, `~`, `^`) and the alternative separator `||`. The `^` operator follows the semver rules where `^0.0.x` locks everything, `^0.x.y` locks major and minor, and `^x.y.z` (x > 0) only locks major. The `~` operator allows patch-level changes only.

