function applyPatch(doc, ops) {
  // Deep clone the doc to avoid mutation
  const result = JSON.parse(JSON.stringify(doc));

  for (const op of ops) {
    const { op: operation, path, value } = op;

    if (operation !== 'add' && operation !== 'remove' && operation !== 'replace') {
      throw new Error(`Unknown op: ${operation}`);
    }

    if (path === "") {
      if (operation === 'add') {
        return value;
      }
      throw new Error(`Path "" only supports "add" operations`);
    }

    // Validate path format: must start with /
    if (!path.startsWith('/')) {
      throw new Error(`Path must start with "/"`);
    }

    const segments = path.substring(1).split('/');
    const target = resolvePath(result, segments);

    if (operation === 'add') {
      if (target.parent === null) {
        throw new Error(`No parent at path ${path}`);
      }
      if (target.parent instanceof Array) {
        if (target.key === '-') {
          target.parent.push(value);
        } else {
          const index = parseInt(target.key, 10);
          if (isNaN(index) || index < 0 || String(index) !== target.key) {
            throw new Error(`Invalid array index: ${target.key}`);
          }
          if (index > target.parent.length) {
            throw new Error(`Array index out of range: ${index}`);
          }
          target.parent.splice(index, 0, value);
        }
      } else if (target.parent instanceof Object && target.parent !== null) {
        target.parent[target.key] = value;
      } else {
        throw new Error(`Cannot add to non-object/non-array at path ${path}`);
      }
    } else if (operation === 'remove') {
      if (target.parent === null) {
        throw new Error(`No parent at path ${path}`);
      }
      if (target.parent instanceof Array) {
        const index = parseInt(target.key, 10);
        if (isNaN(index) || index < 0 || String(index) !== target.key) {
          throw new Error(`Invalid array index: ${target.key}`);
        }
        if (index >= target.parent.length) {
          throw new Error(`Array index out of range: ${index}`);
        }
        target.parent.splice(index, 1);
      } else if (target.parent instanceof Object && target.parent !== null) {
        if (!(target.key in target.parent)) {
          throw new Error(`Key "${target.key}" does not exist in object`);
        }
        delete target.parent[target.key];
      } else {
        throw new Error(`Cannot remove from non-object/non-array at path ${path}`);
      }
    } else if (operation === 'replace') {
      if (target.parent === null) {
        throw new Error(`No parent at path ${path}`);
      }
      if (target.parent instanceof Array) {
        const index = parseInt(target.key, 10);
        if (isNaN(index) || index < 0 || String(index) !== target.key) {
          throw new Error(`Invalid array index: ${target.key}`);
        }
        if (index >= target.parent.length) {
          throw new Error(`Array index out of range: ${index}`);
        }
        target.parent[index] = value;
      } else if (target.parent instanceof Object && target.parent !== null) {
        if (!(target.key in target.parent)) {
          throw new Error(`Key "${target.key}" does not exist in object`);
        }
        target.parent[target.key] = value;
      } else {
        throw new Error(`Cannot replace in non-object/non-array at path ${path}`);
      }
    }
  }

  return result;
}

function resolvePath(root, segments) {
  let current = root;
  let parent = null;
  let key = null;

  for (let i = 0; i < segments.length; i++) {
    const segment = unescapeSegment(segments[i]);

    if (current === null || typeof current !== 'object') {
      return { parent: null, key: null, value: null };
    }

    if (Array.isArray(current)) {
      const index = parseInt(segment, 10);
      if (isNaN(index) || index < 0 || String(index) !== segment) {
        throw new Error(`Invalid array index: ${segment}`);
      }
      if (i === segments.length - 1) {
        // Last segment: target is an array element
        if (index >= current.length) {
          throw new Error(`Array index out of range: ${index}`);
        }
        return { parent: current, key: index, value: current[index] };
      } else {
        parent = current;
        key = index;
        current = current[index];
      }
    } else {
      if (i === segments.length - 1) {
        // Last segment: target is an object member
        if (!(segment in current)) {
          throw new Error(`Key "${segment}" does not exist in object`);
        }
        return { parent: current, key: segment, value: current[segment] };
      } else {
        parent = current;
        key = segment;
        current = current[segment];
      }
    }
  }

  return { parent: null, key: null, value: null };
}

function unescapeSegment(segment) {
  // Replace ~1 with / and ~0 with ~ (in that order to avoid conflicts)
  return segment.replace(/~1/g, '/').replace(/~0/g, '~');
}
```

This function implements JSON Patch (RFC 6902) for a Node.js config service. It:

1. **Deep clones** the input document to ensure no mutation of the original.
2. **Parses paths** using JSON Pointer semantics (`~0` → `~`, `~1` → `/`).
3. **Validates** all operations, paths, and indices, throwing `Error` on invalid input.
4. Supports all three operations: `add`, `remove`, and `replace`.
5. Handles special cases like `-` for array append, path `""` for document replacement, and nested structures.

