from typing import Any


def normalise_order(raw: dict) -> dict:
    # --- sku ---
    sku_raw = raw.get("sku")
    if sku_raw is None:
        raise ValueError("sku is missing")
    sku = str(sku_raw).strip().upper()
    if not sku:
        raise ValueError("sku is empty after stripping")

    # --- qty ---
    qty_raw = raw.get("qty")
    if qty_raw is None:
        raise ValueError("qty is missing")
    try:
        qty = int(str(qty_raw).strip())
    except (TypeError, ValueError):
        raise ValueError("qty is not a valid integer")
    if qty < 1 or qty > 99:
        raise ValueError("qty must be between 1 and 99 inclusive")

    # --- unit_price_pence ---
    upp_raw = raw.get("unit_price_pence")
    if upp_raw is None:
        raise ValueError("unit_price_pence is missing")
    try:
        unit_price_pence = int(str(upp_raw).strip())
    except (TypeError, ValueError):
        raise ValueError("unit_price_pence is not a valid integer")
    if unit_price_pence < 0:
        raise ValueError("unit_price_pence must be 0 or more")

    # --- currency ---
    currency_raw = raw.get("currency")
    if currency_raw is None or (isinstance(currency_raw, str) and not currency_raw.strip()):
        currency = "GBP"
    else:
        currency = str(currency_raw).strip().upper()
        if currency not in ("GBP", "EUR", "USD"):
            raise ValueError("currency must be GBP, EUR or USD")

    # --- total_pence ---
    total_pence = qty * unit_price_pence

    return {
        "sku": sku,
        "qty": qty,
        "unit_price_pence": unit_price_pence,
        "currency": currency,
        "total_pence": total_pence,
    }
