function deepMerge(base, override) {
  if (base === null || base === undefined || typeof base !== 'object') {
    return override;
  }
  if (override === null || override === undefined || typeof override !== 'object') {
    return override;
  }

  const result = Array.isArray(base) ? [] : {};

  for (const key of Object.keys(base)) {
    if (Object.prototype.hasOwnProperty.call(override, key)) {
      const baseVal = base[key];
      const overVal = override[key];
      if (overVal === undefined) {
        result[key] = cloneDeep(baseVal);
      } else if (
        baseVal !== null && typeof baseVal === 'object' &&
        overVal !== null && typeof overVal === 'object' &&
        !Array.isArray(baseVal) && !Array.isArray(overVal)
      ) {
        result[key] = deepMerge(baseVal, overVal);
      } else {
        result[key] = cloneDeep(overVal);
      }
    } else {
      result[key] = cloneDeep(baseVal);
    }
  }

  for (const key of Object.keys(override)) {
    if (!Object.prototype.hasOwnProperty.call(base, key)) {
      result[key] = cloneDeep(override[key]);
    }
  }

  return result;
}

function cloneDeep(obj) {
  if (obj === null || obj === undefined) return obj;
  if (Array.isArray(obj)) return obj.map(cloneDeep);
  if (typeof obj !== 'object') return obj;
  const result = {};
  for (const key of Object.keys(obj)) {
    result[key] = cloneDeep(obj[key]);
  }
  return result;
}
```

