#include <string>
#include <cctype>

long long parse_duration(const std::string& s) {
    if (s.empty()) return -1;

    long long total = 0;
    std::string::size_type pos = 0;
    int last_unit = -1; // 0 = h, 1 = m, 2 = s

    while (pos < s.size()) {
        // Parse number
        if (pos == s.size() || !std::isdigit(static_cast<unsigned char>(s[pos])))
            return -1; // no number before unit

        long long num = 0;
        while (pos < s.size() && std::isdigit(static_cast<unsigned char>(s[pos]))) {
            num = num * 10 + (s[pos] - '0');
            ++pos;
        }

        // Parse unit
        if (pos == s.size())
            return -1; // number without unit

        char unit = s[pos];
        if (unit == 'h') {
            if (last_unit >= 0) return -1; // repeated unit
            last_unit = 0;
            total += num * 3600;
        } else if (unit == 'm') {
            if (last_unit != -1 && last_unit != 0) return -1; // wrong order
            if (last_unit == 1) return -1; // repeated
            last_unit = 1;
            total += num * 60;
        } else if (unit == 's') {
            if (last_unit != -1 && last_unit < 2) return -1; // wrong order
            if (last_unit == 2) return -1; // repeated
            last_unit = 2;
            total += num;
        } else {
            return -1; // unknown unit
        }
        ++pos;
    }

    if (last_unit == -1) return -1; // no valid unit found
    return total;
}
