        self.ttl = ttl
        self.cache = OrderedDict()  # key -> expiry_time

    def put(self, key, value, now: int) -> None:
        expiry = now + self.ttl
        if key in self.cache:
            # Replace and move to end (most recently used)
            self.cache[key] = expiry
            self.cache.move_to_end(key)
        else:
            # New key: evict expired entries first
            self._evict_expired(now)
            # If still full, remove LRU (oldest in OrderedDict)
            if len(self.cache) >= self.capacity:
                self.cache.popitem(last=False)
            # Insert new entry
            self.cache[key] = expiry

    def get(self, key, now: int):
        if key not in self.cache:
            return None
        if now >= self.cache[key]:
            # Expired
            del self.cache[key]
            return None
        # Valid: move to end (most recently used)
        self.cache.move_to_end(key)
        return self.cache[key]

    def size(self, now: int) -> int:
        self._evict_expired(now)
        return len(self.cache)

    def _evict_expired(self, now: int):
        """Remove all expired entries. Called before put when cache is full."""
        expired_keys = [k for k, exp in self.cache.items() if now >= exp]
        for k in expired_keys:
            del self.cache[k]
