def satisfies(version: str, range_: str) -> bool:
    """Check if a version satisfies a range of version constraints."""
    version_parts = [int(x) for x in version.split('.')]

    alternatives = range_.split('||')

    for alt in alternatives:
        comparators = alt.split()
        if _check_comparators(version_parts, comparators):
            return True
    return False


def _check_comparators(version: list, comparators: list) -> bool:
    """Check if version satisfies all comparators in the alternative."""
    for comp in comparators:
        if not _check_single(version, comp):
            return False
    return True


def _check_single(version: list, comparator: str) -> bool:
    """Check if version satisfies a single comparator."""
    if comparator.startswith('>='):
        target = [int(x) for x in comparator[2:].split('.')]
        return _compare(version, target) >= 0
    elif comparator.startswith('<='):
        target = [int(x) for x in comparator[2:].split('.')]
        return _compare(version, target) <= 0
    elif comparator.startswith('>'):
        target = [int(x) for x in comparator[1:].split('.')]
        return _compare(version, target) > 0
    elif comparator.startswith('<'):
        target = [int(x) for x in comparator[1:].split('.')]
        return _compare(version, target) < 0
    elif comparator.startswith('='):
        target = [int(x) for x in comparator[1:].split('.')]
        return _compare(version, target) == 0
    elif comparator.startswith('~'):
        target = [int(x) for x in comparator[1:].split('.')]
        # >= target and < next minor
        lower = target
        upper = [target[0], target[1] + 1, 0]
        return _compare(version, lower) >= 0 and _compare(version, upper) < 0
    elif comparator.startswith('^'):
        target = [int(x) for x in comparator[1:].split('.')]
        # >= target and < next major (with special handling for 0.x)
        lower = target
        if target[0] == 0:
            if target[1] == 0:
                # ^0.0.x: >=0.0.x and <0.0.(x+1)
                upper = [0, 0, target[2] + 1]
            else:
                # ^0.x.y: >=0.x.y and <0.(x+1).0
                upper = [0, target[1] + 1, 0]
        else:
            # ^x.y.z: >=x.y.z and <(x+1).0.0
            upper = [target[0] + 1, 0, 0]
        return _compare(version, lower) >= 0 and _compare(version, upper) < 0
    else:
        # Bare version means exactly that version
        target = [int(x) for x in comparator.split('.')]
        return _compare(version, target) == 0


def _compare(a: list, b: list) -> int:
    """Compare two version lists. Returns -1, 0, or 1."""
    for i in range(3):
        if i < len(a) and i < len(b):
            if a[i] < b[i]:
                return -1
            elif a[i] > b[i]:
                return 1
        elif i < len(a):
            return 1
        else:
            return -1
    return 0
