  let current = JSON.parse(JSON.stringify(doc));

  for (const opEntry of ops) {
    const { op, path, value } = opEntry;
    if (op !== "add" && op !== "remove" && op !== "replace") {
      throw new Error("unknown op: " + op);
    }

    if (path === "") {
      if (op === "add") {
        current = value;
      } else if (op === "replace") {
        current = value;
      } else {
        throw new Error("remove with empty path is invalid");
      }
      continue;
    }

    if (!path.startsWith("/")) {
      throw new Error("path must start with /");
    }

    const segments = path.slice(1).split("/").map(decodeSegment);

    if (segments.length === 0) {
      throw new Error("invalid path");
    }

    const parent = findParent(current, segments.slice(0, -1));
    const lastSegment = segments[segments.length - 1];

    if (parent === undefined) {
      throw new Error("parent does not exist");
    }

    if (op === "add") {
      if (Array.isArray(parent)) {
        const index = lastSegment === "-" ? parent.length : parseInt(lastSegment, 10);
        if (isNaN(index) || index < 0 || index !== Math.floor(index)) {
          throw new Error("invalid array index: " + lastSegment);
        }
        if (index > parent.length) {
          throw new Error("array index out of range");
        }
        parent.splice(index, 0, value);
      } else if (typeof parent === "object" && parent !== null) {
        parent[lastSegment] = value;
      } else {
        throw new Error("cannot add to non-object/non-array");
      }
    } else if (op === "remove") {
      if (Array.isArray(parent)) {
        const index = parseInt(lastSegment, 10);
        if (isNaN(index) || index < 0 || index !== Math.floor(index)) {
          throw new Error("invalid array index: " + lastSegment);
        }
        if (index >= parent.length) {
          throw new Error("array index out of range");
        }
        parent.splice(index, 1);
      } else if (typeof parent === "object" && parent !== null) {
        if (!(lastSegment in parent)) {
          throw new Error("target does not exist");
        }
        delete parent[lastSegment];
      } else {
        throw new Error("cannot remove from non-object/non-array");
      }
    } else if (op === "replace") {
      if (Array.isArray(parent)) {
        const index = parseInt(lastSegment, 10);
        if (isNaN(index) || index < 0 || index !== Math.floor(index)) {
          throw new Error("invalid array index: " + lastSegment);
        }
        if (index >= parent.length) {
          throw new Error("array index out of range");
        }
        parent[index] = value;
      } else if (typeof parent === "object" && parent !== null) {
        if (!(lastSegment in parent)) {
          throw new Error("target does not exist");
        }
        parent[lastSegment] = value;
      } else {
        throw new Error("cannot replace in non-object/non-array");
      }
    }
  }

  return current;
}

function findParent(doc, segments) {
  let current = doc;
  for (const seg of segments) {
    if (current === null || current === undefined || typeof current !== "object") {
      throw new Error("parent does not exist");
    }
    if (Array.isArray(current)) {
      const index = parseInt(seg, 10);
      if (isNaN(index) || index < 0 || index !== Math.floor(index)) {
        throw new Error("invalid array index: " + seg);
      }
      if (index >= current.length) {
        throw new Error("array index out of range");
      }
      current = current[index];
    } else {
      if (!(seg in current)) {
        throw new Error("parent does not exist");
      }
      current = current[seg];
    }
  }
  return current;
}

function decodeSegment(segment) {
  return segment.replace(/~1/g, "/").replace(/~0/g, "~");
}
