import datetime
import re

def parse_date(text: str) -> datetime.date:
    """
    Parse a date string in one of three formats:
    - ISO: '2025-03-07'
    - British numeric: '07/03/2025' (day/month/year)
    - Short text: '7 Mar 2025' (English three-letter month; day with or without leading zero)

    Raises ValueError for invalid formats or impossible dates.
    """
    text = text.strip()

    try:
        return _parse_iso(text) or _parse_british_numeric(text) or _parse_short_text(text)
    except ValueError:
        raise ValueError("Invalid date format or impossible date")

def _parse_iso(text: str):
    """Parse ISO format: YYYY-MM-DD"""
    match = re.match(r'^(\d{4})-(\d{2})-(\d{2})$', text)
    if not match:
        return None

    year, month, day = int(match.group(1)), int(match.group(2)), int(match.group(3))
    try:
        return datetime.date(year, month, day)
    except ValueError:
        return None

def _parse_british_numeric(text: str):
    """Parse British numeric format: DD/MM/YYYY"""
    match = re.match(r'^(\d{2})/(\d{2})/(\d{4})$', text)
    if not match:
        return None

    day, month, year = int(match.group(1)), int(match.group(2)), int(match.group(3))
    try:
        return datetime.date(year, month, day)
    except ValueError:
        return None

def _parse_short_text(text: str):
    """Parse short text format: D Mon YYYY"""
    month_names = {
        'jan': 1, 'feb': 2, 'mar': 3, 'apr': 4, 'may': 5, 'jun': 6,
        'jul': 7, 'aug': 8, 'sep': 9, 'oct': 10, 'nov': 11, 'dec': 12
    }

    match = re.match(r'^(\d{1,2})\s+([A-Za-z]{3})\s+(\d{4})$', text)
    if not match:
        return None

    day = int(match.group(1))
    month_str = match.group(2).lower()[:3]
    year = int(match.group(3))

    if month_str not in month_names:
        return None

    month = month_names[month_str]
    try:
        return datetime.date(year, month, day)
    except ValueError:
        return None
