def normalise_order(raw: dict) -> dict:
    # Extract and validate sku
    sku = raw.get("sku")
    if sku is None:
        raise ValueError("sku is missing")
    sku = str(sku).strip().upper()
    if not sku:
        raise ValueError("sku is empty after stripping")

    # Extract and validate qty
    qty = raw.get("qty")
    if qty is None:
        raise ValueError("qty is missing")
    try:
        qty = int(qty)
    except (ValueError, TypeError):
        raise ValueError("qty is not a valid integer")
    if qty < 1 or qty > 99:
        raise ValueError("qty must be between 1 and 99")

    # Extract and validate unit_price_pence
    unit_price_pence = raw.get("unit_price_pence")
    if unit_price_pence is None:
        raise ValueError("unit_price_pence is missing")
    try:
        unit_price_pence = int(unit_price_pence)
    except (ValueError, TypeError):
        raise ValueError("unit_price_pence is not a valid integer")
    if unit_price_pence < 0:
        raise ValueError("unit_price_pence must be 0 or more")

    # Extract and validate currency
    currency = raw.get("currency")
    if currency is None:
        currency = ""
    currency = str(currency).strip().upper()
    if not currency:
        currency = "GBP"
    elif currency not in {"GBP", "EUR", "USD"}:
        raise ValueError(f"invalid currency: {currency}")

    # Calculate total_pence
    total_pence = qty * unit_price_pence

    return {
        "sku": sku,
        "qty": qty,
        "unit_price_pence": unit_price_pence,
        "currency": currency,
        "total_pence": total_pence,
    }
