        // Parse number
        if (!std::isdigit(s[i])) return -1;

        long long num = 0;
        while (i < s.size() && std::isdigit(s[i])) {
            num = num * 10 + (s[i] - '0');
            i++;
        }

        // Check for unit
        if (i >= s.size()) return -1;

        char unit = s[i];
        i++;

        int unit_value;
        if (unit == 'h') unit_value = 0;
        else if (unit == 'm') unit_value = 1;
        else if (unit == 's') unit_value = 2;
        else return -1; // Unknown unit

        if (unit_value < expected) return -1; // Wrong order
        if (unit_value == expected) expected++; // Move to next expected

        // Convert to seconds
        if (unit == 'h') total += num * 3600;
        else if (unit == 'm') total += num * 60;
        else total += num; // 's'
    }

    return total;
}
